function normalizeSalesPhone(value: unknown): string | null {
  const digits = sanitizeString(value, 40).replace(/\D/g, "");
  if (!digits) return null;
  const withCountry =
    digits.length <= 11 ? `55${digits}` : digits.startsWith("55") ? digits : "";
  if (!/^55\d{10,11}$/.test(withCountry)) return null;
  return withCountry.slice(0, 20);
}

function normalizeSalesInteger(
  value: unknown,
  max: number,
  required = false,
): number | null {
  if (value === "" || value === null || value === undefined)
    return required ? 0 : null;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 0 || parsed > max) return null;
  return parsed;
}

function hashSalesOfferToken(token: string): string {
  return crypto.createHash("sha256").update(token).digest("hex");
}

function deriveSalesActivationToken(checkoutSessionId: string): string {
  const sessionId = sanitizeString(checkoutSessionId, 200);
  const secret = sanitizeString(
    process.env.DATA_ENCRYPTION_KEY || process.env.SESSION_SECRET,
    2000,
  );
  if (!sessionId || !secret) {
    throw new Error("SALES_ACTIVATION_TOKEN_CONFIGURATION_MISSING");
  }
  return crypto
    .createHmac("sha256", secret)
    .update(`sales-assisted-activation:${sessionId}`)
    .digest("base64url");
}

function deriveSalesOfferPublicToken(
  actorUserId: string,
  idempotencyKey: string,
): string {
  const secret = sanitizeString(process.env.SESSION_SECRET, 1000);
  if (!secret) throw new Error("SESSION_SECRET_REQUIRED_FOR_SALES_OFFER");
  return crypto
    .createHmac("sha256", secret)
    .update(`sales-offer:${actorUserId}:${idempotencyKey}`)
    .digest("base64url");
}

function deriveSalesCheckoutPublicToken(
  offerId: string,
  requestHash: string,
): string {
  const secret = sanitizeString(process.env.SESSION_SECRET, 1000);
  if (!secret) throw new Error("SESSION_SECRET_REQUIRED_FOR_SALES_CHECKOUT");
  return crypto
    .createHmac("sha256", secret)
    .update(`sales-modular-checkout:${offerId}:${requestHash}`)
    .digest("base64url");
}

function salesApplicationOrigin(req: any): string {
  return sanitizeString(
    process.env.VERTO_APP_BASE_URL || `${req.protocol}://${req.get("host")}`,
    500,
  ).replace(/\/+$/, "");
}

function serializeSalesCheckoutLink(req: any, link: any) {
  if (!link?.offer_id || !link?.request_hash || !link?.idempotency_key) return link;
  const token = deriveSalesCheckoutPublicToken(
    link.offer_id,
    `${link.request_hash}:${link.idempotency_key}`,
  );
  return {
    ...link,
    publicCheckoutUrl: `${salesApplicationOrigin(req)}/api/public/sales-checkouts/${encodeURIComponent(token)}`,
  };
}

function resolveSalesStripeConfiguration() {
  const basePriceId = sanitizeString(
    process.env.STRIPE_BASE_ACTIVE_PATIENT_PRICE_ID,
    240,
  );
  const couponIds = {
    6: sanitizeString(process.env.STRIPE_COUPON_6_MONTHS_ID, 240),
    12: sanitizeString(process.env.STRIPE_COUPON_12_MONTHS_ID, 240),
    24: sanitizeString(process.env.STRIPE_COUPON_24_MONTHS_ID, 240),
  } as Record<6 | 12 | 24, string>;
  return {
    enabled:
      sanitizeString(
        process.env.SALES_ASSISTED_SIGNUP_ENABLED || "true",
        20,
      ).toLowerCase() !== "false",
    basePriceId,
    couponIds,
    readyForDuration(durationMonths: number | null) {
      if (!basePriceId) return false;
      if (!durationMonths) return true;
      return (
        isCouponDurationMonths(durationMonths) &&
        Boolean(couponIds[durationMonths])
      );
    },
  };
}

