const VERTO_PROTOCOL_BY_KEY = new Map(VERTO_PROTOCOL_CATALOG.map((protocol) => [protocol.key, protocol]));
const VERTO_PROTOCOL_PANEL_RESET_AT = '2026-05-07T15:38:23.081Z';
const LICENSED_VERTO_PROTOCOLS_BY_KEY = new Map<string, any>([
  ['afls-social-participation-adult', AFLS_ADULT_SOCIAL_PARTICIPATION_PROTOCOL],
  ['vb-mapp-level-1', VBMAPP_LEVEL_1_CANONICAL_PROTOCOL],
  ['vb-mapp-level-2', VBMAPP_LEVEL_2_CANONICAL_PROTOCOL],
  ['vb-mapp-level-3', VBMAPP_LEVEL_3_CANONICAL_PROTOCOL]
]);

function cloneJsonValue<T>(value: T): T {
  return JSON.parse(JSON.stringify(value ?? null));
}

function buildProtocolIdentityKeys(protocol: any): string[] {
  const keys = [
    protocol?.canonicalKey,
    protocol?.canonical_key,
    protocol?.id,
    protocol?.title,
    protocol?.name,
    protocol?.protocolName
  ]
    .map((value) => normalizeApprovedProtocolKey(sanitizeString(value, 180)))
    .map((value) => normalizeProtocolKey(value))
    .filter(Boolean);
  return Array.from(new Set(keys));
}

function resolveApprovedProtocolKeyFromRequest(request: any): string {
  const explicit = normalizeApprovedProtocolKey(
    request?.approved_canonical_key ||
    request?.canonicalKey ||
    request?.suggested_canonical_key
  );
  if (LICENSED_VERTO_PROTOCOLS_BY_KEY.has(explicit) || VERTO_PROTOCOL_BY_KEY.has(explicit)) return explicit;
  return normalizeApprovedProtocolKey(
    identifyVertoProtocolCandidate(
      `${request?.approved_canonical_name || ''} ${request?.suggested_canonical_name || ''} ${request?.protocol_name || ''}`
    ).canonicalKey
  );
}

function buildClinicProtocolFromApprovedRequest(request: any): any | null {
  const canonicalKey = resolveApprovedProtocolKeyFromRequest(request);
  const canonicalProtocol = LICENSED_VERTO_PROTOCOLS_BY_KEY.get(canonicalKey);
  if (!canonicalProtocol || !Array.isArray(canonicalProtocol.data) || canonicalProtocol.data.length === 0) {
    return null;
  }

  const approvedAt = sanitizeString(request?.reviewed_at || request?.updated_at || request?.created_at, 80) || new Date().toISOString();
  const requestId = sanitizeString(request?.id, 120);
  const protocol = cloneJsonValue(canonicalProtocol);
  return sanitizeClinicalPayload({
    ...protocol,
    id: protocol.canonicalKey || canonicalKey,
    canonicalKey,
    title: protocol.title || request?.approved_canonical_name || request?.protocol_name || canonicalKey,
    category: protocol.category || 'evaluation',
    origin: 'verto_approved_import',
    source: 'protocol_import_requests',
    sourceRequestId: requestId || null,
    importedAt: sanitizeString(request?.created_at, 80) || approvedAt,
    approvedAt,
    status: 'approved',
    requestStatus: 'approved',
    isApprovedImport: false,
    isManualProtocol: false,
    isLicensed: true
  });
}

function mergeApprovedProtocolsIntoClinicState(existingProtocols: any[], approvedProtocols: any[]) {
  const merged = normalizeProtocolArrayForRoute(existingProtocols);
  const indexByIdentity = new Map<string, number>();
  const registerProtocol = (protocol: any, index: number) => {
    for (const key of buildProtocolIdentityKeys(protocol)) {
      if (!indexByIdentity.has(key)) indexByIdentity.set(key, index);
    }
  };

  merged.forEach(registerProtocol);
  let added = 0;
  let refreshed = 0;

  for (const protocol of approvedProtocols) {
    const keys = buildProtocolIdentityKeys(protocol);
    const existingIndex = keys.map((key) => indexByIdentity.get(key)).find((index) => typeof index === 'number');
    if (typeof existingIndex === 'number') {
      merged[existingIndex] = {
        ...merged[existingIndex],
        ...protocol,
        createdAt: merged[existingIndex]?.createdAt || protocol.createdAt || protocol.importedAt || null
      };
      refreshed += 1;
      registerProtocol(merged[existingIndex], existingIndex);
      continue;
    }
    merged.push(protocol);
    registerProtocol(protocol, merged.length - 1);
    added += 1;
  }

  return { protocols: merged, added, refreshed };
}

function buildProtocolAccessScopeKeys(params: { clinicId?: any; requesterUserId?: any; requesterEmail?: any }): string[] {
  const keys: string[] = [];
  const clinicId = sanitizeString(params.clinicId, 120);
  if (clinicId) keys.push(`clinic:${clinicId}`);
  const requesterUserId = sanitizeString(params.requesterUserId, 120);
  if (requesterUserId) keys.push(`user:${requesterUserId}`);
  const requesterEmail = sanitizeEmail(params.requesterEmail);
  if (requesterEmail) keys.push(`email:${requesterEmail}`);
  return Array.from(new Set(keys.length > 0 ? keys : ['unknown']));
}

function buildProtocolAccessScopeKey(params: { clinicId?: any; requesterUserId?: any; requesterEmail?: any }): string {
  return buildProtocolAccessScopeKeys(params)[0] || 'unknown';
}

async function loadProtocolAccessMap(): Promise<Map<string, string[]>> {
  const accessMap = new Map<string, string[]>();
  try {
    const { data } = await supabase
      .from('activity_logs')
      .select('payload_details, timestamp')
      .eq('type', 'protocol_access_updated')
      .eq('is_active', true)
      .is('deleted_at', null)
      .gte('timestamp', VERTO_PROTOCOL_PANEL_RESET_AT)
      .order('timestamp', { ascending: true })
      .limit(1000);

    for (const log of data || []) {
      try {
        const payload = JSON.parse(String((log as any).payload_details || '{}'));
        const scopeKey = sanitizeString(payload.scopeKey, 220);
        if (!scopeKey) continue;
        const protocolKeys = Array.isArray(payload.protocolKeys)
          ? payload.protocolKeys.map((key: any) => normalizeApprovedProtocolKey(key)).filter((key: string) => VERTO_PROTOCOL_BY_KEY.has(key))
          : [];
        accessMap.set(scopeKey, Array.from(new Set(protocolKeys)));
      } catch {
        // Ignore malformed access history entries.
      }
    }
  } catch {
    // Access history is additive; if it is unavailable, callers fall back to no assignments.
  }
  return accessMap;
}

function normalizeBrazilMobilePhone(value: unknown): string | null {
  const digits = sanitizeString(value, 40).replace(/\D/g, '');
  if (!digits) return null;
  const normalized = digits.startsWith('55') && digits.length >= 13
    ? digits.slice(2)
    : digits;
  if (!/^\d{11}$/.test(normalized)) return null;
  if (normalized[2] !== '9') return null;
  return normalized;
}

function normalizeCpf(value: unknown): string | null {
  const digits = sanitizeString(value, 32).replace(/\D/g, '');
  if (!digits) return null;
  if (digits.length !== 11) return null;
  return digits;
}

function sanitizeDate(value: unknown): string | null {
  const date = sanitizeString(value, 10);
  if (!DATE_ONLY_REGEX.test(date)) return null;
  return date;
}

type ClinicalHistoryCursor = {
  createdAt: string;
  id: string;
};

function normalizeClinicalHistoryBoundary(value: unknown, endOfDay = false): string | null {
  const raw = sanitizeString(value, 80);
  if (!raw) return null;
  if (DATE_ONLY_REGEX.test(raw)) {
    return `${raw}T${endOfDay ? '23:59:59.999' : '00:00:00.000'}Z`;
  }
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function encodeClinicalHistoryCursor(row: any): string | null {
  const id = sanitizeString(row?.id, 160);
  const parsed = new Date(row?.created_at || row?.createdAt || '');
  if (!id || Number.isNaN(parsed.getTime())) return null;
  return Buffer.from(JSON.stringify({ createdAt: parsed.toISOString(), id }), 'utf8').toString('base64url');
}

function decodeClinicalHistoryCursor(value: unknown): ClinicalHistoryCursor | null {
  const raw = sanitizeString(value, 600);
  if (!raw) return null;
  try {
    const decoded = JSON.parse(Buffer.from(raw, 'base64url').toString('utf8'));
    const id = sanitizeString(decoded?.id, 160);
    const parsed = new Date(decoded?.createdAt || '');
    if (!id || !/^[a-zA-Z0-9_-]+$/.test(id) || Number.isNaN(parsed.getTime())) return null;
    return { createdAt: parsed.toISOString(), id };
  } catch {
    return null;
  }
}

function sanitizePhoneE164(value: unknown): string | null {
  const raw = sanitizeString(value, 30);
  if (!raw) return null;
  const digits = raw.replace(/[^\d+]/g, '');
  if (!digits.startsWith('+')) return null;
  if (!/^\+\d{8,15}$/.test(digits)) return null;
  return digits;
}

function resolveStoredCrp(input: any): string | null {
  const raw = (
    sanitizeString(input?.crp, 80) ||
    sanitizeString(input?.council_number, 80) ||
    sanitizeString(input?.councilNumber, 80) ||
    sanitizeString(input?.clinicSettings?.councilNumber, 80) ||
    null
  );
  if (!raw) return null;
  const digits = raw.replace(/\D/g, '').slice(0, 7);
  if (digits.length <= 2) return digits || null;
  return `${digits.slice(0, 2)}/${digits.slice(2)}`;
}

function resolveStoredCouncil(input: any): string | null {
  return sanitizeString(input?.council, 80) || null;
}

function maskEmail(email: string): string {
  const [local, domain] = email.split('@');
  if (!local || !domain) return '***';
  const visible = local.slice(0, 2);
  return `${visible}${'*'.repeat(Math.max(1, local.length - 2))}@${domain}`;
}

function maskPhone(phone: string): string {
  const digits = phone.replace(/\D/g, '');
  if (digits.length < 4) return '***';
  return `***${digits.slice(-4)}`;
}

function hashIdentifier(value: string): string {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function uuidFromStableString(value: string): string {
  const hex = crypto.createHash('sha256').update(value).digest('hex').slice(0, 32).split('');
  hex[12] = '5';
  const variant = Number.parseInt(hex[16] || '8', 16);
  hex[16] = ((variant & 0x3) | 0x8).toString(16);
  const joined = hex.join('');
  return `${joined.slice(0, 8)}-${joined.slice(8, 12)}-${joined.slice(12, 16)}-${joined.slice(16, 20)}-${joined.slice(20)}`;
}

function generate6DigitOtp(): string {
  return String(crypto.randomInt(0, 1_000_000)).padStart(6, '0');
}

function generateTemporaryPassword(length = 20): string {
  const safeLength = Math.max(16, Math.min(length, 64));
  const lower = 'abcdefghijkmnopqrstuvwxyz';
  const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const numbers = '23456789';
  const symbols = '!@#$%*()-_=+?';
  const all = `${lower}${upper}${numbers}${symbols}`;

  const pick = (chars: string) => chars[crypto.randomInt(0, chars.length)];
  const chars: string[] = [
    pick(lower),
    pick(upper),
    pick(numbers),
    pick(symbols)
  ];
  while (chars.length < safeLength) chars.push(pick(all));

  for (let i = chars.length - 1; i > 0; i -= 1) {
    const j = crypto.randomInt(0, i + 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return chars.join('');
}

function getAuthRedirectUrl(): string {
  const baseUrl = sanitizeString(
    process.env.VERTO_APP_BASE_URL || process.env.APP_BASE_URL || '',
    500
  );
  if (!baseUrl) {
    throw new Error('VERTO_APP_BASE_URL (ou APP_BASE_URL) deve estar definida para redirecionamentos de autenticação.');
  }
  return `${baseUrl.replace(/\/+$/, '')}/auth/callback`;
}

type ActivationRedirectOptions = {
  invitationId?: unknown;
  inviteMode?: 'new' | 'existing';
};

function getActivationRedirectUrl(
  role?: unknown,
  email?: unknown,
  options: ActivationRedirectOptions = {}
): string {
  const baseUrl = sanitizeString(
    process.env.VERTO_APP_BASE_URL || process.env.APP_BASE_URL || '',
    500
  );
  if (!baseUrl) {
    throw new Error('VERTO_APP_BASE_URL (ou APP_BASE_URL) deve estar definida para ativação de conta.');
  }
  const normalizedRole = sanitizeString(role, 40).toLowerCase();
  const roleParam = normalizedRole === 'patient' ? 'patient' : 'coordinator';
  const safeEmail = sanitizeEmail(email);
  const invitationId = sanitizeString(options.invitationId, 120);
  const inviteMode = options.inviteMode === 'existing' ? 'existing' : options.inviteMode === 'new' ? 'new' : '';
  const params = new URLSearchParams({
    auth_action: 'activate',
    role: roleParam
  });
  if (safeEmail) params.set('email', safeEmail);
  if (isUuid(invitationId)) params.set('invitation_id', invitationId);
  if (inviteMode) params.set('invite_mode', inviteMode);

  // A entrada pela raiz evita 404 em hospedagens estáticas sem rewrite de SPA
  // para rotas profundas como `/ativar`.
  return `${baseUrl.replace(/\/+$/, '')}/?${params.toString()}`;
}

function getClinicInvitationAcceptanceUrl(invitationIdValue: unknown): string {
  const baseUrl = sanitizeString(
    process.env.VERTO_APP_BASE_URL || process.env.APP_BASE_URL || '',
    500
  );
  const invitationId = sanitizeString(invitationIdValue, 120);
  if (!baseUrl) {
    throw new Error('VERTO_APP_BASE_URL (ou APP_BASE_URL) deve estar definida para aceitar convites.');
  }
  if (!isUuid(invitationId)) {
    throw new Error('O convite precisa de um identificador v\u00e1lido para gerar o acesso.');
  }

  // Deliberately omit the e-mail and clinic from the URL. The authenticated
  // server-side acceptance route remains the sole authority for both values.
  const params = new URLSearchParams({
    auth_action: 'accept_invitation',
    invitation_id: invitationId,
  });
  return `${baseUrl.replace(/\/+$/, '')}/?${params.toString()}`;
}

function getRecoveryRedirectUrl(recoveryToken?: unknown): string {
  const baseUrl = sanitizeString(
    process.env.VERTO_APP_BASE_URL || process.env.APP_BASE_URL || '',
    500
  );
  if (!baseUrl) {
    throw new Error('VERTO_APP_BASE_URL (ou APP_BASE_URL) deve estar definida para recuperação de senha.');
  }
  const params = new URLSearchParams({ auth_action: 'recovery' });
  const token = sanitizeString(recoveryToken, 4096);
  const tokenFragment = new URLSearchParams();
  if (token) tokenFragment.set('recovery_token', token);
  const fragment = tokenFragment.toString();
  return `${baseUrl.replace(/\/+$/, '')}/reset-password?${params.toString()}${fragment ? `#${fragment}` : ''}`;
}

function extractSupabaseErrorMessage(error: any): string {
  if (!error) return '';
  if (typeof error === 'string') return sanitizeString(error, 1000);
  return sanitizeString(error?.message || error?.details || error?.hint || 'Unexpected error', 1000);
}

async function withTimeoutOrFallback<T>(
  promise: Promise<T>,
  timeoutMs: number,
  fallback: T,
  label: string
): Promise<T> {
  let timer: NodeJS.Timeout | null = null;
  try {
    const timeoutPromise = new Promise<T>((resolve) => {
      timer = setTimeout(() => resolve(fallback), timeoutMs);
    });
    const result = await Promise.race([promise, timeoutPromise]);
    if (result === fallback) {
      console.warn(`[Timeout] ${label} excedeu ${timeoutMs}ms; seguindo com fallback.`);
    }
    return result;
  } finally {
    if (timer) clearTimeout(timer);
  }
}

const SENSITIVE_LOG_KEY_REGEX =
  /(password|pass|token|secret|key|authorization|cookie|otp|code|mfa|session|refresh|access|bearer|credential)/i;

function redactForLogs(input: any): any {
  if (input === null || input === undefined) return input;
  if (typeof input === 'string') {
    const trimmed = input.length > 500 ? `${input.slice(0, 500)}...[truncated]` : input;
    if (/bearer\s+[a-z0-9\-_\.]+/i.test(trimmed)) return '[redacted]';
    if (/^[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]+$/.test(trimmed)) return '[redacted-jwt]';
    if (trimmed.length >= 32 && /^[A-Za-z0-9\-_]+$/.test(trimmed)) return '[redacted]';
    return trimmed;
  }
  if (typeof input === 'number' || typeof input === 'boolean') return input;
  if (Array.isArray(input)) return input.slice(0, 20).map((item) => redactForLogs(item));
  if (typeof input === 'object') {
    const output: Record<string, any> = {};
    for (const [key, value] of Object.entries(input)) {
      if (SENSITIVE_LOG_KEY_REGEX.test(key)) {
        output[key] = '[redacted]';
        continue;
      }
      output[key] = redactForLogs(value);
    }
    return output;
  }
  return String(input);
}

function safeJsonPreview(value: unknown, maxLength = 1000): string {
  try {
    const preview = JSON.stringify(redactForLogs(value));
    return sanitizeTextField(preview || '', maxLength) || '';
  } catch {
    try {
      return sanitizeTextField(String(value), maxLength) || '';
    } catch {
      return '';
    }
  }
}

function normalizeUnknownError(error: unknown): {
  code: string | null;
  message: string;
  details: string | null;
  hint: string | null;
  rawType: string;
} {
  const rawType = error === null ? 'null' : Array.isArray(error) ? 'array' : typeof error;
  const unwrapError = (value: any): any => {
    if (!value || typeof value !== 'object') return value;
    if (value.error && value.error !== value) return unwrapError(value.error);
    if (value.cause && value.cause !== value && !value.message) return unwrapError(value.cause);
    return value;
  };
  const unwrapped: any = unwrapError(error as any);
  const code = sanitizeString(unwrapped?.code || unwrapped?.statusCode || unwrapped?.status, 80) || null;
  const details = unwrapped?.details !== undefined ? safeJsonPreview(unwrapped.details, 1000) || null : null;
  const hint = unwrapped?.hint !== undefined ? safeJsonPreview(unwrapped.hint, 1000) || null : null;
  let message = '';
  if (error instanceof Error) message = error.message;
  else if (typeof unwrapped === 'string') message = unwrapped;
  else if (typeof unwrapped === 'number' || typeof unwrapped === 'boolean') message = String(unwrapped);
  else if (unwrapped?.message !== undefined) message = typeof unwrapped.message === 'string' ? unwrapped.message : safeJsonPreview(unwrapped.message, 1000);
  else if (unwrapped?.error_description !== undefined) message = safeJsonPreview(unwrapped.error_description, 1000);
  else if (unwrapped?.details !== undefined) message = safeJsonPreview(unwrapped.details, 1000);
  else message = safeJsonPreview(error, 1000);
  const safeMessage = sanitizeTextField(message && message !== '[object Object]' ? message : safeJsonPreview(error, 1000), 1000);
  return {
    code,
    message: safeMessage || 'Erro desconhecido.',
    details,
    hint,
    rawType
  };
}

function isMissingRelationError(error: any): boolean {
  const code = sanitizeString(error?.code, 20).toUpperCase();
  const message = extractSupabaseErrorMessage(error).toLowerCase();
  if (code === '42P01') return true;
  return (
    message.includes('relation') && message.includes('does not exist')
  );
}

function extractMissingColumnName(error: any): string | null {
  const message = extractSupabaseErrorMessage(error);
  if (!message) return null;

  const directMatch = message.match(/column\s+"?([a-zA-Z0-9_]+)"?\s+does not exist/i);
  if (directMatch?.[1]) return sanitizeString(directMatch[1], 120).toLowerCase();

  const qualifiedMatch = message.match(/column\s+[a-zA-Z0-9_]+\."?([a-zA-Z0-9_]+)"?\s+does not exist/i);
  if (qualifiedMatch?.[1]) return sanitizeString(qualifiedMatch[1], 120).toLowerCase();

  const postgrestCacheMatch = message.match(/could\s+not\s+find\s+the\s+'?([a-zA-Z0-9_]+)'?\s+column\s+of\s+'?[a-zA-Z0-9_]+'?\s+in\s+the\s+schema\s+cache/i);
  if (postgrestCacheMatch?.[1]) return sanitizeString(postgrestCacheMatch[1], 120).toLowerCase();

  return null;
}

function isSalesProfitabilityPolicySchemaMissing(error: any): boolean {
  const code = sanitizeString(error?.code || error?.message, 220);
  return (
    code.includes(SALES_PROFITABILITY_POLICY_MIGRATION_PENDING_CODE) ||
    isSalesProfitabilityPolicySchemaMissingError(error) ||
    extractMissingColumnName(error) === 'profitability_policy'
  );
}

function salesProfitabilityPolicySchemaError(error: any): Error {
  if (!isSalesProfitabilityPolicySchemaMissing(error)) return error;
  const pending = new Error(SALES_PROFITABILITY_POLICY_MIGRATION_PENDING_CODE);
  (pending as any).code = SALES_PROFITABILITY_POLICY_MIGRATION_PENDING_CODE;
  return pending;
}

function sendSalesProfitabilityPolicySchemaPending(
  res: any,
  error: any
): boolean {
  if (!isSalesProfitabilityPolicySchemaMissing(error)) return false;
  res.status(503).json({
    success: false,
    code: SALES_PROFITABILITY_POLICY_MIGRATION_PENDING_CODE,
    error: SALES_PROFITABILITY_POLICY_MIGRATION_PENDING_MESSAGE
  });
  return true;
}

function salesCatalogHasVersionedProfitabilityPolicy(
  catalog: SalesPricingCatalogSnapshot
): boolean {
  return (
    catalog.hasVersionedProfitabilityPolicy === true &&
    validateSalesProfitabilityPolicy(catalog.profitabilityPolicy)
  );
}

function sendSalesProfitabilityPolicyRequired(res: any) {
  return res.status(409).json({
    success: false,
    code: SALES_PROFITABILITY_POLICY_REQUIRED_CODE,
    error: SALES_PROFITABILITY_POLICY_REQUIRED_MESSAGE,
    message: SALES_PROFITABILITY_POLICY_REQUIRED_MESSAGE
  });
}

function hasMissingFinancialSchema(error: any): boolean {
  const code = sanitizeString(error?.code, 20).toUpperCase();
  const message = extractSupabaseErrorMessage(error).toLowerCase();
  if (code === '42P01' || code === '42703') return true;
  return (
    message.includes('schema cache') ||
    message.includes('does not exist') ||
    message.includes('relation')
  );
}

function buildActionResultPayload(params: {
  entity: string;
  action: string;
  item?: any;
  items?: any[];
  removedIds?: string[];
  affected?: Record<string, any>;
  events?: any[];
  warnings?: string[];
  legacy?: Record<string, any>;
}) {
  const items = Array.isArray(params.items)
    ? params.items
    : params.item
      ? [params.item]
      : [];
  const removedIds = Array.from(
    new Set((params.removedIds || []).map((id) => sanitizeString(id, 120)).filter(Boolean))
  );
  return cleanObject({
    success: true,
    entity: params.entity,
    action: params.action,
    item: params.item || items[0] || null,
    items,
    removedIds,
    affected: params.affected || {},
    events: Array.isArray(params.events) ? params.events : [],
    warnings: Array.isArray(params.warnings) ? params.warnings : [],
    ...(params.legacy || {})
  });
}

function logRouteDbError(route: string, error: any, context: Record<string, any> = {}) {
  console.error(`[DB:${route}]`, {
    message: extractSupabaseErrorMessage(error),
    code: sanitizeString(error?.code, 40) || null,
    details: sanitizeString(error?.details, 300) || null,
    hint: sanitizeString(error?.hint, 300) || null,
    context: redactForLogs(context)
  });
}

function safeErrorMessageByStatus(statusCode: number): string {
  if (statusCode === 400) return 'Requisição inválida.';
  if (statusCode === 401) return 'Sessão expirada ou inválida. Faça login novamente.';
  if (statusCode === 403) return 'Acesso negado.';
  if (statusCode === 404) return 'Recurso não encontrado.';
  if (statusCode === 409) return 'Conflito de dados.';
  if (statusCode === 413) return 'Payload excede o limite permitido.';
  if (statusCode === 415) return 'Tipo de conteúdo não suportado.';
  if (statusCode === 422) return 'Dados inválidos para processamento.';
  if (statusCode === 429) return 'Muitas tentativas. Tente novamente em alguns instantes.';
  if (statusCode >= 500) return 'Erro interno do servidor.';
  return 'Não foi possível processar a requisição.';
}

function routeDbErrorPayload(error: any) {
  if (process.env.NODE_ENV === 'production') {
    return { success: false, error: 'Erro interno do servidor.' };
  }

  return cleanObject({
    success: false,
    error: extractSupabaseErrorMessage(error) || 'Erro interno do servidor.',
    code: sanitizeString(error?.code, 40) || undefined,
    details: sanitizeString(error?.details, 500) || undefined,
    hint: sanitizeString(error?.hint, 500) || undefined
  });
}

function sendRouteDbError(res: any, route: string, error: any, context: Record<string, any> = {}) {
  logRouteDbError(route, error, context);
  return res.status(500).json(routeDbErrorPayload(error));
}

function classifyAuthRouteError(error: any): { status: number; kind: string } {
  const code = sanitizeString(error?.code, 40);
  const message = extractSupabaseErrorMessage(error).toLowerCase();
  const upstreamStatus = Number(error?.status || error?.statusCode || 0);
  if (Number.isFinite(upstreamStatus) && upstreamStatus >= 400 && upstreamStatus < 500) {
    return { status: upstreamStatus, kind: 'auth' };
  }
  if (code === '42501' || message.includes('permission denied') || message.includes('row-level security')) {
    return { status: 403, kind: 'permission' };
  }
  if (isMissingRelationError(error) || extractMissingColumnName(error)) {
    return { status: 503, kind: 'schema' };
  }
  if (code === '23505') return { status: 409, kind: 'duplicate' };
  if (code === '23502' || code === '23503' || code === '23514' || code === '22P02') {
    return { status: 400, kind: 'validation' };
  }
  return { status: 500, kind: 'unexpected' };
}

function authRouteErrorPayload(route: string, stage: string, error: any, statusCode: number, kind: string) {
  if (process.env.NODE_ENV === 'production') {
    return { success: false, error: safeErrorMessageByStatus(statusCode) };
  }

  return cleanObject({
    success: false,
    error: extractSupabaseErrorMessage(error) || safeErrorMessageByStatus(statusCode),
    code: sanitizeString(error?.code, 40) || undefined,
    route,
    stage,
    kind,
    details: sanitizeString(error?.details, 500) || undefined,
    hint: sanitizeString(error?.hint, 500) || undefined
  });
}

function sendAuthRouteError(res: any, route: string, stage: string, error: any, context: Record<string, any> = {}) {
  const classified = classifyAuthRouteError(error);
  logRouteDbError(route, error, { ...context, stage, errorKind: classified.kind });
  return res
    .status(classified.status)
    .json(authRouteErrorPayload(route, stage, error, classified.status, classified.kind));
}

const NO_STORE_DYNAMIC_HEADERS = {
  'Cache-Control': 'no-store, no-cache, must-revalidate, private, proxy-revalidate',
  Pragma: 'no-cache',
  Expires: '0',
  'Surrogate-Control': 'no-store'
};

function applyNoStoreHeaders(res: any) {
  for (const [key, value] of Object.entries(NO_STORE_DYNAMIC_HEADERS)) {
    res.setHeader(key, value);
  }
  res.removeHeader?.('ETag');
}

function suppressEtagHeader(res: any) {
  if (!res || res.__noStoreSuppressEtag) return;
  const originalSetHeader = res.setHeader?.bind(res);
  if (!originalSetHeader) return;
  res.__noStoreSuppressEtag = true;
  res.setHeader = (name: string, value: any) => {
    if (String(name || '').toLowerCase() === 'etag') return res;
    return originalSetHeader(name, value);
  };
}

function noStoreDynamicResponse(req: any, res: any, next: any) {
  if (req.headers) {
    delete req.headers['if-none-match'];
    delete req.headers['if-modified-since'];
  }
  suppressEtagHeader(res);
  applyNoStoreHeaders(res);
  return next();
}

function isOperationalNoStorePath(value: any) {
  const pathname = String(value || '').split('?')[0].toLowerCase();
  return (
    pathname === '/api/closure/revalidate-period' ||
    pathname === '/api/closure/appointments' ||
    pathname.startsWith('/api/closure/appointments/') ||
    pathname === '/api/conference/monthly' ||
    pathname.startsWith('/api/conference/monthly/')
  );
}

function noStoreOperationalDynamicRoutes(req: any, res: any, next: any) {
  const pathname = req?.path || req?.originalUrl || req?.url || '';
  if (!isOperationalNoStorePath(pathname)) return next();
  return noStoreDynamicResponse(req, res, next);
}

function sendNoStoreJson(res: any, body: any, statusCode = 200) {
  const payload = JSON.stringify(body);
  res.statusCode = statusCode;
  applyNoStoreHeaders(res);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Length', Buffer.byteLength(payload));
  res.removeHeader?.('ETag');
  return res.end(payload);
}

function isRecoverableSessionSaveError(error: any): boolean {
  const classified = classifyAuthRouteError(error);
  if (classified.kind === 'schema') return true;

  const message = extractSupabaseErrorMessage(error).toLowerCase();
  return (
    message.includes('session') ||
    message.includes('connection') ||
    message.includes('timeout') ||
    message.includes('econn') ||
    message.includes('terminat')
  );
}

function clinicalMutationErrorPayload(route: string, stage: string, error: any, statusCode: number, kind: string) {
  if (process.env.NODE_ENV === 'production') {
    return { success: false, error: safeErrorMessageByStatus(statusCode) };
  }

  return cleanObject({
    success: false,
    error: extractSupabaseErrorMessage(error) || safeErrorMessageByStatus(statusCode),
    code: sanitizeString(error?.code, 40) || undefined,
    route,
    stage,
    kind,
    details: sanitizeString(error?.details, 500) || undefined,
    hint: sanitizeString(error?.hint, 500) || undefined
  });
}

function sendClinicalMutationError(
  res: any,
  route: string,
  stage: string,
  error: any,
  context: Record<string, any> = {}
) {
  const classified = classifyClinicalMutationError(error);
  logRouteDbError(route, error, {
    ...context,
    stage,
    errorKind: classified.kind
  });
  return res
    .status(classified.status)
    .json(clinicalMutationErrorPayload(route, stage, error, classified.status, classified.kind));
}

function requestIdForLogs(req: any): string | null {
  return sanitizeString(
    req?.headers?.['x-request-id'] ||
      req?.headers?.['x-railway-request-id'] ||
      req?.headers?.['x-correlation-id'] ||
      req?.headers?.['cf-ray'] ||
      req?.id,
    160
  ) || null;
}

const OFFICIAL_FROM_CONTACT = 'Verto <contato@appverto.com.br>';
const OFFICIAL_FROM_NOREPLY = 'Verto <naoresponda@appverto.com.br>';
const OFFICIAL_TRANSACTIONAL_REPLY_TO = 'contato@appverto.com.br';

function resolveConfiguredResendFrom(fallback: string): string {
  return sanitizeString(process.env.RESEND_FROM_EMAIL || '', 320) || fallback;
}

type ResendTemplateKind =
  | 'clinic_invitation'
  | 'welcome_professional'
  | 'welcome_patient'
  | 'password_recovery'
  | 'recovery_professional'
  | 'recovery_patient';

function resolveResendTemplateId(kind?: ResendTemplateKind): string | null {
  if (!kind) return null;
  const keysByKind: Record<ResendTemplateKind, string[]> = {
    clinic_invitation: ['RESEND_TEMPLATE_CLINIC_INVITATION_ID'],
    welcome_professional: ['RESEND_TEMPLATE_WELCOME_PROFESSIONAL_ID'],
    welcome_patient: ['RESEND_TEMPLATE_PATIENT_ACTIVATION_ID', 'RESEND_TEMPLATE_WELCOME_PATIENT_ID'],
    password_recovery: [
      'RESEND_TEMPLATE_PASSWORD_RESET_ID',
      'RESEND_TEMPLATE_RECOVERY_PROFESSIONAL_ID',
      'RESEND_TEMPLATE_RECOVERY_PATIENT_ID'
    ],
    recovery_professional: ['RESEND_TEMPLATE_RECOVERY_PROFESSIONAL_ID'],
    recovery_patient: ['RESEND_TEMPLATE_RECOVERY_PATIENT_ID']
  };
  const id = keysByKind[kind]
    .map((envKey) => sanitizeString(process.env[envKey] || '', 200))
    .find(Boolean) || '';
  if (!id && kind === 'welcome_professional') {
    return 'bem-vindo-clnica';
  }
  if (!id && kind === 'welcome_patient') return 'ativao-paciente';
  if (!id && kind === 'password_recovery') return 'password-reset';
  return id || null;
}

function resolveTemplateProfileByRole(role: unknown): 'professional' | 'patient' {
  const normalized = sanitizeString(role, 40).toLowerCase();
  return normalized === 'patient' ? 'patient' : 'professional';
}

async function generateSupabaseActionLink(params: {
  type: 'signup' | 'recovery';
  email: string;
  redirectTo: string;
}): Promise<string | null> {
  const enforceRedirectTarget = (rawLink: string, redirectTo: string): string => {
    try {
      const parsed = new URL(rawLink);
      parsed.searchParams.set('redirect_to', redirectTo);
      return parsed.toString();
    } catch {
      return rawLink;
    }
  };

  try {
    const admin = (supabase as any)?.auth?.admin;
    if (!admin?.generateLink) return null;
    const { data, error } = await admin.generateLink({
      type: params.type,
      email: params.email,
      options: { redirectTo: params.redirectTo }
    });
    if (error) throw error;
    const actionLink = sanitizeString(
      data?.properties?.action_link || data?.action_link || '',
      2000
    );
    if (!actionLink) return null;
    return enforceRedirectTarget(actionLink, params.redirectTo);
  } catch (error: any) {
    console.warn('[Auth] generate action link warning:', {
      type: params.type,
      email: maskEmail(params.email),
      message: error?.message || String(error)
    });
    return null;
  }
}

type ResendEmailDeliveryMode = 'template' | 'html' | 'html_fallback';

type ResendEmailDeliveryResult = {
  sent: boolean;
  provider: 'resend';
  providerMessageId: string | null;
  deliveryMode: ResendEmailDeliveryMode | null;
  templateId: string | null;
  templateFallbackReason: string | null;
  errorCode: string | null;
};

type TransactionalEmailParams = {
  to: string;
  subject: string;
  html: string;
  context: string;
  from?: string;
  replyTo?: string;
  templateKind?: ResendTemplateKind;
  templateData?: Record<string, unknown>;
  metadata?: Record<string, unknown>;
};

function classifyResendDeliveryError(error: any): string {
  const statusCode = Number(error?.statusCode || 0);
  const message = sanitizeString(error?.message || '', 500).toLowerCase();
  if (message.includes('resend_api_key') || message.includes('resend_from_email')) {
    return 'RESEND_CONFIGURATION_MISSING';
  }
  if (statusCode === 401 || statusCode === 403) return 'RESEND_AUTHENTICATION_FAILED';
  if (statusCode === 429) return 'RESEND_RATE_LIMITED';
  if (statusCode >= 500) return 'RESEND_UNAVAILABLE';
  if (statusCode >= 400) return 'RESEND_REQUEST_REJECTED';
  return 'RESEND_SEND_FAILED';
}

async function sendTransactionalEmailWithResultSafe(
  params: TransactionalEmailParams
): Promise<ResendEmailDeliveryResult> {
  const templateId = resolveResendTemplateId(params.templateKind);
  try {
    const result = await sendEmailViaResend({
      to: params.to,
      subject: params.subject,
      html: params.html,
      from: params.from || OFFICIAL_FROM_NOREPLY,
      replyTo: params.replyTo || OFFICIAL_TRANSACTIONAL_REPLY_TO,
      templateId,
      templateData: params.templateData
    });
    return {
      sent: true,
      provider: 'resend',
      providerMessageId: result.providerMessageId,
      deliveryMode: result.deliveryMode,
      templateId: result.templateId,
      templateFallbackReason: result.templateFallbackReason,
      errorCode: null
    };
  } catch (error: any) {
    const errorCode = classifyResendDeliveryError(error);
    console.error('[Email] transactional send failed:', {
      context: params.context,
      errorCode,
      providerStatus: Number(error?.statusCode || 0) || null,
      providerCode: sanitizeString(error?.providerCode || '', 80) || null,
      message: sanitizeString(error?.message || String(error), 500),
      metadata: redactForLogs(params.metadata || null)
    });
    return {
      sent: false,
      provider: 'resend',
      providerMessageId: null,
      deliveryMode: null,
      templateId,
      templateFallbackReason: null,
      errorCode
    };
  }
}

async function sendTransactionalEmailSafe(
  params: TransactionalEmailParams
): Promise<boolean> {
  const result = await sendTransactionalEmailWithResultSafe(params);
  return result.sent;
}

type RecoveryChannel = 'email';
type OtpPurpose = 'password_recovery' | 'phone_verification' | 'portal_login';

type OtpChallenge = {
  key: string;
  channel: RecoveryChannel;
  purpose: OtpPurpose;
  identifier: string;
  userId: string | null;
  codeHash: string;
  expiresAt: number;
  attempts: number;
  consumed: boolean;
  createdAt: number;
};

const otpStore = new Map<string, OtpChallenge>();
const activeSessionByUserId = new Map<string, string>();
let otpTableChecked = false;
let otpTableAvailable = false;

function requiresPersistentRecoveryStorage(): boolean {
  return process.env.NODE_ENV === 'production' || Boolean(process.env.RAILWAY_ENVIRONMENT);
}

function recoveryStorageUnavailableError(): Error & { code: string } {
  const error = new Error('RECOVERY_STORAGE_UNAVAILABLE') as Error & { code: string };
  error.code = 'RECOVERY_STORAGE_UNAVAILABLE';
  return error;
}

function issueSessionToken(userId: string): string {
  const safeUserId = sanitizeString(userId, 120);
  const token = crypto.randomUUID();
  if (safeUserId) {
    activeSessionByUserId.set(safeUserId, token);
  }
  return token;
}

function invalidateActiveSession(userId?: unknown, expectedToken?: unknown): void {
  const safeUserId = sanitizeString(userId, 120);
  if (!safeUserId) return;
  const safeExpectedToken = sanitizeString(expectedToken, 120);
  const current = activeSessionByUserId.get(safeUserId);
  if (!safeExpectedToken || current === safeExpectedToken) {
    activeSessionByUserId.delete(safeUserId);
  }
}

async function ensureOtpTableAvailability(): Promise<boolean> {
  if (otpTableChecked) return otpTableAvailable;
  otpTableChecked = true;
  try {
    const { error } = await supabase
      .from('otp_challenges')
      .select(OTP_CHALLENGE_SELECT)
      .limit(1);
    otpTableAvailable = !error;
    if (error) {
      console.warn('[OTP] otp_challenges indisponível, usando fallback em memória:', error.message);
    }
  } catch (error: any) {
    otpTableAvailable = false;
    console.warn('[OTP] Falha ao validar tabela otp_challenges, usando fallback em memória:', error?.message || String(error));
  }
  return otpTableAvailable;
}

function fromDbOtpRow(row: any): OtpChallenge | null {
  if (!row) return null;
  const key = sanitizeString(row.key, 200);
  if (!key) return null;
  const channel = sanitizeString(row.channel, 40) as RecoveryChannel;
  const purpose = sanitizeString(row.purpose, 60) as OtpPurpose;
  const identifier = sanitizeString(row.identifier, 320);
  const userId = sanitizeString(row.user_id, 120) || null;
  const codeHash = sanitizeString(row.code_hash, 500);
  const expiresAtIso = sanitizeString(row.expires_at, 80);
  const createdAtIso = sanitizeString(row.created_at, 80);
  const attempts = Math.max(0, Number(row.attempts || 0));
  const consumed = Boolean(row.consumed);
  const expiresAtMs = expiresAtIso ? new Date(expiresAtIso).getTime() : 0;
  const createdAtMs = createdAtIso ? new Date(createdAtIso).getTime() : Date.now();
  if (!identifier || !codeHash || !expiresAtMs) return null;
  return {
    key,
    channel: channel || 'email',
    purpose: purpose || 'password_recovery',
    identifier,
    userId,
    codeHash,
    expiresAt: expiresAtMs,
    attempts: Number.isFinite(attempts) ? attempts : 0,
    consumed,
    createdAt: Number.isFinite(createdAtMs) ? createdAtMs : Date.now()
  };
}

function getInMemoryOtpChallenge(key: string): OtpChallenge | null {
  const challenge = otpStore.get(key);
  if (!challenge) return null;
  if (Date.now() > challenge.expiresAt || challenge.consumed) {
    otpStore.delete(key);
    return null;
  }
  return challenge;
}

async function setOtpChallenge(challenge: OtpChallenge): Promise<void> {
  const normalizedChallenge: OtpChallenge = {
    ...challenge,
    key: sanitizeString(challenge.key, 200),
    identifier: sanitizeString(challenge.identifier, 320).toLowerCase(),
    userId: sanitizeString(challenge.userId, 120) || null,
    attempts: Math.max(0, Number(challenge.attempts || 0)),
    consumed: Boolean(challenge.consumed),
    createdAt: challenge.createdAt || Date.now()
  };
  otpStore.set(normalizedChallenge.key, normalizedChallenge);

  const useDb = await ensureOtpTableAvailability();
  if (!useDb) {
    if (normalizedChallenge.purpose === 'password_recovery' && requiresPersistentRecoveryStorage()) {
      otpStore.delete(normalizedChallenge.key);
      throw recoveryStorageUnavailableError();
    }
    return;
  }

  try {
    const payload = {
      key: normalizedChallenge.key,
      channel: sanitizeString(normalizedChallenge.channel, 40),
      purpose: sanitizeString(normalizedChallenge.purpose, 60),
      identifier: normalizedChallenge.identifier,
      user_id: normalizedChallenge.userId,
      code_hash: sanitizeString(normalizedChallenge.codeHash, 500),
      expires_at: new Date(normalizedChallenge.expiresAt).toISOString(),
      attempts: normalizedChallenge.attempts,
      consumed: normalizedChallenge.consumed,
      created_at: new Date(normalizedChallenge.createdAt).toISOString()
    };
    const { error } = await supabase
      .from('otp_challenges')
      .upsert(payload, { onConflict: 'key' });
    if (error) {
      console.warn('[OTP] Falha no upsert de otp_challenges, fallback memória:', error.message);
      otpTableAvailable = false;
      if (normalizedChallenge.purpose === 'password_recovery' && requiresPersistentRecoveryStorage()) {
        otpStore.delete(normalizedChallenge.key);
        throw recoveryStorageUnavailableError();
      }
    }
  } catch (error: any) {
    if (error?.code === 'RECOVERY_STORAGE_UNAVAILABLE') throw error;
    console.warn('[OTP] Exceção no upsert de otp_challenges, fallback memória:', error?.message || String(error));
    otpTableAvailable = false;
    if (normalizedChallenge.purpose === 'password_recovery' && requiresPersistentRecoveryStorage()) {
      otpStore.delete(normalizedChallenge.key);
      throw recoveryStorageUnavailableError();
    }
  }
}

async function getOtpChallenge(
  key: string,
  options: { requirePersistent?: boolean } = {}
): Promise<OtpChallenge | null> {
  const useDb = await ensureOtpTableAvailability();
  if (!useDb) {
    if (options.requirePersistent) throw recoveryStorageUnavailableError();
    return getInMemoryOtpChallenge(key);
  }

  try {
    const { data, error } = await supabase
      .from('otp_challenges')
      .select(OTP_CHALLENGE_SELECT)
      .eq('key', key)
      .maybeSingle();
    if (error || !data) {
      if (error) {
        console.warn('[OTP] Falha ao ler otp_challenges, usando fallback memória:', error.message);
        if (options.requirePersistent) throw recoveryStorageUnavailableError();
      }
      if (options.requirePersistent) return null;
      return getInMemoryOtpChallenge(key);
    }
    const challenge = fromDbOtpRow(data);
    if (!challenge) return getInMemoryOtpChallenge(key);
    if (challenge.consumed || Date.now() > challenge.expiresAt) {
      await consumeOtpChallenge(key, { requirePersistent: options.requirePersistent });
      return null;
    }
    return challenge;
  } catch (error: any) {
    if (error?.code === 'RECOVERY_STORAGE_UNAVAILABLE') throw error;
    console.warn('[OTP] Exceção ao ler otp_challenges, usando fallback memória:', error?.message || String(error));
    if (options.requirePersistent) throw recoveryStorageUnavailableError();
    return getInMemoryOtpChallenge(key);
  }
}

async function updateOtpChallengeAttempts(
  key: string,
  previousAttempts: number,
  nextAttempts: number,
  options: { requirePersistent?: boolean } = {}
): Promise<boolean> {
  const useDb = await ensureOtpTableAvailability();
  if (!useDb) {
    if (options.requirePersistent) throw recoveryStorageUnavailableError();
    const current = getInMemoryOtpChallenge(key);
    if (!current || current.attempts !== previousAttempts) return false;
    current.attempts = nextAttempts;
    otpStore.set(key, current);
    return true;
  }

  try {
    const { data, error } = await supabase
      .from('otp_challenges')
      .update({ attempts: nextAttempts })
      .eq('key', key)
      .eq('consumed', false)
      .eq('attempts', previousAttempts)
      .select('key')
      .maybeSingle();
    if (error) {
      if (options.requirePersistent) throw recoveryStorageUnavailableError();
      return false;
    }
    if (!data) return false;
    const current = otpStore.get(key);
    if (current) otpStore.set(key, { ...current, attempts: nextAttempts });
    return true;
  } catch (error: any) {
    if (error?.code === 'RECOVERY_STORAGE_UNAVAILABLE') throw error;
    console.warn('[OTP] Falha ao registrar tentativa na base:', error?.message || String(error));
    if (options.requirePersistent) throw recoveryStorageUnavailableError();
    return false;
  }
}

async function consumeOtpChallenge(
  key: string,
  options: { requirePersistent?: boolean; expectedAttempts?: number } = {}
): Promise<boolean> {
  const useDb = await ensureOtpTableAvailability();
  if (!useDb) {
    if (options.requirePersistent) throw recoveryStorageUnavailableError();
    const current = getInMemoryOtpChallenge(key);
    if (!current) return false;
    if (
      typeof options.expectedAttempts === 'number' &&
      current.attempts !== options.expectedAttempts
    ) {
      return false;
    }
    otpStore.delete(key);
    return true;
  }

  try {
    let query = supabase
      .from('otp_challenges')
      .update({ consumed: true })
      .eq('key', key)
      .eq('consumed', false);
    if (typeof options.expectedAttempts === 'number') {
      query = query.eq('attempts', options.expectedAttempts);
    }
    const { data, error } = await query.select('key').maybeSingle();
    if (error) {
      if (options.requirePersistent) throw recoveryStorageUnavailableError();
      return false;
    }
    if (!data) return false;
    otpStore.delete(key);
    return true;
  } catch (error: any) {
    if (error?.code === 'RECOVERY_STORAGE_UNAVAILABLE') throw error;
    console.warn('[OTP] Falha ao consumir OTP na base:', error?.message || String(error));
    if (options.requirePersistent) throw recoveryStorageUnavailableError();
    return false;
  }
}

function makeOtpChallengeKey(channel: RecoveryChannel, purpose: OtpPurpose, identifier: string): string {
  return hashIdentifier(`${channel}:${purpose}:${identifier.toLowerCase()}`);
}

function passwordRecoverySigningSecret(): string {
  const secret = sanitizeString(
    process.env.PASSWORD_RECOVERY_LINK_SECRET || process.env.SESSION_SECRET || '',
    2000
  );
  if (secret.length < 32) {
    throw new Error('PASSWORD_RECOVERY_LINK_SECRET_INVALID');
  }
  return secret;
}

async function createPasswordRecoveryLink(params: {
  email: string;
  userId: string;
}): Promise<{ link: string; expiresAt: number }> {
  const email = sanitizeEmail(params.email);
  const userId = sanitizeString(params.userId, 120);
  if (!email || !isUuid(userId)) {
    throw new Error('PASSWORD_RECOVERY_IDENTITY_INVALID');
  }

  const challengeKey = makeOtpChallengeKey('email', 'password_recovery', email);
  const challengeSecret = crypto.randomBytes(32).toString('base64url');
  const expiresAt = Date.now() + OTP_TTL_MS;
  await setOtpChallenge({
    key: challengeKey,
    channel: 'email',
    purpose: 'password_recovery',
    identifier: email,
    userId,
    codeHash: hashIdentifier(challengeSecret),
    expiresAt,
    attempts: 0,
    consumed: false,
    createdAt: Date.now()
  });
  const token = createPasswordRecoveryToken({
    challengeKey,
    challengeSecret,
    expiresAt,
    signingSecret: passwordRecoverySigningSecret()
  });
  return { link: getRecoveryRedirectUrl(token), expiresAt };
}

function validateStrongPassword(password: unknown): string | null {
  if (typeof password !== 'string') return null;
  if (password.length < 12 || password.length > 128) return null;
  const hasUpper = /[A-Z]/.test(password);
  const hasLower = /[a-z]/.test(password);
  const hasDigit = /\d/.test(password);
  const hasSymbol = /[^A-Za-z0-9]/.test(password);
  if (!hasUpper || !hasLower || !hasDigit || !hasSymbol) return null;
  return password;
}

function isMissingColumnError(error: any, columnName?: string): boolean {
  const code = sanitizeString(error?.code, 20);
  const message = sanitizeString(error?.message, 500).toLowerCase();
  if (code === '42703') return true;
  if (!message) return false;
  const isSchemaCacheMissing =
    message.includes('could not find the') &&
    message.includes('column') &&
    message.includes('schema cache');

  if (columnName) {
    return (
      (message.includes(columnName.toLowerCase()) && message.includes('does not exist')) ||
      (isSchemaCacheMissing && message.includes(`'${columnName.toLowerCase()}'`))
    );
  }
  return message.includes('does not exist') || isSchemaCacheMissing;
}

async function readResendResponseBody(response: Response): Promise<{
  json: Record<string, any> | null;
  raw: string;
}> {
  const raw = await response.text();
  if (!raw) return { json: null, raw: '' };
  try {
    const parsed = JSON.parse(raw);
    return {
      json: parsed && typeof parsed === 'object' ? parsed : null,
      raw
    };
  } catch {
    return { json: null, raw };
  }
}

function createResendDeliveryError(params: {
  statusCode: number;
  responseBody: { json: Record<string, any> | null; raw: string };
}): Error & { statusCode: number; providerCode: string | null } {
  const providerCode = sanitizeString(
    params.responseBody.json?.name || params.responseBody.json?.code || '',
    80
  ) || null;
  const providerMessage = sanitizeString(
    params.responseBody.json?.message || params.responseBody.raw || 'Resposta sem detalhes.',
    500
  );
  const error = new Error(
    `Falha no envio de e-mail via Resend: ${params.statusCode} ${providerMessage}`
  ) as Error & { statusCode: number; providerCode: string | null };
  error.statusCode = params.statusCode;
  error.providerCode = providerCode;
  return error;
}

async function postResendEmail(
  apiKey: string,
  payload: Record<string, any>
): Promise<Response> {
  return fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'User-Agent': 'Verto/1.0'
    },
    body: JSON.stringify(payload)
  });
}

async function sendEmailViaResend({
  to,
  subject,
  html,
  from,
  replyTo,
  templateId,
  templateData
}: {
  to: string;
  subject: string;
  html: string;
  from?: string;
  replyTo?: string;
  templateId?: string | null;
  templateData?: Record<string, unknown>;
}): Promise<{
  providerMessageId: string | null;
  deliveryMode: ResendEmailDeliveryMode;
  templateId: string | null;
  templateFallbackReason: string | null;
}> {
  const apiKey = sanitizeString(process.env.RESEND_API_KEY || '', 500);
  const defaultFrom = sanitizeString(process.env.RESEND_FROM_EMAIL || '', 320);
  const effectiveFrom = sanitizeString(from || defaultFrom, 320);
  const effectiveReplyTo = sanitizeString(replyTo || '', 320);
  if (!apiKey || !effectiveFrom) {
    throw new Error('RESEND_API_KEY e RESEND_FROM_EMAIL são obrigatórios para envio de e-mails transacionais.');
  }

  const htmlPayload: Record<string, any> = {
    from: effectiveFrom,
    to: [to],
    subject,
    html,
    ...(effectiveReplyTo ? { reply_to: [effectiveReplyTo] } : {})
  };
  const templatePayload: Record<string, any> | null = templateId
    ? {
        from: effectiveFrom,
        to: [to],
        subject,
        template: {
          id: templateId,
          variables: templateData || {}
        },
        ...(effectiveReplyTo ? { reply_to: [effectiveReplyTo] } : {})
      }
    : null;

  let deliveryMode: ResendEmailDeliveryMode = templatePayload ? 'template' : 'html';
  let templateFallbackReason: string | null = null;
  let response = await postResendEmail(apiKey, templatePayload || htmlPayload);

  if (!response.ok && templatePayload) {
    const templateFailure = await readResendResponseBody(response);
    templateFallbackReason = sanitizeString(
      templateFailure.json?.message || templateFailure.raw || `HTTP ${response.status}`,
      300
    ) || `HTTP ${response.status}`;
    console.warn('[Email] Resend template rejected; using local HTML fallback.', {
      templateId,
      providerStatus: response.status,
      providerCode: sanitizeString(
        templateFailure.json?.name || templateFailure.json?.code || '',
        80
      ) || null,
      message: templateFallbackReason
    });
    response = await postResendEmail(apiKey, htmlPayload);
    deliveryMode = 'html_fallback';
  }

  const responseBody = await readResendResponseBody(response);
  if (!response.ok) {
    throw createResendDeliveryError({
      statusCode: response.status,
      responseBody
    });
  }

  return {
    providerMessageId: sanitizeString(responseBody.json?.id || '', 200) || null,
    deliveryMode,
    templateId: templateId || null,
    templateFallbackReason
  };
}

const HTML_ESCAPE_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
  '`': '&#96;'
};

function escapeHtml(value: string): string {
  return value.replace(/[&<>"'`]/g, (char) => HTML_ESCAPE_MAP[char] || char);
}

