function sanitizeAnamnesisTemplate(input: any) {
  const safeType = (value: any) => {
    const parsed = sanitizeString(value, 40);
    return ['dissertativa', 'multipla_escolha', 'multipla_selecao', 'data', 'numero', 'telefone', 'sim_nao'].includes(parsed)
      ? parsed
      : 'dissertativa';
  };

  const sanitizeSection = (section: any, fallbackOrder: number) => cleanObject({
    id: sanitizeString(section?.id, 120) || `section_${fallbackOrder}`,
    title: sanitizeString(section?.title, 220) || `Seção ${fallbackOrder}`,
    order: Number.isFinite(Number(section?.order)) ? Number(section?.order) : fallbackOrder,
    active: section?.active !== false
  });

  const sanitizeQuestion = (question: any, fallbackOrder: number) => {
    const type = safeType(question?.type);
    const options =
      type === 'multipla_escolha' || type === 'multipla_selecao'
        ? Array.isArray(question?.options)
          ? question.options.map((option: any) => sanitizeString(option, 120)).filter(Boolean).slice(0, 30)
          : []
        : undefined;
    return cleanObject({
      id: sanitizeString(question?.id, 120) || `q_${Date.now()}_${fallbackOrder}`,
      sectionId: sanitizeString(question?.sectionId, 120),
      label: sanitizeString(question?.label, 240),
      type,
      options,
      required: question?.required === true,
      active: question?.active !== false,
      order: Number.isFinite(Number(question?.order)) ? Number(question?.order) : fallbackOrder
    });
  };

  const sanitizeProfile = (profileInput: any, profileFallback: any) => {
    const sections = (Array.isArray(profileInput?.sections) ? profileInput.sections : profileFallback.sections)
      .slice(0, 120)
      .map((section: any, index: number) => sanitizeSection(section, index + 1))
      .filter((section: any) => section.id && section.title);
    const sectionIds = new Set(sections.map((section: any) => section.id));

    const questions = (Array.isArray(profileInput?.questions) ? profileInput.questions : profileFallback.questions)
      .slice(0, 1000)
      .map((question: any, index: number) => sanitizeQuestion(question, index + 1))
      .filter((question: any) => question.id && question.sectionId && sectionIds.has(question.sectionId) && question.label);

    return {
      sections: sections.sort((a: any, b: any) => Number(a.order || 0) - Number(b.order || 0)),
      questions: questions.sort((a: any, b: any) => Number(a.order || 0) - Number(b.order || 0))
    };
  };

  const defaultTemplate = getDefaultAnamnesisTemplate();
  const legacyHidden = new Set(Array.isArray(input?.hiddenFields) ? input.hiddenFields.map((f: any) => sanitizeString(f, 120)) : []);
  const legacyDeleted = new Set(Array.isArray(input?.deletedFields) ? input.deletedFields.map((f: any) => sanitizeString(f, 120)) : []);
  const legacyCustom = Array.isArray(input?.customQuestions) ? input.customQuestions.slice(0, 300) : [];
  const looksLegacy = legacyHidden.size > 0 || legacyDeleted.size > 0 || legacyCustom.length > 0;

  const mergedInput = looksLegacy
    ? {
        ...defaultTemplate,
        profiles: {
          adult: {
            ...defaultTemplate.profiles.adult,
            questions: [
              ...defaultTemplate.profiles.adult.questions.map((question: any) => ({
                ...question,
                active: !(legacyHidden.has(question.id) || legacyDeleted.has(question.id))
              })),
              ...legacyCustom
                .filter((question: any) => ['both', 'adult', ''].includes(sanitizeString(question?.appliesTo, 20)))
                .map((question: any, index: number) => ({
                  id: sanitizeString(question?.id, 120) || `legacy_adult_${index + 1}`,
                  sectionId: 'personalizadas',
                  label: sanitizeString(question?.label, 240) || `Pergunta personalizada ${index + 1}`,
                  type: safeType(question?.type),
                  options: Array.isArray(question?.options) ? question.options : [],
                  required: question?.required === true,
                  active: question?.active !== false,
                  order: 900 + index
                }))
            ]
          },
          child: {
            ...defaultTemplate.profiles.child,
            questions: [
              ...defaultTemplate.profiles.child.questions.map((question: any) => ({
                ...question,
                active: !(legacyHidden.has(question.id) || legacyDeleted.has(question.id))
              })),
              ...legacyCustom
                .filter((question: any) => ['both', 'child', ''].includes(sanitizeString(question?.appliesTo, 20)))
                .map((question: any, index: number) => ({
                  id: sanitizeString(question?.id, 120) || `legacy_child_${index + 1}`,
                  sectionId: 'personalizadas',
                  label: sanitizeString(question?.label, 240) || `Pergunta personalizada ${index + 1}`,
                  type: safeType(question?.type),
                  options: Array.isArray(question?.options) ? question.options : [],
                  required: question?.required === true,
                  active: question?.active !== false,
                  order: 900 + index
                }))
            ]
          }
        }
      }
    : input;

  const version = Number.isFinite(Number(mergedInput?.version)) ? Math.max(1, Number(mergedInput.version)) : 1;
  const profileType = sanitizeString(mergedInput?.profileType, 20) === 'child' ? 'child' : 'adult';

  return {
    version,
    profileType,
    profiles: {
      adult: sanitizeProfile(mergedInput?.profiles?.adult, defaultTemplate.profiles.adult),
      child: sanitizeProfile(mergedInput?.profiles?.child, defaultTemplate.profiles.child)
    }
  };
}

function listAnamnesisTemplateChanges(previousTemplate: any, nextTemplate: any): string[] {
  const changes: string[] = [];
  const safePrev = sanitizeAnamnesisTemplate(previousTemplate || {});
  const safeNext = sanitizeAnamnesisTemplate(nextTemplate || {});

  (['adult', 'child'] as Array<'adult' | 'child'>).forEach((profileType) => {
    const prevProfile = safePrev.profiles?.[profileType];
    const nextProfile = safeNext.profiles?.[profileType];

    const prevSections = new Map((prevProfile?.sections || []).map((section: any) => [section.id, section]));
    const nextSections = new Map((nextProfile?.sections || []).map((section: any) => [section.id, section]));

    nextSections.forEach((section: any, sectionId: string) => {
      const prevSection = prevSections.get(sectionId);
      if (!prevSection) {
        changes.push(`[${profileType}] Seção criada: ${section.title}`);
        return;
      }
      if (prevSection.title !== section.title) {
        changes.push(`[${profileType}] Seção editada: ${prevSection.title} -> ${section.title}`);
      }
      if (prevSection.active !== section.active) {
        changes.push(`[${profileType}] Seção ${section.active ? 'reativada' : 'desativada'}: ${section.title}`);
      }
    });

    const prevQuestions = new Map((prevProfile?.questions || []).map((question: any) => [question.id, question]));
    const nextQuestions = new Map((nextProfile?.questions || []).map((question: any) => [question.id, question]));

    nextQuestions.forEach((question: any, questionId: string) => {
      const prevQuestion = prevQuestions.get(questionId);
      if (!prevQuestion) {
        changes.push(`[${profileType}] Pergunta criada: ${question.label}`);
        return;
      }
      if (prevQuestion.label !== question.label || prevQuestion.type !== question.type || prevQuestion.required !== question.required) {
        changes.push(`[${profileType}] Pergunta editada: ${question.label}`);
      }
      if (prevQuestion.active !== question.active) {
        changes.push(`[${profileType}] Pergunta ${question.active ? 'reativada' : 'desativada'}: ${question.label}`);
      }
    });
  });

  if (safePrev.version !== safeNext.version) {
    changes.push(`Publicação de versão da anamnese: v${safePrev.version} -> v${safeNext.version}`);
  }

  return Array.from(new Set(changes)).slice(0, 40);
}

function currentClinicId(user: any): string | null {
  const id = sanitizeString(
    user?.activeAccessContext?.clinicId || user?.activeWorkspaceId || user?.clinicId || user?.clinic_id,
    120
  );
  return id || null;
}

function currentClinicTimeZone(user: any): string {
  return sanitizeString(
    user?.clinicTimeZone ||
      user?.clinic_timezone ||
      user?.timezone ||
      user?.time_zone ||
      process.env.DEFAULT_CLINIC_TIMEZONE ||
      'America/Sao_Paulo',
    80
  ) || 'America/Sao_Paulo';
}

function dateGroupForClinic(value: unknown, user: any): string {
  const date = value ? new Date(String(value)) : new Date();
  const safeDate = Number.isNaN(date.getTime()) ? new Date() : date;
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: currentClinicTimeZone(user),
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  return formatter.format(safeDate);
}

function hasGlobalClinicAccess(user: any): boolean {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  return role === 'admin' || role === 'owner';
}

async function resolveEffectiveClinicRole(
  user: any
): Promise<ClinicAuthorityRole | null> {
  if (user?.activeAccessContext?.kind === 'patient_portal') return null;
  const actorId = sanitizeString(user?.id || user?.user_id, 120);
  const clinicId = sanitizeString(currentClinicId(user), 120);
  const sessionRole = sanitizeString(user?.role, 40).toLowerCase();
  if (!isUuid(actorId)) return null;

  const [globalActorResult, membershipResult] = await Promise.all([
    supabase
      .from('users')
      .select('id,role')
      .eq('id', actorId)
      .limit(1)
      .maybeSingle(),
    isUuid(clinicId)
      ? supabase
          .from('clinic_memberships')
          .select('user_id,clinic_id,role,status')
          .eq('user_id', actorId)
          .eq('clinic_id', clinicId)
          .eq('status', 'active')
          .limit(1)
          .maybeSingle()
      : Promise.resolve({ data: null, error: null })
  ]);
  if (globalActorResult.error) throw globalActorResult.error;
  if (membershipResult.error) throw membershipResult.error;

  return resolveEffectiveClinicRoleFromMembership({
    actorId,
    clinicId,
    sessionRole,
    globalRole: globalActorResult.data?.role,
    membership: membershipResult.data
  });
}

function requireActiveClinicRoles(
  ...allowedRoles: ClinicAuthorityRole[]
) {
  const allowed = new Set<ClinicAuthorityRole>(allowedRoles);
  return async (req: any, res: any, next: any) => {
    try {
      const role = await resolveEffectiveClinicRole(req.session?.user);
      if (!role || !allowed.has(role)) {
        return res.status(403).json({
          success: false,
          error: 'CLINIC_MEMBERSHIP_ROLE_DENIED',
          message: 'Seu acesso atual nesta clínica não permite esta ação.'
        });
      }
      if (
        role === 'owner' &&
        !hasVerifiedOwnerMfaSession({
          ...req.session?.user,
          role: 'owner'
        })
      ) {
        return res.status(401).json({
          success: false,
          error: 'OWNER_MFA_REQUIRED',
          message: 'Confirme o Google Authenticator para acessar esta área.'
        });
      }
      req.effectiveClinicRole = role;
      return next();
    } catch (error) {
      logRouteDbError('requireActiveClinicRoles', error, {
        clinicId: sanitizeString(currentClinicId(req.session?.user), 120),
        userId: sanitizeString(req.session?.user?.id, 120)
      });
      if (isMissingRelationError(error)) {
        return res.status(503).json({
          success: false,
          error: 'CLINIC_MEMBERSHIP_SCHEMA_UNAVAILABLE',
          message: 'A estrutura de acesso por clínica ainda não foi aplicada.'
        });
      }
      return res.status(500).json({
        success: false,
        error: 'CLINIC_MEMBERSHIP_ROLE_UNAVAILABLE',
        message: 'Não foi possível validar seu acesso nesta clínica agora.'
      });
    }
  };
}

function normalizePromptTypeKey(value: unknown): string {
  return sanitizeString(value, 160)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function buildAbaPromptTypePayload(input: any, clinicId: string, actorId?: string | null) {
  const name = sanitizeTextField(input?.name || input?.label, 120);
  const key = normalizePromptTypeKey(input?.key || name);
  const score = asSafeNumber(input?.independence_score ?? input?.independenceScore, 0, 100);
  const order = Math.max(0, Math.round(asSafeNumber(input?.intrusiveness_order ?? input?.intrusivenessOrder, 0, 1000) || 0));
  return cleanObject({
    id: isUuid(sanitizeString(input?.id || input?.prompt_type_id || input?.promptTypeId, 120))
      ? sanitizeString(input?.id || input?.prompt_type_id || input?.promptTypeId, 120)
      : crypto.randomUUID(),
    organization_id: clinicId,
    key,
    name,
    category: sanitizeTextField(input?.category, 80) || 'Geral',
    independence_score: score,
    intrusiveness_order: order,
    counts_as_independent: Boolean(input?.counts_as_independent ?? input?.countsAsIndependent),
    show_in_session: input?.show_in_session !== false && input?.showInSession !== false,
    active: input?.active !== false,
    description: sanitizeTextField(input?.description, 500),
    is_system_default: Boolean(input?.is_system_default ?? input?.isSystemDefault),
    updated_by: sanitizeString(actorId, 120) || null,
    updated_at: new Date().toISOString(),
    created_by: sanitizeString(actorId, 120) || null
  });
}

function canAccessClinicFinance(user: any): boolean {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  return role === 'coordinator' || role === 'admin' || role === 'owner';
}

const TEAM_ACCESS_PER_ACTIVE_PATIENT = 10;
const MIN_TEAM_ACCESS_LIMIT = 10;

async function getClinicTeamAccessUsage(clinicId: string) {
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!safeClinicId) {
    return {
      activePatients: 0,
      activeMembers: 0,
      pendingInvitations: 0,
      limit: MIN_TEAM_ACCESS_LIMIT,
      used: 0
    };
  }

  const [patientsResult, membersResult, invitationsResult] = await Promise.all([
    supabase
      .from('patients')
      .select('id', { count: 'exact', head: true })
      .eq('clinic_id', safeClinicId)
      .eq('is_active', true)
      .is('deleted_at', null),
    supabase
      .from('clinic_memberships')
      .select('user_id', { count: 'exact', head: true })
      .eq('clinic_id', safeClinicId)
      .eq('status', 'active')
      .in('role', ['coordinator', 'therapist', 'receptionist']),
    supabase
      .from('invitations')
      .select('id', { count: 'exact', head: true })
      .eq('clinic_id', safeClinicId)
      .eq('status', 'pending')
      .in('role', ['coordinator', 'therapist', 'receptionist'])
  ]);

  const activePatients = Math.max(0, Number(patientsResult.count || 0));
  const activeMembers = Math.max(0, Number(membersResult.count || 0));
  const pendingInvitations = Math.max(0, Number(invitationsResult.count || 0));
  const limit = Math.max(MIN_TEAM_ACCESS_LIMIT, activePatients * TEAM_ACCESS_PER_ACTIVE_PATIENT);
  return {
    activePatients,
    activeMembers,
    pendingInvitations,
    limit,
    used: activeMembers + pendingInvitations
  };
}

type PatientSchemaFallbackFilter = {
  op: 'eq' | 'is' | 'ilike';
  column: string;
  value: any;
  onMissing?: 'omit' | 'empty' | 'throw';
};

async function queryPatientsWithSchemaFallback(params: {
  selectColumns: string[] | string;
  filters?: PatientSchemaFallbackFilter[];
  limit?: number;
  context?: string;
}): Promise<any[]> {
  let selectColumns = Array.isArray(params.selectColumns)
    ? params.selectColumns.map((column) => sanitizeString(column, 120)).filter(Boolean)
    : String(params.selectColumns || '')
      .split(',')
      .map((column) => sanitizeString(column, 120))
      .filter(Boolean);
  if (selectColumns.length === 0) selectColumns = ['id'];

  let filters = (params.filters || [])
    .map((filter) => ({
      ...filter,
      column: sanitizeString(filter.column, 120),
      onMissing: filter.onMissing || 'throw'
    }))
    .filter((filter) => filter.column);

  let lastError: any = null;
  for (let attempt = 0; attempt < 20; attempt += 1) {
    let query = supabase
      .from('patients')
      .select(selectColumns.join(','));

    for (const filter of filters) {
      if (filter.op === 'eq') query = query.eq(filter.column, filter.value);
      if (filter.op === 'is') query = query.is(filter.column, filter.value);
      if (filter.op === 'ilike') query = query.ilike(filter.column, filter.value);
    }
    if (params.limit) query = query.limit(params.limit);

    const { data, error } = await query;
    if (!error) return Array.isArray(data) ? data : [];

    lastError = error;
    const missingColumn = extractMissingColumnName(error);
    if (!missingColumn) throw error;

    const filterIndex = filters.findIndex((filter) => filter.column === missingColumn);
    if (filterIndex >= 0) {
      const filter = filters[filterIndex];
      if (filter.onMissing === 'empty') return [];
      if (filter.onMissing === 'omit') {
        filters = filters.filter((_, index) => index !== filterIndex);
        console.warn('[Patients] filtro opcional removido por schema legado:', {
          context: sanitizeString(params.context, 120) || 'patients',
          missingColumn
        });
        continue;
      }
      throw error;
    }

    if (selectColumns.includes(missingColumn) && selectColumns.length > 1) {
      selectColumns = selectColumns.filter((column) => column !== missingColumn);
      console.warn('[Patients] coluna opcional removida do select por schema legado:', {
        context: sanitizeString(params.context, 120) || 'patients',
        missingColumn
      });
      continue;
    }

    throw error;
  }

  if (lastError) throw lastError;
  return [];
}

async function upsertPatientWithSchemaFallback(payload: Record<string, any>) {
  let safePayload: Record<string, any> = cleanObject({ ...payload });
  let selectColumns = PATIENT_MUTATION_SELECT
    .split(',')
    .map((column) => sanitizeString(column, 120))
    .filter(Boolean);
  let lastResult: { data: any; error: any } = { data: null, error: null };
  let triedLegacyPendingStatus = false;

  for (let attempt = 0; attempt < 30; attempt += 1) {
    const result = await supabase
      .from('patients')
      .upsert([safePayload], { onConflict: 'id' })
      .select(selectColumns.join(','))
      .single();
    lastResult = result;
    if (!result.error) return result;

    const missingColumn = extractMissingColumnName(result.error);
    if (!missingColumn) {
      const message = extractSupabaseErrorMessage(result.error).toLowerCase();
      if (
        !triedLegacyPendingStatus &&
        Object.prototype.hasOwnProperty.call(safePayload, 'status') &&
        (sanitizeString(result.error?.code, 20) === '23514' || message.includes('check constraint'))
      ) {
        triedLegacyPendingStatus = true;
        safePayload.status = 'pending';
        console.warn('[Patients] status clinico pendente adaptado para schema legado.');
        continue;
      }
      return result;
    }

    if (Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[Patients] coluna opcional removida do payload de cadastro:', { missingColumn });
      continue;
    }

    if (selectColumns.includes(missingColumn) && selectColumns.length > 1) {
      selectColumns = selectColumns.filter((column) => column !== missingColumn);
      console.warn('[Patients] coluna opcional removida do retorno de cadastro:', { missingColumn });
      continue;
    }

    return result;
  }

  return lastResult;
}

async function insertRowWithSchemaFallback(tableName: string, payload: Record<string, any>, context = tableName) {
  let safePayload: Record<string, any> = cleanObject({ ...payload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 30; attempt += 1) {
    const { error } = await supabase.from(tableName).insert([safePayload]);
    if (!error) return { success: true, data: safePayload, error: null };
    lastError = error;

    const missingColumn = extractMissingColumnName(error);
    if (missingColumn && Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[SchemaFallback] coluna opcional removida do insert:', {
        table: tableName,
        context: sanitizeString(context, 160),
        missingColumn
      });
      continue;
    }

    return { success: false, data: null, error };
  }

  return { success: false, data: null, error: lastError || new Error('Falha ao inserir registro.') };
}

async function updateRowsWithSchemaFallback(params: {
  tableName: string;
  payload: Record<string, any>;
  filters: Array<{ column: string; value: any }>;
  context?: string;
}) {
  let safePayload: Record<string, any> = cleanObject({ ...params.payload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 30; attempt += 1) {
    let query = supabase.from(params.tableName).update(safePayload);
    for (const filter of params.filters || []) {
      const column = sanitizeString(filter.column, 120);
      if (column) query = query.eq(column, filter.value);
    }

    const { error } = await query;
    if (!error) return { success: true, error: null };
    lastError = error;

    const missingColumn = extractMissingColumnName(error);
    if (missingColumn && Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[SchemaFallback] coluna opcional removida do update:', {
        table: params.tableName,
        context: sanitizeString(params.context || params.tableName, 160),
        missingColumn
      });
      continue;
    }

    return { success: false, error };
  }

  return { success: false, error: lastError || new Error('Falha ao atualizar registro.') };
}

type DemoClinicState = {
  id: string;
  name: string;
  isDemo: boolean;
  billingModel: string;
  demoStatus: string;
  demoExpiresAt: string | null;
  demoSource: string | null;
  demoTemplateId: string | null;
  demoOwnerUserId: string | null;
  demoKind: string | null;
  demoKey: string | null;
  demoLastActivityAt: string | null;
};

function isDemoExpiredAt(value: any): boolean {
  const raw = sanitizeString(value, 80);
  if (!raw) return false;
  const time = new Date(raw).getTime();
  return Number.isFinite(time) && time <= Date.now();
}

function isDemoSessionUser(user: any): boolean {
  const billingModel = sanitizeString(user?.billingModel || user?.billing_model, 40).toLowerCase();
  const activeWorkspaceId = sanitizeString(user?.activeWorkspaceId || user?.clinicId || user?.clinic_id, 120);
  const workspaces = Array.isArray(user?.workspaces) ? user.workspaces : [];
  const activeWorkspace = workspaces.find((workspace: any) => sanitizeString(workspace?.clinicId, 120) === activeWorkspaceId);
  return Boolean(
    user?.isDemoUser ||
    user?.is_demo_user ||
    billingModel === DEMO_SANDBOX_BILLING_MODEL ||
    activeWorkspace?.isDemo ||
    sanitizeString(activeWorkspace?.billingModel, 40).toLowerCase() === DEMO_SANDBOX_BILLING_MODEL
  );
}

function isExplicitDemoUser(user: any): boolean {
  const demoRole = sanitizeString(user?.demoRole || user?.demo_role, 80).toLowerCase();
  const accessMode = sanitizeString(user?.demoAccessMode || user?.demo_access_mode, 80).toLowerCase();
  return Boolean(
    user?.is_demo_user === true ||
    demoRole === 'shared_demo_coordinator' ||
    demoRole === 'prospect_demo' ||
    accessMode === 'shared_guided' ||
    accessMode === 'prospect'
  );
}

async function fetchClinicDemoState(clinicId: string | null | undefined): Promise<DemoClinicState> {
  const safeClinicId = sanitizeString(clinicId, 120);
  const fallback: DemoClinicState = {
    id: safeClinicId,
    name: '',
    isDemo: false,
    billingModel: '',
    demoStatus: 'active',
    demoExpiresAt: null,
    demoSource: null,
    demoTemplateId: null,
    demoOwnerUserId: null,
    demoKind: null,
    demoKey: null,
    demoLastActivityAt: null
  };
  if (!safeClinicId || !supabase) return fallback;

  const run = (columns: string) =>
    supabase
      .from('clinics')
      .select(columns)
      .eq('id', safeClinicId)
      .maybeSingle();

  let result = await run('id,name,is_demo,demo_status,demo_expires_at,demo_source,demo_template_id,demo_owner_user_id,demo_kind,demo_key,demo_last_activity_at,billing_model,subscription_status');
  if (result.error && extractMissingColumnName(result.error)) {
    result = await run('id,name,subscription_status');
  }
  if (result.error || !result.data) return fallback;

  const row = result.data as any;
  const billingModel = sanitizeString(row?.billing_model, 40).toLowerCase();
  const subscriptionStatus = sanitizeString(row?.subscription_status, 40).toLowerCase();
  return {
    id: sanitizeString(row?.id, 120) || safeClinicId,
    name: sanitizeString(row?.name, 180),
    isDemo: row?.is_demo === true || billingModel === DEMO_SANDBOX_BILLING_MODEL || subscriptionStatus === DEMO_SANDBOX_BILLING_MODEL,
    billingModel,
    demoStatus: sanitizeString(row?.demo_status, 40).toLowerCase() || 'active',
    demoExpiresAt: sanitizeString(row?.demo_expires_at, 80) || null,
    demoSource: sanitizeString(row?.demo_source, 40) || null,
    demoTemplateId: sanitizeString(row?.demo_template_id, 120) || null,
    demoOwnerUserId: sanitizeString(row?.demo_owner_user_id, 120) || null,
    demoKind: sanitizeString(row?.demo_kind, 40).toLowerCase() || null,
    demoKey: sanitizeString(row?.demo_key, 80) || null,
    demoLastActivityAt: sanitizeString(row?.demo_last_activity_at, 80) || null
  };
}

async function resolveDemoAccessBlock(
  user: any,
  knownState?: DemoClinicState | null
): Promise<{ blocked: boolean; status: number; error: string; message: string } | null> {
  const clinicId = currentClinicId(user);
  if (!clinicId || !isDemoSessionUser(user)) return null;
  const state = knownState || await fetchClinicDemoState(clinicId);
  if (!state.isDemo) return null;
  const expired =
    state.demoStatus === 'expired' ||
    state.demoStatus === 'archived' ||
    isDemoExpiredAt(state.demoExpiresAt) ||
    isDemoExpiredAt(user?.demoExpiresAt || user?.demo_expires_at);
  if (!expired) return null;
  return {
    blocked: true,
    status: 403,
    error: 'DEMO_SANDBOX_EXPIRED',
    message: 'Este ambiente demo expirou. Solicite reativacao para continuar.'
  };
}

const demoActivityTouchByClinicId = new Map<string, number>();

function isDemoRouteForbidden(pathname: string): boolean {
  const path = pathname.toLowerCase();
  const forbiddenPrefixes = [
    '/api/admin',
    '/api/owner',
    '/api/billing',
    '/api/payments',
    '/api/financial',
    '/api/logs',
    '/api/activity-logs',
    '/api/clinic/members',
    '/api/clinic/invite',
    '/api/clinic/invitations',
    '/api/clinic/assign-role',
    '/api/protocol-import-requests'
  ];
  return forbiddenPrefixes.some((prefix) => path === prefix || path.startsWith(`${prefix}/`)) ||
    path.includes('/export') ||
    path.includes('feature-flag') ||
    path.includes('feature_flag');
}

function trackDemoActivityAfterSuccess(req: any, res: any, clinicId: string) {
  if (req.__demoActivityTracking) return;
  req.__demoActivityTracking = true;
  res.on('finish', () => {
    if (res.statusCode < 200 || res.statusCode >= 400) return;
    const nowMs = Date.now();
    const previousTouch = demoActivityTouchByClinicId.get(clinicId) || 0;
    if (nowMs - previousTouch < 60_000) return;
    demoActivityTouchByClinicId.set(clinicId, nowMs);
    void writeDemoRowWithSchemaFallback({
      tableName: 'clinics',
      operation: 'update',
      context: 'demo_last_activity',
      filters: [{ column: 'id', value: clinicId }],
      payload: {
        demo_last_activity_at: new Date(nowMs).toISOString(),
        updated_at: new Date(nowMs).toISOString()
      }
    });
  });
}

async function resolveDemoRoutePolicyBlock(
  req: any,
  res: any,
  user: any,
  knownState?: DemoClinicState | null
): Promise<{ status: number; error: string; message: string } | null> {
  if (!isExplicitDemoUser(user)) return null;

  const pathname = sanitizeString(req.path || req.originalUrl, 240);
  const method = sanitizeString(req.method, 20).toUpperCase();
  const workspaceRecoveryRoute =
    pathname === '/api/workspaces' ||
    pathname === '/api/workspaces/select' ||
    pathname === '/api/access-contexts/select' ||
    pathname === '/api/auth/me';
  if (workspaceRecoveryRoute) return null;

  const clinicId = currentClinicId(user);
  const state = knownState || await fetchClinicDemoState(clinicId);
  if (!clinicId || !state.isDemo) {
    return {
      status: 403,
      error: 'DEMO_REAL_CLINIC_ACCESS_DENIED',
      message: 'A conta demo só pode acessar ambientes de demonstração.'
    };
  }

  if (pathname.startsWith('/api/stripe/')) {
    if (pathname === '/api/stripe/clinic-billing-summary' && method === 'GET') return null;
    void persistDemoSandboxAuditLog({
      clinicId,
      actorUserId: user?.id,
      action: 'blocked_demo_billing_attempt',
      details: { endpoint: pathname, method }
    });
    return {
      status: 403,
      error: 'DEMO_BILLING_DISABLED',
      message: 'O faturamento real fica desativado no ambiente demo.'
    };
  }

  if (isDemoRouteForbidden(pathname)) {
    if (
      pathname.startsWith('/api/billing') ||
      pathname.startsWith('/api/payments') ||
      pathname.startsWith('/api/financial')
    ) {
      void persistDemoSandboxAuditLog({
        clinicId,
        actorUserId: user?.id,
        action: 'blocked_demo_billing_attempt',
        details: { endpoint: pathname, method }
      });
    }
    return {
      status: 403,
      error: 'DEMO_RESTRICTED_OPERATION',
      message: 'Esta operação não está disponível para a conta demo.'
    };
  }

  if (method === 'DELETE') {
    return {
      status: 403,
      error: 'DEMO_PERMANENT_DELETE_DISABLED',
      message: 'Exclusões permanentes ficam desativadas no ambiente demo.'
    };
  }

  if (state.demoKind === 'presentation' && !['GET', 'HEAD', 'OPTIONS'].includes(method)) {
    return {
      status: 403,
      error: 'DEMO_PRESENTATION_READ_ONLY',
      message: 'A demo de apresentação é somente leitura. Use o Playground Demo para testes.'
    };
  }

  if (!['GET', 'HEAD', 'OPTIONS'].includes(method)) {
    trackDemoActivityAfterSuccess(req, res, clinicId);
  }
  return null;
}

async function writeDemoRowWithSchemaFallback(params: {
  tableName: string;
  payload: Record<string, any>;
  operation?: 'insert' | 'upsert' | 'update';
  onConflict?: string;
  filters?: Array<{ column: string; value: any }>;
  context?: string;
}) {
  let safePayload: Record<string, any> = cleanObject({ ...params.payload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 30 && Object.keys(safePayload).length > 0; attempt += 1) {
    let query: any;
    if (params.operation === 'update') {
      query = supabase.from(params.tableName).update(safePayload);
      for (const filter of params.filters || []) {
        const column = sanitizeString(filter.column, 120);
        if (column) query = query.eq(column, filter.value);
      }
    } else if (params.operation === 'upsert') {
      query = params.onConflict
        ? supabase.from(params.tableName).upsert([safePayload], { onConflict: params.onConflict })
        : supabase.from(params.tableName).upsert([safePayload]);
    } else {
      query = supabase.from(params.tableName).insert([safePayload]);
    }

    const { error } = await query;
    if (!error) return { success: true, data: safePayload, error: null };
    if (isMissingRelationError(error)) return { success: false, data: null, error, skipped: true };
    lastError = error;

    const missingColumn = extractMissingColumnName(error);
    if (missingColumn && Object.prototype.hasOwnProperty.call(safePayload, missingColumn)) {
      delete safePayload[missingColumn];
      console.warn('[Demo Sandbox] coluna opcional removida:', {
        table: params.tableName,
        context: sanitizeString(params.context || params.tableName, 160),
        missingColumn
      });
      continue;
    }
    return { success: false, data: null, error };
  }

  return { success: false, data: null, error: lastError || new Error('Falha ao persistir sandbox demo.') };
}

async function deleteDemoRowsByColumn(tableName: string, column: string, values: string[] | string | null | undefined) {
  const safeColumn = sanitizeString(column, 120);
  const safeValues = (Array.isArray(values) ? values : [values])
    .map((value) => sanitizeString(value, 120))
    .filter(Boolean);
  if (!safeColumn || safeValues.length === 0) return { deleted: 0, skipped: false };
  const query = safeValues.length === 1
    ? supabase.from(tableName).delete().eq(safeColumn, safeValues[0])
    : supabase.from(tableName).delete().in(safeColumn, safeValues);
  const { error } = await query;
  if (!error) return { deleted: safeValues.length, skipped: false };
  if (isMissingRelationError(error) || extractMissingColumnName(error)) return { deleted: 0, skipped: true };
  throw error;
}

async function persistDemoSandboxAuditLog(params: {
  clinicId: string;
  actorUserId?: string | null;
  action: string;
  details?: Record<string, any>;
}) {
  try {
    await writeDemoRowWithSchemaFallback({
      tableName: 'demo_sandbox_audit_logs',
      operation: 'insert',
      context: 'demo_audit',
      payload: {
        id: crypto.randomUUID(),
        clinic_id: params.clinicId,
        actor_user_id: sanitizeString(params.actorUserId, 120) || null,
        action: sanitizeString(params.action, 80),
        details: redactForLogs(params.details || {}),
        created_at: new Date().toISOString()
      }
    });
  } catch (error: any) {
    console.warn('[Demo Sandbox] Falha ao registrar auditoria demo:', sanitizeString(error?.message || String(error), 240));
  }
}

async function fetchDemoPatientIds(clinicId: string): Promise<string[]> {
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!safeClinicId) return [];
  const { data, error } = await supabase
    .from('patients')
    .select('id,is_demo')
    .eq('clinic_id', safeClinicId)
    .limit(2000);
  if (error) {
    if (isMissingRelationError(error)) return [];
    if (extractMissingColumnName(error)) {
      const fallback = await supabase
        .from('patients')
        .select('id')
        .eq('clinic_id', safeClinicId)
        .limit(2000);
      if (fallback.error) {
        if (isMissingRelationError(fallback.error) || extractMissingColumnName(fallback.error)) return [];
        throw fallback.error;
      }
      return (fallback.data || [])
        .map((row: any) => sanitizeString(row?.id, 120))
        .filter(Boolean);
    }
    throw error;
  }
  return (data || [])
    .filter((row: any) => row?.is_demo === true || String(row?.id || '').startsWith('demo-'))
    .map((row: any) => sanitizeString(row?.id, 120))
    .filter(Boolean);
}

async function removeDemoPatientStorage(clinicId: string, patientIds: string[]) {
  let removed = 0;
  for (const patientId of patientIds) {
    const prefix = `demo/${clinicId}/${patientId}`;
    const { data, error } = await supabase.storage
      .from('patient-photos')
      .list(prefix, { limit: 1000 });
    if (error) {
      if (sanitizeString(error?.message, 240).toLowerCase().includes('bucket not found')) continue;
      console.warn('[Demo Sandbox] Falha ao listar mídia demo para reset:', {
        clinicId,
        patientId,
        message: sanitizeString(error?.message || String(error), 240)
      });
      continue;
    }
    const paths = (data || [])
      .filter((item: any) => sanitizeString(item?.name, 240) && sanitizeString(item?.id, 120))
      .map((item: any) => `${prefix}/${sanitizeString(item.name, 240)}`);
    if (!paths.length) continue;
    const removal = await supabase.storage.from('patient-photos').remove(paths);
    if (!removal.error) removed += paths.length;
  }
  return removed;
}

async function resetDemoClinicData(clinicId: string) {
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!safeClinicId) throw new Error('clinic_id ausente para reset demo.');
  const patientIds = await fetchDemoPatientIds(safeClinicId);
  const storageObjectsRemoved = await removeDemoPatientStorage(safeClinicId, patientIds);

  const patientScopedTables = [
    'aba_trials',
    'aba_behavior_events',
    'aba_interval_records',
    'aba_interval_summaries',
    'aba_abc_events',
    'aba_mastery_evaluations',
    'aba_maintenance_schedules',
    'aba_maintenance_probe_results',
    'aba_session_summaries',
    'aba_sessions',
    'aba_targets',
    'patient_records',
    'patient_files',
    'notes',
    'history',
    'patient_logs',
    'tasks',
    'assigned_tasks',
    'patient_financial_plans',
    'appointments'
  ];
  for (const tableName of patientScopedTables) {
    await deleteDemoRowsByColumn(tableName, 'patient_id', patientIds);
  }

  const clinicScopedTables = [
    'clinic_payers',
    'clinic_rooms',
    'billing_sync_audit_logs'
  ];
  for (const tableName of clinicScopedTables) {
    await deleteDemoRowsByColumn(tableName, 'clinic_id', safeClinicId);
  }

  await deleteDemoRowsByColumn('patients', 'id', patientIds);
  return { patientIdsRemoved: patientIds.length, storageObjectsRemoved };
}

