async function fetchMatchingTussServiceCatalogForAppointmentTissBilling(
  organizationId: string,
  serviceType: any,
  procedureCode?: any
) {
  if (!isUuid(organizationId)) return null;
  const { data, error } = await supabase
    .from('tuss_service_catalog')
    .select(TUSS_SERVICE_CATALOG_SELECT)
    .eq('organization_id', organizationId)
    .eq('active', true)
    .order('name', { ascending: true })
    .limit(120);
  if (error) {
    if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return null;
    throw error;
  }
  const services = Array.isArray(data) ? data : [];
  const procedureKey = sanitizeString(procedureCode, 80).toLowerCase();
  if (procedureKey) {
    const byCode = services.find((service: any) => sanitizeString(service?.internal_code, 80).toLowerCase() === procedureKey);
    if (byCode) return byCode;
  }
  const serviceKey = normalizeBillingServiceMatchKey(serviceType);
  const activeMatch = services.find((service: any) => normalizeBillingServiceMatchKey(service?.service_type) === serviceKey) ||
    services.find((service: any) => normalizeBillingServiceMatchKey(service?.name) === serviceKey) ||
    null;
  if (activeMatch) return activeMatch;
  return services.find((service: any) => {
    const serviceCompositeKey = [
      service?.service_type,
      service?.name,
      service?.internal_code,
      service?.specialty
    ].map(normalizeBillingServiceMatchKey).filter(Boolean).join('_');
    return Boolean(serviceKey && serviceCompositeKey && (serviceCompositeKey.includes(serviceKey) || serviceKey.includes(serviceCompositeKey)));
  }) || null;
}

async function fetchActivePayerTussMappingForAppointmentTissBilling(
  organizationId: string,
  payerId: string,
  serviceCatalogId: string,
  appointmentDate: any
) {
  if (!isUuid(organizationId) || !isUuid(payerId) || !isUuid(serviceCatalogId)) return null;
  const { data, error } = await supabase
    .from('payer_tuss_mappings')
    .select(PAYER_TUSS_MAPPING_SELECT)
    .eq('organization_id', organizationId)
    .eq('payer_id', payerId)
    .eq('service_catalog_id', serviceCatalogId)
    .eq('active', true)
    .order('valid_from', { ascending: false, nullsFirst: false })
    .limit(20);
  if (error) {
    if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return null;
    throw error;
  }
  const date = appointmentDateKeyForAuthorization(appointmentDate);
  return (Array.isArray(data) ? data : []).find((mapping: any) => appointmentTissMappingIsValidForDate(mapping, date)) || null;
}

async function hydratePatientPayerAuthorizationsForAppointmentTissBilling(organizationId: string, rows: any[]) {
  const safeRows = Array.isArray(rows) ? rows : [];
  const payerIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.payer_id, 120)).filter((id: string) => isUuid(id))));
  const serviceIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.service_catalog_id, 120)).filter((id: string) => isUuid(id))));
  const codeIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.tuss_code_id, 120)).filter((id: string) => isUuid(id))));
  const mappingIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.payer_tuss_mapping_id, 120)).filter((id: string) => isUuid(id))));
  const [payersResult, servicesResult, codesResult, mappingsResult] = await Promise.all([
    payerIds.length > 0
      ? supabase.from('clinic_payers').select(CLINIC_PAYER_SELECT).eq('organization_id', organizationId).in('id', payerIds).limit(payerIds.length)
      : Promise.resolve({ data: [], error: null } as any),
    serviceIds.length > 0
      ? supabase.from('tuss_service_catalog').select(TUSS_SERVICE_CATALOG_SELECT).eq('organization_id', organizationId).in('id', serviceIds).limit(serviceIds.length)
      : Promise.resolve({ data: [], error: null } as any),
    codeIds.length > 0
      ? supabase.from('tuss_codes').select(TUSS_CODE_SELECT).eq('organization_id', organizationId).in('id', codeIds).limit(codeIds.length)
      : Promise.resolve({ data: [], error: null } as any),
    mappingIds.length > 0
      ? supabase.from('payer_tuss_mappings').select(PAYER_TUSS_MAPPING_SELECT).eq('organization_id', organizationId).in('id', mappingIds).limit(mappingIds.length)
      : Promise.resolve({ data: [], error: null } as any)
  ]);
  for (const result of [payersResult, servicesResult, codesResult, mappingsResult]) {
    if (result.error && !hasMissingFinancialSchema(result.error) && !isMissingRelationError(result.error)) throw result.error;
  }
  const payersById = new Map<string, any>((payersResult.error ? [] : payersResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
  const servicesById = new Map<string, any>((servicesResult.error ? [] : servicesResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
  const codesById = new Map<string, any>((codesResult.error ? [] : codesResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
  const mappingsById = new Map<string, any>((mappingsResult.error ? [] : mappingsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));

  return safeRows.map((row: any) => {
    const payer = payersById.get(sanitizeString(row?.payer_id, 120));
    const service = servicesById.get(sanitizeString(row?.service_catalog_id, 120));
    const code = codesById.get(sanitizeString(row?.tuss_code_id, 120));
    const mapping = mappingsById.get(sanitizeString(row?.payer_tuss_mapping_id, 120));
    const authorizedQuantity = Number(row?.authorized_quantity ?? 0) || 0;
    const usedQuantity = Number(row?.used_quantity ?? 0) || 0;
    return {
      id: sanitizeString(row?.id, 120),
      patientId: sanitizeString(row?.patient_id, 120),
      payerId: sanitizeString(row?.payer_id, 120),
      payerName: sanitizeString(payer?.name, 180) || null,
      authorizationNumber: sanitizeString(row?.authorization_number || row?.authorization_code, 120) || null,
      authorizationCode: sanitizeString(row?.authorization_code || row?.authorization_number, 120) || null,
      guideNumber: sanitizeString(row?.guide_number, 120) || null,
      validFrom: row?.valid_from || null,
      validUntil: row?.valid_until || null,
      authorizedQuantity,
      usedQuantity,
      serviceCatalogId: sanitizeString(row?.service_catalog_id, 120) || null,
      serviceName: sanitizeString(service?.name || row?.procedure_name_snapshot, 180) || null,
      internalCode: sanitizeString(service?.internal_code || row?.procedure_code || row?.procedure_code_snapshot, 80) || null,
      serviceType: sanitizeString(service?.service_type, 120) || null,
      tussCodeId: sanitizeString(row?.tuss_code_id, 120) || null,
      tussCode: sanitizeString(code?.code || row?.procedure_tuss_code, 80) || null,
      tussDescription: sanitizeTextField(code?.description || row?.procedure_name_snapshot, 600) || null,
      payerTussMappingId: sanitizeString(row?.payer_tuss_mapping_id, 120) || null,
      status: sanitizeString(row?.status, 40) || 'active',
      active: appointmentTissRecordIsActive(row?.active),
      createdAt: row?.created_at || null,
      updatedAt: row?.updated_at || null,
      procedureNameSnapshot: sanitizeString(row?.procedure_name_snapshot, 180) || null,
      procedureTussCode: sanitizeString(row?.procedure_tuss_code, 80) || null
    };
  });
}

type ConfirmedTissAuthorizationBalance = TissAuthorizationBalance & {
  confirmed: boolean;
  errorCode: string | null;
  preGuideCount: number;
  officialPreGuideCount: number;
};

const readTissAuthorizationIdFromBillingMetadata = (value: any) => {
  const metadata = parseStoredJsonObject(value);
  return sanitizeString(
    metadata?.patient_tiss_authorization_id ||
      metadata?.patientTissAuthorizationId ||
      metadata?.authorization_id ||
      metadata?.authorizationId ||
      metadata?.tiss_authorization?.authorizationId ||
      metadata?.tiss_authorization?.authorization_id ||
      metadata?.tissAuthorization?.authorizationId ||
      metadata?.tissAuthorization?.authorization_id,
    120
  );
};

const readTissAuthorizationIdFromPreGuideSnapshot = (value: any) => {
  const snapshot = parseStoredJsonObject(value);
  return sanitizeString(
    snapshot?.patient_tiss_authorization_id ||
      snapshot?.patientTissAuthorizationId ||
      snapshot?.authorization_id ||
      snapshot?.authorizationId ||
      snapshot?.authorization?.patientTissAuthorizationId ||
      snapshot?.authorization?.patient_tiss_authorization_id ||
      snapshot?.authorization?.authorizationId ||
      snapshot?.authorization?.authorization_id ||
      snapshot?.authorization?.id ||
      snapshot?.billingContext?.patientTissAuthorizationId ||
      snapshot?.billing_context?.patient_tiss_authorization_id,
    120
  );
};

async function fetchPatientTissAuthorizationBalances(params: {
  organizationId: string;
  authorizations: any[];
  currentAppointmentId?: any;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const currentAppointmentId = sanitizeString(params.currentAppointmentId, 120);
  const authorizationRows = (Array.isArray(params.authorizations) ? params.authorizations : [])
    .map((row: any) => ({
      row,
      authorizationId: sanitizeString(row?.id || row?.authorizationId || row?.authorization_id, 120),
      patientId: sanitizeString(row?.patientId || row?.patient_id, 120),
      authorizedQuantity: Number(row?.authorizedQuantity ?? row?.authorized_quantity ?? row?.quantityAuthorized ?? 0) || 0,
      consumedQuantity: Number(row?.usedQuantity ?? row?.used_quantity ?? row?.quantityConsumed ?? 0) || 0
    }))
    .filter((entry) => isUuid(entry.authorizationId) && isUuid(entry.patientId));
  const balances = new Map<string, ConfirmedTissAuthorizationBalance>();
  const buildUnconfirmedBalances = (errorCode: string) => {
    for (const authorization of authorizationRows) {
      balances.set(authorization.authorizationId, {
        authorized: Math.max(0, authorization.authorizedQuantity),
        consumed: Math.max(0, authorization.consumedQuantity),
        reserved: 0,
        available: null,
        futureReservations: 0,
        historicalOfficialCommitments: 0,
        currentAppointmentReserved: false,
        confirmed: false,
        errorCode,
        preGuideCount: 0,
        officialPreGuideCount: 0
      });
    }
    return balances;
  };
  if (!isUuid(organizationId) || authorizationRows.length === 0) return balances;

  const authorizationIds = new Set(authorizationRows.map((entry) => entry.authorizationId));
  const patientIds = Array.from(new Set(authorizationRows.map((entry) => entry.patientId)));
  const patientIdByAuthorizationId = new Map(
    authorizationRows.map((entry) => [entry.authorizationId, entry.patientId])
  );
  const queryLimit = Math.min(10000, Math.max(2000, patientIds.length * 250));

  try {
    const [contextResult, preGuideResult] = await Promise.all([
      supabase
        .from('appointment_billing_contexts')
        .select('appointment_id,patient_id,metadata')
        .eq('organization_id', organizationId)
        .in('patient_id', patientIds)
        .limit(queryLimit),
      supabase
        .from('appointment_tiss_pre_guides')
        .select('appointment_id,patient_id,scheduled_start,official_document_id,snapshot_data,status')
        .eq('organization_id', organizationId)
        .in('patient_id', patientIds)
        .limit(queryLimit)
    ]);
    const sourceError = contextResult.error || preGuideResult.error;
    if (sourceError) {
      console.warn('[TissAuthorizationBalance] source unavailable; balance was not assumed.', {
        organizationId,
        patientCount: patientIds.length,
        message: sanitizeString(sourceError?.message || String(sourceError), 300),
        code: sanitizeString(sourceError?.code, 80) || null
      });
      return buildUnconfirmedBalances('TISS_AUTHORIZATION_BALANCE_SOURCE_UNAVAILABLE');
    }
    if (
      (Array.isArray(contextResult.data) && contextResult.data.length >= queryLimit) ||
      (Array.isArray(preGuideResult.data) && preGuideResult.data.length >= queryLimit)
    ) {
      console.warn('[TissAuthorizationBalance] source limit reached; balance was not assumed.', {
        organizationId,
        patientCount: patientIds.length,
        queryLimit
      });
      return buildUnconfirmedBalances('TISS_AUTHORIZATION_BALANCE_SOURCE_LIMIT_REACHED');
    }

    const candidates = new Map<string, {
      appointmentId: string;
      authorizationId: string;
      hasBillingContext: boolean;
      activePreGuide: boolean;
      officialPreGuide: boolean;
      scheduledStart: string | null;
    }>();
    const reservationKey = (appointmentId: string, authorizationId: string) => `${appointmentId}:${authorizationId}`;
    for (const context of Array.isArray(contextResult.data) ? contextResult.data : []) {
      const appointmentId = sanitizeString(context?.appointment_id, 120);
      const patientId = sanitizeString(context?.patient_id, 120);
      const authorizationId = readTissAuthorizationIdFromBillingMetadata(context?.metadata);
      if (
        !isUuid(appointmentId) ||
        !authorizationIds.has(authorizationId) ||
        patientIdByAuthorizationId.get(authorizationId) !== patientId
      ) continue;
      const key = reservationKey(appointmentId, authorizationId);
      const current = candidates.get(key);
      candidates.set(key, {
        appointmentId,
        authorizationId,
        hasBillingContext: true,
        activePreGuide: Boolean(current?.activePreGuide),
        officialPreGuide: Boolean(current?.officialPreGuide),
        scheduledStart: current?.scheduledStart || null
      });
    }
    for (const preGuide of Array.isArray(preGuideResult.data) ? preGuideResult.data : []) {
      const appointmentId = sanitizeString(preGuide?.appointment_id, 120);
      const patientId = sanitizeString(preGuide?.patient_id, 120);
      const authorizationId = readTissAuthorizationIdFromPreGuideSnapshot(preGuide?.snapshot_data);
      if (
        !isUuid(appointmentId) ||
        !authorizationIds.has(authorizationId) ||
        patientIdByAuthorizationId.get(authorizationId) !== patientId
      ) continue;
      const key = reservationKey(appointmentId, authorizationId);
      const current = candidates.get(key);
      const status = sanitizeString(preGuide?.status, 80).toLowerCase();
      const activePreGuide = !['cancelled', 'canceled', 'deleted', 'refused'].includes(status);
      candidates.set(key, {
        appointmentId,
        authorizationId,
        hasBillingContext: Boolean(current?.hasBillingContext),
        activePreGuide: Boolean(current?.activePreGuide) || activePreGuide,
        officialPreGuide: Boolean(current?.officialPreGuide) || (
          activePreGuide && isUuid(sanitizeString(preGuide?.official_document_id, 120))
        ),
        scheduledStart: sanitizeString(preGuide?.scheduled_start, 80) || current?.scheduledStart || null
      });
    }

    const appointmentIds = Array.from(new Set(Array.from(candidates.values()).map((entry) => entry.appointmentId)));
    const appointmentResult = appointmentIds.length > 0
      ? await supabase
          .from('appointments')
          .select('id,status,scheduled_at,scheduled_start_at,scheduled_end_at,is_active,deleted_at')
          .or(`organization_id.eq.${organizationId},clinic_id.eq.${organizationId}`)
          .in('id', appointmentIds)
          .limit(appointmentIds.length)
      : { data: [], error: null } as any;
    if (appointmentResult.error) {
      console.warn('[TissAuthorizationBalance] appointments unavailable; balance was not assumed.', {
        organizationId,
        appointmentCount: appointmentIds.length,
        message: sanitizeString(appointmentResult.error?.message || String(appointmentResult.error), 300),
        code: sanitizeString(appointmentResult.error?.code, 80) || null
      });
      return buildUnconfirmedBalances('TISS_AUTHORIZATION_APPOINTMENTS_UNAVAILABLE');
    }

    const appointmentsById = new Map<string, any>(
      (Array.isArray(appointmentResult.data) ? appointmentResult.data : []).map((appointment: any) => [
        sanitizeString(appointment?.id, 120),
        appointment
      ])
    );
    const nowTime = Date.now();
    const today = new Date(nowTime).toISOString().slice(0, 10);
    const commitments: TissAuthorizationCommitment[] = [];
    const unconfirmedAuthorizationIds = new Set<string>();
    const preGuideCountByAuthorizationId = new Map<string, number>();
    const officialPreGuideCountByAuthorizationId = new Map<string, number>();
    for (const candidate of candidates.values()) {
      const appointment = appointmentsById.get(candidate.appointmentId);
      const scheduledStart = candidate.scheduledStart || appointment?.scheduled_start_at || appointment?.scheduled_at;
      const appointmentDate = appointmentDateKeyForAuthorization(scheduledStart);
      if (!appointmentDate || (!appointment && candidate.hasBillingContext && !candidate.scheduledStart)) {
        unconfirmedAuthorizationIds.add(candidate.authorizationId);
        continue;
      }
      const status = normalizeAppointmentStatusForUi(appointment?.status || 'pending');
      const activeAppointment = Boolean(appointment) &&
        appointment?.is_active !== false &&
        !appointment?.deleted_at &&
        !['cancelled', 'canceled', 'deleted', 'refused'].includes(status);
      const scheduledTime = Date.parse(sanitizeString(scheduledStart, 100));
      const isHistorical = Number.isFinite(scheduledTime) ? scheduledTime < nowTime : appointmentDate < today;
      const futureReservation = !isHistorical && (
        candidate.officialPreGuide ||
        candidate.activePreGuide ||
        (candidate.hasBillingContext && activeAppointment)
      );
      const historicalOfficialCommitment = isHistorical && candidate.officialPreGuide;
      commitments.push({
        appointmentId: candidate.appointmentId,
        authorizationId: candidate.authorizationId,
        futureReservation,
        historicalOfficialCommitment
      });
      if (candidate.activePreGuide || candidate.officialPreGuide) {
        preGuideCountByAuthorizationId.set(
          candidate.authorizationId,
          (preGuideCountByAuthorizationId.get(candidate.authorizationId) || 0) + 1
        );
      }
      if (candidate.officialPreGuide) {
        officialPreGuideCountByAuthorizationId.set(
          candidate.authorizationId,
          (officialPreGuideCountByAuthorizationId.get(candidate.authorizationId) || 0) + 1
        );
      }
    }

    for (const authorization of authorizationRows) {
      const balance = resolveTissAuthorizationBalance({
        authorizationId: authorization.authorizationId,
        authorizedQuantity: authorization.authorizedQuantity,
        consumedQuantity: authorization.consumedQuantity,
        commitments,
        currentAppointmentId
      });
      const confirmed = !unconfirmedAuthorizationIds.has(authorization.authorizationId);
      balances.set(authorization.authorizationId, {
        ...balance,
        available: confirmed ? balance.available : null,
        confirmed,
        errorCode: confirmed ? null : 'TISS_AUTHORIZATION_COMMITMENT_INCOMPLETE',
        preGuideCount: preGuideCountByAuthorizationId.get(authorization.authorizationId) || 0,
        officialPreGuideCount: officialPreGuideCountByAuthorizationId.get(authorization.authorizationId) || 0
      });
    }
  } catch (error: any) {
    console.warn('[TissAuthorizationBalance] resolution failed; balance was not assumed.', {
      organizationId,
      patientCount: patientIds.length,
      message: sanitizeString(error?.message || String(error), 300)
    });
    return buildUnconfirmedBalances('TISS_AUTHORIZATION_BALANCE_RESOLUTION_FAILED');
  }
  return balances;
}

async function resolveAppointmentTissAuthorizationForBilling(params: {
  organizationId: string;
  patientId: string;
  payerId?: any;
  payerName?: any;
  serviceType?: any;
  procedureCode?: any;
  appointmentDate?: any;
  authorizationId?: any;
  currentAppointmentId?: any;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const patientId = sanitizeString(params.patientId, 120);
  if (!isUuid(organizationId) || !isUuid(patientId)) return null;
  try {
    const referenceDateKey = appointmentDateKeyForAuthorization(params.appointmentDate);
    let payerId = sanitizeString(params.payerId, 120);
    const payerName = sanitizeString(params.payerName, 180);
    let payer: any = isUuid(payerId) ? await fetchPayerForAppointmentTissBilling(payerId, organizationId) : null;
    if (!payer?.id && payerName) {
      const payerResult = await supabase
        .from('clinic_payers')
        .select(CLINIC_PAYER_SELECT)
        .eq('organization_id', organizationId)
        .ilike('name', payerName)
        .limit(2);
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error) && !isMissingRelationError(payerResult.error)) throw payerResult.error;
      payer = Array.isArray(payerResult.data) && payerResult.data.length === 1 ? payerResult.data[0] : null;
      payerId = sanitizeString(payer?.id, 120);
    }
    if (!isUuid(payerId)) return null;

    const serviceType = sanitizeString(params.serviceType, 120);
    const serviceCatalog = await fetchMatchingTussServiceCatalogForAppointmentTissBilling(organizationId, serviceType, params.procedureCode);
    const mapping = serviceCatalog?.id
      ? await fetchActivePayerTussMappingForAppointmentTissBilling(organizationId, payerId, sanitizeString(serviceCatalog.id, 120), referenceDateKey)
      : null;
    const tussCode = isUuid(sanitizeString(mapping?.tuss_code_id, 120))
      ? await fetchTussCodeByIdForAppointmentTissBilling(organizationId, sanitizeString(mapping.tuss_code_id, 120))
      : null;
    if (!mapping?.id || !tussCode?.id) return null;

    let query = supabase
      .from('patient_payer_authorizations')
      .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
      .eq('organization_id', organizationId)
      .eq('patient_id', patientId)
      .eq('payer_id', payerId)
      .limit(120);
    const requestedAuthorizationId = sanitizeString(params.authorizationId, 120);
    if (isUuid(requestedAuthorizationId)) query = query.eq('id', requestedAuthorizationId);
    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return null;
      throw error;
    }
    const hydratedRows = await hydratePatientPayerAuthorizationsForAppointmentTissBilling(organizationId, Array.isArray(data) ? data : []);
    const authorizationBalances = await fetchPatientTissAuthorizationBalances({
      organizationId,
      authorizations: hydratedRows,
      currentAppointmentId: params.currentAppointmentId
    });
    const hydrated = hydratedRows.map((authorization: any) => {
      const authorizationBalance = authorizationBalances.get(sanitizeString(authorization?.id, 120));
      return {
        ...authorization,
        reservedQuantity: authorizationBalance?.confirmed ? authorizationBalance.reserved : null,
        availableQuantity: authorizationBalance?.confirmed ? authorizationBalance.available : null,
        balanceConfirmed: authorizationBalance?.confirmed === true,
        balanceErrorCode: authorizationBalance?.errorCode || null,
        currentAppointmentReserved: authorizationBalance?.currentAppointmentReserved === true
      };
    });
    const enriched = hydrated.map((authorization: any) => ({
      ...authorization,
      serviceType: authorization?.serviceType || serviceType
    }));
    const suggested = findSuggestedTissAuthorizationForAppointment({
      payerId,
      payerName: payer?.name || payerName,
      serviceType,
      serviceCatalogId: sanitizeString(serviceCatalog?.id, 120),
      payerTussMappingId: sanitizeString(mapping?.id, 120),
      tussCodeId: sanitizeString(tussCode?.id, 120),
      tussCode: sanitizeString(tussCode?.code, 80),
      appointmentDate: referenceDateKey
    }, enriched);
    return serializeAppointmentTissAuthorizationSuggestion(suggested, referenceDateKey);
  } catch (error: any) {
    console.warn('[AppointmentTissAuthorization] resolver failed.', {
      organizationId,
      patientId,
      message: error?.message || String(error)
    });
    return null;
  }
}

async function listAppointmentTissAuthorizationOptionsForBilling(params: {
  organizationId: string;
  patientId: string;
  payerId?: any;
  payerName?: any;
  serviceType?: any;
  procedureCode?: any;
  appointmentDate?: any;
  currentAppointmentId?: any;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const patientId = sanitizeString(params.patientId, 120);
  if (!isUuid(organizationId) || !isUuid(patientId)) return [];
  try {
    const referenceDateKey = appointmentDateKeyForAuthorization(params.appointmentDate);
    let payerId = sanitizeString(params.payerId, 120);
    const payerName = sanitizeString(params.payerName, 180);
    let payer: any = isUuid(payerId) ? await fetchPayerForAppointmentTissBilling(payerId, organizationId) : null;
    if (!payer?.id && payerName) {
      const payerResult = await supabase
        .from('clinic_payers')
        .select(CLINIC_PAYER_SELECT)
        .eq('organization_id', organizationId)
        .ilike('name', payerName)
        .limit(2);
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error) && !isMissingRelationError(payerResult.error)) throw payerResult.error;
      payer = Array.isArray(payerResult.data) && payerResult.data.length === 1 ? payerResult.data[0] : null;
      payerId = sanitizeString(payer?.id, 120);
    }
    if (!isUuid(payerId)) return [];

    const serviceType = sanitizeString(params.serviceType, 120);
    const serviceCatalog = await fetchMatchingTussServiceCatalogForAppointmentTissBilling(organizationId, serviceType, params.procedureCode);
    const mapping = serviceCatalog?.id
      ? await fetchActivePayerTussMappingForAppointmentTissBilling(organizationId, payerId, sanitizeString(serviceCatalog.id, 120), referenceDateKey)
      : null;

    const { data, error } = await supabase
      .from('patient_payer_authorizations')
      .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
      .eq('organization_id', organizationId)
      .eq('patient_id', patientId)
      .eq('payer_id', payerId)
      .limit(120);
    if (error) {
      if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return [];
      throw error;
    }
    const hydratedRows = await hydratePatientPayerAuthorizationsForAppointmentTissBilling(organizationId, Array.isArray(data) ? data : []);
    const authorizationBalances = await fetchPatientTissAuthorizationBalances({
      organizationId,
      authorizations: hydratedRows,
      currentAppointmentId: params.currentAppointmentId
    });
    const hydrated = hydratedRows.map((authorization: any) => {
      const authorizationBalance = authorizationBalances.get(sanitizeString(authorization?.id, 120));
      return {
        ...authorization,
        reservedQuantity: authorizationBalance?.confirmed ? authorizationBalance.reserved : null,
        availableQuantity: authorizationBalance?.confirmed ? authorizationBalance.available : null,
        balanceConfirmed: authorizationBalance?.confirmed === true,
        balanceErrorCode: authorizationBalance?.errorCode || null,
        currentAppointmentReserved: authorizationBalance?.currentAppointmentReserved === true
      };
    });
    const expectedServiceCatalogId = sanitizeString(serviceCatalog?.id, 120);
    const expectedMappingId = sanitizeString(mapping?.id, 120);
    const expectedTussCodeId = sanitizeString(mapping?.tuss_code_id || mapping?.tussCodeId, 120);
    const expectedTussCodeRow = isUuid(expectedTussCodeId)
      ? await fetchTussCodeByIdForAppointmentTissBilling(organizationId, expectedTussCodeId)
      : null;
    const mappingMetadata = mapping?.metadata && typeof mapping.metadata === 'object' && !Array.isArray(mapping.metadata) ? mapping.metadata : {};
    const expectedTussCode = sanitizeString(
      mapping?.authorized_code ||
        mapping?.authorizedCode ||
        mappingMetadata.authorized_code ||
        mappingMetadata.authorizedCode ||
        expectedTussCodeRow?.code ||
        mapping?.tussCode ||
        mapping?.procedure_tuss_code,
      80
    ).toUpperCase();
    const serializedOptions = hydrated.map((authorization: any) => {
      const serialized = serializeAppointmentTissAuthorizationSuggestion(authorization, referenceDateKey);
      if (!serialized) return null;
      const active = authorization?.active !== false && ![
        'inactive',
        'inativo',
        'cancelled',
        'canceled',
        'cancelada',
        'archived',
        'arquivada',
        'substituted',
        'substituida',
        'closed',
        'encerrada'
      ].includes(sanitizeString(authorization?.status, 40).toLowerCase());
      const authorizationServiceCatalogId = sanitizeString(authorization?.serviceCatalogId, 120);
      const authorizationMappingId = sanitizeString(authorization?.payerTussMappingId, 120);
      const authorizationTussCodeId = sanitizeString(authorization?.tussCodeId, 120);
      const authorizationTussCode = sanitizeString(authorization?.tussCode || authorization?.procedureTussCode, 80).toUpperCase();
      const sameService = !expectedServiceCatalogId || !authorizationServiceCatalogId || authorizationServiceCatalogId === expectedServiceCatalogId;
      const sameMapping = !expectedMappingId || !authorizationMappingId || authorizationMappingId === expectedMappingId;
      const sameTussCode =
        (!expectedTussCodeId && !expectedTussCode) ||
        (!authorizationTussCodeId && !authorizationTussCode) ||
        (expectedTussCodeId && authorizationTussCodeId === expectedTussCodeId) ||
        (expectedTussCode && authorizationTussCode === expectedTussCode);
      const dateStatus = getPatientTissAuthorizationVisualState(authorization, referenceDateKey);
      let availabilityGroup = 'usable';
      let availabilityLabel = 'Vigente e utilizavel';
      let unavailableReason = '';
      if (!active) {
        availabilityGroup = 'inactive';
        availabilityLabel = 'Inativa';
        unavailableReason = 'Autorizacao inativa no cadastro.';
      } else if (!serialized.balanceConfirmed) {
        availabilityGroup = 'balance_unconfirmed';
        availabilityLabel = 'Saldo nao confirmado';
        unavailableReason = 'Nao foi possivel confirmar o saldo desta autorizacao. Atualize os dados antes de aplica-la.';
      } else if (!dateStatus.isCurrent) {
        const validFrom = sanitizeString(authorization?.validFrom || authorization?.valid_from, 40).slice(0, 10);
        availabilityGroup = validFrom && referenceDateKey < validFrom ? 'future' : 'expired';
        availabilityLabel = availabilityGroup === 'future' ? 'Futura' : 'Vencida';
        unavailableReason = availabilityGroup === 'future'
          ? 'Autorizacao ainda nao vigente na data da sessão.'
          : 'Autorizacao vencida para a data da sessão.';
      } else if (
        serialized.balance !== null &&
        serialized.balance <= 0 &&
        serialized.currentAppointmentReserved !== true
      ) {
        availabilityGroup = 'no_balance';
        availabilityLabel = 'Sem saldo';
        unavailableReason = 'Autorizacao sem saldo disponivel para esta sessão.';
      } else if (!sameService || !sameMapping || !sameTussCode) {
        availabilityGroup = 'other_service';
        availabilityLabel = 'Outro servico/procedimento';
        unavailableReason = 'Autorizacao pertence a outro servico, procedimento, TUSS ou De/Para.';
      }
      return cleanObject({
        ...serialized,
        availabilityGroup,
        availabilityLabel,
        unavailableReason,
        canUseForAppointment: availabilityGroup === 'usable',
        isEligibleForAppointment: availabilityGroup === 'usable'
      });
    }).filter(Boolean);
    return dedupePatientTissAuthorizationSelectionOptions(serializedOptions);
  } catch (error: any) {
    console.warn('[AppointmentTissAuthorization] options failed.', {
      organizationId,
      patientId,
      message: error?.message || String(error)
    });
    return [];
  }
}

async function resolveAppointmentBillingSuggestion(params: {
  organizationId: string;
  patientId: string;
  serviceType?: string | null;
  payerId?: string | null;
  payerName?: string | null;
  appointmentDate?: string | null;
  procedureCode?: string | null;
  currentAppointmentId?: string | null;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const patientId = sanitizeString(params.patientId, 120);
  if (!isUuid(organizationId) || !isUuid(patientId)) return null;
  const serviceType = sanitizeString(params.serviceType, 120);
  const requestedPayerId = sanitizeString(params.payerId, 120);
  const requestedPayerName = sanitizeString(params.payerName, 180);
  const appointmentDate = sanitizeString(params.appointmentDate, 80) || new Date().toISOString();
  const procedureCode = sanitizeString(params.procedureCode, 80);

  const planResult = await supabase
    .from('patient_financial_plans')
    .select(PATIENT_FINANCIAL_PLAN_SELECT)
    .eq('organization_id', organizationId)
    .eq('patient_id', patientId)
    .eq('status', 'ACTIVE')
    .eq('billing_mode', 'INSURANCE')
    .limit(20);
  if (planResult.error && !hasMissingFinancialSchema(planResult.error)) throw planResult.error;
  const plans = planResult.error ? [] : Array.isArray(planResult.data) ? planResult.data : [];
  const patientResult = await supabase
    .from('patients')
    .select('id, insurance_type, insurance_name, insurance_card_number, insurance_card_valid_until, insurance_plan_category, insurance_holder_name')
    .eq('id', patientId)
    .eq('clinic_id', organizationId)
    .limit(1)
    .maybeSingle();
  if (patientResult.error) {
    if (!hasMissingFinancialSchema(patientResult.error)) throw patientResult.error;
  }
  const patientBillingRow = patientResult.error ? null : patientResult.data;
  const patientInsuranceName = sanitizeString(patientBillingRow?.insurance_name, 180);
  const patientInsuranceCardNumber = sanitizeString(patientBillingRow?.insurance_card_number, 120);
  const patientInsurancePlanName = sanitizeString(patientBillingRow?.insurance_plan_category, 160);
  const patientInsuranceHolderName = sanitizeString(patientBillingRow?.insurance_holder_name, 160);
  const patientInsuranceCardValidUntil = sanitizeIsoDateOnly(patientBillingRow?.insurance_card_valid_until);
  const normalizePayerFallbackKey = (value: any) =>
    sanitizeString(value, 180)
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim()
      .toLowerCase()
      .replace(/\s+/g, ' ');
  const patientInsuranceFallbackMatches = (payerName?: any) => {
    const patientKey = normalizePayerFallbackKey(patientInsuranceName);
    const payerKey = normalizePayerFallbackKey(payerName);
    return !patientKey || !payerKey || patientKey === payerKey;
  };
  const patientInsuranceCardForPayer = (payerName?: any) =>
    patientInsuranceFallbackMatches(payerName) ? patientInsuranceCardNumber : '';
  const patientInsurancePlanForPayer = (payerName?: any) =>
    patientInsuranceFallbackMatches(payerName) ? patientInsurancePlanName : '';
  const patientInsuranceHolderForPayer = (payerName?: any) =>
    patientInsuranceFallbackMatches(payerName) ? patientInsuranceHolderName : '';
  const patientInsuranceValidityForPayer = (payerName?: any) =>
    patientInsuranceFallbackMatches(payerName) ? patientInsuranceCardValidUntil : '';
  const usablePlans = plans.filter((plan: any) =>
    isUuid(sanitizeString(plan?.payer_id, 120)) || Boolean(sanitizeString(plan?.payer_name_snapshot, 180))
  );
  const payerScopedPlans = isUuid(requestedPayerId)
    ? usablePlans.filter((plan: any) => sanitizeString(plan?.payer_id, 120) === requestedPayerId)
    : requestedPayerName
      ? usablePlans.filter((plan: any) => sanitizeString(plan?.payer_name_snapshot, 180).toLowerCase() === requestedPayerName.toLowerCase())
      : usablePlans;
  const matchingPlans = serviceType
    ? payerScopedPlans.filter((plan: any) => financialPlanMatchesAppointmentService(plan, serviceType))
    : [];
  const selectedPlan =
    matchingPlans.length === 1
      ? matchingPlans[0]
      : !serviceType && payerScopedPlans.length === 1
        ? payerScopedPlans[0]
        : null;
  const attachTissAuthorization = async (suggestion: any) => {
    const availableTissAuthorizations = await listAppointmentTissAuthorizationOptionsForBilling({
      organizationId,
      patientId,
      payerId: suggestion?.payerId || requestedPayerId,
      payerName: suggestion?.payerName || requestedPayerName,
      serviceType: suggestion?.serviceType || serviceType,
      procedureCode,
      appointmentDate,
      currentAppointmentId: params.currentAppointmentId
    });
    const usableTissAuthorizations = availableTissAuthorizations.filter((authorization: any) => Boolean(authorization?.canUseForAppointment || authorization?.isEligibleForAppointment));
    const unavailableTissAuthorizations = availableTissAuthorizations.filter((authorization: any) =>
      !Boolean(authorization?.canUseForAppointment || authorization?.isEligibleForAppointment) &&
        appointmentTissAuthorizationIsRecentHistory(authorization, appointmentDateKeyForAuthorization(appointmentDate), 60)
    );
    const tissAuthorization = availableTissAuthorizations.find((authorization: any) => authorization?.canUseForAppointment) ||
      await resolveAppointmentTissAuthorizationForBilling({
        organizationId,
        patientId,
        payerId: suggestion?.payerId || requestedPayerId,
        payerName: suggestion?.payerName || requestedPayerName,
        serviceType: suggestion?.serviceType || serviceType,
        procedureCode,
        appointmentDate,
        currentAppointmentId: params.currentAppointmentId
      });
    const suggestionWithOptions = {
      ...suggestion,
      availableTissAuthorizations: usableTissAuthorizations,
      available_tiss_authorizations: usableTissAuthorizations,
      unavailableTissAuthorizations,
      unavailable_tiss_authorizations: unavailableTissAuthorizations,
      allTissAuthorizations: availableTissAuthorizations,
      all_tiss_authorizations: availableTissAuthorizations
    };
    if (!tissAuthorization?.authorizationId) return suggestionWithOptions;
    return {
      ...suggestionWithOptions,
      authorizationCode: tissAuthorization.authorizationCode || suggestion?.authorizationCode || null,
      guideNumber: tissAuthorization.guideNumber || suggestion?.guideNumber || null,
      patientTissAuthorizationId: tissAuthorization.authorizationId,
      tissAuthorization,
      source: 'PATIENT_TISS_AUTHORIZATION'
    };
  };
  if (selectedPlan) {
    let payerName = sanitizeString(selectedPlan.payer_name_snapshot, 180);
    const payerId = sanitizeString(selectedPlan.payer_id, 120);
    if (!payerName && isUuid(payerId)) {
      const payerResult = await supabase
        .from('clinic_payers')
        .select('id, name')
        .eq('organization_id', organizationId)
        .eq('id', payerId)
        .limit(1)
        .maybeSingle();
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
      payerName = sanitizeString(payerResult.data?.name, 180);
    }
    return attachTissAuthorization({
      payerId: isUuid(payerId) ? payerId : null,
      payerName: payerName || null,
      serviceType: sanitizeString(selectedPlan.service_type || serviceType, 120) || null,
      insuranceCardNumber: patientInsuranceCardForPayer(payerName) || null,
      insurancePlanName: sanitizeString(selectedPlan.insurance_plan_name, 160) || patientInsurancePlanForPayer(payerName) || null,
      insuranceHolderName: patientInsuranceHolderForPayer(payerName) || null,
      insuranceCardValidUntil: patientInsuranceValidityForPayer(payerName) || null,
      authorizationCode: sanitizeString(selectedPlan.authorization_code, 120) || null,
      guideNumber: null,
      notes: sanitizeTextField(selectedPlan.notes, 1200) || null,
      source: 'PATIENT_DEFAULT'
    });
  }

  if (isUuid(requestedPayerId) || requestedPayerName) {
    let payerName = requestedPayerName;
    if (!payerName && isUuid(requestedPayerId)) {
      const payerResult = await supabase
        .from('clinic_payers')
        .select('id, name')
        .eq('organization_id', organizationId)
        .eq('id', requestedPayerId)
        .limit(1)
        .maybeSingle();
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
      payerName = sanitizeString(payerResult.data?.name, 180);
    }
    return attachTissAuthorization({
      payerId: isUuid(requestedPayerId) ? requestedPayerId : null,
      payerName: payerName || null,
      serviceType: serviceType || null,
      insuranceCardNumber: patientInsuranceCardForPayer(payerName) || null,
      insurancePlanName: patientInsurancePlanForPayer(payerName) || null,
      insuranceHolderName: patientInsuranceHolderForPayer(payerName) || null,
      insuranceCardValidUntil: patientInsuranceValidityForPayer(payerName) || null,
      authorizationCode: null,
      guideNumber: null,
      notes: null,
      source: 'PATIENT_DEFAULT'
    });
  }

  const insuranceName = sanitizeString(patientBillingRow?.insurance_name, 180);
  const insuranceType = sanitizeString(patientBillingRow?.insurance_type, 80)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
  if (!insuranceName || insuranceType === 'particular' || insuranceType === 'private') return null;
  const payerResult = await supabase
    .from('clinic_payers')
    .select('id, name')
    .eq('organization_id', organizationId)
    .ilike('name', insuranceName)
    .limit(2);
  if (payerResult.error && !hasMissingFinancialSchema(payerResult.error)) throw payerResult.error;
  const matchingPayer = Array.isArray(payerResult.data) && payerResult.data.length === 1 ? payerResult.data[0] : null;
  return attachTissAuthorization({
    payerId: isUuid(sanitizeString(matchingPayer?.id, 120)) ? sanitizeString(matchingPayer.id, 120) : null,
    payerName: sanitizeString(matchingPayer?.name || insuranceName, 180) || null,
    serviceType: serviceType || null,
    insuranceCardNumber: patientInsuranceCardNumber || null,
    insurancePlanName: patientInsurancePlanName || null,
    insuranceHolderName: patientInsuranceHolderName || null,
    insuranceCardValidUntil: patientInsuranceCardValidUntil || null,
    authorizationCode: null,
    guideNumber: null,
    notes: null,
    source: 'PATIENT_DEFAULT'
  });
}

async function upsertInitialBillingContextFromAppointment(params: {
  organizationId: string;
  appointmentId: string;
  patientId: string;
  appointment: any;
  overwriteExplicit?: boolean;
}) {
  let requiresAtomicAuthorizationReservation = false;
  try {
    const organizationId = sanitizeString(params.organizationId, 120);
    const appointmentId = sanitizeString(params.appointmentId, 120);
    const patientId = sanitizeString(params.patientId, 120);
    if (!isUuid(organizationId) || !isUuid(appointmentId) || !isUuid(patientId)) return;
    const appointmentPayload = mergeAppointmentBillingPayload(params.appointment);
    const explicitFinancialContextType = readAppointmentFinancialContextType(appointmentPayload);
    const requestedTissAuthorizationId = sanitizeString(
      appointmentPayload?.patientTissAuthorizationId ||
        appointmentPayload?.patient_tiss_authorization_id ||
        appointmentPayload?.authorizationId ||
        appointmentPayload?.authorization_id,
      120
    );
    requiresAtomicAuthorizationReservation = Boolean(requestedTissAuthorizationId);
    if (requestedTissAuthorizationId && !isUuid(requestedTissAuthorizationId)) {
      throw new Error('TISS_AUTHORIZATION_ID_INVALID');
    }
    const existing = await supabase
      .from('appointment_billing_contexts')
      .select('id, created_at, metadata')
      .eq('organization_id', organizationId)
      .eq('appointment_id', appointmentId)
      .limit(1)
      .maybeSingle();
    if (existing.error) {
      if (hasMissingFinancialSchema(existing.error) || isMissingRelationError(existing.error) || extractMissingColumnName(existing.error)) return;
      throw existing.error;
    }
    if (
      existing.data?.id &&
      !requestedTissAuthorizationId &&
      (!params.overwriteExplicit || !explicitFinancialContextType)
    ) return;
    const rawPayerId = explicitFinancialContextType === 'INSURANCE'
      ? sanitizeString(appointmentPayload?.payerId || appointmentPayload?.payer_id, 120)
      : '';
    let payer: any = null;
    if (isUuid(rawPayerId)) {
      const payerResult = await supabase
        .from('clinic_payers')
        .select('id, name')
        .eq('organization_id', organizationId)
        .eq('id', rawPayerId)
        .limit(1)
        .maybeSingle();
      if (payerResult.error && !hasMissingFinancialSchema(payerResult.error) && !isMissingRelationError(payerResult.error)) throw payerResult.error;
      payer = payerResult.data || null;
    }
    const serviceType = sanitizeString(
      appointmentPayload?.service_type ||
        appointmentPayload?.serviceType ||
        appointmentPayload?.approach ||
        appointmentPayload?.type,
      120
    );
    let payerName = explicitFinancialContextType === 'INSURANCE'
      ? sanitizeString(
          payer?.name ||
            appointmentPayload?.payerName ||
            appointmentPayload?.payer_name_snapshot ||
            appointmentPayload?.payerNameSnapshot,
          180
        )
      : '';
    let suggestedBilling: any = null;
    if (!explicitFinancialContextType && !payer?.id && !payerName) {
      suggestedBilling = await resolveAppointmentBillingSuggestion({
        organizationId,
        patientId,
        serviceType
      });
      const suggestedPayerId = sanitizeString(suggestedBilling?.payerId || suggestedBilling?.payer_id, 120);
      if (isUuid(suggestedPayerId)) {
        const suggestedPayerResult = await supabase
          .from('clinic_payers')
          .select('id, name')
          .eq('organization_id', organizationId)
          .eq('id', suggestedPayerId)
          .limit(1)
          .maybeSingle();
        if (suggestedPayerResult.error && !hasMissingFinancialSchema(suggestedPayerResult.error) && !isMissingRelationError(suggestedPayerResult.error)) throw suggestedPayerResult.error;
        payer = suggestedPayerResult.data || null;
      }
      payerName = sanitizeString(payer?.name || suggestedBilling?.payerName || suggestedBilling?.payer_name_snapshot, 180);
    }
    const financialContextType =
      explicitFinancialContextType ||
      (payer?.id ? 'INSURANCE' : null) ||
      normalizeAppointmentFinancialContextType(suggestedBilling?.payerType || suggestedBilling?.payer_type);
    if (financialContextType === 'INSURANCE' && (payer?.id || payerName) && !suggestedBilling) {
      suggestedBilling = await resolveAppointmentBillingSuggestion({
        organizationId,
        patientId,
        serviceType,
        payerId: sanitizeString(payer?.id || rawPayerId, 120),
        payerName,
        appointmentDate: appointmentPayload?.scheduled_start_at || appointmentPayload?.scheduled_at || appointmentPayload?.date,
        procedureCode: appointmentPayload?.procedureCode || appointmentPayload?.procedure_code,
        currentAppointmentId: appointmentId
      });
    }
    const authorizationOptions = Array.isArray(suggestedBilling?.allTissAuthorizations)
      ? suggestedBilling.allTissAuthorizations
      : Array.isArray(suggestedBilling?.all_tiss_authorizations)
        ? suggestedBilling.all_tiss_authorizations
        : [];
    const selectedTissAuthorization = requestedTissAuthorizationId
      ? authorizationOptions.find((authorization: any) =>
          sanitizeString(authorization?.authorizationId || authorization?.patientTissAuthorizationId, 120) === requestedTissAuthorizationId
        ) || (
          sanitizeString(
            suggestedBilling?.tissAuthorization?.authorizationId ||
              suggestedBilling?.tissAuthorization?.patientTissAuthorizationId,
            120
          ) === requestedTissAuthorizationId
            ? suggestedBilling.tissAuthorization
            : null
        )
      : null;
    if (
      requestedTissAuthorizationId &&
      (!selectedTissAuthorization?.authorizationId ||
        (!selectedTissAuthorization?.canUseForAppointment && !selectedTissAuthorization?.isEligibleForAppointment))
    ) {
      throw new Error(
        selectedTissAuthorization?.availabilityGroup === 'no_balance'
          ? 'TISS_AUTHORIZATION_NO_AVAILABLE_BALANCE'
          : 'TISS_AUTHORIZATION_NOT_AVAILABLE'
      );
    }
    const existingTissAuthorizationId = sanitizeString(
      existing.data?.metadata?.patient_tiss_authorization_id ||
        existing.data?.metadata?.patientTissAuthorizationId ||
        existing.data?.metadata?.tiss_authorization?.authorizationId ||
        existing.data?.metadata?.tissAuthorization?.authorizationId,
      120
    );
    const payload = cleanObject({
      id: existing.data?.id || crypto.randomUUID(),
      organization_id: organizationId,
      appointment_id: appointmentId,
      patient_id: patientId,
      payer_id: payer?.id || null,
      payer_type: financialContextType || null,
      payer_name_snapshot: payerName || null,
      service_type: serviceType || sanitizeString(suggestedBilling?.serviceType || suggestedBilling?.service_type, 120) || null,
      insurance_card_number: sanitizeString(appointmentPayload?.insuranceCardNumber || appointmentPayload?.insurance_card_number || appointmentPayload?.cardNumber || appointmentPayload?.card_number || suggestedBilling?.insuranceCardNumber || suggestedBilling?.insurance_card_number, 120) || null,
      insurance_plan_name: sanitizeString(appointmentPayload?.insurancePlanName || appointmentPayload?.insurance_plan_name || suggestedBilling?.insurancePlanName || suggestedBilling?.insurance_plan_name, 160) || null,
      authorization_code: sanitizeString(appointmentPayload?.authorizationCode || appointmentPayload?.authorization_code || selectedTissAuthorization?.authorizationCode, 120) || null,
      guide_number: sanitizeString(appointmentPayload?.guideNumber || appointmentPayload?.guide_number || selectedTissAuthorization?.guideNumber, 120) || null,
      procedure_code: sanitizeString(appointmentPayload?.procedureCode || appointmentPayload?.procedure_code || selectedTissAuthorization?.tussCode || selectedTissAuthorization?.procedureCode, 80) || null,
      notes: sanitizeTextField(appointmentPayload?.billingNotes || appointmentPayload?.billing_notes || suggestedBilling?.notes, 1200) || null,
      source: sanitizeString(
        selectedTissAuthorization?.authorizationId
          ? 'PATIENT_TISS_AUTHORIZATION'
          : explicitFinancialContextType
            ? 'APPOINTMENT_CONTEXT'
          : suggestedBilling?.source || (suggestedBilling ? 'PATIENT_DEFAULT' : 'MANUAL'),
        60
      ) || null,
      metadata: sanitizeClinicalPayload(cleanObject({
        financialContextType: financialContextType || undefined,
        explicitFinancialContext: Boolean(explicitFinancialContextType),
        skipTussResolution: financialContextSkipsInsuranceBilling(financialContextType),
        insurance_holder_name: sanitizeString(appointmentPayload?.insuranceHolderName || appointmentPayload?.insurance_holder_name || suggestedBilling?.insuranceHolderName, 160) || undefined,
        insurance_card_valid_until: sanitizeIsoDateOnly(appointmentPayload?.insuranceCardValidUntil || appointmentPayload?.insurance_card_valid_until || suggestedBilling?.insuranceCardValidUntil) || undefined,
        clinic_timezone: sanitizeString(appointmentPayload?.clinicTimezone || appointmentPayload?.clinic_timezone, 80) || 'America/Sao_Paulo',
        expected_previous_authorization_id: isUuid(existingTissAuthorizationId) ? existingTissAuthorizationId : undefined,
        patient_tiss_authorization_id: selectedTissAuthorization?.authorizationId || undefined,
        tiss_authorization: selectedTissAuthorization || undefined
      })),
      created_at: existing.data?.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString()
    });
    const hasContextValue = Boolean(
      payload.payer_type ||
        payload.payer_id ||
        payload.payer_name_snapshot ||
        payload.authorization_code ||
        payload.guide_number ||
        payload.insurance_card_number ||
        payload.insurance_plan_name ||
        payload.procedure_code ||
        payload.notes
    );
    if (!hasContextValue) return;
    if (selectedTissAuthorization?.authorizationId) {
      const reservationResult = await supabase.rpc('reserve_tiss_authorization_billing_context', {
        p_organization_id: organizationId,
        p_appointment_id: appointmentId,
        p_patient_id: patientId,
        p_authorization_id: selectedTissAuthorization.authorizationId,
        p_context: payload
      });
      if (reservationResult.error) throw reservationResult.error;
      const reservationEnvelope = parseStoredJsonObject(reservationResult.data);
      const persistedReservationContext = parseStoredJsonObject(reservationEnvelope?.billing_context);
      if (!persistedReservationContext?.id) throw new Error('TISS_AUTHORIZATION_RESERVATION_SCHEMA_UNAVAILABLE');
      return;
    }
    const upsertResult = await supabase
      .from('appointment_billing_contexts')
      .upsert([payload], { onConflict: 'organization_id,appointment_id' });
    if (upsertResult.error && extractMissingColumnName(upsertResult.error)) {
      const legacyPayload = { ...payload };
      delete legacyPayload.payer_type;
      delete legacyPayload.insurance_card_number;
      delete legacyPayload.insurance_plan_name;
      delete legacyPayload.source;
      delete legacyPayload.metadata;
      delete legacyPayload.created_by;
      delete legacyPayload.updated_by;
      const legacyResult = await supabase
        .from('appointment_billing_contexts')
        .upsert([cleanObject(legacyPayload)], { onConflict: 'organization_id,appointment_id' });
      if (legacyResult.error && !hasMissingFinancialSchema(legacyResult.error) && !isMissingRelationError(legacyResult.error)) throw legacyResult.error;
      return;
    }
    if (upsertResult.error && !hasMissingFinancialSchema(upsertResult.error) && !isMissingRelationError(upsertResult.error)) throw upsertResult.error;
  } catch (error: any) {
    console.warn('[Appointments] Contexto financeiro inicial ignorado.', {
      appointmentId: sanitizeString(params.appointmentId, 120) || null,
      message: sanitizeString(error?.message || String(error), 240)
    });
    if (requiresAtomicAuthorizationReservation) throw error;
  }
}

async function syncAppointmentsTableFromClinicState(params: {
  clinicId: string | null;
  appointments: any[];
  actorId: string;
  specialtySettings?: Record<string, any>;
}) {
  const clinicId = sanitizeString(params.clinicId, 120);
  const actorId = sanitizeString(params.actorId, 120);
  if (!isUuid(clinicId) || !Array.isArray(params.appointments)) return { mirrored: 0, skipped: 0 };

  let mirrored = 0;
  let skipped = 0;
  const appointmentIds = Array.from(
    new Set(
      params.appointments
        .map((appointment: any) => sanitizeString(appointment?.id, 120))
        .filter((id: string) => isUuid(id))
    )
  );
  const existingById = new Map<string, any>();
  if (appointmentIds.length > 0) {
    const { data: existingRows, error: existingError } = await supabase
      .from('appointments')
      .select('id, scheduled_at, scheduled_start_at, status, patient_response, patient_responded_at, patient_confirmation_status, patient_confirmation_at, patient_confirmation_by, patient_confirmation_source, notification_24h_sent_at, notification_12h_sent_at, notification_sent, notification_sent_at, notification_12h_sent')
      .in('id', appointmentIds);
    if (!existingError) {
      for (const row of existingRows || []) {
        existingById.set(sanitizeString(row?.id, 120), row);
      }
    }
  }
  const requestedPatientIds = Array.from(
    new Set(
      params.appointments
        .map((appointment: any) => readAppointmentPatientId(appointment))
        .filter((id: string) => isUuid(id))
    )
  ).slice(0, 1000);
  const patientNamesById = new Map<string, string>();
  const patientResponsibleNamesById = new Map<string, string>();
  if (requestedPatientIds.length > 0) {
    let patientNamesResult = await supabase
      .from('patients')
      .select('id, name, responsible_name, metadata')
      .eq('clinic_id', clinicId)
      .in('id', requestedPatientIds)
      .limit(requestedPatientIds.length);
    if (patientNamesResult.error && extractMissingColumnName(patientNamesResult.error) === 'metadata') {
      patientNamesResult = await supabase
        .from('patients')
        .select('id, name, responsible_name')
        .eq('clinic_id', clinicId)
        .in('id', requestedPatientIds)
        .limit(requestedPatientIds.length);
    }
    if (patientNamesResult.error && extractMissingColumnName(patientNamesResult.error) === 'responsible_name') {
      patientNamesResult = await supabase
        .from('patients')
        .select('id, name, metadata')
        .eq('clinic_id', clinicId)
        .in('id', requestedPatientIds)
        .limit(requestedPatientIds.length);
    }
    if (
      patientNamesResult.error &&
      ['metadata', 'responsible_name'].includes(String(extractMissingColumnName(patientNamesResult.error) || ''))
    ) {
      patientNamesResult = await supabase
        .from('patients')
        .select('id, name')
        .eq('clinic_id', clinicId)
        .in('id', requestedPatientIds)
        .limit(requestedPatientIds.length);
    }
    const { data: patientRows, error: patientNamesError } = patientNamesResult;
    if (!patientNamesError) {
      for (const row of patientRows || []) {
        const id = sanitizeString(row?.id, 120);
        const name = sanitizeString(row?.name, 180);
        if (isUuid(id) && !isGenericAppointmentPatientLabel(name)) patientNamesById.set(id, name);
        const metadata = parseStoredJsonObject(row?.metadata);
        const responsibleName = sanitizeString(
          row?.responsible_name ||
            metadata?.guardian?.nome ||
            metadata?.guardian?.name ||
            metadata?.responsible?.nome ||
            metadata?.responsible?.name ||
            metadata?.responsavelNome,
          180
        );
        if (isUuid(id) && responsibleName) patientResponsibleNamesById.set(id, responsibleName);
      }
    } else if (!hasMissingFinancialSchema(patientNamesError)) {
      console.warn('[Appointments] Nomes de pacientes indisponíveis ao espelhar agenda.', patientNamesError.message);
    }
  }
  const hasOwn = (source: any, key: string) =>
    Object.prototype.hasOwnProperty.call(source || {}, key);
  const hasAnyOwn = (source: any, keys: string[]) =>
    keys.some((key) => hasOwn(source, key));
  const firstOwnValue = (source: any, keys: string[]) => {
    for (const key of keys) {
      if (hasOwn(source, key)) return source?.[key];
    }
    return undefined;
  };

  for (const appointment of params.appointments) {
    const appointmentId = sanitizeString(appointment?.id, 120);
    const scheduledAt = buildAppointmentScheduledAt(appointment);
    const rawPatientId = sanitizeString(appointment?.patientId || appointment?.patient_id, 120);
    const patientEmail = sanitizeEmail(appointment?.patientEmail || appointment?.patient_email);
    const resolvedPatientIds = await resolvePatientIdsForPush({
      supabase,
      patientId: rawPatientId,
      patientEmail,
      clinicId
    });
    const patientId = resolvedPatientIds[0] || '';

    if (!isUuid(appointmentId) || !scheduledAt || !isUuid(patientId)) {
      skipped += 1;
      continue;
    }

    const therapistIdCandidates = [
      appointment?.therapistId,
      appointment?.therapist_id,
      appointment?.professionalId,
      appointment?.professional_id
    ];
    const therapistId = therapistIdCandidates
      .map((value) => sanitizeString(value, 120))
      .find((value) => isUuid(value));
    if (!therapistId) {
      skipped += 1;
      continue;
    }

    const approach = sanitizeString(appointment?.type || appointment?.approach, 120);
    const configuredDuration = Number(params.specialtySettings?.[approach]);
    const duration = Number(
      appointment?.duration_minutes ||
      appointment?.durationMinutes ||
      appointment?.scheduled_duration_minutes ||
      appointment?.scheduledDurationMinutes ||
      configuredDuration ||
      50
    );
    const safeDuration = Number.isFinite(duration) && duration > 0 ? Math.round(duration) : 50;
    const scheduledEndAt = new Date(new Date(scheduledAt).getTime() + safeDuration * 60 * 1000).toISOString();
    const roomId = sanitizeString(
      appointment?.room_id || appointment?.roomId || appointment?.room,
      180
    );
    const roomName = sanitizeString(
      appointment?.room_name || appointment?.roomName || appointment?.roomDisplayName,
      180
    );
    const locationType = roomId
      ? 'clinica'
      : normalizeScheduleLocationType(
          appointment?.location_type ||
            appointment?.locationType ||
            appointment?.location ||
            'outro'
        );
    const careSetting = normalizeCareSetting(
      appointment?.care_setting || appointment?.careSetting,
      locationType
    );
    const professionalIds = Array.from(
      new Set(
        [
          therapistId,
          appointment?.professionalId,
          appointment?.professional_id,
          ...(Array.isArray(appointment?.professionalIds) ? appointment.professionalIds : []),
          ...(Array.isArray(appointment?.professional_ids) ? appointment.professional_ids : []),
          ...(Array.isArray(appointment?.teamProfessionalIds) ? appointment.teamProfessionalIds : []),
          ...(Array.isArray(appointment?.team_professional_ids) ? appointment.team_professional_ids : [])
        ]
          .map((value) => sanitizeString(value, 120))
          .filter((value) => isUuid(value))
      )
    );
    const statusForTable = normalizeAppointmentStatusForTable(appointment?.status);
    const patientResponse =
      sanitizeString(appointment?.patient_response || appointment?.patientResponse, 40) ||
      (
        ['confirmed', 'reschedule', 'cancelled', 'canceled'].includes(normalizeAppointmentStatusForUi(appointment?.status))
          ? normalizeAppointmentStatusForUi(appointment?.status)
          : null
      );
    const existing = existingById.get(appointmentId) || {};
    const previousScheduledAt = buildAppointmentScheduledAt(existing);
    const scheduleChanged = Boolean(previousScheduledAt && scheduledAt && previousScheduledAt !== scheduledAt);
    const hasIncomingPatientResponse = hasAnyOwn(appointment, [
      'patient_response',
      'patientResponse',
      'patientConfirmationStatus',
      'patient_confirmation_status',
      'patientRespondedAt',
      'patient_responded_at',
      'patientConfirmationAt',
      'patient_confirmation_at'
    ]) || Boolean(patientResponse);
    const existingResponseStatus =
      normalizeAppointmentResponseAction(existing.patient_response || existing.patient_confirmation_status) ||
      normalizeAppointmentStatusForUi(existing.status);
    const incomingUiStatus = normalizeAppointmentStatusForUi(appointment?.status);
    const shouldPreserveExistingResponseStatus =
      !hasIncomingPatientResponse &&
      ['confirmed', 'reschedule', 'canceled'].includes(existingResponseStatus) &&
      (incomingUiStatus === 'pending' || incomingUiStatus === 'scheduled');
    const effectiveStatusForTable = shouldPreserveExistingResponseStatus
      ? normalizeAppointmentStatusForTable(existingResponseStatus)
      : statusForTable;
    const resolvedPatientResponse = hasIncomingPatientResponse
      ? (patientResponse === 'canceled' ? 'cancelled' : patientResponse)
      : (existing.patient_response || null);
    const resolvedPatientRespondedAt = hasIncomingPatientResponse
      ? (appointment?.patient_responded_at || appointment?.patientRespondedAt || appointment?.patientConfirmationAt || null)
      : (existing.patient_responded_at || null);
    const resolvedPatientConfirmationStatus = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationStatus || appointment?.patient_confirmation_status || patientResponse || null)
      : (existing.patient_confirmation_status || null);
    const resolvedPatientConfirmationAt = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationAt || appointment?.patient_confirmation_at || appointment?.patient_responded_at || null)
      : (existing.patient_confirmation_at || null);
    const resolvedPatientConfirmationBy = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationBy || appointment?.patient_confirmation_by || null)
      : (existing.patient_confirmation_by || null);
    const resolvedPatientConfirmationSource = hasIncomingPatientResponse
      ? (appointment?.patientConfirmationSource || appointment?.patient_confirmation_source || null)
      : (existing.patient_confirmation_source || null);
    const hasIncoming24hMarker = scheduleChanged || hasAnyOwn(appointment, [
      'notification_24h_sent_at',
      'notification24hSentAt',
      'notification_sent_at',
      'notification_sent'
    ]);
    const incoming24hSentAt = firstOwnValue(appointment, [
      'notification_24h_sent_at',
      'notification24hSentAt',
      'notification_sent_at'
    ]);
    const resolved24hSentAt = scheduleChanged
      ? null
      : hasIncoming24hMarker
      ? (incoming24hSentAt || null)
      : (existing.notification_24h_sent_at || existing.notification_sent_at || null);
    const resolvedNotificationSent = scheduleChanged
      ? false
      : hasIncoming24hMarker
      ? (hasOwn(appointment, 'notification_sent') ? Boolean(appointment.notification_sent) : Boolean(resolved24hSentAt))
      : Boolean(existing.notification_sent || existing.notification_24h_sent_at || existing.notification_sent_at);
    const hasIncoming12hMarker = scheduleChanged || hasAnyOwn(appointment, [
      'notification_12h_sent_at',
      'notification12hSentAt',
      'notification_12h_sent'
    ]);
    const incoming12hSentAt = firstOwnValue(appointment, [
      'notification_12h_sent_at',
      'notification12hSentAt'
    ]);
    const resolved12hSentAt = scheduleChanged
      ? null
      : hasIncoming12hMarker
      ? (incoming12hSentAt || null)
      : (existing.notification_12h_sent_at || null);
    const resolvedNotification12hSent = scheduleChanged
      ? false
      : hasIncoming12hMarker
      ? (hasOwn(appointment, 'notification_12h_sent') ? Boolean(appointment.notification_12h_sent) : Boolean(resolved12hSentAt))
      : Boolean(existing.notification_12h_sent || existing.notification_12h_sent_at);
    const resolvedPatientName = pickAppointmentPatientName([
      patientNamesById.get(patientId),
      appointment?.patientName,
      appointment?.patient_name,
      appointment?.name
    ]);
    const resolvedFamilyResponsibleName = sanitizeString(
      appointment?.familyResponsibleName ||
        appointment?.family_responsible_name ||
        appointment?.guardianName ||
        appointment?.guardian_name ||
        appointment?.responsibleName ||
        appointment?.responsible_name ||
        patientResponsibleNamesById.get(patientId),
      180
    ) || null;

    const row = {
      id: appointmentId,
      organization_id: isUuid(sanitizeString(appointment?.organization_id || appointment?.organizationId, 120))
        ? sanitizeString(appointment?.organization_id || appointment?.organizationId, 120)
        : clinicId,
      clinic_id: clinicId,
      patient_id: patientId,
      therapist_id: therapistId,
      scheduled_at: scheduledAt,
      scheduled_start_at: appointment?.scheduled_start_at || appointment?.scheduledStartAt || scheduledAt,
      scheduled_end_at: appointment?.scheduled_end_at || appointment?.scheduledEndAt || scheduledEndAt,
      scheduled_duration_minutes: safeDuration,
      actual_start_at: appointment?.actual_start_at || appointment?.actualStartAt || appointment?.actual_start || appointment?.actualStart || null,
      actual_end_at: appointment?.actual_end_at || appointment?.actualEndAt || appointment?.actual_end || appointment?.actualEnd || null,
      actual_duration_minutes:
        Number.isFinite(Number(appointment?.actual_duration_minutes ?? appointment?.actualDurationMinutes))
          ? Math.max(0, Math.round(Number(appointment?.actual_duration_minutes ?? appointment?.actualDurationMinutes)))
          : null,
      duration_minutes: safeDuration,
      status: effectiveStatusForTable,
      notes: sanitizeString(appointment?.notes || appointment?.note, 2000) || null,
      patient_response: resolvedPatientResponse,
      patient_responded_at: resolvedPatientRespondedAt,
      notification_24h_sent_at: resolved24hSentAt,
      notification_12h_sent_at: resolved12hSentAt,
      notification_sent: resolvedNotificationSent,
      notification_sent_at: resolved24hSentAt,
      notification_12h_sent: resolvedNotification12hSent,
      patient_confirmation_status: resolvedPatientConfirmationStatus,
      patient_confirmation_at: resolvedPatientConfirmationAt,
      patient_confirmation_by: resolvedPatientConfirmationBy,
      patient_confirmation_source: resolvedPatientConfirmationSource,
      patient_email: patientEmail || null,
      patient_name: resolvedPatientName || null,
      therapist_name: sanitizeString(appointment?.therapistName || appointment?.professional || appointment?.therapist_name, 180) || null,
      approach,
      service_type: sanitizeString(appointment?.service_type || appointment?.serviceType || approach, 120) || null,
      room_id: roomId || null,
      room_name: roomName || (roomId && !isUuid(roomId) ? roomId : null),
      location_type: locationType,
      care_setting: careSetting,
      school_id: isUuid(sanitizeString(appointment?.school_id || appointment?.schoolId, 120))
        ? sanitizeString(appointment?.school_id || appointment?.schoolId, 120)
        : null,
      school_unit_id: isUuid(sanitizeString(appointment?.school_unit_id || appointment?.schoolUnitId, 120))
        ? sanitizeString(appointment?.school_unit_id || appointment?.schoolUnitId, 120)
        : null,
      location_snapshot: parseStoredJsonObject(appointment?.location_snapshot || appointment?.locationSnapshot),
      location_name_snapshot: sanitizeString(appointment?.location_name_snapshot || appointment?.locationNameSnapshot, 240) || null,
      location_address_snapshot: sanitizeString(appointment?.location_address_snapshot || appointment?.locationAddressSnapshot, 1000) || null,
      location_source: sanitizeString(appointment?.location_source || appointment?.locationSource, 60) || null,
      location_timezone: sanitizeString(appointment?.location_timezone || appointment?.locationTimezone, 80) || 'America/Sao_Paulo',
      location_notes: sanitizeString(appointment?.location_notes || appointment?.locationNotes || appointment?.addressNote, 1000) || null,
      call_link: sanitizeString(appointment?.call_link || appointment?.callLink, 500) || null,
      financial_event_actor_id: isUuid(actorId) ? actorId : null,
      financial_event_reason: sanitizeString(
        appointment?.privatePricingReason ||
          appointment?.private_pricing_reason ||
          appointment?.financialEventReason ||
          appointment?.financial_event_reason,
        1200
      ) || null,
      recurrence_group_id: sanitizeString(appointment?.recurrenceGroupId || appointment?.recurrence_group_id, 120) || null,
      recurrence_index: Number.isFinite(Number(appointment?.recurrenceIndex ?? appointment?.recurrence_index))
        ? Math.max(0, Math.round(Number(appointment?.recurrenceIndex ?? appointment?.recurrence_index)))
        : null,
      recurrence_total: Number.isFinite(Number(appointment?.recurrenceTotal ?? appointment?.recurrence_total))
        ? Math.max(1, Math.round(Number(appointment?.recurrenceTotal ?? appointment?.recurrence_total)))
        : null,
      recurrence_frequency: sanitizeString(appointment?.recurrenceFrequency || appointment?.recurrence_frequency, 60) || null,
      source_payload: {
        ...appointment,
        patientName: resolvedPatientName || appointment?.patientName || appointment?.patient_name || appointment?.name || null,
        patient_name: resolvedPatientName || appointment?.patient_name || appointment?.patientName || appointment?.name || null,
        name: resolvedPatientName || appointment?.name || appointment?.patientName || appointment?.patient_name || null,
        familyResponsibleName: resolvedFamilyResponsibleName,
        family_responsible_name: resolvedFamilyResponsibleName,
        guardianName: resolvedFamilyResponsibleName,
        guardian_name: resolvedFamilyResponsibleName,
        professionalIds,
        professional_ids: professionalIds,
        room_id: roomId || appointment?.room_id || appointment?.roomId || null,
        roomName: roomName || appointment?.roomName || null,
        locationType,
        location_type: locationType,
        careSetting,
        care_setting: careSetting,
        schoolId: appointment?.school_id || appointment?.schoolId || null,
        school_id: appointment?.school_id || appointment?.schoolId || null,
        schoolUnitId: appointment?.school_unit_id || appointment?.schoolUnitId || null,
        school_unit_id: appointment?.school_unit_id || appointment?.schoolUnitId || null,
        locationSnapshot: appointment?.location_snapshot || appointment?.locationSnapshot || {},
        location_snapshot: appointment?.location_snapshot || appointment?.locationSnapshot || {},
        locationNameSnapshot: appointment?.location_name_snapshot || appointment?.locationNameSnapshot || null,
        location_name_snapshot: appointment?.location_name_snapshot || appointment?.locationNameSnapshot || null,
        locationAddressSnapshot: appointment?.location_address_snapshot || appointment?.locationAddressSnapshot || null,
        location_address_snapshot: appointment?.location_address_snapshot || appointment?.locationAddressSnapshot || null,
        durationMinutes: safeDuration,
        duration_minutes: safeDuration,
        scheduled_end_at: appointment?.scheduled_end_at || appointment?.scheduledEndAt || scheduledEndAt
      },
      is_active: !['cancelled', 'canceled', 'deleted'].includes(effectiveStatusForTable),
      updated_at: new Date().toISOString()
    };

    const ok = await upsertAppointmentMirrorRow(row);
    if (ok) {
      mirrored += 1;
      await syncAppointmentProfessionalsMirrorRows({
        appointmentId,
        organizationId: row.organization_id,
        clinicId,
        professionalIds,
        professionalName: row.therapist_name
      });
      await upsertInitialBillingContextFromAppointment({
        organizationId: row.organization_id,
        appointmentId,
        patientId,
        appointment
      });
      try {
        await flagPendingMaintenanceProbesForAppointment({
          appointmentId,
          organizationId: row.organization_id,
          clinicId,
          patientId,
          scheduledAt,
          actorId
        });
      } catch (error: any) {
        console.warn('[Appointments] Sugestao de Maintenance Probe ignorada ao criar sessão.', {
          appointmentId,
          message: sanitizeString(error?.message || String(error), 240)
        });
      }
    } else skipped += 1;
  }

  return { mirrored, skipped };
}

async function ensureAppointmentMirrorForBillingContext(params: {
  organizationId: string;
  appointment: any;
  user: any;
}) {
  const organizationId = sanitizeString(params.organizationId, 120);
  const appointmentId = sanitizeString(params.appointment?.id || params.appointment?.appointment_id, 120);
  if (!isUuid(organizationId) || !isUuid(appointmentId)) return false;

  const existingResult = await supabase
    .from('appointments')
    .select('id')
    .eq('id', appointmentId)
    .limit(1)
    .maybeSingle();
  if (!existingResult.error && existingResult.data?.id) return true;
  if (existingResult.error && !hasMissingFinancialSchema(existingResult.error)) {
    const missingColumn = extractMissingColumnName(existingResult.error);
    if (!missingColumn) throw existingResult.error;
  }
  return false;
}

async function syncClinicRoomsTableFromClinicState(params: {
  clinicId: string | null;
  rooms: any[];
  organizationId?: string | null;
}) {
  const clinicId = sanitizeString(params.clinicId, 120);
  const organizationId = sanitizeString(params.organizationId || clinicId, 120);
  if (!isUuid(clinicId) || !Array.isArray(params.rooms)) return { mirrored: 0, skipped: 0 };
  let mirrored = 0;
  let skipped = 0;
  for (const room of params.rooms.slice(0, 400)) {
    const roomId = sanitizeString(room?.id, 180);
    const name = sanitizeString(room?.name, 180);
    if (!isUuid(roomId) || !name) {
      skipped += 1;
      continue;
    }
    const payload = cleanObject({
      id: roomId,
      organization_id: isUuid(organizationId) ? organizationId : clinicId,
      clinic_id: clinicId,
      name,
      specialties: normalizeClinicRoomSpecialties(room?.specialties || room?.specialty),
      description: sanitizeString(room?.description, 1000) || null,
      capacity: Number.isFinite(Number(room?.capacity)) ? Math.max(0, Math.round(Number(room.capacity))) : null,
      is_active: room?.is_active !== false && room?.isActive !== false,
      updated_at: new Date().toISOString()
    });
    const { error } = await supabase
      .from('clinic_rooms')
      .upsert([payload], { onConflict: 'id' });
    if (!error) mirrored += 1;
    else {
      if (hasMissingFinancialSchema(error)) return { mirrored, skipped: skipped + 1 };
      skipped += 1;
      console.warn('[Rooms] Falha ao espelhar sala da clínica.', { roomId, message: error.message });
    }
  }
  return { mirrored, skipped };
}

function normalizeClinicRoomSpecialties(value: any) {
  if (Array.isArray(value)) {
    return value.map((item) => sanitizeString(item, 120)).filter(Boolean).slice(0, 12).join(', ') || null;
  }
  return sanitizeString(value, 1000) || null;
}

async function fetchUserWorkspaces(userId: string) {
  const run = (clinicColumns: string, includeMembershipSettings = true) =>
    supabase
      .from('clinic_memberships')
      .select(`
      clinic_id,
      role,
      status,
      ${includeMembershipSettings ? 'specialty,' : ''}
      clinics:clinic_id (
        ${clinicColumns}
      )
    `)
      .eq('user_id', userId)
      .eq('status', 'active');

  let { data, error } = await run('id,name,logo_url,is_demo,demo_status,demo_expires_at,demo_source,demo_kind,demo_key,demo_last_activity_at,billing_model');
  if (error && extractMissingColumnName(error)) {
    const fallback = await run('id,name,logo_url', false);
    data = fallback.data;
    error = fallback.error;
  }

  if (error) {
    return [];
  }

  return (data || []).map((membership: any) => {
    const clinic = membership.clinics || {};
    return {
      clinicId: sanitizeString(clinic.id || membership.clinic_id, 120),
      clinicName: sanitizeString(clinic.name, 160) || 'Clinica',
      clinicLogoUrl: sanitizeSessionUrl(clinic.logo_url),
      role: ensureRole(membership.role) ? membership.role : 'therapist',
      specialty: normalizeClinicalSpecialty(membership.specialty) || null,
      isDemo: clinic?.is_demo === true || sanitizeString(clinic?.billing_model, 40).toLowerCase() === DEMO_SANDBOX_BILLING_MODEL,
      demoStatus: sanitizeString(clinic?.demo_status, 40).toLowerCase() || null,
      demoExpiresAt: sanitizeString(clinic?.demo_expires_at, 80) || null,
      demoSource: sanitizeString(clinic?.demo_source, 40) || null,
      demoKind: sanitizeString(clinic?.demo_kind, 40).toLowerCase() || null,
      demoKey: sanitizeString(clinic?.demo_key, 80) || null,
      demoLastActivityAt: sanitizeString(clinic?.demo_last_activity_at, 80) || null,
      billingModel: sanitizeString(clinic?.billing_model, 40).toLowerCase() || null
    };
  }).filter((w: any) => w.clinicId);
}

type AccessContextKind = 'clinic_workspace' | 'patient_portal';

type UserAccessContext = {
  id: string;
  kind: AccessContextKind;
  clinicId: string;
  clinicName: string;
  clinicLogoUrl: string | null;
  role: AppRole;
  label: string;
  patientId: string | null;
  specialty: string | null;
};

function clinicAccessContextId(clinicId: unknown): string {
  return `clinic:${sanitizeString(clinicId, 120)}`;
}

function patientAccessContextId(patientId: unknown, clinicId: unknown): string {
  return `patient:${sanitizeString(patientId, 120)}:${sanitizeString(clinicId, 120)}`;
}

function compactAccessContextsForSession(value: any): UserAccessContext[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  return value.slice(0, 60).map((item: any): UserAccessContext | null => {
    const kind: AccessContextKind | null = item?.kind === 'patient_portal'
      ? 'patient_portal'
      : item?.kind === 'clinic_workspace'
        ? 'clinic_workspace'
        : null;
    const clinicId = sanitizeString(item?.clinicId, 120);
    const patientId = kind === 'patient_portal' ? sanitizeString(item?.patientId, 120) : '';
    const id = sanitizeString(
      item?.id || (kind === 'patient_portal'
        ? patientAccessContextId(patientId, clinicId)
        : clinicAccessContextId(clinicId)),
      380
    );
    if (!kind || !id || !isUuid(clinicId) || (kind === 'patient_portal' && !isUuid(patientId)) || seen.has(id)) {
      return null;
    }
    seen.add(id);
    const resolvedRole = kind === 'patient_portal'
      ? 'patient'
      : ensureRole(item?.role) && item.role !== 'patient'
        ? item.role
        : 'therapist';
    return {
      id,
      kind,
      clinicId,
      clinicName: sanitizeString(item?.clinicName, 160) || 'Clínica',
      clinicLogoUrl: sanitizeSessionUrl(item?.clinicLogoUrl),
      role: resolvedRole,
      label: sanitizeString(item?.label, 180) || (kind === 'patient_portal' ? 'Meu cuidado' : 'Trabalhar'),
      patientId: patientId || null,
      specialty: kind === 'clinic_workspace' ? normalizeClinicalSpecialty(item?.specialty) || null : null
    };
  }).filter((item: UserAccessContext | null): item is UserAccessContext => Boolean(item));
}

async function fetchPatientPortalAccessContexts(userId: string): Promise<UserAccessContext[]> {
  const safeUserId = sanitizeString(userId, 120);
  if (!isUuid(safeUserId)) return [];

  const patientColumns = 'id,clinic_id,name,status,is_active,deleted_at,responsible_user_id';
  let patientResult = await supabase
    .from('patients')
    .select(patientColumns)
    .or(`responsible_user_id.eq.${safeUserId},id.eq.${safeUserId}`)
    .limit(100);
  if (patientResult.error && extractMissingColumnName(patientResult.error) === 'responsible_user_id') {
    patientResult = await supabase
      .from('patients')
      .select('id,clinic_id,name,status,is_active,deleted_at')
      .eq('id', safeUserId)
      .limit(100);
  }
  if (patientResult.error) throw patientResult.error;

  const patientRows = (patientResult.data || []).filter((patient: any) => {
    const status = sanitizeString(patient?.status, 80).trim().toUpperCase();
    return status !== 'DELETED' && patient?.deleted_at == null && patient?.is_active !== false;
  });
  const clinicIds = Array.from(new Set(
    patientRows
      .map((patient: any) => sanitizeString(patient?.clinic_id, 120))
      .filter((clinicId: string) => isUuid(clinicId))
  ));
  if (clinicIds.length === 0) return [];

  let clinicResult = await supabase
    .from('clinics')
    .select('id,name,logo_url')
    .in('id', clinicIds);
  if (clinicResult.error && extractMissingColumnName(clinicResult.error) === 'logo_url') {
    clinicResult = await supabase.from('clinics').select('id,name').in('id', clinicIds);
  }
  if (clinicResult.error) throw clinicResult.error;
  const clinicsById = new Map(
    (clinicResult.data || []).map((clinic: any) => [sanitizeString(clinic?.id, 120), clinic])
  );

  return compactAccessContextsForSession(patientRows.map((patient: any) => {
    const patientId = sanitizeString(patient?.id, 120);
    const clinicId = sanitizeString(patient?.clinic_id, 120);
    const clinic = clinicsById.get(clinicId) as any;
    const patientName = sanitizeString(patient?.name, 160);
    return {
      id: patientAccessContextId(patientId, clinicId),
      kind: 'patient_portal',
      clinicId,
      clinicName: sanitizeString(clinic?.name, 160) || 'Clínica',
      clinicLogoUrl: sanitizeSessionUrl(clinic?.logo_url),
      role: 'patient',
      patientId,
      label: patientName ? `Cuidado de ${patientName}` : 'Meu cuidado'
    };
  }));
}

async function fetchUserAccessContexts(userId: string, suppliedWorkspaces?: any[]): Promise<UserAccessContext[]> {
  const workspaces = Array.isArray(suppliedWorkspaces)
    ? suppliedWorkspaces
    : await fetchUserWorkspaces(userId);
  const [patientContexts] = await Promise.all([
    fetchPatientPortalAccessContexts(userId)
  ]);
  const clinicContexts = workspaces.map((workspace: any) => ({
    id: clinicAccessContextId(workspace?.clinicId),
    kind: 'clinic_workspace',
    clinicId: workspace?.clinicId,
    clinicName: workspace?.clinicName,
    clinicLogoUrl: workspace?.clinicLogoUrl,
    role: workspace?.role,
    patientId: null,
    specialty: workspace?.specialty,
    label: workspace?.specialty || 'Equipe da clínica'
  }));
  return compactAccessContextsForSession([...clinicContexts, ...patientContexts]);
}


type OnboardingContextMode =
  | 'invited_professional'
  | 'clinic_member'
  | 'clinic_owner'
  | 'standard'
  | 'invalid';

type ResolvedOnboardingContext = {
  onboardingMode: OnboardingContextMode;
  requiresPayment: boolean;
  canAccessDashboard: boolean;
  canEditClinic: boolean;
  source: 'membership_invitation' | 'membership' | 'clinic_owner' | 'profile';
  errorCode: string | null;
  clinic: {
    id: string;
    name: string;
    phone: string | null;
    whatsapp: string | null;
    logoUrl: string | null;
    subscriptionStatus: string | null;
    billingModel: string | null;
    address: string | null;
  } | null;
  membership: {
    role: string;
    specialty: string | null;
    invitedBy: string | null;
    invitationId: string | null;
    invitationStatus: string | null;
  } | null;
};

function compactOnboardingContextForSession(value: any): ResolvedOnboardingContext | null {
  if (!value || typeof value !== 'object') return null;
  const mode = sanitizeString(value.onboardingMode, 60) as OnboardingContextMode;
  if (!['invited_professional', 'clinic_member', 'clinic_owner', 'standard', 'invalid'].includes(mode)) {
    return null;
  }
  const clinic = value.clinic && typeof value.clinic === 'object'
    ? {
        id: sanitizeString(value.clinic.id, 120),
        name: sanitizeString(value.clinic.name, 160) || 'Clínica',
        phone: sanitizePhone(value.clinic.phone) || null,
        whatsapp: sanitizePhone(value.clinic.whatsapp) || null,
        logoUrl: sanitizeSessionUrl(value.clinic.logoUrl),
        subscriptionStatus: normalizeClinicAccessStatus(value.clinic.subscriptionStatus) || null,
        billingModel: sanitizeString(value.clinic.billingModel, 60).toLowerCase() || null,
        address: sanitizeString(value.clinic.address, 320) || null,
      }
    : null;
  const membership = value.membership && typeof value.membership === 'object'
    ? {
        role: ensureClinicRole(value.membership.role) ? sanitizeString(value.membership.role, 40) : 'therapist',
        specialty: normalizeClinicalSpecialty(value.membership.specialty) || null,
        invitedBy: sanitizeString(value.membership.invitedBy, 120) || null,
        invitationId: sanitizeString(value.membership.invitationId, 120) || null,
        invitationStatus: sanitizeString(value.membership.invitationStatus, 40).toLowerCase() || null,
      }
    : null;
  return {
    onboardingMode: mode,
    requiresPayment: value.requiresPayment === true,
    canAccessDashboard: value.canAccessDashboard !== false,
    canEditClinic: value.canEditClinic === true,
    source: ['membership_invitation', 'membership', 'clinic_owner', 'profile'].includes(value.source)
      ? value.source
      : 'profile',
    errorCode: sanitizeString(value.errorCode, 80) || null,
    clinic,
    membership,
  };
}

async function fetchClinicOnboardingSnapshot(clinicId: string) {
  const requiredColumns = ['id', 'name'];
  const optionalColumns = [
    'display_name',
    'owner_user_id',
    'phone_commercial',
    'phone',
    'clinic_phone',
    'whatsapp',
    'logo_url',
    'subscription_status',
    'billing_model',
    'address',
    'clinic_address',
    'city',
    'state',
  ];
  let columns = [...requiredColumns, ...optionalColumns];
  let lastError: any = null;

  for (let attempt = 0; attempt < optionalColumns.length + 2; attempt += 1) {
    const result = await supabase
      .from('clinics')
      .select(columns.join(','))
      .eq('id', clinicId)
      .maybeSingle();
    if (!result.error) return { data: result.data || null, error: null };
    lastError = result.error;
    const missingColumn = extractMissingColumnName(result.error);
    if (!missingColumn || !optionalColumns.includes(missingColumn) || !columns.includes(missingColumn)) break;
    columns = columns.filter((column) => column !== missingColumn);
  }

  return { data: null, error: lastError };
}

function clinicOnboardingAddress(row: any): string | null {
  const rawAddress = row?.clinic_address ?? row?.address;
  if (typeof rawAddress === 'string') return sanitizeString(rawAddress, 320) || null;
  if (rawAddress && typeof rawAddress === 'object') {
    return sanitizeString(
      [
        rawAddress.address_line || rawAddress.logradouro || rawAddress.street,
        rawAddress.number,
        rawAddress.district || rawAddress.bairro,
        rawAddress.city || rawAddress.cidade,
        rawAddress.state || rawAddress.uf,
      ].filter(Boolean).join(', '),
      320,
    ) || null;
  }
  return sanitizeString([row?.city, row?.state].filter(Boolean).join(' - '), 320) || null;
}

async function resolveOnboardingContextForUser(params: {
  userId: string;
  email?: string | null;
  preferredClinicId?: string | null;
  role?: string | null;
}): Promise<ResolvedOnboardingContext> {
  const userId = sanitizeString(params.userId, 120);
  const email = sanitizeEmail(params.email);
  const preferredClinicId = sanitizeString(params.preferredClinicId, 120);
  const fallbackRole = ensureClinicRole(params.role) ? sanitizeString(params.role, 40) : 'therapist';

  if (!isUuid(userId)) {
    return {
      onboardingMode: 'invalid',
      requiresPayment: false,
      canAccessDashboard: false,
      canEditClinic: false,
      source: 'profile',
      errorCode: 'ONBOARDING_USER_INVALID',
      clinic: null,
      membership: null,
    };
  }

  let membershipResult = await supabase
    .from('clinic_memberships')
    .select('user_id,clinic_id,role,status,invited_by,created_at,specialty')
    .eq('user_id', userId)
    .eq('status', 'active')
    .order('created_at', { ascending: true })
    .limit(30);
  if (membershipResult.error && extractMissingColumnName(membershipResult.error) === 'specialty') {
    membershipResult = await supabase
      .from('clinic_memberships')
      .select('user_id,clinic_id,role,status,invited_by,created_at')
      .eq('user_id', userId)
      .eq('status', 'active')
      .order('created_at', { ascending: true })
      .limit(30);
  }
  if (membershipResult.error) throw membershipResult.error;

  const memberships = Array.isArray(membershipResult.data) ? membershipResult.data : [];
  const membership =
    memberships.find((item: any) => sanitizeString(item?.clinic_id, 120) === preferredClinicId) ||
    memberships[0] ||
    null;
  const ownerFallbackClinicId = ['owner', 'coordinator'].includes(fallbackRole) ? userId : '';
  const clinicId = sanitizeString(membership?.clinic_id || preferredClinicId || ownerFallbackClinicId, 120);
  const role = ensureClinicRole(membership?.role) ? sanitizeString(membership.role, 40) : fallbackRole;

  if (!isUuid(clinicId)) {
    return {
      onboardingMode: role === 'coordinator' || role === 'admin' ? 'clinic_owner' : 'standard',
      requiresPayment: roleRequiresClinicBillingAccess(role),
      canAccessDashboard: false,
      canEditClinic: role === 'coordinator' || role === 'admin',
      source: 'profile',
      errorCode: 'ONBOARDING_CLINIC_NOT_RESOLVED',
      clinic: null,
      membership: null,
    };
  }

  const clinicResult = await fetchClinicOnboardingSnapshot(clinicId);
  if (clinicResult.error) throw clinicResult.error;
  const clinicRow = clinicResult.data as any;
  if (!clinicRow?.id) {
    const canProvisionOwnerClinic = !membership && ['owner', 'coordinator'].includes(role);
    if (canProvisionOwnerClinic) {
      return {
        onboardingMode: 'clinic_owner',
        requiresPayment: true,
        canAccessDashboard: false,
        canEditClinic: true,
        source: 'clinic_owner',
        errorCode: null,
        clinic: {
          id: clinicId,
          name: 'Minha Clínica',
          phone: null,
          whatsapp: null,
          logoUrl: null,
          subscriptionStatus: null,
          billingModel: null,
          address: null,
        },
        membership: null,
      };
    }
    return {
      onboardingMode: 'invalid',
      requiresPayment: false,
      canAccessDashboard: false,
      canEditClinic: false,
      source: membership ? 'membership' : 'profile',
      errorCode: 'ONBOARDING_CLINIC_NOT_FOUND',
      clinic: null,
      membership: membership
        ? {
            role,
            specialty: null,
            invitedBy: sanitizeString(membership.invited_by, 120) || null,
            invitationId: null,
            invitationStatus: null,
          }
        : null,
    };
  }

  let invitation: any = null;
  if (email) {
    const invitationResult = await fetchClinicInvitationsWithSchemaFallback({
      supabase,
      clinicId,
      limit: 300,
      logger: console,
    });
    if (invitationResult.error) throw invitationResult.error;
    invitation = (invitationResult.data || []).find((item: any) => {
      const status = sanitizeString(item?.status, 40).toLowerCase();
      return sanitizeEmail(item?.email) === email && ['pending', 'accepted'].includes(status);
    }) || null;
  }

  const professionalProfileResult = await fetchProfessionalProfileWithSchemaFallback({
    supabase,
    userId,
    logger: console,
  });
  if (professionalProfileResult.error && !isMissingRelationError(professionalProfileResult.error)) {
    throw professionalProfileResult.error;
  }
  const professionalProfile = professionalProfileResult.data as any;
  const specialty = role === 'therapist'
    ? normalizeClinicalSpecialty(
        membership?.specialty ||
        readClinicalSpecialtyFromSource(invitation, '') ||
        readClinicalSpecialtyFromSource(professionalProfile, ''),
      ) || null
    : null;
  const invitedBy = sanitizeString(membership?.invited_by || invitation?.invited_by, 120) || null;
  const isInvited = Boolean(invitedBy || invitation?.id);
  const ownerUserId = sanitizeString(clinicRow?.owner_user_id, 120);
  const isOwner = ownerUserId === userId || role === 'owner' || (!isInvited && role === 'coordinator' && clinicId === userId);
  const onboardingMode: OnboardingContextMode = isInvited
    ? 'invited_professional'
    : isOwner
      ? 'clinic_owner'
      : membership
        ? 'clinic_member'
        : 'standard';
  const clinicSubscriptionStatus = normalizeClinicAccessStatus(clinicRow?.subscription_status);
  const billingModel = sanitizeString(clinicRow?.billing_model, 60).toLowerCase();
  const canAccessDashboard = onboardingMode === 'clinic_owner'
    ? CLINIC_ACCESS_ACTIVE_STATUSES.has(clinicSubscriptionStatus) || billingModel === 'demo' || billingModel === 'demo_sandbox'
    : !clinicSubscriptionStatus || CLINIC_ACCESS_ACTIVE_STATUSES.has(clinicSubscriptionStatus) || billingModel === 'demo' || billingModel === 'demo_sandbox';

  return {
    onboardingMode,
    requiresPayment: onboardingMode === 'clinic_owner',
    canAccessDashboard,
    canEditClinic: onboardingMode === 'clinic_owner' && ['owner', 'admin', 'coordinator'].includes(role),
    source: isInvited ? 'membership_invitation' : isOwner ? 'clinic_owner' : membership ? 'membership' : 'profile',
    errorCode: null,
    clinic: {
      id: clinicId,
      name: sanitizeString(clinicRow?.display_name || clinicRow?.name, 160) || 'Clínica',
      phone: sanitizePhone(clinicRow?.phone_commercial || clinicRow?.clinic_phone || clinicRow?.phone) || null,
      whatsapp: sanitizePhone(clinicRow?.whatsapp) || null,
      logoUrl: sanitizeSessionUrl(clinicRow?.logo_url),
      subscriptionStatus: clinicSubscriptionStatus || null,
      billingModel: billingModel || null,
      address: clinicOnboardingAddress(clinicRow),
    },
    membership: membership
      ? {
          role,
          specialty,
          invitedBy,
          invitationId: sanitizeString(invitation?.id, 120) || null,
          invitationStatus: sanitizeString(invitation?.status, 40).toLowerCase() || null,
        }
      : null,
  };
}

async function persistSpecialtyFromOnboardingContext(params: {
  userId: string;
  userName?: string | null;
  context: ResolvedOnboardingContext;
}) {
  const specialty = normalizeClinicalSpecialty(params.context?.membership?.specialty);
  if (params.context.onboardingMode !== 'invited_professional' || params.context.membership?.role !== 'therapist' || !specialty) {
    return;
  }
  const existingResult = await fetchProfessionalProfileWithSchemaFallback({
    supabase,
    userId: params.userId,
    logger: console,
  });
  if (existingResult.error && !isMissingRelationError(existingResult.error)) throw existingResult.error;
  const existing = existingResult.data as any;
  const metadata = existing?.metadata && typeof existing.metadata === 'object' ? existing.metadata : {};
  const existingGlobalSpecialty = normalizeClinicalSpecialty(
    existing?.specialty
      || metadata?.specialty
      || metadata?.professionalTitle
      || metadata?.professional_title,
  );
  if (existingGlobalSpecialty) {
    return;
  }
  const { error } = await supabase
    .from('professional_profiles')
    .upsert(cleanObject({
      user_id: params.userId,
      full_name: sanitizeString(existing?.full_name || params.userName, 180) || undefined,
      specialty,
      metadata: cleanObject({
        ...metadata,
        specialty: metadata?.specialty || specialty,
        professionalTitle: metadata?.professionalTitle || specialty,
        professional_title: metadata?.professional_title || specialty,
        specialtyAuthority: metadata?.specialtyAuthority || 'first_clinic_invitation',
        specialtyConfirmedAt: metadata?.specialtyConfirmedAt || new Date().toISOString(),
      }),
      updated_at: new Date().toISOString(),
    }), { onConflict: 'user_id' });
  if (error) throw error;
}

function mergeAuthoritativeClinicSettings(sessionSettings: any, context: ResolvedOnboardingContext) {
  if (!context.clinic) return compactClinicSettingsForSession(sessionSettings);
  return compactClinicSettingsForSession({
    ...(sessionSettings && typeof sessionSettings === 'object' ? sessionSettings : {}),
    clinicName: context.clinic.name,
    clinicPhone: context.clinic.phone,
    clinicWhatsapp: context.clinic.whatsapp,
    clinicLogoUrl: context.clinic.logoUrl,
    clinicAddress: context.clinic.address,
    specialty: context.membership?.specialty || sessionSettings?.specialty || null,
  });
}

async function hydrateSessionUserWithOnboardingContext(sessionUser: any) {
  if (!sessionUser?.id) return buildSessionUserPayload(sessionUser);
  const workspaces = filterWorkspacesForUser(
    await fetchUserWorkspaces(sessionUser.id),
    sessionUser
  );
  const accessContexts = await fetchUserAccessContexts(sessionUser.id, workspaces);
  const baseSessionUser = buildSessionUserPayload({
    ...sessionUser,
    workspaces,
    accessContexts
  });
  if (!baseSessionUser.activeAccessContext || baseSessionUser.mustSelectAccessContext) {
    return baseSessionUser;
  }
  if (baseSessionUser.activeAccessContext.kind === 'patient_portal') {
    return buildSessionUserPayload({
      ...baseSessionUser,
      role: 'patient',
      clinicId: baseSessionUser.activeAccessContext.clinicId,
      activeWorkspaceId: null,
      onboardingContext: null,
      workspaces,
      accessContexts,
      activeAccessContextId: baseSessionUser.activeAccessContext.id,
      accessContextSelectionExplicit: baseSessionUser.accessContextSelectionExplicit
    });
  }
  const context = await resolveOnboardingContextForUser({
    userId: baseSessionUser.id,
    email: baseSessionUser.email,
    preferredClinicId: baseSessionUser.activeAccessContext.clinicId,
    role: baseSessionUser.activeAccessContext.role,
  });
  const clinicManagedBilling = ['invited_professional', 'clinic_member'].includes(context.onboardingMode) && Boolean(context.clinic?.id);
  return buildSessionUserPayload({
    ...baseSessionUser,
    role: context.membership?.role || baseSessionUser.role,
    clinicId: context.clinic?.id || baseSessionUser.clinicId,
    activeWorkspaceId: context.clinic?.id || baseSessionUser.activeWorkspaceId,
    subscriptionStatus: clinicManagedBilling
      ? context.clinic?.subscriptionStatus || baseSessionUser.subscriptionStatus
      : baseSessionUser.subscriptionStatus,
    billingModel: clinicManagedBilling
      ? context.clinic?.billingModel || baseSessionUser.billingModel
      : baseSessionUser.billingModel,
    specialties: context.membership?.specialty || baseSessionUser.specialties,
    clinicSettings: clinicManagedBilling
      ? mergeAuthoritativeClinicSettings(baseSessionUser.clinicSettings, context)
      : baseSessionUser.clinicSettings,
    onboardingContext: context,
    workspaces,
    accessContexts,
    activeAccessContextId: baseSessionUser.activeAccessContext.id,
    accessContextSelectionExplicit: baseSessionUser.accessContextSelectionExplicit
  });
}

async function findAuthUserByEmail(email: string): Promise<any | null> {
  if (!supabase) return null;
  const target = sanitizeEmail(email);
  if (!target) return null;

  let page = 1;
  const perPage = 200;
  for (;;) {
    const listResult = await withTimeoutOrFallback(
      supabase.auth.admin.listUsers({ page, perPage }),
      7000,
      { data: { users: [] }, error: null } as any,
      'supabase.auth.admin.listUsers'
    );
    const { data, error } = listResult;
    if (error) return null;
    const users = data?.users || [];
    const found = users.find((u: any) => sanitizeEmail(u.email) === target);
    if (found) return found;
    if (users.length < perPage) break;
    page += 1;
    if (page > 20) break;
  }
  return null;
}


type AtomicClinicInvitationAcceptance = {
  invitationId: string;
  clinicId: string;
  role: string;
  invitationStatus: string;
  membershipStatus: string;
  idempotent: boolean;
};

function clinicInvitationAcceptanceError(error: any): Error & { code: string; statusCode: number } {
  const raw = sanitizeString(error?.message || error?.details || error?.hint, 500);
  const knownCodes = [
    'CLINIC_INVITATION_INVALID',
    'CLINIC_INVITATION_NOT_FOUND',
    'CLINIC_INVITATION_EMAIL_MISMATCH',
    'CLINIC_INVITATION_ROLE_INVALID',
    'CLINIC_INVITATION_ALREADY_USED',
    'CLINIC_INVITATION_NOT_AVAILABLE',
    'CLINIC_INVITATION_CONCURRENT_UPDATE',
  ];
  const code = knownCodes.find((candidate) => raw.includes(candidate))
    || (raw.includes('accept_clinic_invitation_v1') || raw.includes('schema cache')
      ? 'CLINIC_INVITATION_MIGRATION_REQUIRED'
      : 'CLINIC_INVITATION_ACCEPT_FAILED');
  const statusByCode: Record<string, number> = {
    CLINIC_INVITATION_INVALID: 400,
    CLINIC_INVITATION_NOT_FOUND: 404,
    CLINIC_INVITATION_EMAIL_MISMATCH: 403,
    CLINIC_INVITATION_ROLE_INVALID: 422,
    CLINIC_INVITATION_ALREADY_USED: 409,
    CLINIC_INVITATION_NOT_AVAILABLE: 409,
    CLINIC_INVITATION_CONCURRENT_UPDATE: 409,
    CLINIC_INVITATION_MIGRATION_REQUIRED: 503,
  };
  const normalized = new Error(code) as Error & { code: string; statusCode: number };
  normalized.code = code;
  normalized.statusCode = statusByCode[code] || 500;
  return normalized;
}

async function acceptClinicInvitationAtomically(params: {
  invitationId: string;
  userId: string;
  verifiedEmail: string;
}): Promise<AtomicClinicInvitationAcceptance> {
  const invitationId = sanitizeString(params.invitationId, 120);
  const userId = sanitizeString(params.userId, 120);
  const verifiedEmail = sanitizeEmail(params.verifiedEmail);
  if (!isUuid(invitationId) || !isUuid(userId) || !verifiedEmail) {
    throw clinicInvitationAcceptanceError({ message: 'CLINIC_INVITATION_INVALID' });
  }
  const { data, error } = await supabase.rpc('accept_clinic_invitation_v1', {
    p_invitation_id: invitationId,
    p_user_id: userId,
    p_verified_email: verifiedEmail,
  });
  if (error) throw clinicInvitationAcceptanceError(error);
  const row = Array.isArray(data) ? data[0] : data;
  const clinicId = sanitizeString(row?.clinic_id, 120);
  const role = sanitizeString(row?.membership_role, 40).toLowerCase();
  if (!isUuid(clinicId) || !ensureClinicRole(role)) {
    throw clinicInvitationAcceptanceError({ message: 'CLINIC_INVITATION_ACCEPT_FAILED' });
  }
  return {
    invitationId: sanitizeString(row?.invitation_id, 120) || invitationId,
    clinicId,
    role,
    invitationStatus: sanitizeString(row?.invitation_status, 40).toLowerCase() || 'accepted',
    membershipStatus: sanitizeString(row?.membership_status, 40).toLowerCase() || 'active',
    idempotent: row?.idempotent === true,
  };
}

async function findRecoverableAuthUserByEmail(email: string): Promise<any | null> {
  const target = sanitizeEmail(email);
  if (!target) return null;

  const authUser = await findAuthUserByEmail(target);
  if (authUser?.id) return authUser;

  try {
    const profileResult = await fetchProfileByEmailWithSchemaFallback({
      supabase,
      email: target,
      logger: console
    });
    const profile = profileResult.data as any;
    if (profile?.id) {
      console.warn('[Auth] Recuperação usando fallback users.id por e-mail após listUsers não localizar usuário:', {
        email: maskEmail(target),
        userId: sanitizeString(profile.id, 120)
      });
      return {
        id: sanitizeString(profile.id, 120),
        email: sanitizeEmail(profile.email) || target,
        user_metadata: {
          full_name: sanitizeString(profile.name, 180) || undefined,
          type: sanitizeString(profile.type, 80) || undefined
        }
      };
    }
  } catch (error: any) {
    console.warn('[Auth] Fallback de recuperação por users.email falhou:', error?.message || String(error));
  }

  return null;
}

async function insertUserProfileWithSchemaFallback(basePayload: Record<string, any>) {
  let payload = cleanObject({ ...basePayload });
  let lastError: any = null;

  for (let attempt = 0; attempt < 12 && Object.keys(payload).length > 0; attempt += 1) {
    const { error } = await supabase
      .from('users')
      .insert([payload]);

    if (!error) return { error: null, payload };

    lastError = error;
    const missingColumn = extractMissingColumnName(error);
    if (!missingColumn || !(missingColumn in payload)) break;

    console.warn('[Auth] Removendo coluna opcional ausente ao criar perfil no login:', {
      table: 'users',
      removedColumn: missingColumn,
      code: sanitizeString(error?.code, 40) || null,
      message: extractSupabaseErrorMessage(error)
    });
    const nextPayload = { ...payload };
    delete nextPayload[missingColumn];
    payload = nextPayload;
  }

  return { error: lastError, payload };
}

function compactClinicSettingsForSession(settings: any) {
  if (!settings || typeof settings !== 'object') return null;
  return cleanObject({
    clinicName: sanitizeString(settings.clinicName, 160) || null,
    clinicLegalName: sanitizeString(settings.clinicLegalName || settings.legalName, 180) || null,
    legalName: sanitizeString(settings.legalName || settings.clinicLegalName, 180) || null,
    clinicDocumentType: sanitizeString(settings.clinicDocumentType || settings.documentType, 10).toUpperCase() || null,
    documentType: sanitizeString(settings.documentType || settings.clinicDocumentType, 10).toUpperCase() || null,
    clinicDocumentNumber: sanitizeString(settings.clinicDocumentNumber || settings.documentNumber, 30).replace(/\D/g, '') || null,
    clinicCnpj: sanitizeString(settings.clinicCnpj, 30) || null,
    clinicPhone: sanitizeString(settings.clinicPhone, 30) || null,
    clinicWhatsapp: sanitizeString(settings.clinicWhatsapp || settings.whatsapp, 30) || null,
    clinicEmail: sanitizeEmail(settings.clinicEmail) || null,
    clinicSite: sanitizeString(settings.clinicSite || settings.site, 180) || null,
    specialty: sanitizeString(settings.specialty, 160) || null,
    council: sanitizeString(settings.council, 80) || null,
    councilNumber: sanitizeString(settings.councilNumber, 80) || null,
    clinicAddress: sanitizeString(settings.clinicAddress, 240) || null,
    clinicAddressLine: sanitizeString(settings.clinicAddressLine || settings.addressLine, 180) || null,
    clinicAddressNumber: sanitizeString(settings.clinicAddressNumber || settings.addressNumber, 40) || null,
    clinicAddressComplement: sanitizeString(settings.clinicAddressComplement || settings.addressComplement, 120) || null,
    clinicDistrict: sanitizeString(settings.clinicDistrict || settings.district, 120) || null,
    clinicCity: sanitizeString(settings.clinicCity || settings.city, 120) || null,
    clinicState: sanitizeString(settings.clinicState || settings.state, 2).toUpperCase() || null,
    clinicPostalCode: sanitizeString(settings.clinicPostalCode || settings.postalCode, 20).replace(/\D/g, '') || null,
    clinicCnesCode: sanitizeString(settings.clinicCnesCode || settings.cnesCode, 40).replace(/\D/g, '') || null,
    clinicProviderCode: sanitizeString(settings.clinicProviderCode || settings.providerCode, 80) || null,
    clinicLogoUrl: sanitizeSessionUrl(settings.clinicLogoUrl),
    signatureDataUrl: sanitizeSessionUrl(settings.signatureDataUrl),
    therapistSpecialties: sanitizeString(settings.therapistSpecialties, 240) || null,
    therapistMiniCurriculum: sanitizeString(settings.therapistMiniCurriculum, 3000) || null,
    defaultSessionDuration: asSafeNumber(settings.defaultSessionDuration, 20, 240) || 50,
    workStart: sanitizeString(settings.workStart, 5) || '08:00',
    workEnd: sanitizeString(settings.workEnd, 5) || '18:00'
  });
}

function compactWorkspacesForSession(workspaces: any[]) {
  if (!Array.isArray(workspaces)) return [];
  return workspaces.slice(0, 30).map((w: any) => ({
    clinicId: sanitizeString(w?.clinicId, 120),
    clinicName: sanitizeString(w?.clinicName, 160) || 'Clinica',
    clinicLogoUrl: sanitizeSessionUrl(w?.clinicLogoUrl),
    role: ensureRole(w?.role) ? w.role : 'therapist',
    specialty: normalizeClinicalSpecialty(w?.specialty) || null,
    isDemo: Boolean(w?.isDemo || w?.is_demo),
    demoStatus: sanitizeString(w?.demoStatus || w?.demo_status, 40).toLowerCase() || null,
    demoExpiresAt: sanitizeString(w?.demoExpiresAt || w?.demo_expires_at, 80) || null,
    demoSource: sanitizeString(w?.demoSource || w?.demo_source, 40) || null,
    demoKind: sanitizeString(w?.demoKind || w?.demo_kind, 40).toLowerCase() || null,
    demoKey: sanitizeString(w?.demoKey || w?.demo_key, 80) || null,
    demoLastActivityAt: sanitizeString(w?.demoLastActivityAt || w?.demo_last_activity_at, 80) || null,
    billingModel: sanitizeString(w?.billingModel || w?.billing_model, 40).toLowerCase() || null
  })).filter((w: any) => w.clinicId);
}

function filterWorkspacesForUser(workspaces: any[], user: any) {
  const compacted = compactWorkspacesForSession(workspaces);
  if (!isExplicitDemoUser(user)) return compacted;
  return compacted.filter((workspace: any) => (
    workspace.isDemo || workspace.billingModel === DEMO_SANDBOX_BILLING_MODEL
  ));
}

function buildSessionUserPayload(input: any) {
  const professionalProfile =
    input?.professionalProfile && typeof input.professionalProfile === 'object'
      ? input.professionalProfile
      : input?.professional_profile && typeof input.professional_profile === 'object'
        ? input.professional_profile
        : null;
  const professionalMetadata =
    professionalProfile?.metadata && typeof professionalProfile.metadata === 'object'
      ? professionalProfile.metadata
      : {};
  const explicitDemoUser = isExplicitDemoUser(input);
  const compactedWorkspaces = compactWorkspacesForSession(input?.workspaces || []);
  const workspaces = explicitDemoUser
    ? compactedWorkspaces.filter((workspace: any) => workspace.isDemo || workspace.billingModel === DEMO_SANDBOX_BILLING_MODEL)
    : compactedWorkspaces;
  const suppliedAccessContexts = compactAccessContextsForSession(input?.accessContexts || []);
  const accessContexts = suppliedAccessContexts.length > 0
    ? suppliedAccessContexts
    : compactAccessContextsForSession(workspaces.map((workspace: any) => ({
        ...workspace,
        id: clinicAccessContextId(workspace.clinicId),
        kind: 'clinic_workspace',
        patientId: null,
        label: workspace.specialty || 'Equipe da clínica'
      })));
  const requestedAccessContextId = sanitizeString(
    input?.activeAccessContextId || input?.activeAccessContext?.id,
    380
  );
  const activeAccessContext =
    (requestedAccessContextId
      ? accessContexts.find((context) => context.id === requestedAccessContextId) || null
      : null) ||
    (accessContexts.length === 1 ? accessContexts[0] : null);
  const activeWorkspaceId = activeAccessContext?.kind === 'clinic_workspace'
    ? activeAccessContext.clinicId
    : null;
  const selectedWorkspace = activeWorkspaceId
    ? workspaces.find((w: any) => w.clinicId === activeWorkspaceId) || null
    : null;
  const canonicalInputRole = sanitizeString(input?.role, 40).toLowerCase();
  const resolvedRole = activeAccessContext?.kind === 'patient_portal'
    ? 'patient'
    : explicitDemoUser
    ? selectedWorkspace?.role || workspaces[0]?.role || 'coordinator'
    : canonicalInputRole === 'owner'
      ? 'owner'
      : selectedWorkspace?.role || input?.role;
  const mustSelectWorkspace = !activeAccessContext && workspaces.length > 1 && !activeWorkspaceId;
  const mustSelectAccessContext = accessContexts.length > 1 && !activeAccessContext;
  const resolvedBillingModel = sanitizeString(
    selectedWorkspace?.billingModel || input?.billingModel || input?.billing_model,
    40
  ).toLowerCase();
  const resolvedIsDemoUser = explicitDemoUser;

  return {
    id: sanitizeString(input?.id, 120),
    email: sanitizeEmail(input?.email) || sanitizeString(input?.email, 320),
    role: ensureRole(resolvedRole) ? resolvedRole : 'therapist',
    name: sanitizeString(input?.name, 180),
    profilePicture: sanitizeSessionUrl(input?.profilePicture),
    profilePicturePath: sanitizeString(input?.profilePicturePath || input?.profile_picture_path, 500) || null,
    address: sanitizeString(input?.address, 320) || null,
    type: sanitizeString(input?.type, 80) || null,
    age: typeof input?.age === 'number' ? input.age : null,
    subscriptionStatus: sanitizeString(input?.subscriptionStatus, 40) || null,
    planName: sanitizeString(input?.planName, 80) || null,
    planPrice: asSafeNumber(input?.planPrice, 0, 100000) || null,
    billingModel: resolvedBillingModel || null,
    isDemoUser: resolvedIsDemoUser,
    demoRole: sanitizeString(input?.demoRole || input?.demo_role, 80) || null,
    demoAccessMode: sanitizeString(input?.demoAccessMode || input?.demo_access_mode, 80).toLowerCase() || null,
    demoExpiresAt: sanitizeString(selectedWorkspace?.demoExpiresAt || input?.demoExpiresAt || input?.demo_expires_at, 80) || null,
    demoStatus: sanitizeString(selectedWorkspace?.demoStatus || input?.demoStatus || input?.demo_status, 40).toLowerCase() || null,
    demoSource: sanitizeString(selectedWorkspace?.demoSource || input?.demoSource || input?.demo_source, 40) || null,
    demoKind: sanitizeString(selectedWorkspace?.demoKind || input?.demoKind || input?.demo_kind, 40).toLowerCase() || null,
    demoKey: sanitizeString(selectedWorkspace?.demoKey || input?.demoKey || input?.demo_key, 80) || null,
    treatmentStatus: sanitizeString(input?.treatmentStatus, 40) || null,
    clinicId: mustSelectAccessContext
      ? null
      : activeAccessContext?.clinicId || selectedWorkspace?.clinicId || sanitizeString(input?.clinicId, 120) || null,
    activeWorkspaceId,
    mustSelectWorkspace,
    accessContexts,
    activeAccessContext,
    activeAccessContextId: activeAccessContext?.id || null,
    accessContextSelectionExplicit: Boolean(
      activeAccessContext && (requestedAccessContextId || input?.accessContextSelectionExplicit === true)
    ),
    mustSelectAccessContext,
    patientPortalPatientId: activeAccessContext?.kind === 'patient_portal'
      ? activeAccessContext.patientId
      : null,
    sessionToken: sanitizeString(input?.sessionToken, 120) || null,
    mfaVerified: input?.mfaVerified === true,
    mfaVerifiedAt: sanitizeString(input?.mfaVerifiedAt, 80) || null,
    mfaMethod: input?.mfaMethod === 'totp' ? 'totp' : null,
    authPolicyVersion: OWNER_MFA_POLICY_VERSION,
    emailVerified: Boolean(input?.emailVerified),
    phoneVerified: Boolean(input?.phoneVerified),
    portalVerified: Boolean(input?.portalVerified),
    accountState: sanitizeString(input?.accountState, 60) || null,
    passwordStatus: sanitizeString(input?.passwordStatus, 60) || null,
    firstLoginCompleted:
      typeof input?.firstLoginCompleted === 'boolean' ? input.firstLoginCompleted : null,
    activationRequired: Boolean(input?.activationRequired),
    onboardingContext: compactOnboardingContextForSession(input?.onboardingContext),
    crp: resolveStoredCrp(input),
    cpf:
      normalizeCpf(input?.cpf) ||
      normalizeCpf(professionalProfile?.cpf) ||
      normalizeCpf(professionalMetadata?.cpf || professionalMetadata?.professionalCpf) ||
      null,
    phone:
      sanitizePhone(input?.phone) ||
      sanitizePhone(professionalProfile?.phone) ||
      sanitizePhone(professionalMetadata?.phone || professionalMetadata?.professionalPhone) ||
      null,
    professionalRoleTitle:
      sanitizeString(
        input?.professionalRoleTitle ||
          professionalProfile?.roleTitle ||
          professionalProfile?.role_title ||
          professionalMetadata?.roleTitle ||
          professionalMetadata?.professionalRoleTitle,
        160
      ) || null,
    signatureDataUrl:
      sanitizeSessionUrl(input?.signatureDataUrl) ||
      sanitizeSessionUrl(input?.clinicSettings?.signatureDataUrl) ||
      null,
    specialties:
      sanitizeString(input?.specialties || input?.clinicSettings?.therapistSpecialties || input?.clinicSettings?.specialty, 240) ||
      null,
    miniCurriculum:
      sanitizeString(input?.miniCurriculum || input?.clinicSettings?.therapistMiniCurriculum, 3000) ||
      null,
    clinicSettings: compactClinicSettingsForSession(input?.clinicSettings),
    professionalProfile: professionalProfile
      ? cleanObject({
          fullName:
            sanitizeString(professionalProfile.fullName || professionalProfile.full_name || input?.name, 180) ||
            null,
          cpf:
            normalizeCpf(professionalProfile.cpf) ||
            normalizeCpf(professionalMetadata?.cpf || professionalMetadata?.professionalCpf) ||
            null,
          phone:
            sanitizePhone(professionalProfile.phone) ||
            sanitizePhone(professionalMetadata?.phone || professionalMetadata?.professionalPhone) ||
            null,
          roleTitle:
            sanitizeString(
              professionalProfile.roleTitle ||
                professionalProfile.role_title ||
                professionalMetadata?.roleTitle ||
                professionalMetadata?.professionalRoleTitle,
              160
            ) || null,
          crp:
            sanitizeString(professionalProfile.crp || professionalProfile.council_number || input?.crp, 80) ||
            null,
          specialties:
            sanitizeString(professionalProfile.specialties || professionalProfile.specialty, 240) ||
            null,
          miniCurriculum:
            sanitizeString(professionalProfile.miniCurriculum || professionalProfile.mini_curriculum, 3000) ||
            null,
          metadata: Object.keys(professionalMetadata).length > 0 ? professionalMetadata : null
        })
      : null,
    workspaces
  };
}

async function derivePatientTreatmentStatus(user: any): Promise<'active' | 'inactive' | 'waiting_treatment'> {
  const role = sanitizeString(user?.role, 40).toLowerCase();
  if (role !== 'patient') return 'active';

  const safeEmail = sanitizeEmail(user?.email);
  const fallbackHasClinic = Boolean(sanitizeString(user?.clinicId || user?.activeWorkspaceId, 120));
  const hasWorkspace = Array.isArray(user?.workspaces) && user.workspaces.length > 0;
  if (hasWorkspace) return 'active';

  let patientRows: any[] = [];
  if (safeEmail) {
    const { data } = await supabase
      .from('patients')
      .select('id, clinic_id, status')
      .ilike('email', safeEmail)
      .eq('is_active', true)
      .is('deleted_at', null)
      .limit(1000);
    patientRows = Array.isArray(data) ? data : [];
  }

  const hasLinkedClinic = patientRows.some((row: any) => Boolean(sanitizeString(row?.clinic_id, 120))) || fallbackHasClinic;
  const hasActivePatientStatus = patientRows.some((row: any) => sanitizeString(row?.status, 40).toLowerCase() === 'active');
  const patientIds = patientRows
    .map((row: any) => sanitizeString(row?.id, 120))
    .filter((id: string) => isUuid(id));

  let hasAssignedTasks = false;
  if (patientIds.length > 0) {
    const { count } = await supabase
      .from('assigned_tasks')
      .select('id', { count: 'exact', head: true })
      .in('patient_id', patientIds);
    hasAssignedTasks = Number(count || 0) > 0;
  }
  if (!hasAssignedTasks && safeEmail) {
    const { count } = await supabase
      .from('assigned_tasks')
      .select('id', { count: 'exact', head: true })
      .eq('patient_email', safeEmail);
    hasAssignedTasks = Number(count || 0) > 0;
  }

  // Regra de vínculo: paciente já vinculado à clínica não deve cair como "sem tratamento ativo"
  // imediatamente após ativação/login, mesmo sem tarefas atribuídas ainda.
  if (hasActivePatientStatus || hasLinkedClinic || hasAssignedTasks) return 'active';
  return 'waiting_treatment';
}

async function checkoutSessionUsesActivePatientPrice(
  stripe: Stripe,
  session: Stripe.Checkout.Session,
): Promise<boolean> {
  const activePatientPriceId = resolveActivePatientPriceId();
  const knownPriceIds = new Set<string>([activePatientPriceId].filter(Boolean));
  try {
    const { plans } = await loadBillingPlansFromSnapshots({ allowSync: true });
    for (const plan of plans) {
      const priceId = sanitizeString(plan.priceId, 120);
      if (priceId) knownPriceIds.add(priceId);
    }
  } catch (error: any) {
    console.warn('[Stripe] Falha ao carregar snapshots para validar Price ID ativo:', {
      message: sanitizeString(error?.message || String(error), 200)
    });
  }
  if (!knownPriceIds.size) return false;
  try {
    const lineItems = await stripe.checkout.sessions.listLineItems(session.id, { limit: 10 });
    for (const lineItem of lineItems.data || []) {
      const priceId = sanitizeString(typeof lineItem.price === 'string' ? lineItem.price : lineItem.price?.id, 160);
      if (knownPriceIds.has(priceId)) return true;
    }
  } catch (error: any) {
    console.warn('[Stripe] Falha ao validar Price ID ativo pelos line items da sessao:', {
      sessionId: sanitizeString(session.id, 200),
      message: error?.message || String(error)
    });
  }

  return false;
}

async function loadPatientProfessionalAccessEvidence(params: {
  patientId: string;
  clinicId: string;
  actorId: string;
}) {
  const [professionalLinkResult, membershipResult, profileResult] =
    await Promise.all([
      supabase
        .from('patient_professional_links')
        .select('id,organization_id,clinic_id,patient_id,professional_id,status,permissions')
        .eq('organization_id', params.clinicId)
        .eq('patient_id', params.patientId)
        .eq('professional_id', params.actorId)
        .eq('status', 'active')
        .limit(1)
        .maybeSingle(),
      supabase
        .from('clinic_memberships')
        .select('user_id,clinic_id,role,status')
        .eq('user_id', params.actorId)
        .eq('clinic_id', params.clinicId)
        .limit(1)
        .maybeSingle(),
      supabase
        .from('professional_profiles')
        .select('user_id,specialty')
        .eq('user_id', params.actorId)
        .limit(1)
        .maybeSingle()
    ]);

  const legacyMembershipSchemaUnavailable =
    isMissingRelationError(professionalLinkResult.error) ||
    isMissingRelationError(membershipResult.error);
  for (const result of [
    professionalLinkResult,
    membershipResult,
    profileResult
  ]) {
    if (result.error && !isMissingRelationError(result.error)) {
      throw result.error;
    }
  }
  if (
    profileResult.error &&
    !legacyMembershipSchemaUnavailable
  ) {
    throw profileResult.error;
  }

  return {
    activeProfessionalLink: legacyMembershipSchemaUnavailable
      ? null
      : professionalLinkResult.data,
    activeProfessionalMembership: legacyMembershipSchemaUnavailable
      ? null
      : membershipResult.data,
    activeProfessionalProfile: profileResult.error
      ? null
      : profileResult.data,
    activeManagerMembership: legacyMembershipSchemaUnavailable
      ? null
      : membershipResult.data,
    legacyMembershipSchemaUnavailable
  };
}

async function canAccessPatientInCurrentClinic(
  patientId: string,
  user: any,
  requiredPermission: 'read' | 'write' = 'read'
): Promise<boolean> {
  if (!isUuid(patientId)) return false;
  const explicitDemoUser = isExplicitDemoUser(user);
  if (hasGlobalClinicAccess(user) && !explicitDemoUser) return true;
  const clinicId = currentClinicId(user);
  const role = sanitizeString(user?.role, 40).toLowerCase();
  const userId = sanitizeString(user?.id, 120);
  let query = supabase
    .from('patients')
    .select('id,therapist_id,clinic_id,is_demo')
    .eq('id', patientId)
    .eq('is_active', true)
    .is('deleted_at', null);
  if (clinicId) {
    query = query.eq('clinic_id', clinicId);
  }
  const { data, error } = await query.maybeSingle();
  if (error) return false;
  if (data?.id) {
    if (explicitDemoUser && (data?.is_demo !== true || sanitizeString(data?.clinic_id, 120) !== clinicId)) {
      return false;
    }
    const resolvedAccess = {
      actorId: userId,
      actorRole: role,
      actorClinicId: clinicId,
      patientId: data.id,
      patientClinicId: data.clinic_id,
      legacyTherapistId: data.therapist_id,
      requiredPermission
    };
    if (
      clinicId &&
      sanitizeString(data?.clinic_id, 120) === clinicId &&
      isUuid(userId)
    ) {
      try {
        const evidence = await loadPatientProfessionalAccessEvidence({
          patientId,
          clinicId,
          actorId: userId
        });
        if (evidence.legacyMembershipSchemaUnavailable) {
          return (
            (role === 'therapist' &&
              sanitizeString(data?.therapist_id, 120) === userId) ||
            role === 'coordinator'
          );
        }
        return evaluatePatientClinicalAccess({
          ...resolvedAccess,
          ...evidence
        });
      } catch {
        return false;
      }
    }
    return false;
  }

  // Compatibilidade restrita a instalações legadas sem o schema de
  // memberships. Com o schema canônico disponível, a clínica ativa é
  // obrigatória e therapist_id não substitui a membership.
  if (!clinicId && !explicitDemoUser && role === 'therapist' && isUuid(userId)) {
    const { data: byTherapist, error: byTherapistError } = await supabase
      .from('patients')
      .select('id,clinic_id,therapist_id')
      .eq('id', patientId)
      .eq('therapist_id', userId)
      .eq('is_active', true)
      .is('deleted_at', null)
      .maybeSingle();
    const legacyClinicId = sanitizeString(byTherapist?.clinic_id, 120);
    if (!byTherapistError && byTherapist?.id && isUuid(legacyClinicId)) {
      try {
        const evidence = await loadPatientProfessionalAccessEvidence({
          patientId,
          clinicId: legacyClinicId,
          actorId: userId
        });
        return evidence.legacyMembershipSchemaUnavailable;
      } catch {
        return false;
      }
    }
  }

  return false;
}

async function canPortalSessionAccessPatient(patientId: string, user: any): Promise<boolean> {
  if (!isUuid(patientId)) return false;
  const role = sanitizeString(user?.role, 40).toLowerCase();
  if (!['patient', 'responsible', 'responsavel', 'guardian'].includes(role)) {
    return canAccessPatientInCurrentClinic(patientId, user);
  }

  const userId = sanitizeString(user?.id, 120);
  const userEmail = sanitizeEmail(user?.email);
  if (isUuid(userId) && userId === patientId) return true;

  let query = supabase
    .from('patients')
    .select('id, email, responsible_email, responsible_user_id, clinic_id')
    .eq('id', patientId)
    .eq('is_active', true)
    .is('deleted_at', null)
    .limit(1);
  const clinicId = sanitizeString(currentClinicId(user), 120);
  if (isUuid(clinicId)) query = query.eq('clinic_id', clinicId);
  const { data, error } = await query.maybeSingle();
  if (error || !data?.id) return false;

  const responsibleUserId = sanitizeString(data?.responsible_user_id, 120);
  const patientEmail = sanitizeEmail(data?.email);
  const responsibleEmail = sanitizeEmail(data?.responsible_email);
  return Boolean(
    (isUuid(userId) && responsibleUserId === userId) ||
    (userEmail && patientEmail && userEmail === patientEmail) ||
    (userEmail && responsibleEmail && userEmail === responsibleEmail)
  );
}

function normalizeAnamnesisAnswers(input: any, depth = 0): any {
  if (depth > 4) return null;
  if (input === null || input === undefined) return null;
  if (typeof input === 'string') return sanitizeString(input, 5000);
  if (typeof input === 'number') return Number.isFinite(input) ? input : null;
  if (typeof input === 'boolean') return input;
  if (Array.isArray(input)) {
    return input.slice(0, 200).map((item) => normalizeAnamnesisAnswers(item, depth + 1));
  }
  if (typeof input === 'object') {
    const entries = Object.entries(input).slice(0, 1000);
    return Object.fromEntries(entries.map(([key, value]) => [
      sanitizeString(key, 120),
      normalizeAnamnesisAnswers(value, depth + 1)
    ]).filter(([key]) => Boolean(key)));
  }
  return sanitizeString(String(input), 500);
}

function hasAnamnesisAnswers(input: any): boolean {
  if (!input || typeof input !== 'object') return false;
  return Object.values(input).some((value) => {
    if (Array.isArray(value)) return value.length > 0;
    if (value && typeof value === 'object') return hasAnamnesisAnswers(value);
    return String(value ?? '').trim().length > 0;
  });
}

function resolvePatientAnamnesisProfile(patient: any): 'adult' | 'child' {
  const source = sanitizeString(
    patient?.patient_profile_type ||
      patient?.panel_type ||
      patient?.profile_type ||
      patient?.type ||
      patient?.anamnesisData?.formType,
    80
  ).toLowerCase();
  if (['kids_tea', 'kids', 'child', 'infantil', 'crianca', 'criança', 'aba'].includes(source)) return 'child';
  const age = Number(patient?.age);
  if (Number.isFinite(age) && age >= 0 && age <= 12) return 'child';
  return 'adult';
}

function calculateAgeMonthsFromDateOnly(value: unknown): number | null {
  const raw = sanitizeString(value, 40);
  if (!raw) return null;
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const birth = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
    : new Date(raw);
  if (Number.isNaN(birth.getTime())) return null;
  const today = new Date();
  let months = (today.getFullYear() - birth.getFullYear()) * 12 + (today.getMonth() - birth.getMonth());
  if (today.getDate() < birth.getDate()) months -= 1;
  return months >= 0 ? months : null;
}

function anamnesisTemplateMatchesPatient(row: any, patient: any) {
  if (!row?.id || row?.is_active === false) return false;
  const ageMonths = calculateAgeMonthsFromDateOnly(patient?.birth_date || patient?.birthDate || patient?.dataNascimento);
  const minMonths = row?.age_min_months === null || row?.age_min_months === undefined ? null : Number(row.age_min_months);
  const maxMonths = row?.age_max_months === null || row?.age_max_months === undefined ? null : Number(row.age_max_months);
  const hasAgeRule = Number.isFinite(minMonths) || Number.isFinite(maxMonths);
  const ageMatches =
    ageMonths === null || !hasAgeRule
      ? true
      : (!Number.isFinite(minMonths) || ageMonths >= Number(minMonths)) &&
        (!Number.isFinite(maxMonths) || ageMonths <= Number(maxMonths));
  if (!ageMatches) return false;

  const rowProfile = sanitizeString(row?.patient_profile_type, 80).toUpperCase();
  if (!rowProfile) return true;
  const patientProfile = sanitizeString(
    patient?.patient_profile_type || patient?.panel_type || patient?.profile_type || patient?.type,
    80
  ).toUpperCase();
  if (!patientProfile) return true;
  if (rowProfile === 'TEEN' && patientProfile === 'KIDS') return true;
  if (rowProfile === 'KIDS_TEA' && patientProfile === 'KIDS') return true;
  if (rowProfile === 'ADULT' && patientProfile === 'ABA') return true;
  return rowProfile === patientProfile || patientProfile.includes(rowProfile) || rowProfile.includes(patientProfile);
}

function normalizeAgeBasedAnamnesisTemplate(row: any, patient: any, compatibleRows: any[] = [], availableRows: any[] = compatibleRows) {
  const fallback = getDefaultAnamnesisTemplate();
  const profileType = resolvePatientAnamnesisProfile(patient);
  const rawQuestions = row?.questions && typeof row.questions === 'object' ? row.questions : {};
  const template = sanitizeAnamnesisTemplate(
    rawQuestions?.profiles || rawQuestions?.version ? rawQuestions : fallback
  );
  const mapTemplateSummary = (item: any) => ({
    id: sanitizeString(item?.id, 120),
    name: sanitizeString(item?.name, 180),
    description: sanitizeString(item?.description, 240) || null,
    ageMinMonths: Number.isFinite(Number(item?.age_min_months)) ? Number(item.age_min_months) : null,
    ageMaxMonths: Number.isFinite(Number(item?.age_max_months)) ? Number(item.age_max_months) : null,
    patientProfileType: sanitizeString(item?.patient_profile_type, 80) || null
  });
  return {
    ...template,
    selectedTemplateId: sanitizeString(row?.id, 120) || null,
    templateName: sanitizeString(row?.name, 180) || (profileType === 'child' ? 'Ficha infantil' : 'Ficha adulta'),
    templateDescription: sanitizeString(row?.description, 500) || null,
    ageMinMonths: Number.isFinite(Number(row?.age_min_months)) ? Number(row.age_min_months) : null,
    ageMaxMonths: Number.isFinite(Number(row?.age_max_months)) ? Number(row.age_max_months) : null,
    patientProfileType: sanitizeString(row?.patient_profile_type, 80) || null,
    compatibleTemplates: compatibleRows.slice(0, 12).map(mapTemplateSummary).filter((item: any) => item.id && item.name),
    availableTemplates: availableRows.slice(0, 20).map(mapTemplateSummary).filter((item: any) => item.id && item.name)
  };
}

function buildPublicAnamnesisTemplate(template: any) {
  const sanitized = sanitizeAnamnesisTemplate(template || getDefaultAnamnesisTemplate());
  return {
    ...sanitized,
    templateName: sanitizeString(template?.templateName, 180) || null,
    templateDescription: sanitizeString(template?.templateDescription, 500) || null,
    ageMinMonths: Number.isFinite(Number(template?.ageMinMonths)) ? Number(template.ageMinMonths) : null,
    ageMaxMonths: Number.isFinite(Number(template?.ageMaxMonths)) ? Number(template.ageMaxMonths) : null,
    patientProfileType: sanitizeString(template?.patientProfileType, 80) || null,
    compatibleTemplates: Array.isArray(template?.compatibleTemplates)
      ? template.compatibleTemplates.map((item: any) => ({
          name: sanitizeString(item?.name, 180),
          description: sanitizeString(item?.description, 240) || null,
          ageMinMonths: Number.isFinite(Number(item?.ageMinMonths)) ? Number(item.ageMinMonths) : null,
          ageMaxMonths: Number.isFinite(Number(item?.ageMaxMonths)) ? Number(item.ageMaxMonths) : null,
          patientProfileType: sanitizeString(item?.patientProfileType, 80) || null
        })).filter((item: any) => item.name)
      : [],
    availableTemplates: Array.isArray(template?.availableTemplates)
      ? template.availableTemplates.map((item: any) => ({
          name: sanitizeString(item?.name, 180),
          description: sanitizeString(item?.description, 240) || null,
          ageMinMonths: Number.isFinite(Number(item?.ageMinMonths)) ? Number(item.ageMinMonths) : null,
          ageMaxMonths: Number.isFinite(Number(item?.ageMaxMonths)) ? Number(item.ageMaxMonths) : null,
          patientProfileType: sanitizeString(item?.patientProfileType, 80) || null
        })).filter((item: any) => item.name)
      : []
  };
}

function mapAnamnesisTemplateRowForEditor(row: any) {
  const template = sanitizeAnamnesisTemplate(row?.questions || getDefaultAnamnesisTemplate());
  return {
    id: sanitizeString(row?.id, 120),
    selectedTemplateId: sanitizeString(row?.id, 120),
    name: sanitizeString(row?.name, 180) || 'Ficha de anamnese',
    templateName: sanitizeString(row?.name, 180) || 'Ficha de anamnese',
    description: sanitizeString(row?.description, 500) || '',
    templateDescription: sanitizeString(row?.description, 500) || '',
    ageMinMonths: Number.isFinite(Number(row?.age_min_months)) ? Number(row.age_min_months) : null,
    ageMaxMonths: Number.isFinite(Number(row?.age_max_months)) ? Number(row.age_max_months) : null,
    patientProfileType: sanitizeString(row?.patient_profile_type, 80) || null,
    isDefault: Boolean(row?.is_default),
    isActive: row?.is_active !== false,
    updatedAt: sanitizeString(row?.updated_at, 80) || null,
    createdAt: sanitizeString(row?.created_at, 80) || null,
    ...template
  };
}

function normalizeAnamnesisTemplateAgeMonth(value: unknown): number | null {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return null;
  return Math.min(1440, Math.floor(parsed));
}

function normalizeAnamnesisPatientProfileType(value: unknown): string | null {
  const raw = sanitizeString(value, 80).toUpperCase();
  if (!raw) return null;
  return ['KIDS_TEA', 'KIDS', 'TEEN', 'ABA', 'ADULT'].includes(raw) ? raw : null;
}

async function fetchAnamnesisTemplateForClinic(clinicId: string) {
  const templateResult = await fetchClinicAnamnesisTemplateWithSchemaFallback({
    supabase,
    clinicId,
    logger: console
  });
  if (templateResult.error) {
    if (isMissingRelationError(templateResult.error)) return getDefaultAnamnesisTemplate();
    throw templateResult.error;
  }
  return sanitizeAnamnesisTemplate(templateResult.data?.template_json || getDefaultAnamnesisTemplate());
}

async function fetchAnamnesisTemplateForPatient(patient: any, clinicId: string, requestedTemplateId?: string | null) {
  const fallback = await fetchAnamnesisTemplateForClinic(clinicId);
  const safeClinicId = sanitizeString(clinicId, 120);
  if (!isUuid(safeClinicId)) return fallback;
  const requestedId = sanitizeString(requestedTemplateId, 120);

  try {
    let query = supabase
      .from('anamnesis_templates')
      .select(ANAMNESIS_TEMPLATE_SELECT)
      .eq('is_active', true)
      .or(`organization_id.is.null,organization_id.eq.${safeClinicId}`)
      .order('organization_id', { ascending: false })
      .order('is_default', { ascending: false })
      .order('created_at', { ascending: true })
      .limit(120);
    const { data, error } = await query;
    if (error) {
      if (isMissingRelationError(error) || extractMissingColumnName(error)) return fallback;
      throw error;
    }
    const rows = Array.isArray(data) ? data : [];
    const compatible = rows.filter((row: any) => anamnesisTemplateMatchesPatient(row, patient));
    const requestedRow = isUuid(requestedId)
      ? rows.find((row: any) => sanitizeString(row?.id, 120) === requestedId)
      : null;
    const patientProfileKey = sanitizeString(
      patient?.patient_profile_type || patient?.panel_type || patient?.profile_type || patient?.type,
      80
    ).toUpperCase();
    const exactCompatible = compatible.filter((row: any) => (
      patientProfileKey &&
      sanitizeString(row?.patient_profile_type, 80).toUpperCase() === patientProfileKey
    ));
    const selected =
      requestedRow ||
      exactCompatible.find((row: any) => sanitizeString(row?.organization_id, 120) === safeClinicId) ||
      exactCompatible[0] ||
      compatible.find((row: any) => sanitizeString(row?.organization_id, 120) === safeClinicId) ||
      compatible[0] ||
      rows.find((row: any) => sanitizeString(row?.organization_id, 120) === safeClinicId) ||
      rows[0];
    return selected ? normalizeAgeBasedAnamnesisTemplate(selected, patient, compatible, rows) : fallback;
  } catch (error: any) {
    console.warn('[AnamnesisTemplates] fallback para template legado:', error?.message || String(error));
    return fallback;
  }
}

