  const sanitizeIsoDateTime = (value: unknown, fallback = new Date().toISOString()) => {
    const raw = typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '';
    if (!raw) return fallback;
    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? fallback : date.toISOString();
  };

  const sanitizeClinicalDate = (value: unknown, fallback = new Date().toISOString().slice(0, 10)) => {
    const raw = typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
    const date = new Date(raw || fallback);
    if (Number.isNaN(date.getTime())) return fallback;
    return date.toISOString().slice(0, 10);
  };

  const readClinicalDateInput = (value: unknown) => {
    const raw = typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '';
    if (!raw) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
    const date = new Date(raw);
    return Number.isNaN(date.getTime()) ? '' : date.toISOString().slice(0, 10);
  };

  const parseClinicalDateMs = (value: unknown) => {
    const raw = sanitizeClinicalDate(value, '');
    if (!raw) return NaN;
    const [year, month, day] = raw.split('-').map(Number);
    const date = new Date(year, (month || 1) - 1, day || 1);
    return date.getTime();
  };

  const normalizeAbaSessionStatus = (value: unknown) => {
    const safe = sanitizeString(value, 40).toLowerCase();
    return ABA_SESSION_STATUSES.has(safe) ? safe : 'active';
  };

  const isAbaSessionInProgressStatus = (value: unknown) => {
    const safe = sanitizeString(value, 40).toLowerCase();
    return safe === 'active' || safe === 'in_progress';
  };

  const calculateAbaSessionDurationMinutes = (start: unknown, end: unknown, fallback: unknown = null) => {
    const fallbackNumber = Number(fallback);
    if (Number.isFinite(fallbackNumber) && fallbackNumber >= 0) return Math.round(fallbackNumber);
    const startTime = new Date(sanitizeString(start, 80)).getTime();
    const endTime = new Date(sanitizeString(end, 80)).getTime();
    if (!Number.isFinite(startTime) || !Number.isFinite(endTime) || endTime < startTime) return null;
    return Math.max(0, Math.ceil((endTime - startTime) / 60000));
  };

  const normalizeAbaCollectionType = (value: unknown) => {
    const safe = sanitizeString(value, 60).toLowerCase();
    if (safe === 'dtt' || safe === 'discrete_trial') return 'dtt';
    if (safe === 'natural_environment' || safe === 'natural_environment_training') return 'net';
    return ABA_COLLECTION_TYPES.has(safe) ? safe : 'dtt';
  };

  const isAbaMaintenanceProbeCollection = (value: unknown) => normalizeAbaCollectionType(value) === 'maintenance_probe';

  const normalizeAbaBehaviorMeasurementType = (value: unknown) => {
    const safe = sanitizeString(value, 80).toLowerCase();
    if (safe === 'partial') return 'partial_interval';
    if (safe === 'whole') return 'whole_interval';
    if (safe === 'momentary' || safe === 'mts') return 'momentary_time_sampling';
    return ABA_BEHAVIOR_MEASUREMENT_TYPES.has(safe) ? safe : 'frequency';
  };

  const normalizeAbaSyncStatus = (value: unknown, fallback = 'synced') => {
    const safe = sanitizeString(value, 40).toLowerCase();
    if (safe === 'offline') return 'local';
    if (safe === 'pending') return 'queued';
    return ABA_SYNC_STATUSES.has(safe) ? safe : fallback;
  };

