  const parseAbaRecordListLimit = (value: unknown) => parseBoundedListLimit(value, ABA_RECORD_LIST_FALLBACK_LIMIT, ABA_RECORD_LIST_MAX_LIMIT);
  const parseAbaPageParams = (query: any) => {
    const pageSize = parseAbaRecordListLimit(query?.pageSize ?? query?.limit);
    const page = Math.max(1, Math.round(asSafeNumber(query?.page, 1, 100000) || 1));
    const from = (page - 1) * pageSize;
    const to = from + pageSize - 1;
    return { page, pageSize, from, to };
  };
  const ABA_CHART_FALLBACK_DAYS = 30;
  const ABA_CHART_MAX_POINTS = 180;
  const parseAbaChartParams = (query: any) => {
    const periodDays = Math.max(1, Math.min(365, Math.round(asSafeNumber(query?.days || query?.periodDays, ABA_CHART_FALLBACK_DAYS, 365) || ABA_CHART_FALLBACK_DAYS)));
    const now = new Date();
    const fallbackFrom = new Date(now);
    fallbackFrom.setDate(now.getDate() - periodDays);
    const dateFrom = sanitizeDate(query?.dateFrom) || fallbackFrom.toISOString().slice(0, 10);
    const dateTo = sanitizeDate(query?.dateTo) || now.toISOString().slice(0, 10);
    const limit = Math.max(1, Math.min(ABA_CHART_MAX_POINTS, Math.round(asSafeNumber(query?.limit || query?.pageSize, 90, ABA_CHART_MAX_POINTS) || 90)));
    return {
      dateFrom,
      dateTo,
      dateFromIso: `${dateFrom}T00:00:00.000Z`,
      dateToIso: `${dateTo}T23:59:59.999Z`,
      limit,
      targetId: sanitizeString(query?.targetId || query?.target_id, 180),
      behaviorId: sanitizeString(query?.behaviorId || query?.behavior_id, 180),
      metricType: sanitizeString(query?.metricType || query?.metric_type, 80).toUpperCase(),
      specialty: sanitizeTextField(query?.specialty, 120),
      professionalId: sanitizeString(query?.professionalId || query?.professional_id, 120),
      significantOnly: String(query?.significantOnly || query?.significant_only || '').toLowerCase() === 'true'
    };
  };

  const parseAbaClinicalLineParams = (query: any) => {
    const period = query?.period || query?.days || query?.periodDays;
    const base = parseAbaChartParams({
      ...query,
      days: period,
      dateFrom: query?.from || query?.dateFrom,
      dateTo: query?.to || query?.dateTo,
      limit: query?.limit || 120
    });
    const category = normalizeAbaClinicalLineCategory(query?.category || query?.chart || 'target');
    const groupByValue = sanitizeString(query?.groupBy || query?.group_by || 'session', 20).toLowerCase();
    const groupBy = groupByValue === 'day' || groupByValue === 'week' ? groupByValue : 'session';
    const rawItemId = query?.itemId || query?.item_id ||
      (category === 'behavior' ? query?.behaviorId || query?.behavior_id : query?.targetId || query?.target_id);
    const itemId = sanitizeString(rawItemId, 180);
    const metric = resolveAbaClinicalLineMetric(category, query?.metric || query?.metricType || query?.metric_type);
    return {
      ...base,
      category,
      itemId,
      metric,
      groupBy: groupBy as 'session' | 'day' | 'week'
    };
  };

  const applyAbaChartTenantScope = (query: any, user: any, clinicId: string, organizationId: string) => {
    let scoped = query;
    if (organizationId) scoped = scoped.eq('organization_id', organizationId);
    if (!hasGlobalClinicAccess(user) && clinicId) scoped = scoped.eq('clinic_id', clinicId);
    return scoped;
  };

  const normalizeAbaSnapshotPoint = (row: any) => ({
    id: row?.id,
    sessionId: row?.session_id,
    targetId: row?.target_id,
    behaviorId: row?.behavior_id,
    metricType: row?.metric_type,
    metricLabel: row?.metric_label,
    value: Number(row?.metric_value ?? 0),
    previousValue: row?.previous_value === null || row?.previous_value === undefined ? null : Number(row.previous_value),
    deltaValue: row?.delta_value === null || row?.delta_value === undefined ? null : Number(row.delta_value),
    deltaPercent: row?.delta_percent === null || row?.delta_percent === undefined ? null : Number(row.delta_percent),
    trendDirection: row?.trend_direction,
    changeStatus: row?.change_status,
    statusLabel: row?.status_label,
    metricDirection: row?.metric_direction,
    changedAt: row?.changed_at,
    sourceSummaryId: row?.source_summary_id,
    professionalId: row?.professional_id_snapshot || null,
    specialty: row?.specialty_snapshot || 'Especialidade não informada',
    specialtySource: row?.specialty_source || 'unavailable',
    attemptsCount: Number(row?.aggregation_weight_snapshot) > 0
      ? Number(row.aggregation_weight_snapshot)
      : null
  });

  const formatAbaInsightNumber = (value: any) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return '-';
    return String(Math.round(numeric * 10) / 10);
  };

  const abaMetricUnit = (metric: string) => {
    if (isAbaPercentMetric(metric)) return '%';
    if (metric === 'BEHAVIOR_FREQUENCY') return ' ocorrência(s)';
    if (metric === 'BEHAVIOR_DURATION_EPISODES') return ' episódio(s)';
    if (metric === 'TARGET_TRIAL_COUNT') return ' tentativa(s)';
    if (metric.includes('DURATION')) return 's';
    return '';
  };

  const buildAbaDeltaText = (point: any) => {
    const metric = sanitizeString(point.metricType, 80);
    const unit = abaMetricUnit(metric);
    const previous = point.previousValue;
    const current = point.value;
    if (previous === null || previous === undefined) {
      return `primeira medição registrada: ${formatAbaInsightNumber(current)}${unit}`;
    }
    const previousText = `${formatAbaInsightNumber(previous)}${unit}`;
    const currentText = `${formatAbaInsightNumber(current)}${unit}`;
    if (isAbaPercentMetric(metric)) {
      const delta = Number(point.deltaValue ?? point.deltaPercent ?? 0);
      const sign = delta > 0 ? '+' : '';
      return `de ${previousText} para ${currentText} (${sign}${formatAbaInsightNumber(delta)} p.p.)`;
    }
    const deltaPercent = Number(point.deltaPercent);
    if (Number.isFinite(deltaPercent)) {
      const sign = deltaPercent > 0 ? '+' : '';
      return `de ${previousText} para ${currentText} (${sign}${formatAbaInsightNumber(deltaPercent)}%)`;
    }
    const deltaValue = Number(point.deltaValue);
    const sign = deltaValue > 0 ? '+' : '';
    return `de ${previousText} para ${currentText} (${sign}${formatAbaInsightNumber(deltaValue)}${unit})`;
  };

  const buildAbaChartInsight = (row: any) => {
    const point = normalizeAbaSnapshotPoint(row);
    const label = sanitizeTextField(point.metricLabel, 160) || 'Métrica clínica';
    const metric = sanitizeString(point.metricType, 80);
    const deltaText = buildAbaDeltaText(point);
    if (point.changeStatus === 'FIRST_MEASUREMENT') return `${label}: ${deltaText}.`;
    if (point.changeStatus === 'REGRESSION_SIGNAL') return `${label} apresentou sinal de regressão: ${deltaText}.`;
    if (point.changeStatus === 'CLINICALLY_SIGNIFICANT_CHANGE' && metric === 'MASTERY_STATUS') return `${label} está pronto para revisão de maestria.`;
    if (point.changeStatus === 'CLINICALLY_SIGNIFICANT_CHANGE') return `${label} teve mudança clinicamente relevante: ${deltaText}.`;
    if (point.trendDirection === 'IMPROVED') {
      if (point.metricDirection === 'LOWER_IS_BETTER') return `${label} reduziu: ${deltaText}.`;
      return `${label} subiu: ${deltaText}.`;
    }
    if (point.trendDirection === 'WORSENED') return `${label} piorou: ${deltaText}.`;
    if (point.trendDirection === 'STABLE') return `${label} está estável: ${deltaText}.`;
    return `${label}: ${deltaText}.`;
  };

  const fetchAbaGraphAnnotations = async (params: {
    patientId: string;
    clinicId: string;
    organizationId: string;
    user: any;
    chartType: string;
    dateFromIso: string;
    dateToIso: string;
    targetId?: string;
    behaviorId?: string;
  }) => {
    let query = supabase
      .from('aba_graph_annotations')
      .select(ABA_GRAPH_ANNOTATION_SELECT)
      .eq('patient_id', params.patientId)
      .eq('chart_type', params.chartType)
      .gte('date', params.dateFromIso)
      .lte('date', params.dateToIso)
      .order('date', { ascending: true })
      .limit(100);
    query = applyAbaChartTenantScope(query, params.user, params.clinicId, params.organizationId);
    if (params.targetId) query = query.eq('target_id', params.targetId);
    if (params.behaviorId) query = query.eq('behavior_id', params.behaviorId);
    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error)) return [];
      throw error;
    }
    return data || [];
  };

  const fetchAbaSnapshotRows = async (params: {
    patientId: string;
    clinicId: string;
    organizationId: string;
    user: any;
    metricTypes?: string[];
    targetId?: string;
    behaviorId?: string;
    metricType?: string;
    dateFromIso: string;
    dateToIso: string;
    limit: number;
    significantOnly?: boolean;
    ascending?: boolean;
    specialty?: string;
    professionalId?: string;
  }) => {
    let query = supabase
      .from('aba_session_metric_snapshots')
      .select(ABA_SESSION_METRIC_SNAPSHOT_SELECT)
      .eq('patient_id', params.patientId)
      .gte('changed_at', params.dateFromIso)
      .lte('changed_at', params.dateToIso)
      .order('changed_at', { ascending: params.ascending !== false })
      .limit(params.limit);
    query = applyAbaChartTenantScope(query, params.user, params.clinicId, params.organizationId);
    if (params.metricTypes?.length) query = query.in('metric_type', params.metricTypes);
    if (params.targetId) query = query.eq('target_id', params.targetId);
    if (params.behaviorId) query = query.eq('behavior_id', params.behaviorId);
    if (params.metricType) query = query.eq('metric_type', params.metricType);
    if (params.specialty) query = query.eq('specialty_snapshot', params.specialty);
    if (params.professionalId) query = query.eq('professional_id_snapshot', params.professionalId);
    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error)) return [];
      throw error;
    }
    const rows = data || [];
    return params.significantOnly
      ? rows.filter((row: any) => isAbaSignificantChange(row?.change_status, row?.trend_direction))
      : rows;
  };

  const fetchAbaTargetSummaryRows = async (params: {
    patientId: string;
    clinicId: string;
    organizationId: string;
    user: any;
    targetId?: string;
    dateFromIso: string;
    dateToIso: string;
    limit: number;
  }) => {
    let query = supabase
      .from('aba_target_live_summaries')
      .select(ABA_TARGET_CHART_SUMMARY_SELECT)
      .eq('patient_id', params.patientId)
      .gte('updated_at', params.dateFromIso)
      .lte('updated_at', params.dateToIso)
      .order('updated_at', { ascending: true })
      .limit(params.limit);
    query = applyAbaChartTenantScope(query, params.user, params.clinicId, params.organizationId);
    if (params.targetId) query = query.eq('target_id', params.targetId);
    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error)) return [];
      throw error;
    }
    return data || [];
  };

  const uniqueLineItems = (rows: any[], category: AbaClinicalLineCategory) => {
    const map = new Map<string, { id: string; label: string; category: AbaClinicalLineCategory }>();
    for (const row of rows || []) {
      const isBehavior = category === 'behavior';
      const id = sanitizeString(
        isBehavior
          ? row?.behavior_id || row?.behaviorId || row?.behavior_key || row?.behaviorKey
          : row?.target_id || row?.targetId || row?.target_key || row?.targetKey,
        180
      );
      if (!id) continue;
      const label = sanitizeTextField(
        isBehavior
          ? row?.behavior_name || row?.behaviorName || row?.behavior_key || row?.metric_label || row?.metricLabel || id
          : row?.target_name || row?.targetName || row?.name || row?.metric_label || row?.metricLabel || id,
        240
      ) || id;
      if (!map.has(id)) map.set(id, { id, label, category });
    }
    return Array.from(map.values()).slice(0, 80);
  };

  const behaviorDailyLineValue = (row: any, metric: string) => {
    if (metric === 'BEHAVIOR_DURATION_EPISODES') return Number(row?.duration_episode_count || 0);
    if (metric === 'BEHAVIOR_DURATION_TOTAL') return Number(row?.duration_total_seconds || 0);
    if (metric === 'BEHAVIOR_DURATION_AVG') return Number(row?.duration_avg_seconds || 0);
    if (metric === 'BEHAVIOR_INTERVAL_OCCURRENCE') return Number(row?.interval_occurrence_percent || 0);
    return Number(row?.frequency_count || 0);
  };

  const buildBehaviorDailyLinePoints = (rows: any[], metric: string, groupBy: 'session' | 'day' | 'week'): AbaClinicalLinePoint[] => {
    const points = (rows || []).map((row: any, index: number) => ({
      id: `${row.id || row.behavior_id || 'behavior'}-${metric}`,
      sessionId: null,
      sessionLabel: row.date ? new Date(`${row.date}T12:00:00.000Z`).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : `Dia ${index + 1}`,
      itemId: sanitizeString(row.behavior_id || row.behavior_key, 180) || null,
      itemLabel: sanitizeTextField(row.behavior_name || row.behavior_key || 'Comportamento', 240) || 'Comportamento',
      metric,
      metricLabel: sanitizeTextField(row.behavior_name || row.behavior_key || 'Comportamento', 240) || 'Comportamento',
      date: `${row.date}T12:00:00.000Z`,
      value: behaviorDailyLineValue(row, metric),
      attemptsCount: Number(row.frequency_count || row.duration_episode_count || row.interval_total_count || 0),
      metadata: {
        source: 'aba_behavior_daily_summaries',
        frequency: Number(row.frequency_count || 0),
        durationTotal: Number(row.duration_total_seconds || 0),
        durationAvg: Number(row.duration_avg_seconds || 0),
        intervalOccurrencePct: Number(row.interval_occurrence_percent || 0)
      }
    }));
    return aggregateAbaClinicalLinePoints(points, groupBy, metric);
  };

  const masteryLineValue = (row: any, metric: string) => {
    const status = sanitizeString(row?.status || row?.evaluation_status, 80).toUpperCase();
    if (metric === 'MASTERY_CONSECUTIVE_DAYS') return Number(row?.consecutive_successful_days ?? row?.consecutive_successes ?? 0);
    if (metric === 'MASTERY_VALID_ATTEMPTS') return Number(row?.trials_considered ?? row?.total_trials ?? 0);
    if (metric === 'MASTERY_READY_FOR_REVIEW') return status === 'READY_FOR_REVIEW' || status === 'MASTERED_APPROVED' ? 1 : 0;
    if (status === 'MASTERED_APPROVED' || status === 'MASTERED') return 4;
    if (status === 'READY_FOR_REVIEW') return 3;
    if (status === 'MET_TODAY' || status === 'MET') return 2;
    if (status === 'REGRESSION_RISK' || status === 'REGRESSED') return -1;
    return 1;
  };

  const buildMasteryLinePoints = (rows: any[], metric: string, groupBy: 'session' | 'day' | 'week'): AbaClinicalLinePoint[] => {
    const points = (rows || []).map((row: any, index: number) => ({
      id: row.id,
      sessionId: sanitizeString(row.session_id, 180) || null,
      sessionLabel: row.session_id ? `Sessao #${String(row.session_id).slice(-4)}` : `Avaliacao ${index + 1}`,
      itemId: sanitizeString(row.target_id, 180) || null,
      itemLabel: sanitizeTextField(row.target_name || row.target_id || 'Habilidade', 240) || 'Habilidade',
      metric,
      metricLabel: sanitizeTextField(row.target_name || row.target_id || 'Habilidade', 240) || 'Habilidade',
      date: sanitizeIsoDateTime(row.evaluated_at || row.created_at),
      value: masteryLineValue(row, metric),
      attemptsCount: Number(row.trials_considered ?? row.total_trials ?? 0),
      status: sanitizeString(row.status || row.evaluation_status, 80).toUpperCase(),
      metadata: {
        source: 'aba_mastery_evaluations',
        accuracyPct: row.accuracy_percent,
        independencePct: row.independence_percent,
        consecutiveDays: row.consecutive_successful_days ?? row.consecutive_successes,
        readyForReview: sanitizeString(row.status || row.evaluation_status, 80).toUpperCase() === 'READY_FOR_REVIEW'
      }
    }));
    return aggregateAbaClinicalLinePoints(points, groupBy, metric);
  };

  const maintenanceLineValue = (row: any, metric: string, failureCountByTarget: Map<string, number>) => {
    const status = sanitizeString(row?.status, 80).toUpperCase();
    if (metric === 'MAINTENANCE_ACCURACY') return Number(row?.accuracy_percent || 0);
    if (metric === 'MAINTENANCE_INDEPENDENCE') return Number(row?.independence_percent || 0);
    if (metric === 'MAINTENANCE_FAILURES') return Number(failureCountByTarget.get(sanitizeString(row?.target_id, 180)) || 0);
    if (metric === 'MAINTENANCE_DAYS_SINCE_PROBE') {
      const occurred = new Date(row?.occurred_at || 0).getTime();
      return Number.isFinite(occurred) ? Math.max(0, Math.floor((Date.now() - occurred) / 86400000)) : 0;
    }
    if (status === 'MAINTAINED' || status === 'COMPLETED') return 3;
    if (status === 'WATCH' || status === 'PENDING') return 1;
    if (status === 'REGRESSION_RISK') return -1;
    return 0;
  };

  const buildMaintenanceLinePoints = (rows: any[], metric: string, groupBy: 'session' | 'day' | 'week'): AbaClinicalLinePoint[] => {
    const failureCountByTarget = new Map<string, number>();
    for (const row of rows || []) {
      const target = sanitizeString(row?.target_id, 180);
      const status = sanitizeString(row?.status, 80).toUpperCase();
      if (target && ['WATCH', 'REGRESSION_RISK', 'MISSED'].includes(status)) {
        failureCountByTarget.set(target, (failureCountByTarget.get(target) || 0) + 1);
      }
      if (target && status === 'MAINTAINED') failureCountByTarget.set(target, 0);
    }
    const points = (rows || []).map((row: any, index: number) => ({
      id: row.id,
      sessionId: sanitizeString(row.session_id, 180) || null,
      sessionLabel: row.session_id ? `Sessao #${String(row.session_id).slice(-4)}` : `Probe ${index + 1}`,
      itemId: sanitizeString(row.target_id, 180) || null,
      itemLabel: sanitizeTextField(row.raw_payload?.targetName || row.target_name || row.target_id || 'Habilidade', 240) || 'Habilidade',
      metric,
      metricLabel: sanitizeTextField(row.raw_payload?.targetName || row.target_name || row.target_id || 'Habilidade', 240) || 'Habilidade',
      date: sanitizeIsoDateTime(row.occurred_at || row.created_at),
      value: maintenanceLineValue(row, metric, failureCountByTarget),
      attemptsCount: Number(row.total_trials || 0),
      status: sanitizeString(row.status, 80).toUpperCase(),
      metadata: {
        source: 'aba_maintenance_probe_results',
        accuracyPct: row.accuracy_percent,
        independencePct: row.independence_percent,
        independentTrials: row.independent_trials,
        promptedTrials: row.prompted_trials,
        errorTrials: row.error_trials
      }
    }));
    return aggregateAbaClinicalLinePoints(points, groupBy, metric);
  };

  const buildClinicalLinePhases = (annotations: any[]) => (annotations || [])
    .filter((annotation: any) => sanitizeString(annotation.annotation_type || annotation.annotationType, 40).toUpperCase() === 'CONDITION_LINE')
    .map((annotation: any) => ({
      id: annotation.id,
      label: annotation.label,
      date: annotation.date,
      sessionId: annotation.session_id || annotation.sessionId || null,
      type: 'CONDITION_LINE'
    }));

  const dedupeAnnotations = (annotations: any[]) => {
    const map = new Map<string, any>();
    for (const annotation of annotations || []) {
      if (!annotation?.id || !map.has(String(annotation.id))) map.set(String(annotation?.id || crypto.randomUUID()), annotation);
    }
    return Array.from(map.values()).sort((a, b) => new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime());
  };

  const buildSessionMetricSnapshots = async (sessionIdValue: string) => {
    const sessionId = sanitizeString(sessionIdValue, 180);
    if (!sessionId) return [];
    const currentResult = await supabase
      .from('aba_session_summaries')
      .select(ABA_SESSION_REPORT_SELECT)
      .eq('session_id', sessionId)
      .order('ended_at', { ascending: false })
      .limit(1)
      .maybeSingle();
    if (currentResult.error) {
      if (hasMissingFinancialSchema(currentResult.error)) return [];
      throw currentResult.error;
    }
    const currentSummary = currentResult.data;
    if (!currentSummary?.patient_id) return [];

    const patientId = sanitizeString(currentSummary.patient_id, 120);
    const clinicId = sanitizeString(currentSummary.clinic_id, 120);
    const organizationId = sanitizeString(currentSummary.organization_id || clinicId, 120);
    const endedAt = sanitizeIsoDateTime(currentSummary.ended_at || currentSummary.created_at);

    let previousQuery = supabase
      .from('aba_session_summaries')
      .select(ABA_SESSION_REPORT_SELECT)
      .eq('patient_id', patientId)
      .lt('ended_at', endedAt)
      .order('ended_at', { ascending: false })
      .limit(1);
    if (organizationId) previousQuery = previousQuery.eq('organization_id', organizationId);
    if (clinicId) previousQuery = previousQuery.eq('clinic_id', clinicId);
    const previousResult = await previousQuery.maybeSingle();
    if (previousResult.error && !hasMissingFinancialSchema(previousResult.error)) throw previousResult.error;
    const previousSummary = previousResult.data || null;

    let currentTargetQuery = supabase
      .from('aba_target_live_summaries')
      .select(ABA_TARGET_CHART_SUMMARY_SELECT)
      .eq('patient_id', patientId)
      .eq('session_id', sessionId)
      .limit(100);
    if (organizationId) currentTargetQuery = currentTargetQuery.eq('organization_id', organizationId);
    if (clinicId) currentTargetQuery = currentTargetQuery.eq('clinic_id', clinicId);
    const currentTargetResult = await currentTargetQuery;
    if (currentTargetResult.error && !hasMissingFinancialSchema(currentTargetResult.error)) throw currentTargetResult.error;

    let previousTargets: any[] = [];
    const previousSessionId = sanitizeString(previousSummary?.session_id || previousSummary?.sessionId, 180);
    if (previousSessionId) {
      let previousTargetQuery = supabase
        .from('aba_target_live_summaries')
        .select(ABA_TARGET_CHART_SUMMARY_SELECT)
        .eq('patient_id', patientId)
        .eq('session_id', previousSessionId)
        .limit(100);
      if (organizationId) previousTargetQuery = previousTargetQuery.eq('organization_id', organizationId);
      if (clinicId) previousTargetQuery = previousTargetQuery.eq('clinic_id', clinicId);
      const previousTargetResult = await previousTargetQuery;
      if (!previousTargetResult.error) previousTargets = previousTargetResult.data || [];
      if (previousTargetResult.error && !hasMissingFinancialSchema(previousTargetResult.error)) throw previousTargetResult.error;
    }

    const snapshots = buildSessionMetricSnapshotsFromSummaries({
      currentSummary,
      previousSummary,
      currentTargetSummaries: currentTargetResult.error ? [] : currentTargetResult.data || [],
      previousTargetSummaries: previousTargets
    });

    const saved: any[] = [];
    for (const snapshot of snapshots) {
      const stableKey = crypto
        .createHash('sha1')
        .update([
          snapshot.sessionId,
          snapshot.metricType,
          snapshot.targetId || '',
          snapshot.behaviorId || '',
          snapshot.metricLabel
        ].join('|'))
        .digest('hex')
        .slice(0, 24);
      const payload = cleanObject({
        id: `snapshot-${stableKey}`,
        organization_id: sanitizeString(snapshot.organizationId || organizationId, 120),
        clinic_id: sanitizeString(snapshot.clinicId || clinicId, 120),
        patient_id: patientId,
        session_id: sessionId,
        target_id: sanitizeString(snapshot.targetId, 180) || null,
        behavior_id: sanitizeString(snapshot.behaviorId, 180) || null,
        metric_type: sanitizeString(snapshot.metricType, 80),
        metric_label: sanitizeTextField(snapshot.metricLabel, 240),
        metric_value: asSafeNumber(snapshot.metricValue, 0, 100000000) || 0,
        previous_value: snapshot.previousValue === null || snapshot.previousValue === undefined ? null : asSafeNumber(snapshot.previousValue, -100000000, 100000000),
        delta_value: snapshot.deltaValue === null || snapshot.deltaValue === undefined ? null : asSafeNumber(snapshot.deltaValue, -100000000, 100000000),
        delta_percent: snapshot.deltaPercent === null || snapshot.deltaPercent === undefined ? null : asSafeNumber(snapshot.deltaPercent, -100000000, 100000000),
        trend_direction: sanitizeString(snapshot.trendDirection, 40),
        change_status: sanitizeString(snapshot.changeStatus, 80),
        status_label: sanitizeTextField(snapshot.statusLabel, 160),
        metric_direction: sanitizeString(snapshot.metricDirection, 40),
        changed_at: sanitizeIsoDateTime(snapshot.changedAt, endedAt),
        source_summary_id: sanitizeString(snapshot.sourceSummaryId, 180) || sanitizeString(currentSummary.id, 180) || null,
        created_at: new Date().toISOString()
      });
      const writeResult = await writeAbaRowWithSchemaFallback('aba_session_metric_snapshots', payload, 'upsert');
      if (writeResult.error) {
        if (hasMissingFinancialSchema(writeResult.error)) return saved;
        throw writeResult.error;
      }
      saved.push({ ...payload, id: (writeResult.data as any)?.id || payload.id });
    }
    return saved;
  };

  const resolveAbaChartPatientScope = (req: any) => {
    const patientId = sanitizeString(req.resolvedPatientId || req.params.patientId, 120);
    const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
    const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
    return { patientId, clinicId, organizationId };
  };

  const writeAbaRowWithSchemaFallback = async (
    tableName: string,
    payloadBase: Record<string, any>,
    mode: 'insert' | 'upsert' = 'insert',
    options: { criticalColumns?: string[] } = {}
  ) => {
    let payload: Record<string, any> = { ...payloadBase };
    const criticalColumns = new Set((options.criticalColumns || []).map((column) => sanitizeString(column, 80)).filter(Boolean));
    while (Object.keys(payload).length > 0) {
      const query = mode === 'upsert'
        ? supabase.from(tableName).upsert([payload], { onConflict: 'id' })
        : supabase.from(tableName).insert([payload]);
      const result = await query.select('id').single();
      if (!result.error) return { data: result.data, error: null };
      const missingColumn = extractMissingColumnName(result.error);
      if (missingColumn && missingColumn in payload) {
        if (criticalColumns.has(missingColumn)) {
          return { data: null, error: result.error };
        }
        delete payload[missingColumn];
        continue;
      }
      return { data: null, error: result.error };
    }
    return { data: null, error: { message: 'Payload ABA vazio após fallback de schema.' } };
  };

  const selectAbaMaintenanceSchedulesWithSchemaFallback = async (
    buildQuery: (selectColumns: string, availableColumns: string[]) => any
  ) => {
    const baseColumns = [
      'id',
      'organization_id',
      'clinic_id',
      'patient_id',
      'target_id',
      'mastery_evaluation_id',
      'schedule_day',
      'scheduled_for',
      'status',
      'created_at'
    ];
    let columns = [...ABA_MAINTENANCE_SCHEDULE_COLUMNS];
    for (let attempt = 0; attempt < ABA_MAINTENANCE_SCHEDULE_COLUMNS.length + 2; attempt += 1) {
      const activeColumns = columns.length > 0 ? columns : baseColumns;
      const result = await buildQuery(activeColumns.join(','), activeColumns);
      if (!result.error) return result;
      const missingColumn = extractMissingColumnName(result.error);
      if (missingColumn && columns.includes(missingColumn)) {
        columns = columns.filter((column) => column !== missingColumn);
        continue;
      }
      return result;
    }
    return buildQuery(baseColumns.join(','), baseColumns);
  };

  const stableAbaUuidFromParts = (scope: string, parts: any[] = []) => {
    const digest = crypto
      .createHash('sha1')
      .update([scope, ...parts].map((part) => sanitizeString(part, 500)).join('|'))
      .digest();
    const bytes = Buffer.from(digest.subarray(0, 16));
    bytes[6] = (bytes[6] & 0x0f) | 0x50;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    const hex = bytes.toString('hex');
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`;
  };

  const materializePeiTargetsForMaintenance = async (params: {
    patientId: string;
    clinicId: string;
    organizationId: string;
    sessionUser: any;
    peiTargets: any[];
    existingTargets: any[];
  }) => {
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    const organizationId = sanitizeString(params.organizationId || clinicId, 120);
    const existingTargets = Array.isArray(params.existingTargets) ? params.existingTargets : [];
    const peiTargets = Array.isArray(params.peiTargets) ? params.peiTargets : [];
    const targetById = new Map<string, any>();
    const targetByComposite = new Map<string, any>();
    const duplicateComposite = new Set<string>();
    const targetByName = new Map<string, any>();
    const duplicateName = new Set<string>();
    const targetByClinicalId = new Map<string, any>();
    const duplicateClinicalId = new Set<string>();
    const registerTargetMatch = (map: Map<string, any>, duplicates: Set<string>, key: string, target: any) => {
      if (!key) return;
      if (map.has(key)) {
        duplicates.add(key);
        map.delete(key);
        return;
      }
      if (!duplicates.has(key)) map.set(key, target);
    };
    const getPeiMaintenanceTargetClinicalIds = (source: any) => {
      const masteryCriteria = source?.mastery_criteria && typeof source.mastery_criteria === 'object' ? source.mastery_criteria : {};
      return [
        source?.peiGoalId,
        source?.goalId,
        source?.goal_id,
        source?.skillId,
        source?.skill_id,
        source?.localTargetRef,
        source?.local_target_ref,
        masteryCriteria?.peiGoalId,
        masteryCriteria?.pei_goal_id,
        masteryCriteria?.goalId,
        masteryCriteria?.goal_id,
        masteryCriteria?.skillId,
        masteryCriteria?.skill_id,
        masteryCriteria?.localTargetRef,
        masteryCriteria?.local_target_ref
      ]
        .map((value: any) => sanitizePeiLocalIdentifier(value, 180))
        .filter(Boolean);
    };
    existingTargets.forEach((target: any) => {
      const id = sanitizeString(target?.id || target?.target_id || target?.targetId, 180);
      if (!isUuid(id) || targetById.has(id)) return;
      targetById.set(id, target);
      const targetName = sanitizeString(target?.name || target?.description || target?.targetName || target?.target_name, 240);
      const protocolName = sanitizeString(target?.protocol_title || target?.protocolTitle || target?.protocolName || target?.protocol_name, 240);
      const domainName = sanitizeString(target?.domain_name || target?.domainName, 240);
      registerTargetMatch(targetByComposite, duplicateComposite, [targetName, protocolName, domainName].map(normalizePeiTargetMatchKey).filter(Boolean).join('|'), target);
      registerTargetMatch(targetByName, duplicateName, normalizePeiTargetMatchKey(targetName), target);
      getPeiMaintenanceTargetClinicalIds(target).forEach((clinicalId: string) => registerTargetMatch(targetByClinicalId, duplicateClinicalId, clinicalId, target));
    });
    const materializedTargets: any[] = [];
    const hydratedPeiTargets: any[] = [];
    const resolveSourceStatus = (source: any) => {
      const status = sanitizeString(source?.clinicalStatus || source?.clinical_status || source?.status || source?.phase || source?.masteryStatus || source?.mastery_status, 80).toUpperCase();
      if (['MAINTENANCE', 'MAINTAINED'].includes(status)) return { clinicalStatus: 'MAINTENANCE', phase: 'maintenance' };
      return { clinicalStatus: 'MASTERED', phase: 'mastered' };
    };
    for (const peiTarget of peiTargets) {
      if (!peiTarget?.eligibleForMaintenance) {
        hydratedPeiTargets.push(peiTarget);
        continue;
      }
      const targetName = sanitizeString(peiTarget?.targetName, 240);
      const protocolName = sanitizeString(peiTarget?.protocolName, 240) || 'Sem protocolo informado';
      const domainName = sanitizeString(peiTarget?.domainName, 240) || 'Sem domínio informado';
      const compositeKey = sanitizeString(peiTarget?.matchCompositeKey, 500) ||
        [targetName, protocolName, domainName].map(normalizePeiTargetMatchKey).filter(Boolean).join('|');
      const nameKey = sanitizeString(peiTarget?.matchNameKey, 280) || normalizePeiTargetMatchKey(targetName);
      const explicitTargetId = sanitizeString(peiTarget?.targetId || peiTarget?.target_id || peiTarget?.abaTargetId || peiTarget?.aba_target_id, 180);
      const sourcePeiGoalId = sanitizePeiLocalIdentifier(peiTarget?.peiGoalId || peiTarget?.goalId || peiTarget?.goal_id, 180);
      const sourceSkillId = sanitizePeiLocalIdentifier(peiTarget?.skillId || peiTarget?.skill_id, 180);
      const sourceLocalTargetRef = sanitizePeiLocalIdentifier(peiTarget?.localTargetRef, 180);
      const sourceIndex = sanitizePeiLocalIdentifier(peiTarget?.peiGoalIndex, 40);
      const stableTargetId = stableAbaUuidFromParts('patient-pei-maintenance-target', [
        organizationId,
        patientId,
        sourcePeiGoalId,
        sourceSkillId,
        sourceLocalTargetRef,
        sourceIndex,
        compositeKey
      ]);
      const legacyStableTargetIds = [
        stableAbaUuidFromParts('patient-pei-maintenance-target', [organizationId, patientId, '', sourceSkillId, '', '', compositeKey]),
        stableAbaUuidFromParts('patient-pei-maintenance-target', [organizationId, patientId, '', sourceSkillId, '', String(peiTarget?.peiGoalIndex ?? ''), compositeKey]),
        stableAbaUuidFromParts('patient-pei-maintenance-target', [organizationId, patientId, sourcePeiGoalId, sourceSkillId, '', '', compositeKey])
      ].filter((id, index, list) => isUuid(id) && list.indexOf(id) === index);
      const clinicalMatchedTarget = getPeiMaintenanceTargetClinicalIds(peiTarget)
        .map((clinicalId: string) => !duplicateClinicalId.has(clinicalId) ? targetByClinicalId.get(clinicalId) : null)
        .find(Boolean) || null;
      const stableMatchedTarget = [stableTargetId, ...legacyStableTargetIds]
        .map((candidateId: string) => targetById.get(candidateId))
        .find(Boolean) || null;
      const matchedTarget =
        (isUuid(explicitTargetId) ? targetById.get(explicitTargetId) : null) ||
        stableMatchedTarget ||
        clinicalMatchedTarget ||
        (compositeKey && !duplicateComposite.has(compositeKey) ? targetByComposite.get(compositeKey) : null) ||
        (nameKey && !duplicateName.has(nameKey) ? targetByName.get(nameKey) : null) ||
        null;
      if (matchedTarget?.id) {
        const matchedId = sanitizeString(matchedTarget.id, 180);
        hydratedPeiTargets.push(cleanObject({
          ...peiTarget,
          targetId: matchedId,
          target_id: matchedId,
          target: matchedTarget,
          hasRealTarget: true,
          needsTargetReview: false,
          canScheduleMaintenance: true,
          canWaitNextSession: true,
          canAssignAppointment: true,
          canReviewLink: false,
          protocolName: protocolName || sanitizeString(matchedTarget?.protocol_title, 240) || 'Sem protocolo informado',
          domainName: domainName || sanitizeString(matchedTarget?.domain_name, 240) || 'Sem domínio informado'
        }));
        continue;
      }
      if (!targetName || !isUuid(patientId) || !clinicId) {
        hydratedPeiTargets.push(peiTarget);
        continue;
      }
      const targetId = isUuid(explicitTargetId) ? explicitTargetId : stableTargetId;
      const status = resolveSourceStatus(peiTarget);
      const now = new Date().toISOString();
      const payload = cleanObject({
        id: targetId,
        organization_id: organizationId,
        clinic_id: clinicId,
        patient_id: patientId,
        program_id: null,
        name: targetName,
        description: sanitizeString(peiTarget?.description || targetName, 500) || targetName,
        target_type: 'dtt',
        phase: status.phase,
        protocol_id: null,
        protocol_title: protocolName,
        domain_id: null,
        domain_name: domainName,
        mastery_criteria: sanitizeClinicalPayload({
          source: 'patient_pei_materialized',
          peiGoalId: sanitizePeiLocalIdentifier(peiTarget?.peiGoalId, 180) || null,
          skillId: sanitizePeiLocalIdentifier(peiTarget?.skillId, 180) || null,
          localTargetRef: sanitizePeiLocalIdentifier(peiTarget?.localTargetRef, 180) || null,
          peiGoalIndex: Number.isFinite(Number(peiTarget?.peiGoalIndex)) ? Number(peiTarget.peiGoalIndex) : null,
          materializedForMaintenance: true
        }),
        clinical_status: status.clinicalStatus,
        created_by: sanitizeString(params.sessionUser?.id || params.sessionUser?.user_id || params.sessionUser?.email, 120) || null,
        updated_at: now
      });
      const writeResult = await writeAbaRowWithSchemaFallback('aba_targets', payload, 'upsert');
      if (writeResult.error) {
        if (hasMissingFinancialSchema(writeResult.error) || isMissingRelationError(writeResult.error)) {
          hydratedPeiTargets.push(peiTarget);
          continue;
        }
        throw writeResult.error;
      }
      const target = cleanObject({
        ...payload,
        id: sanitizeString((writeResult.data as any)?.id, 180) || targetId,
        target_id: sanitizeString((writeResult.data as any)?.id, 180) || targetId,
        targetId: sanitizeString((writeResult.data as any)?.id, 180) || targetId,
        created_at: now
      });
      targetById.set(target.id, target);
      materializedTargets.push(target);
      hydratedPeiTargets.push(cleanObject({
        ...peiTarget,
        targetId: target.id,
        target_id: target.id,
        target,
        hasRealTarget: true,
        needsTargetReview: false,
        canScheduleMaintenance: true,
        canWaitNextSession: true,
        canAssignAppointment: true,
        canReviewLink: false
      }));
    }
    return {
      targets: Array.from(targetById.values()),
      peiTargets: hydratedPeiTargets,
      materializedTargets
    };
  };

  const abaPlanningHash = (parts: any[]) => crypto
    .createHash('sha1')
    .update(parts.map((part) => sanitizeString(part, 240)).join('|'))
    .digest('hex')
    .slice(0, 24);

  const readPeiMaintenanceEnsureSource = (payload: any = {}) => {
    const row = payload?.skill && typeof payload.skill === 'object'
      ? payload.skill
      : payload?.row && typeof payload.row === 'object'
        ? payload.row
        : payload?.target && typeof payload.target === 'object'
          ? payload.target
          : payload;
    const source = row?.source && typeof row.source === 'object' ? row.source : {};
    const goal = row?.goal && typeof row.goal === 'object' ? row.goal : {};
    const target = row?.target && typeof row.target === 'object' ? row.target : {};
    const firstText = (max: number, ...values: any[]) => {
      for (const value of values) {
        const text = sanitizeString(value, max);
        if (text) return text;
      }
      return '';
    };
    const firstIdentifier = (max: number, ...values: any[]) => {
      for (const value of values) {
        const text = sanitizePeiLocalIdentifier(value, max);
        if (text) return text;
      }
      return '';
    };
    const targetName = firstText(
      240,
      row?.targetName,
      row?.target_name,
      row?.name,
      row?.title,
      source?.targetName,
      source?.target_name,
      source?.name,
      source?.title,
      goal?.targetName,
      goal?.target_name,
      goal?.name,
      goal?.title,
      target?.name,
      target?.targetName,
      row?.objective,
      source?.objective,
      goal?.objective
    );
    const protocolName = firstText(
      240,
      row?.protocolName,
      row?.protocol_name,
      row?.protocolTitle,
      row?.protocol_title,
      row?.protocol,
      source?.protocolName,
      source?.protocol_name,
      source?.protocolTitle,
      source?.protocol_title,
      source?.protocol,
      goal?.protocolName,
      goal?.protocol_name,
      goal?.protocolTitle,
      goal?.protocol_title,
      goal?.protocol,
      target?.protocol_title,
      target?.protocolTitle,
      target?.protocolName
    ) || 'Sem protocolo informado';
    const domainName = firstText(
      240,
      row?.domainName,
      row?.domain_name,
      row?.domain,
      row?.programName,
      row?.program_name,
      source?.domainName,
      source?.domain_name,
      source?.domain,
      source?.programName,
      source?.program_name,
      goal?.domainName,
      goal?.domain_name,
      goal?.domain,
      goal?.programName,
      goal?.program_name,
      target?.domain_name,
      target?.domainName,
      target?.program_name,
      target?.programName
    ) || 'Sem domínio informado';
    const progressPercent = Number(
      row?.progressPercent ??
      row?.progress_percent ??
      row?.progress ??
      source?.progressPercent ??
      source?.progress_percent ??
      source?.progress ??
      goal?.progressPercent ??
      goal?.progress_percent ??
      goal?.progress
    );
    const clinicalStatus = firstText(80, row?.clinicalStatus, row?.clinical_status, row?.status, source?.clinicalStatus, source?.clinical_status, source?.status, goal?.clinicalStatus, goal?.clinical_status, goal?.status);
    const masteryStatus = firstText(80, row?.masteryStatus, row?.mastery_status, row?.evaluationStatus, row?.evaluation_status, source?.masteryStatus, source?.mastery_status, goal?.masteryStatus, goal?.mastery_status);
    const candidate = cleanObject({
      source: 'patient_pei_request',
      peiGoalId: firstIdentifier(180, row?.peiGoalId, row?.goalId, row?.goal_id, source?.peiGoalId, source?.goalId, source?.goal_id, source?.id, goal?.id),
      skillId: firstIdentifier(180, row?.skillId, row?.skill_id, source?.skillId, source?.skill_id, goal?.skillId, goal?.skill_id),
      targetId: isUuid(firstText(180, row?.targetId, row?.target_id, row?.abaTargetId, row?.aba_target_id, target?.id, source?.targetId, source?.target_id)) ? firstText(180, row?.targetId, row?.target_id, row?.abaTargetId, row?.aba_target_id, target?.id, source?.targetId, source?.target_id) : null,
      localTargetRef: firstIdentifier(180, row?.localTargetRef, source?.localTargetRef, source?.id, goal?.id, row?.goalId, row?.goal_id),
      targetName,
      protocolName,
      domainName,
      description: firstText(500, row?.description, row?.objective, source?.description, source?.objective, goal?.description, goal?.objective, target?.description, targetName),
      clinicalStatus,
      masteryStatus,
      progressPercent: Number.isFinite(progressPercent) ? Math.max(0, Math.min(100, Math.round(progressPercent))) : null,
      acquiredAt: sanitizeIsoDateTime(row?.acquiredAt || row?.completedAt || row?.updatedAt || source?.acquiredAt || source?.completedAt || source?.updatedAt || null),
      eligibleForMaintenance: isMaintenanceEligiblePeiGoal({
        status: clinicalStatus,
        clinical_status: clinicalStatus,
        mastery_status: masteryStatus,
        progressPercent: Number.isFinite(progressPercent) ? progressPercent : null
      }),
      matchNameKey: normalizePeiTargetMatchKey(targetName),
      matchCompositeKey: [targetName, protocolName, domainName].map(normalizePeiTargetMatchKey).filter(Boolean).join('|')
    });
    return candidate;
  };

  const resolvePeiMaintenanceSourceTarget = (peiTargets: any[] = [], candidate: any = {}) => {
    const eligibleTargets = (Array.isArray(peiTargets) ? peiTargets : []).filter((target: any) => target?.eligibleForMaintenance);
    const targetId = sanitizeString(candidate?.targetId, 180);
    if (isUuid(targetId)) {
      const byTargetId = eligibleTargets.find((target: any) => sanitizeString(target?.targetId || target?.target_id, 180) === targetId);
      if (byTargetId) return byTargetId;
    }
    const peiGoalId = sanitizePeiLocalIdentifier(candidate?.peiGoalId || candidate?.goalId, 180);
    if (peiGoalId) {
      const byGoalId = eligibleTargets.find((target: any) =>
        sanitizePeiLocalIdentifier(target?.peiGoalId || target?.goalId || target?.goal_id, 180) === peiGoalId ||
        sanitizePeiLocalIdentifier(target?.localTargetRef, 180) === peiGoalId
      );
      if (byGoalId) return byGoalId;
    }
    const skillId = sanitizePeiLocalIdentifier(candidate?.skillId || candidate?.skill_id, 180);
    if (skillId) {
      const bySkillId = eligibleTargets.find((target: any) => sanitizePeiLocalIdentifier(target?.skillId || target?.skill_id, 180) === skillId);
      if (bySkillId) return bySkillId;
    }
    const localTargetRef = sanitizePeiLocalIdentifier(candidate?.localTargetRef, 180);
    if (localTargetRef) {
      const byLocalRef = eligibleTargets.find((target: any) => sanitizePeiLocalIdentifier(target?.localTargetRef, 180) === localTargetRef);
      if (byLocalRef) return byLocalRef;
    }
    const compositeKey = sanitizeString(candidate?.matchCompositeKey, 500);
    if (compositeKey) {
      const compositeMatches = eligibleTargets.filter((target: any) => sanitizeString(target?.matchCompositeKey, 500) === compositeKey);
      if (compositeMatches.length === 1) return compositeMatches[0];
    }
    const nameKey = sanitizeString(candidate?.matchNameKey, 280);
    if (nameKey) {
      const nameMatches = eligibleTargets.filter((target: any) => sanitizeString(target?.matchNameKey, 280) === nameKey);
      if (nameMatches.length === 1) return nameMatches[0];
    }
    return null;
  };

  const persistPeiSkillAcquiredMasteryEvent = async (params: {
    organizationId: string;
    clinicId: string;
    patientId: string;
    targetId: string;
    source: any;
    changedBy?: string | null;
  }) => {
    const targetId = sanitizeString(params.targetId, 180);
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    const organizationId = sanitizeString(params.organizationId || clinicId, 120);
    if (!isUuid(targetId) || !isUuid(patientId) || !clinicId) return null;
    const source = params.source || {};
    const now = new Date().toISOString();
    const evaluatedAt = sanitizeIsoDateTime(source?.acquiredAt || source?.updatedAt || now);
    const sourceEventKey = sanitizeString(
      source?.peiGoalId ||
      source?.goalId ||
      source?.goal_id ||
      source?.skillId ||
      source?.skill_id ||
      source?.localTargetRef ||
      source?.matchCompositeKey ||
      'pei',
      240
    );
    const eventId = `mastery-pei-acquired-${abaPlanningHash([organizationId, patientId, targetId, sourceEventKey])}`;
    const payload = cleanObject({
      id: eventId,
      organization_id: organizationId,
      clinic_id: clinicId,
      patient_id: patientId,
      session_id: null,
      target_id: targetId,
      target_name: sanitizeString(source?.targetName, 240),
      criteria_id: null,
      status: 'MASTERED_APPROVED',
      evaluation_status: 'mastered',
      suggested_phase: 'maintenance',
      total_trials: 0,
      independent_trials: 0,
      prompted_trials: 0,
      error_trials: 0,
      accuracy_percent: null,
      independence_percent: null,
      consecutive_successes: 0,
      consecutive_successful_days: 0,
      min_consecutive_successes: 1,
      trials_considered: 0,
      cold_probe_trials_count: 0,
      distinct_therapists_count: null,
      first_trial_independent: null,
      criteria: sanitizeClinicalPayload({
        source: 'patient_pei',
        eventType: 'SKILL_ACQUIRED',
        manualAcquisition: true,
        peiGoalId: sanitizeString(source?.peiGoalId, 180) || null,
        skillId: sanitizeString(source?.skillId, 180) || null
      }),
      reasons: sanitizeClinicalPayload(['SKILL_ACQUIRED_FROM_PEI']),
      evaluated_at: evaluatedAt,
      therapist_id: sanitizeString(params.changedBy, 120) || null,
      source_trial_id: null,
      raw_payload: sanitizeClinicalPayload({
        source: 'patient_pei',
        eventType: 'SKILL_ACQUIRED',
        manualAcquisition: true,
        noAutomaticTargetMutation: true,
        targetName: sanitizeString(source?.targetName, 240),
        protocolName: sanitizeString(source?.protocolName, 240),
        domainName: sanitizeString(source?.domainName, 240),
        progressPercent: source?.progressPercent ?? null
      }),
      created_at: now
    });
    const writeResult = await writeAbaRowWithSchemaFallback('aba_mastery_evaluations', payload, 'upsert');
    if (writeResult.error && !hasMissingFinancialSchema(writeResult.error) && !isMissingRelationError(writeResult.error)) {
      console.warn('[PEI Maintenance] Falha ao registrar evento SKILL_ACQUIRED:', writeResult.error?.message || String(writeResult.error));
    }
    return eventId;
  };

  const ensurePeiMaintenanceTargetForPatient = async (params: {
    patientId: string;
    clinicId: string;
    organizationId: string;
    sessionUser: any;
    payload: any;
  }) => {
    const patientId = sanitizeString(params.patientId, 120);
    const clinicId = sanitizeString(params.clinicId, 120);
    const organizationId = sanitizeString(params.organizationId || clinicId, 120);
    if (!isUuid(patientId) || !clinicId) {
      return { ok: false, status: 400, error: 'Dados insuficientes para preparar a habilidade.' };
    }
    const candidate = readPeiMaintenanceEnsureSource(params.payload || {});
    let targetQuery = supabase
      .from('aba_targets')
      .select(ABA_TARGET_RECOMMENDATION_SELECT)
      .eq('organization_id', organizationId)
      .eq('patient_id', patientId)
      .limit(500);
    targetQuery = applyAbaTenantScope(targetQuery, params.sessionUser, clinicId, organizationId);
    const targetResult = await targetQuery;
    if (targetResult.error && !hasMissingFinancialSchema(targetResult.error) && !isMissingRelationError(targetResult.error)) throw targetResult.error;
    const existingTargets = targetResult.error ? [] : (Array.isArray(targetResult.data) ? targetResult.data : []);
    const requestedTargetId = sanitizeString(candidate?.targetId, 180);
    const existingTarget = isUuid(requestedTargetId)
      ? existingTargets.find((target: any) => sanitizeString(target?.id, 180) === requestedTargetId) || null
      : null;
    if (existingTarget?.id) {
      const eventId = await persistPeiSkillAcquiredMasteryEvent({
        organizationId,
        clinicId,
        patientId,
        targetId: sanitizeString(existingTarget.id, 180),
        source: { ...candidate, targetName: candidate?.targetName || existingTarget?.name },
        changedBy: sanitizeString(params.sessionUser?.id || params.sessionUser?.user_id, 120)
      });
      return { ok: true, status: 200, target: existingTarget, targetId: sanitizeString(existingTarget.id, 180), masteryEvaluationId: eventId, materialized: false };
    }

    const peiTargets = await getPatientPeiTargets(patientId, clinicId, organizationId, params.sessionUser);
    const matchedPeiTarget = resolvePeiMaintenanceSourceTarget(peiTargets, candidate);
    const sourceTarget = matchedPeiTarget || (candidate?.eligibleForMaintenance && candidate?.targetName ? candidate : null);
    if (!sourceTarget?.targetName) {
      return { ok: false, status: 404, error: 'Habilidade adquirida não encontrada no PEI do paciente.' };
    }
    const materialized = await materializePeiTargetsForMaintenance({
      patientId,
      clinicId,
      organizationId,
      sessionUser: params.sessionUser,
      peiTargets: [sourceTarget],
      existingTargets
    });
    const hydrated = Array.isArray(materialized.peiTargets) ? materialized.peiTargets[0] : null;
    const targetId = sanitizeString(hydrated?.targetId || hydrated?.target_id || materialized.materializedTargets?.[0]?.id, 180);
    let target = (Array.isArray(materialized.targets) ? materialized.targets : []).find((item: any) => sanitizeString(item?.id, 180) === targetId) || null;
    if (!target?.id && isUuid(targetId)) {
      target = await fetchTargetForMaintenance({ targetId, patientId, clinicId, organizationId });
    }
    if (!isUuid(targetId) || !target?.id) {
      return { ok: false, status: 500, error: 'Não foi possível materializar a habilidade adquirida.' };
    }
    const eventId = await persistPeiSkillAcquiredMasteryEvent({
      organizationId,
      clinicId,
      patientId,
      targetId,
      source: { ...sourceTarget, targetName: sourceTarget?.targetName || target?.name },
      changedBy: sanitizeString(params.sessionUser?.id || params.sessionUser?.user_id, 120)
    });
    return { ok: true, status: 200, target, targetId, masteryEvaluationId: eventId, materialized: Boolean(materialized.materializedTargets?.length) };
  };

  const logAbaPlanningEgress = (details: Record<string, any>) => {
    if (process.env.NODE_ENV !== 'production') {
      console.log('[ABA Planning Egress]', cleanObject(details));
    }
  };

  const applyAbaTenantScope = (query: any, user: any, clinicId: string, organizationId?: string) => {
    if (hasGlobalClinicAccess(user)) return query;
    if (clinicId) return query.eq('clinic_id', clinicId);
    if (organizationId) return query.eq('organization_id', organizationId);
    return query;
  };

  const parseCalendarFilterList = (value: unknown, max = 24) =>
    String(Array.isArray(value) ? value.join(',') : value || '')
      .split(',')
      .map((item) => sanitizeString(item, 120))
      .filter(Boolean)
      .slice(0, max);

  const parseCalendarRangeParams = (query: any) => {
    const now = new Date();
    const fallbackFrom = new Date(now);
    fallbackFrom.setHours(0, 0, 0, 0);
    const fallbackTo = new Date(fallbackFrom);
    fallbackTo.setDate(fallbackTo.getDate() + 7);
    fallbackTo.setHours(23, 59, 59, 999);
    const fromIso = sanitizeIsoDateTime(query?.from || query?.time_min || query?.timeMin, fallbackFrom.toISOString());
    const toIso = sanitizeIsoDateTime(query?.to || query?.time_max || query?.timeMax, fallbackTo.toISOString());
    const fromTime = new Date(fromIso).getTime();
    const toTime = new Date(toIso).getTime();
    if (!Number.isFinite(fromTime) || !Number.isFinite(toTime) || toTime < fromTime) {
      return { ok: false as const, fromIso, toIso, limit: parseBoundedListLimit(query?.limit, 120, 200) };
    }
    return {
      ok: true as const,
      fromIso,
      toIso,
      limit: parseBoundedListLimit(query?.limit, 120, 200)
    };
  };

  const parseCalendarSourcePayload = (value: any) => {
    if (!value) return {};
    if (typeof value === 'object' && !Array.isArray(value)) return value;
    if (typeof value !== 'string') return {};
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  };

  const readCalendarBooleanFlag = (source: any, keys: string[]) =>
    keys.some((key) => {
      const value = source?.[key];
      if (typeof value === 'boolean') return value;
      if (typeof value === 'string') return ['1', 'true', 'yes', 'sim', 'pending', 'pendente'].includes(value.toLowerCase());
      return Boolean(value);
    });

  const isGenericCalendarPatientName = (value: any) => {
    const normalized = sanitizeString(value, 180)
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim();
    return !normalized || ['paciente', 'patient', 'cliente', 'paciente nao identificado', 'patient not identified'].includes(normalized);
  };

  const pickCalendarPatientName = (candidates: any[]) => {
    const labels = candidates.map((value) => sanitizeString(value, 180)).filter(Boolean);
    return labels.find((label) => !isGenericCalendarPatientName(label)) || labels[0] || '';
  };
  const hydrateCalendarPatientNames = async (rows: any[], clinicId: string) => {
    const safeClinicId = sanitizeString(clinicId, 120);
    if (!Array.isArray(rows) || rows.length === 0 || !isUuid(safeClinicId)) return rows;
    const knownNamesById = new Map<string, string>();
    const readRowPatientId = (row: any) => {
      const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
      return sanitizeString(row?.patient_id || row?.patientId || source?.patient_id || source?.patientId, 120);
    };
    const readRowPatientName = (row: any) => {
      const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
      return pickCalendarPatientName([
        row?.patient_name,
        row?.patientName,
        row?.patient?.name,
        source?.patientName,
        source?.patient_name,
        source?.patient?.name,
        row?.name,
        source?.name
      ]);
    };
    for (const row of rows) {
      const patientId = readRowPatientId(row);
      const currentName = readRowPatientName(row);
      if (isUuid(patientId) && currentName && !isGenericCalendarPatientName(currentName)) {
        knownNamesById.set(patientId, currentName);
      }
    }
    const hydrateRowsFromKnownNames = (sourceRows: any[]) => sourceRows.map((row: any) => {
      const patientId = readRowPatientId(row);
      const hydratedName = knownNamesById.get(patientId);
      const currentName = readRowPatientName(row);
      if (!hydratedName || hydratedName === currentName) return row;
      return {
        ...row,
        patient_name: hydratedName,
        patientName: hydratedName,
        name: hydratedName
      };
    });
    let hydratedRows = hydrateRowsFromKnownNames(rows);
    const idsNeedingHydration = Array.from(new Set(
      hydratedRows
        .map((row: any) => readRowPatientId(row))
        .filter((patientId: string) => isUuid(patientId))
    ));
    if (idsNeedingHydration.length === 0) return hydratedRows;
    const { data, error } = await supabase
      .from('patients')
      .select('id, name')
      .eq('clinic_id', safeClinicId)
      .in('id', idsNeedingHydration)
      .limit(idsNeedingHydration.length);
    if (error) {
      if (!hasMissingFinancialSchema(error)) console.warn('[Calendar] patient label hydration skipped:', error?.message || String(error));
      return hydratedRows;
    }
    for (const row of data || []) {
      const id = sanitizeString(row?.id, 120);
      const name = resolveClinicalPatientDisplayName(row);
      if (isUuid(id) && !isGenericCalendarPatientName(name)) knownNamesById.set(id, name);
    }
    hydratedRows = hydrateRowsFromKnownNames(hydratedRows);
    return hydratedRows;
  };

  const buildCalendarAppointmentStart = (row: any) => {
    const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
    const scheduledAt =
      row?.scheduled_start_at ||
      row?.scheduledStartAt ||
      row?.scheduled_at ||
      row?.scheduledAt ||
      source?.scheduled_start_at ||
      source?.scheduledStartAt ||
      source?.scheduled_at ||
      source?.scheduledAt ||
      source?.start_time ||
      source?.startTime;
    if (scheduledAt) {
      const date = new Date(scheduledAt);
      if (!Number.isNaN(date.getTime())) return date;
    }
    const dateKey = sanitizeDate(row?.date || source?.date);
    const rawTime = sanitizeString(row?.time || source?.time || '08:00', 12);
    const date = buildAppointmentDateTime(dateKey || formatDateInAppointmentTimezone(new Date()), rawTime || '08:00');
    return date || new Date();
  };

  const getCalendarAppointmentDuration = (row: any) => {
    const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
    const duration = Number(
      row?.scheduled_duration_minutes ||
      row?.scheduledDurationMinutes ||
      row?.duration_minutes ||
      row?.durationMinutes ||
      source?.scheduled_duration_minutes ||
      source?.scheduledDurationMinutes ||
      source?.duration_minutes ||
      source?.durationMinutes ||
      source?.duration ||
      50
    );
    return Number.isFinite(duration) && duration > 0 ? Math.min(360, Math.round(duration)) : 50;
  };

  const normalizeCalendarAppointmentRow = (row: any, counters: any = {}) => {
    const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
    const start = buildCalendarAppointmentStart(row);
    const end = calculateAppointmentEnd(start, getCalendarAppointmentDuration(row)) || new Date(start.getTime());
    const sourceDate = sanitizeDate(row?.date || source?.date);
    const sourceTime = normalizeAppointmentTime(row?.time || source?.time);
    const appointmentId = sanitizeString(row?.id || source?.id, 180);
    const patientId = sanitizeString(row?.patient_id || row?.patientId || source?.patient_id || source?.patientId, 120);
    const status = normalizeAppointmentStatusForUi(row?.status || source?.status || 'pending');
    const confirmationSnapshot = resolveAppointmentConfirmationSnapshot(row, source);
    const patientConfirmationStatus = normalizePatientConfirmationStatusForAgenda(
      confirmationSnapshot.confirmationStatus ?? confirmationSnapshot.response,
      row?.status || source?.status
    );
    const patientRespondedAt = confirmationSnapshot.respondedAt ?? confirmationSnapshot.confirmationAt;
    const statusText = sanitizeString(row?.status || source?.status, 80).toLowerCase();
    const hasSessionRecord =
      readCalendarBooleanFlag(source, ['has_session_record', 'hasSessionRecord', 'session_registered', 'sessionRegistered', 'registeredSession']) ||
      /registered|registrad|completed|conclu/.test(statusText);
    const hasReport = readCalendarBooleanFlag(source, ['has_report', 'hasReport', 'report_ready', 'reportReady', 'reportId', 'report_id']);
    const hasPendingSignature = readCalendarBooleanFlag(source, ['has_pending_signature', 'hasPendingSignature', 'pendingSignature', 'signaturePending']);
    const planCount = Number(counters.planCountByPatient?.get(patientId) || source?.plan_item_count || source?.planItemCount || 0);
    const probeCounter = counters.probeCountByAppointment?.get(appointmentId);
    const probeCount = Number((probeCounter && typeof probeCounter === 'object' ? probeCounter.total : probeCounter) || source?.maintenance_probe_count || source?.maintenanceProbeCount || 0);
    const pendingProbeCount = Number((probeCounter && typeof probeCounter === 'object' ? probeCounter.pending : 0) || source?.pending_maintenance_probe_count || source?.pendingMaintenanceProbeCount || 0);
    const pendingConfirmationCount = Number((probeCounter && typeof probeCounter === 'object' ? probeCounter.pendingConfirmation : 0) || source?.pending_maintenance_confirmation_count || source?.pendingMaintenanceConfirmationCount || 0);
    const unlinkedProbeCount = Number((probeCounter && typeof probeCounter === 'object' ? probeCounter.unlinked : 0) || source?.unlinked_maintenance_probe_count || source?.unlinkedMaintenanceProbeCount || 0);
    const dueTodayProbeCount = Number((probeCounter && typeof probeCounter === 'object' ? probeCounter.dueToday : 0) || source?.maintenance_due_today_count || source?.maintenanceDueTodayCount || 0);
    const overdueProbeCount = Number((probeCounter && typeof probeCounter === 'object' ? probeCounter.overdue : 0) || source?.overdue_maintenance_probe_count || source?.overdueMaintenanceProbeCount || 0);
    const roomId = sanitizeString(row?.room_id || row?.roomId || source?.room_id || source?.roomId || source?.room, 180);
    const sanitizeHumanRoom = (value: any) => {
      const text = sanitizeString(value, 180);
      if (!text) return '';
      if (isUuid(text) || /^[0-9a-f]{20,}$/i.test(text) || /^(clinic_room|room|sala)_[0-9a-f-]{8,}$/i.test(text)) return '';
      return text;
    };
    const location = roomId
      ? 'clinica'
      : sanitizeString(
          row?.location_type ||
            row?.locationType ||
            source?.location ||
            source?.locationType ||
            source?.location_type ||
            source?.local ||
            source?.place ||
            (String(row?.room_name || row?.roomName || row?.room || source?.roomDisplayName || source?.roomName || source?.room || '').toLowerCase().includes('online') ? 'online' : ''),
          120
        );
    const isClinicLocation = /clinic|clinica|sala/i.test(location) || Boolean(roomId);
    const room = sanitizeHumanRoom(
      row?.room_name ||
      row?.roomName ||
      source?.roomDisplayName ||
      source?.roomName ||
      source?.room_name ||
      row?.roomDisplayName ||
      row?.roomName ||
      row?.room ||
      source?.room
    ) || (isClinicLocation ? (roomId ? 'Sala não identificada' : 'Sala não informada') : '');
    const roomSpecialties = normalizeClinicRoomSpecialties(source?.room_specialties || source?.roomSpecialties || row?.room_specialties || row?.roomSpecialties);
    const careSetting = normalizeCareSetting(row?.care_setting || source?.care_setting || source?.careSetting, location);
    const locationNameSnapshot = sanitizeString(row?.location_name_snapshot || source?.location_name_snapshot || source?.locationNameSnapshot, 240) || null;
    const locationAddressSnapshot = sanitizeString(row?.location_address_snapshot || source?.location_address_snapshot || source?.locationAddressSnapshot, 1000) || null;
    const locationLabel = location ? (
      /online|remoto/i.test(location) ? 'Online' :
      /domic/i.test(location) ? 'Domicílio' :
      /escola/i.test(location) ? 'Escola' :
      /clinic|clinica|sala/i.test(location) ? 'Clínica' :
      'Outro'
    ) : (room ? 'Clínica' : 'Local não informado');
    const therapistId = sanitizeString(
      row?.therapist_id ||
        row?.therapistId ||
        source?.therapist_id ||
        source?.therapistId ||
        source?.professionalId,
      120
    ) || null;
    const therapistName = sanitizeString(
      row?.therapist_name ||
        row?.therapistName ||
        source?.therapistName ||
        source?.professional ||
        source?.therapist_name,
      180
    ) || null;
    const payerId = sanitizeString(row?.payer_id || row?.payerId || source?.payer_id || source?.payerId, 120) || null;
    const payerName = sanitizeString(
      row?.payer_name_snapshot || row?.payerName || row?.payer_name || source?.payer_name_snapshot || source?.payerName || source?.payer_name,
      180
    ) || null;
    const authorizationCode = sanitizeString(
      row?.authorization_code || row?.authorizationCode || source?.authorization_code || source?.authorizationCode,
      120
    ) || null;
    const guideNumber = sanitizeString(row?.guide_number || row?.guideNumber || source?.guide_number || source?.guideNumber, 120) || null;
    const procedureCode = sanitizeString(row?.procedure_code || row?.procedureCode || source?.procedure_code || source?.procedureCode, 80) || null;
    const insuranceCardNumber = sanitizeString(
      row?.insurance_card_number || row?.insuranceCardNumber || source?.insurance_card_number || source?.insuranceCardNumber,
      120
    ) || null;
    const insurancePlanName = sanitizeString(
      row?.insurance_plan_name || row?.insurancePlanName || source?.insurance_plan_name || source?.insurancePlanName,
      180
    ) || null;
    const explicitFinancialContext = sanitizeString(
      row?.financial_context_type || row?.financialContextType || source?.financial_context_type || source?.financialContextType,
      40
    ).toUpperCase();
    const financialContextType = explicitFinancialContext || (payerId || payerName ? 'INSURANCE' : null);

    return {
      id: appointmentId,
      patient_id: patientId || null,
      patient_name: pickCalendarPatientName([
        row?.patient_name,
        row?.patientName,
        row?.patient?.name,
        source?.patientName,
        source?.patient_name,
        source?.patient?.name,
        source?.name,
        row?.name
      ]) || 'Paciente',
      therapist_id: therapistId,
      therapistId,
      therapist_name: therapistName,
      therapistName,
      responsible_professional_id: therapistId,
      responsibleProfessionalId: therapistId,
      responsible_professional_name: therapistName,
      responsibleProfessionalName: therapistName,
      payer_id: payerId,
      payerId,
      payer_name_snapshot: payerName,
      payer_name: payerName,
      payerName,
      financial_context_type: financialContextType,
      financialContextType,
      insurance_card_number: insuranceCardNumber,
      insuranceCardNumber,
      insurance_plan_name: insurancePlanName,
      insurancePlanName,
      authorization_code: authorizationCode,
      authorizationCode,
      guide_number: guideNumber,
      guideNumber,
      procedure_code: procedureCode,
      procedureCode,
      start_time: start.toISOString(),
      end_time: end.toISOString(),
      date: sourceDate || formatDateInAppointmentTimezone(start),
      time: sourceTime || formatTimeInAppointmentTimezone(start),
      endTime: formatTimeInAppointmentTimezone(end),
      scheduled_start: row?.scheduled_start_at || source?.scheduled_start_at || start.toISOString(),
      scheduled_end: row?.scheduled_end_at || source?.scheduled_end_at || end.toISOString(),
      scheduled_duration_minutes: getCalendarAppointmentDuration(row),
      duration_minutes: getCalendarAppointmentDuration(row),
      actual_start: row?.actual_start_at || source?.actual_start_at || source?.actualStartAt || null,
      actual_end: row?.actual_end_at || source?.actual_end_at || source?.actualEndAt || null,
      actual_duration_minutes: Number(row?.actual_duration_minutes ?? source?.actual_duration_minutes ?? source?.actualDurationMinutes) || null,
      aba_session_id: sanitizeString(row?.aba_session_id || row?.abaSessionId || source?.aba_session_id || source?.abaSessionId, 180) || null,
      abaSessionId: sanitizeString(row?.abaSessionId || row?.aba_session_id || source?.abaSessionId || source?.aba_session_id, 180) || null,
      type: sanitizeString(row?.service_type || row?.approach || row?.type || source?.service_type || source?.serviceType || source?.approach || source?.type, 120) || 'Sessão',
      status,
      patientResponse: confirmationSnapshot.response,
      patient_response: confirmationSnapshot.response,
      patientRespondedAt,
      patient_responded_at: patientRespondedAt,
      patientConfirmationStatus,
      patient_confirmation_status: patientConfirmationStatus,
      patientConfirmationLabel: getPatientConfirmationLabelForAgenda(patientConfirmationStatus),
      patient_confirmation_label: getPatientConfirmationLabelForAgenda(patientConfirmationStatus),
      patientConfirmationColor: getPatientConfirmationColorForAgenda(patientConfirmationStatus),
      patient_confirmation_color: getPatientConfirmationColorForAgenda(patientConfirmationStatus),
      patientConfirmationSource: sanitizeString(confirmationSnapshot.source, 80) || null,
      patient_confirmation_source: sanitizeString(confirmationSnapshot.source, 80) || null,
      patient_response_source: sanitizeString(confirmationSnapshot.source, 80) || null,
      location: location || (room ? 'sala' : 'clinica'),
      location_type: normalizeScheduleLocationType(location || (room ? 'clinica' : 'outro')),
      care_setting: careSetting,
      careSetting,
      school_id: sanitizeString(row?.school_id || source?.school_id || source?.schoolId, 120) || null,
      schoolId: sanitizeString(row?.school_id || source?.schoolId || source?.school_id, 120) || null,
      school_unit_id: sanitizeString(row?.school_unit_id || source?.school_unit_id || source?.schoolUnitId, 120) || null,
      schoolUnitId: sanitizeString(row?.school_unit_id || source?.schoolUnitId || source?.school_unit_id, 120) || null,
      location_snapshot: parseStoredJsonObject(row?.location_snapshot || source?.location_snapshot || source?.locationSnapshot),
      locationSnapshot: parseStoredJsonObject(row?.location_snapshot || source?.locationSnapshot || source?.location_snapshot),
      location_name_snapshot: locationNameSnapshot,
      locationNameSnapshot,
      location_address_snapshot: locationAddressSnapshot,
      locationAddressSnapshot,
      location_source: sanitizeString(row?.location_source || source?.location_source || source?.locationSource, 60) || null,
      locationSource: sanitizeString(row?.location_source || source?.locationSource || source?.location_source, 60) || null,
      location_timezone: sanitizeString(row?.location_timezone || source?.location_timezone || source?.locationTimezone, 80) || 'America/Sao_Paulo',
      locationTimezone: sanitizeString(row?.location_timezone || source?.locationTimezone || source?.location_timezone, 80) || 'America/Sao_Paulo',
      location_label: locationLabel,
      room_id: roomId || null,
      roomId: roomId || null,
      room: room || null,
      room_name: room || null,
      roomName: room || null,
      room_specialties: roomSpecialties,
      roomSpecialties,
      locationType: normalizeScheduleLocationType(location || (room ? 'clinica' : 'outro')),
      locationLabel,
      has_session_record: hasSessionRecord,
      has_report: hasReport,
      has_pending_signature: hasPendingSignature,
      closure_readiness_status: sanitizeString(row?.closure_readiness_status || source?.closure_readiness_status, 40) || null,
      closure_blocking_count: Number(row?.closure_blocking_count ?? source?.closure_blocking_count ?? 0) || 0,
      closure_warning_count: Number(row?.closure_warning_count ?? source?.closure_warning_count ?? 0) || 0,
      closure_main_issues: Array.isArray(row?.closure_main_issues)
        ? row.closure_main_issues.slice(0, 3)
        : Array.isArray(source?.closure_main_issues)
          ? source.closure_main_issues.slice(0, 3)
          : [],
      has_next_session_plan: planCount > 0 || readCalendarBooleanFlag(source, ['has_next_session_plan', 'hasNextSessionPlan']),
      has_maintenance_probe: probeCount > 0 || readCalendarBooleanFlag(source, ['has_maintenance_probe', 'hasMaintenanceProbe']),
      maintenance_probe_count: probeCount,
      pending_maintenance_probe_count: pendingProbeCount,
      pending_maintenance_confirmation_count: pendingConfirmationCount,
      unlinked_maintenance_probe_count: unlinkedProbeCount,
      maintenance_due_today_count: dueTodayProbeCount,
      overdue_maintenance_probe_count: overdueProbeCount,
      has_pending_maintenance_confirmation: pendingConfirmationCount > 0,
      has_unlinked_maintenance_probe: unlinkedProbeCount > 0,
      has_overdue_maintenance_probe: overdueProbeCount > 0,
      has_maintenance_due_today: dueTodayProbeCount > 0,
      plan_item_count: planCount,
      recurrence_group_id: sanitizeString(row?.recurrence_group_id || row?.recurrenceGroupId || source?.recurrence_group_id || source?.recurrenceGroupId, 120) || null,
      recurrenceGroupId: sanitizeString(row?.recurrenceGroupId || row?.recurrence_group_id || source?.recurrenceGroupId || source?.recurrence_group_id, 120) || null,
      recurrence_index: Number(row?.recurrence_index ?? row?.recurrenceIndex ?? source?.recurrence_index ?? source?.recurrenceIndex) || null,
      recurrenceIndex: Number(row?.recurrenceIndex ?? row?.recurrence_index ?? source?.recurrenceIndex ?? source?.recurrence_index) || null,
      is_active: row?.is_active ?? row?.isActive ?? source?.is_active ?? source?.isActive ?? true,
      deleted_at: row?.deleted_at || row?.deletedAt || source?.deleted_at || source?.deletedAt || null
    };
  };

  const classifyCalendarEventLocation = (event: any) => {
    const careSetting = normalizeCareSetting(event?.care_setting || event?.careSetting, event?.location_type || event?.location);
    if (careSetting === 'ONLINE') return 'online';
    if (careSetting === 'PATIENT_HOME') return 'domicilio';
    if (careSetting === 'SCHOOL') return 'escola';
    if (careSetting === 'CLINIC') return 'sala';
    const value = sanitizeString(`${event?.location || ''} ${event?.location_type || ''} ${event?.location_label || ''} ${event?.room_name || ''} ${event?.room || ''}`, 600).toLowerCase();
    if (value.includes('online') || value.includes('remoto')) return 'online';
    if (value.includes('domic')) return 'domicilio';
    if (value.includes('escola')) return 'escola';
    if (value.includes('clinic') || value.includes('clínic') || value.includes('sala') || event?.room_id || event?.room_name) return 'sala';
    return 'outro';
  };

  const calendarEventMatchesFilters = (event: any, filters: any) => {
    const rawStatus = sanitizeString(event?.status, 80).toLowerCase();
    if (event?.is_active === false || event?.isActive === false || event?.deleted_at || event?.deletedAt || rawStatus === 'deleted') return false;
    if (filters.therapistIds.length > 0 && !filters.therapistIds.includes(String(event.therapist_id || ''))) return false;
    if (filters.patientIds.length > 0 && !filters.patientIds.includes(String(event.patient_id || ''))) return false;
    if (filters.roomIds?.length > 0 && !filters.roomIds.includes(String(event.room_id || ''))) return false;
    if (filters.schoolIds?.length > 0 && !filters.schoolIds.includes(String(event.school_id || event.schoolId || ''))) return false;
    if (filters.schoolUnitIds?.length > 0 && !filters.schoolUnitIds.includes(String(event.school_unit_id || event.schoolUnitId || ''))) return false;
    if (filters.locationTypes?.length > 0) {
      const locationClass = classifyCalendarEventLocation(event);
      const locationType = sanitizeString(event.location_type, 80).toLowerCase();
      if (!filters.locationTypes.some((item: string) => item.toLowerCase() === locationClass || item.toLowerCase() === locationType)) return false;
    }
    if (filters.types.length > 0) {
      const type = sanitizeString(event.type, 120).toLowerCase();
      if (!filters.types.some((item: string) => type === item.toLowerCase())) return false;
    }
    if (filters.statuses.length > 0) {
      const statusSet = filters.statuses.map((item: string) => item.toLowerCase());
      const status = sanitizeString(event.status, 80).toLowerCase();
      const matchesStatus =
        statusSet.includes(status) ||
        (statusSet.includes('sessao_registrada') && event.has_session_record) ||
        (statusSet.includes('session_registered') && event.has_session_record) ||
        (statusSet.includes('relatorio_pendente') && !event.has_report && status.includes('concl')) ||
        (statusSet.includes('report_pending') && !event.has_report && status.includes('concl')) ||
        (statusSet.includes('assinatura_pendente') && event.has_pending_signature) ||
        (statusSet.includes('signature_pending') && event.has_pending_signature) ||
        (statusSet.includes('maintenance_only') && event.has_maintenance_probe) ||
        (statusSet.includes('probes_pending') && Number(event.pending_maintenance_probe_count || 0) > 0) ||
        (statusSet.includes('probes_today') && Number(event.maintenance_due_today_count || 0) > 0) ||
        (statusSet.includes('probes_overdue') && Number(event.overdue_maintenance_probe_count || 0) > 0) ||
        (statusSet.includes('maintenance_pending_confirmation') && Number(event.pending_maintenance_confirmation_count || 0) > 0) ||
        (statusSet.includes('maintenance_unlinked') && Number(event.unlinked_maintenance_probe_count || 0) > 0);
      if (!matchesStatus) return false;
    }
    return true;
  };

  const normalizeConflictInputDates = (input: any) => {
    const recurrenceDates = Array.isArray(input?.recurrence_dates)
      ? input.recurrence_dates
      : Array.isArray(input?.recurrenceDates)
        ? input.recurrenceDates
        : [];
    const baseDate = sanitizeDate(input?.date || input?.start_date || input?.startDate);
    const fromStart = input?.start_time || input?.startTime;
    const startDate = input?.start_time && String(input.start_time).includes('T')
      ? new Date(input.start_time)
      : null;
    const dateFromIso = startDate && !Number.isNaN(startDate.getTime()) ? formatDateInAppointmentTimezone(startDate) : '';
    const startTimeFromIso = startDate && !Number.isNaN(startDate.getTime())
      ? formatTimeInAppointmentTimezone(startDate)
      : '';
    const date = baseDate || dateFromIso;
    const startTime = normalizeAppointmentTime(
      String(fromStart || '').includes('T')
        ? startTimeFromIso
        : fromStart || input?.time || '08:00',
    );
    const duration = Math.max(15, Math.min(720, Math.round(Number(input?.duration_minutes || input?.durationMinutes || 50) || 50)));
    const endFromIso = input?.end_time || input?.endTime;
    const endDate = endFromIso && String(endFromIso).includes('T') ? new Date(endFromIso) : null;
    const endTime = endDate && !Number.isNaN(endDate.getTime())
      ? formatTimeInAppointmentTimezone(endDate)
      : addMinutesToTime(startTime || '08:00', duration);
    const dates = (recurrenceDates.length > 0 ? recurrenceDates : [date])
      .map((value: any) => sanitizeDate(value))
      .filter(Boolean)
      .slice(0, 120);
    return { date, startTime, endTime, duration, recurrenceDates: dates.length > 0 ? dates : [date].filter(Boolean) };
  };

  const normalizeConflictAppointment = (row: any) => {
    const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
    const event = normalizeCalendarAppointmentRow(row);
    const durationMinutes = getAppointmentDurationMinutes({ ...source, ...row, ...event });
    return {
      ...source,
      ...row,
      ...event,
      patientId: event.patient_id,
      patientName: event.patient_name,
      therapistId: event.therapist_id,
      therapistName: event.therapist_name,
      professionalId: event.therapist_id,
      professional: event.therapist_name,
      professionalIds: Array.from(new Set([
        event.therapist_id,
        source?.professionalId,
        source?.professional_id,
        ...(Array.isArray(source?.professionalIds) ? source.professionalIds : []),
        ...(Array.isArray(source?.professional_ids) ? source.professional_ids : []),
        ...(Array.isArray(source?.teamProfessionalIds) ? source.teamProfessionalIds : []),
        ...(Array.isArray(source?.team_professional_ids) ? source.team_professional_ids : [])
      ].map((value) => sanitizeString(value, 120)).filter(Boolean))),
      professionalNames: Array.from(new Set([
        event.therapist_name,
        source?.professionalName,
        source?.professional,
        ...(Array.isArray(source?.professionalNames) ? source.professionalNames : []),
        ...(Array.isArray(source?.professional_names) ? source.professional_names : []),
        ...(Array.isArray(source?.teamProfessionalNames) ? source.teamProfessionalNames : [])
      ].map((value) => sanitizeString(value, 180)).filter(Boolean))),
      roomId: event.room_id || source?.roomId || source?.room_id || source?.room || null,
      room_id: event.room_id || source?.roomId || source?.room_id || source?.room || null,
      roomName: event.room_name || event.room || source?.roomName || source?.roomDisplayName || null,
      room_name: event.room_name || event.room || source?.roomName || source?.roomDisplayName || null,
      locationType: event.location_type || source?.locationType || source?.location_type || null,
      durationMinutes,
      duration_minutes: durationMinutes
    };
  };

  const fetchConflictAppointmentsFromState = async (clinicId: string, input: any) => {
    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId, logger: console });
    if (stateResult.error) {
      if (hasMissingFinancialSchema(stateResult.error)) return [];
      throw stateResult.error;
    }
    const dateSet = new Set((input.recurrenceDates || []).map((date: string) => String(date || '').slice(0, 10)));
    return (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
      .filter((appointment: any) => !dateSet.size || dateSet.has(String(appointment?.date || '').slice(0, 10)))
      .slice(0, 500)
      .map((appointment: any) => normalizeConflictAppointment({ ...appointment, source_payload: appointment }));
  };

  const fetchConflictAppointmentsFromTable = async (params: {
    clinicId: string;
    organizationId: string;
    input: any;
  }) => {
    const dates = params.input.recurrenceDates || [];
    const firstDate = dates[0] || params.input.date;
    const lastDate = dates[dates.length - 1] || firstDate;
    const windowStartBase = buildAppointmentDateTime(firstDate, '00:00');
    const windowEndBase = buildAppointmentDateTime(lastDate, '23:59');
    if (!windowStartBase || !windowEndBase) return [];
    const windowStart = new Date(windowStartBase.getTime() - 12 * 60 * 60 * 1000);
    const windowEnd = new Date(windowEndBase.getTime() + 12 * 60 * 60 * 1000);

    let query = supabase
      .from('appointments')
      .select(SCHEDULE_CONFLICT_APPOINTMENT_SELECT)
      .eq('clinic_id', params.clinicId)
      .gte('scheduled_at', windowStart.toISOString())
      .lte('scheduled_at', windowEnd.toISOString())
      .in('status', BLOCKING_APPOINTMENT_STATUS_QUERY_VALUES)
      .order('scheduled_at', { ascending: true })
      .limit(500);

    if (isUuid(params.organizationId)) query = query.eq('organization_id', params.organizationId);

    const orParts: string[] = [];
    if (isUuid(params.input.patientId)) orParts.push(`patient_id.eq.${params.input.patientId}`);
    const professionalIds = (params.input.professionalIds || []).filter((id: string) => isUuid(id)).slice(0, 20);
    if (professionalIds.length > 0) orParts.push(`therapist_id.in.(${professionalIds.join(',')})`);
    if (params.input.roomId) orParts.push(`room_id.eq.${String(params.input.roomId).replace(/[(),]/g, '')}`);
    if (orParts.length > 0) query = query.or(orParts.join(','));

    const { data, error } = await query;
    if (error) {
      if (hasMissingFinancialSchema(error)) return fetchConflictAppointmentsFromState(params.clinicId, params.input);
      throw error;
    }
    const rows = Array.isArray(data) ? [...data] : [];
    if (professionalIds.length > 0 && isUuid(params.organizationId)) {
      const teamResult = await supabase
        .from('appointment_professionals')
        .select('appointment_id, professional_id, professional_name')
        .eq('organization_id', params.organizationId)
        .in('professional_id', professionalIds)
        .limit(200);
      if (!teamResult.error && Array.isArray(teamResult.data) && teamResult.data.length > 0) {
        const existingIds = new Set(rows.map((row: any) => sanitizeString(row?.id, 180)));
        const teamAppointmentIds = Array.from(new Set(
          teamResult.data
            .map((row: any) => sanitizeString(row?.appointment_id, 180))
            .filter((id: string) => isUuid(id) && !existingIds.has(id))
        )).slice(0, 100);
        if (teamAppointmentIds.length > 0) {
          let teamAppointmentQuery = supabase
            .from('appointments')
            .select(SCHEDULE_CONFLICT_APPOINTMENT_SELECT)
            .in('id', teamAppointmentIds)
            .gte('scheduled_at', windowStart.toISOString())
            .lte('scheduled_at', windowEnd.toISOString())
            .in('status', BLOCKING_APPOINTMENT_STATUS_QUERY_VALUES)
            .limit(100);
          if (isUuid(params.organizationId)) teamAppointmentQuery = teamAppointmentQuery.eq('organization_id', params.organizationId);
          const teamAppointmentResult = await teamAppointmentQuery;
          if (!teamAppointmentResult.error && Array.isArray(teamAppointmentResult.data)) {
            rows.push(...teamAppointmentResult.data);
          }
        }
      }
    }
    return rows.map((row: any) => normalizeConflictAppointment(row));
  };

  const fetchConflictRooms = async (clinicId: string, organizationId: string) => {
    const roomsById = new Map<string, any>();
    const addRoom = (room: any, overwrite = true) => {
      const id = sanitizeString(room?.id || room?.room_id || room?.roomId, 180);
      if (!id) return;
      if (!overwrite && roomsById.has(id)) return;
      roomsById.set(id, {
        ...room,
        id,
        name: sanitizeString(room?.name || room?.room_name || room?.roomName, 180),
        prevent_overlapping_appointments:
          room?.prevent_overlapping_appointments ??
          room?.preventOverlappingAppointments ??
          true,
      });
    };

    let tableQuery = supabase
      .from('clinic_rooms')
      .select(CLINIC_ROOM_SELECT)
      .limit(400);
    if (isUuid(organizationId)) tableQuery = tableQuery.eq('organization_id', organizationId);
    else if (isUuid(clinicId)) tableQuery = tableQuery.eq('clinic_id', clinicId);
    const tableResult = await tableQuery;
    if (!tableResult.error && Array.isArray(tableResult.data)) {
      tableResult.data.forEach(addRoom);
    } else if (extractMissingColumnName(tableResult.error) === 'prevent_overlapping_appointments') {
      let legacyQuery = supabase
        .from('clinic_rooms')
        .select(CLINIC_ROOM_LEGACY_SELECT)
        .limit(400);
      if (isUuid(organizationId)) legacyQuery = legacyQuery.eq('organization_id', organizationId);
      else if (isUuid(clinicId)) legacyQuery = legacyQuery.eq('clinic_id', clinicId);
      const legacyResult = await legacyQuery;
      if (!legacyResult.error && Array.isArray(legacyResult.data)) legacyResult.data.forEach(addRoom);
    } else if (tableResult.error && !hasMissingFinancialSchema(tableResult.error)) {
      throw tableResult.error;
    }

    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId, logger: console });
    if (!stateResult.error && Array.isArray(stateResult.data?.rooms)) {
      stateResult.data.rooms.forEach((room: any) => addRoom(room, false));
    }
    return Array.from(roomsById.values());
  };

  const checkScheduleConflicts = async (rawInput: any, user: any): Promise<any> => {
    const clinicId = sanitizeString(rawInput?.clinic_id || rawInput?.clinicId || currentClinicId(user), 120);
    const organizationId = sanitizeString(rawInput?.organization_id || rawInput?.organizationId || user?.organizationId || user?.organization_id || clinicId, 120);
    const parsedDates = normalizeConflictInputDates(rawInput);
    const patientId = sanitizeString(rawInput?.patient_id || rawInput?.patientId, 120);
    const professionalIds = Array.from(new Set([
      ...(Array.isArray(rawInput?.professional_ids) ? rawInput.professional_ids : []),
      ...(Array.isArray(rawInput?.professionalIds) ? rawInput.professionalIds : []),
      rawInput?.professional_id,
      rawInput?.professionalId,
      rawInput?.therapist_id,
      rawInput?.therapistId
    ].map((value) => sanitizeString(value, 120)).filter(Boolean)));
    const professionalNames = Array.from(new Set([
      ...(Array.isArray(rawInput?.professional_names) ? rawInput.professional_names : []),
      ...(Array.isArray(rawInput?.professionalNames) ? rawInput.professionalNames : []),
      rawInput?.professional_name,
      rawInput?.professionalName,
      rawInput?.therapist_name,
      rawInput?.therapistName,
      rawInput?.professional
    ].map((value) => sanitizeString(value, 180)).filter(Boolean)));
    const locationType = normalizeScheduleLocationType(rawInput?.location_type || rawInput?.locationType || rawInput?.location);
    const roomId = sanitizeString(rawInput?.room_id || rawInput?.roomId || rawInput?.room, 180);
    const roomName = sanitizeString(rawInput?.room_name || rawInput?.roomName || rawInput?.roomDisplayName || roomId, 180);
    let sessionBufferMinutes = Math.round(asSafeNumber(rawInput?.session_buffer_minutes ?? rawInput?.sessionBufferMinutes, 0, 120) ?? 0);
    if (professionalIds[0]) {
      try {
        const professionalSchedule = await fetchProfessionalWorkingSchedule(clinicId, professionalIds[0]);
        const schedule = professionalSchedule?.workSchedule || {};
        sessionBufferMinutes = Math.round(asSafeNumber((schedule as any)?.sessionBufferMinutes ?? (schedule as any)?.session_buffer_minutes, 0, 120) ?? sessionBufferMinutes);
      } catch (error: any) {
        console.warn('[Calendar] session buffer fallback used:', error?.message || String(error));
      }
    }

    if (locationType === 'clinica' && !roomId) {
      return {
        hasConflict: true,
        blocking: true,
        conflicts: [{
          conflictType: 'room',
          blocking: true,
          humanMessage: 'Selecione uma sala da clinica para este atendimento.'
        }],
        humanMessage: 'Selecione uma sala da clinica para este atendimento.'
      };
    }

    const tableAppointments = await fetchConflictAppointmentsFromTable({
      clinicId,
      organizationId,
      input: {
        ...parsedDates,
        patientId,
        professionalIds,
        roomId
      }
    });
    const stateAppointments = await fetchConflictAppointmentsFromState(clinicId, {
      ...parsedDates,
      patientId,
      professionalIds,
      roomId
    }).catch(() => []);
    let institutionalEvents: any[] = [];
    const conflictDateKeys = (parsedDates.recurrenceDates.length > 0 ? parsedDates.recurrenceDates : [parsedDates.date])
      .map((value: any) => sanitizeDate(value))
      .filter(Boolean)
      .sort();
    if (conflictDateKeys.length > 0) {
      const institutionalFrom = new Date(`${conflictDateKeys[0]}T00:00:00-03:00`).toISOString();
      const institutionalToDate = new Date(`${conflictDateKeys[conflictDateKeys.length - 1]}T00:00:00-03:00`);
      institutionalToDate.setUTCDate(institutionalToDate.getUTCDate() + 1);
      const meetingsResult = await supabase
        .from('school_meetings')
        .select('id,title,meeting_type,status,scheduled_start,scheduled_end,responsible_professional_id,school_id,school_unit_id,location_type,timezone')
        .eq('organization_id', organizationId)
        .eq('clinic_id', clinicId)
        .in('status', ['SCHEDULED', 'CONFIRMED', 'RESCHEDULED'])
        .gte('scheduled_start', institutionalFrom)
        .lt('scheduled_start', institutionalToDate.toISOString())
        .limit(1000);
      if (!meetingsResult.error && (meetingsResult.data || []).length > 0) {
        const meetingIds = (meetingsResult.data || []).map((meeting: any) => meeting.id);
        const [patientLinks, participantLinks] = await Promise.all([
          supabase
            .from('school_meeting_patients')
            .select('meeting_id,patient_id')
            .eq('organization_id', organizationId)
            .in('meeting_id', meetingIds)
            .neq('participation_status', 'REMOVED'),
          supabase
            .from('school_meeting_participants')
            .select('meeting_id,professional_id')
            .eq('organization_id', organizationId)
            .in('meeting_id', meetingIds)
            .is('removed_at', null),
        ]);
        if (patientLinks.error) throw patientLinks.error;
        if (participantLinks.error) throw participantLinks.error;
        const patientsByMeeting = new Map<string, string[]>();
        const professionalsByMeeting = new Map<string, string[]>();
        for (const link of patientLinks.data || []) {
          const key = sanitizeString(link.meeting_id, 120);
          patientsByMeeting.set(key, [...(patientsByMeeting.get(key) || []), sanitizeString(link.patient_id, 120)].filter(Boolean));
        }
        for (const link of participantLinks.data || []) {
          const key = sanitizeString(link.meeting_id, 120);
          professionalsByMeeting.set(key, [...(professionalsByMeeting.get(key) || []), sanitizeString(link.professional_id, 120)].filter(Boolean));
        }
        institutionalEvents = (meetingsResult.data || []).flatMap((meeting: any) => {
          const meetingId = sanitizeString(meeting.id, 120);
          const meetingPatientIds = patientsByMeeting.get(meetingId) || [];
          const meetingProfessionalIds = Array.from(new Set([
            sanitizeString(meeting.responsible_professional_id, 120),
            ...(professionalsByMeeting.get(meetingId) || []),
          ].filter(Boolean)));
          const patientRows = meetingPatientIds.length > 0 ? meetingPatientIds : [null];
          return patientRows.map((meetingPatientId: string | null, index: number) => ({
            id: `${meetingId}:institutional:${index}`,
            source: 'school_meeting',
            type: sanitizeString(meeting.title || meeting.meeting_type, 180) || 'Compromisso escolar',
            status: 'scheduled',
            patient_id: meetingPatientId,
            patientId: meetingPatientId,
            professional_ids: meetingProfessionalIds,
            professionalIds: meetingProfessionalIds,
            therapist_id: meeting.responsible_professional_id || meetingProfessionalIds[0] || null,
            scheduled_at: meeting.scheduled_start,
            scheduled_start_at: meeting.scheduled_start,
            scheduled_end_at: meeting.scheduled_end,
            start_time: meeting.scheduled_start,
            end_time: meeting.scheduled_end,
            location_type: 'escola',
            care_setting: 'SCHOOL',
            school_id: meeting.school_id,
            school_unit_id: meeting.school_unit_id,
            timezone: meeting.timezone || 'America/Sao_Paulo',
          }));
        });
      } else if (meetingsResult.error && !isMissingRelationError(meetingsResult.error)) {
        throw meetingsResult.error;
      }
    }
    const appointmentsById = new Map<string, any>();
    [...stateAppointments, ...tableAppointments, ...institutionalEvents].forEach((appointment: any, index: number) => {
      appointmentsById.set(sanitizeString(appointment?.id, 180) || `idx-${index}`, appointment);
    });
    const appointments = Array.from(appointmentsById.values());
    const rooms = await fetchConflictRooms(clinicId, organizationId).catch(() => []);

    const result = checkLocalScheduleConflicts({
      appointments,
      patient_id: patientId,
      patient_name: rawInput?.patient_name || rawInput?.patientName,
      professional_ids: professionalIds,
      professional_names: professionalNames,
      room_id: locationType === 'clinica' ? roomId : '',
      room_name: roomName,
      rooms,
      location_type: locationType,
      date: parsedDates.date,
      start_time: parsedDates.startTime,
      end_time: parsedDates.endTime,
      duration_minutes: parsedDates.duration,
      session_buffer_minutes: sessionBufferMinutes,
      exclude_event_id: rawInput?.exclude_event_id || rawInput?.excludeEventId,
      exclude_event_ids: Array.isArray(rawInput?.exclude_event_ids)
        ? rawInput.exclude_event_ids
        : Array.isArray(rawInput?.excludeEventIds)
          ? rawInput.excludeEventIds
          : [],
      recurrence_dates: parsedDates.recurrenceDates
    });

    if (parsedDates.recurrenceDates.length > 1 && result.hasConflict) {
      const conflictDates = new Set(result.conflicts.map((conflict: any) => conflict.date).filter(Boolean));
      return {
        ...result,
        humanMessage: `${conflictDates.size} das ${parsedDates.recurrenceDates.length} sessoes recorrentes possuem conflito. ${result.humanMessage}`
      };
    }
    return result;
  };

  const PORTAL_SESSION_CONSENT_TEXT_VERSION = 'responsible-session-acceptance-v1';
  const PORTAL_SESSION_CONSENT_TEXT = 'Confirmo que a sessão descrita foi realizada e que estou ciente das informações registradas pela clínica.';

  const portalSafeError = (status = 500) => ({
    success: false,
    error:
      status === 400
        ? 'Dados inválidos para esta ação.'
        : status === 403 || status === 404
          ? 'Sessão não encontrada para este acesso.'
          : status === 409
            ? 'Esta ação não está disponível para a sessão atual.'
            : 'Não foi possível concluir a ação agora.'
  });

  const hashOperationalValue = (value: unknown) => {
    const safe = sanitizeString(value, 1200);
    if (!safe) return null;
    const pepper = sanitizeString(process.env.SESSION_SECRET || process.env.SUPABASE_SERVICE_ROLE_KEY || 'verto-local', 500);
    return crypto.createHash('sha256').update(`${pepper}:${safe}`).digest('hex');
  };

  const isResponsiblePortalRole = (role: unknown) =>
    ['patient', 'responsible', 'responsavel', 'guardian'].includes(sanitizeString(role, 40).toLowerCase());

  const readClinicPatientReschedulePolicy = async (clinicIdValue: unknown) => {
    const clinicId = sanitizeString(clinicIdValue, 120);
    if (!isUuid(clinicId)) return true;
    const result = await supabase
      .from('clinics')
      .select('allow_patient_reschedule')
      .eq('id', clinicId)
      .limit(1)
      .maybeSingle();
    if (result.error) {
      if (extractMissingColumnName(result.error) === 'allow_patient_reschedule') return true;
      throw result.error;
    }
    return result.data?.allow_patient_reschedule !== false;
  };

  const readClinicPatientReschedulePolicies = async (clinicIdsValue: unknown[]) => {
    const clinicIds = Array.from(new Set(
      (Array.isArray(clinicIdsValue) ? clinicIdsValue : [])
        .map((value) => sanitizeString(value, 120))
        .filter((value) => isUuid(value))
    ));
    const policies = new Map<string, boolean>(clinicIds.map((clinicId) => [clinicId, true]));
    if (clinicIds.length === 0) return policies;
    const result = await supabase
      .from('clinics')
      .select('id,allow_patient_reschedule')
      .in('id', clinicIds)
      .limit(clinicIds.length);
    if (result.error) {
      if (extractMissingColumnName(result.error) === 'allow_patient_reschedule') return policies;
      throw result.error;
    }
    for (const row of result.data || []) {
      policies.set(sanitizeString(row?.id, 120), row?.allow_patient_reschedule !== false);
    }
    return policies;
  };

  const portalAllowedActions = (allowPatientReschedule: boolean) => ({
    canConfirm: true,
    canCancel: true,
    canRequestReschedule: allowPatientReschedule
  });

  const patientRescheduleDisabledResponse = () => ({
    success: false,
    error: 'PATIENT_RESCHEDULE_DISABLED',
    code: 'PATIENT_RESCHEDULE_DISABLED',
    message: 'Esta clínica não aceita novas solicitações de reagendamento pelo portal. Você ainda pode confirmar ou cancelar a sessão.'
  });

  const sanitizePortalRoomName = (value: unknown) => {
    const room = sanitizeString(value, 180);
    if (!room) return '';
    if (isUuid(room) || /^clinic_room[_-]/i.test(room)) return '';
    return room;
  };

  const getPortalPatientIdsForUser = async (user: any) => {
    const userId = sanitizeString(user?.id, 120);
    const userEmail = sanitizeEmail(user?.email);
    const clinicId = sanitizeString(currentClinicId(user), 120);
    const ids = await resolvePatientIdsForPush({
      supabase,
      patientEmail: userEmail,
      userId,
      clinicId
    });
    const appendLinkedPatientIds = async (column: 'responsible_user_id' | 'responsible_email', value: string) => {
      if (!value) return;
      let query = supabase
        .from('patients')
        .select('id')
        .eq(column, value)
        .eq('is_active', true)
        .is('deleted_at', null)
        .limit(50);
      if (isUuid(clinicId)) query = query.eq('clinic_id', clinicId);
      const { data, error } = await query;
      if (error) {
        const missingColumn = extractMissingColumnName(error);
        if (missingColumn === column) return;
        throw error;
      }
      (Array.isArray(data) ? data : []).forEach((row: any) => {
        const id = sanitizeString(row?.id, 120);
        if (isUuid(id)) ids.push(id);
      });
    };
    if (isUuid(userId)) await appendLinkedPatientIds('responsible_user_id', userId);
    if (userEmail) await appendLinkedPatientIds('responsible_email', userEmail);
    if (isUuid(userId)) {
      const direct = await supabase
        .from('patients')
        .select('id')
        .eq('id', userId)
        .eq('is_active', true)
        .is('deleted_at', null)
        .limit(1)
        .maybeSingle();
      if (!direct.error && direct.data?.id) ids.push(sanitizeString(direct.data.id, 120));
    }
    return Array.from(new Set(ids.filter((id) => isUuid(id)))).slice(0, 50);
  };

  const resolvePatientPortalContext = async (user: any) => {
    const patientIds = await getPortalPatientIdsForUser(user);
    if (patientIds.length === 0) {
      return {
        resolvedPatientId: null,
        resolvedPatientEmail: sanitizeEmail(user?.email) || null,
        patientName: null,
        portalDisplayName: null,
        responsibleUserId: sanitizeString(user?.id, 120) || null,
        responsibleEmail: sanitizeEmail(user?.email) || null,
        clinicId: sanitizeString(currentClinicId(user), 120) || null,
        clinicName: null,
        clinicLegalName: null,
        clinicLogoUrl: null,
        portalType: sanitizeString(user?.type || user?.portalType, 80) || null,
        patientProfileType: null,
        patientIds: []
      };
    }

    const primaryPatientId = patientIds[0];
    let patientRead = await supabase
      .from('patients')
      .select('id,email,clinic_id,name,type,patient_profile_type,panel_type,profile_type,responsible_user_id,responsible_email,metadata')
      .eq('id', primaryPatientId)
      .limit(1)
      .maybeSingle();
    if (patientRead.error && extractMissingColumnName(patientRead.error)) {
      patientRead = await supabase
        .from('patients')
        .select('id,email,clinic_id,name,type,responsible_user_id,responsible_email,metadata')
        .eq('id', primaryPatientId)
        .limit(1)
        .maybeSingle();
    }
    if (patientRead.error && extractMissingColumnName(patientRead.error)) {
      patientRead = await supabase
        .from('patients')
        .select('id,email,clinic_id,name')
        .eq('id', primaryPatientId)
        .limit(1)
        .maybeSingle();
    }
    if (patientRead.error && !extractMissingColumnName(patientRead.error)) throw patientRead.error;
    const patient = patientRead.data;
    const row = patient || { id: primaryPatientId };
    const clinicId = sanitizeString(row?.clinic_id || currentClinicId(user), 120);
    const clinicBranding = await readClinicBrandingForFamilyView(clinicId);
    const portalDisplayName = resolvePortalPatientDisplayName(row, user?.name);
    return {
      resolvedPatientId: sanitizeString(row?.id || primaryPatientId, 120),
      resolvedPatientEmail: sanitizeEmail(row?.email) || sanitizeEmail(user?.email) || null,
      patientName: portalDisplayName,
      portalDisplayName,
      responsibleUserId: sanitizeString(row?.responsible_user_id || user?.id, 120) || null,
      responsibleEmail: sanitizeEmail(row?.responsible_email || user?.email) || null,
      clinicId: clinicBranding.id || (isUuid(clinicId) ? clinicId : null),
      clinicName: clinicBranding.displayName !== 'Clínica' ? clinicBranding.displayName : null,
      clinicLegalName: null,
      clinicLogoUrl: clinicBranding.logoUrl,
      portalType: sanitizeString(user?.portalType || user?.type || row?.panel_type || row?.type, 80) || null,
      patientProfileType: sanitizeString(row?.patient_profile_type || row?.profile_type || row?.type, 80) || null,
      patientIds
    };
  };

  app.get('/api/portal/context', checkAuth, requireRoles('patient'), async (req: any, res) => {
    try {
      const context = await resolvePatientPortalContext(req.session.user);
      return res.json({ success: true, data: context });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/portal/context [GET]', error, {
        requestId: requestIdForLogs(req)
      });
    }
  });

  const readPortalAppointmentPatientScope = (appointment: any) => {
    const source = parseCalendarSourcePayload(appointment?.source_payload || appointment?.sourcePayload);
    return {
      patientId: sanitizeString(appointment?.patient_id || appointment?.patientId || source?.patient_id || source?.patientId, 120),
      patientEmail: sanitizeEmail(appointment?.patient_email || appointment?.patientEmail || source?.patient_email || source?.patientEmail),
      responsibleEmail: sanitizeEmail(source?.responsible_email || source?.responsibleEmail || source?.guardianEmail || source?.guardian_email)
    };
  };

  const normalizePortalNotificationType = (value: unknown) =>
    sanitizeString(value, 80).replace(/_(24h|12h)$/i, '') || 'appointment_reminder';

  const isPatientAppointmentNotificationActionable = (appointment: any, notification?: any) => {
    if (normalizePortalNotificationType(notification?.type) !== 'appointment_reminder') return true;
    if (!appointment?.id) return false;
    const source = parseCalendarSourcePayload(appointment?.source_payload || appointment?.sourcePayload);
    const appointmentStatus = normalizeOperationalAppointmentStatus(appointment?.status || appointment?.appointment_status || source?.status);
    const confirmationSnapshot = resolveAppointmentConfirmationSnapshot(appointment, source);
    const responseStatus = normalizeOperationalAppointmentStatus(
      confirmationSnapshot.confirmationStatus ?? confirmationSnapshot.response
    );
    const nonActionableStatuses = new Set([
      'CONFIRMED',
      'CANCELLED',
      'COMPLETED',
      'NO_SHOW',
      'RESCHEDULE_REQUESTED',
      'CANCEL_REQUESTED',
      'DECLINED',
      'REFUSED'
    ]);
    if (nonActionableStatuses.has(appointmentStatus) || nonActionableStatuses.has(responseStatus)) return false;
    const notificationMetadata = parseStoredJsonObject(notification?.metadata);
    const notificationAppointmentStart = sanitizeIsoDateTime(
      notificationMetadata.scheduledAt ||
      notificationMetadata.scheduled_at ||
      notification?.appointment_scheduled_at ||
      notification?.appointmentScheduledAt
    );
    const currentAppointmentStart = sanitizeIsoDateTime(
      appointment?.scheduled_start_at ||
      appointment?.scheduledStartAt ||
      appointment?.scheduled_at ||
      appointment?.scheduledAt ||
      source?.scheduled_start_at ||
      source?.scheduledStartAt ||
      source?.scheduled_at ||
      source?.scheduledAt
    );
    if (
      notificationAppointmentStart && currentAppointmentStart &&
      Math.abs(new Date(notificationAppointmentStart).getTime() - new Date(currentAppointmentStart).getTime()) >= 60_000
    ) {
      return false;
    }
    if (
      appointment?.patient_responded_at ||
      appointment?.patientRespondedAt ||
      appointment?.patient_confirmation_at ||
      appointment?.patientConfirmationAt ||
      appointment?.confirmed_at ||
      appointment?.confirmedAt ||
      appointment?.cancel_requested_at ||
      appointment?.cancelRequestedAt ||
      appointment?.reschedule_requested_at ||
      appointment?.rescheduleRequestedAt
    ) {
      return false;
    }
    const scheduledAt = sanitizeString(
      appointment?.scheduled_start_at ||
        appointment?.scheduledStartAt ||
        appointment?.scheduled_at ||
        appointment?.scheduledAt ||
        source?.scheduled_start_at ||
        source?.scheduledStartAt ||
        source?.scheduled_at ||
        source?.scheduledAt,
      120
    );
    const parsedStart = scheduledAt ? new Date(scheduledAt) : null;
    if (parsedStart && !Number.isNaN(parsedStart.getTime())) {
      const durationMinutes = Number(
        appointment?.scheduled_duration_minutes ||
          appointment?.scheduledDurationMinutes ||
          appointment?.duration_minutes ||
          appointment?.durationMinutes ||
          source?.duration_minutes ||
          source?.durationMinutes ||
          90
      ) || 90;
      const actionWindowEndedAt = parsedStart.getTime() + Math.max(30, durationMinutes) * 60_000;
      if (actionWindowEndedAt < Date.now()) return false;
    }
    return true;
  };

  const queryPortalAppointmentsWithSchemaFallback = async (
    buildQuery: (selectColumns: string) => PromiseLike<any>,
    stage: string
  ) => {
    const knownMissingColumns = new Set([
      ...(appointmentActionSchemaState.missingCriticalColumns || []),
      ...(appointmentActionSchemaState.missingApprovalColumns || []),
      ...(appointmentActionSchemaState.missingOptionalColumns || [])
    ]);
    let columns = PORTAL_APPOINTMENT_SELECT
      .split(',')
      .map((column) => column.trim())
      .filter((column) => Boolean(column) && !knownMissingColumns.has(column));
    const removedColumns = new Set<string>();
    for (let attempt = 0; attempt < 24 && columns.length > 1; attempt += 1) {
      const result = await buildQuery(columns.join(','));
      if (!result?.error) return result;
      const missingColumn = extractMissingColumnName(result.error);
      if (!missingColumn || missingColumn === 'id' || removedColumns.has(missingColumn) || !columns.includes(missingColumn)) {
        return result;
      }
      removedColumns.add(missingColumn);
      columns = columns.filter((column) => column !== missingColumn);
      console.warn('[PortalAppointments] optional column unavailable', {
        stage,
        removedColumn: missingColumn
      });
    }
    return buildQuery(columns.join(','));
  };

  const readPortalPatientContexts = async (rawPatientIds: unknown[]) => {
    const patientIds = Array.from(new Set(
      (Array.isArray(rawPatientIds) ? rawPatientIds : [])
        .map((id) => sanitizeString(id, 120))
        .filter((id) => isUuid(id))
    )).slice(0, 200);
    if (patientIds.length === 0) return { data: [] as any[], error: null };

    let columns = ['id', 'name', 'email', 'clinic_id', 'responsible_user_id', 'responsible_email', 'metadata'];
    const removedColumns = new Set<string>();
    for (let attempt = 0; attempt < 6 && columns.length > 1; attempt += 1) {
      const result = await supabase
        .from('patients')
        .select(columns.join(','))
        .in('id', patientIds)
        .limit(patientIds.length);
      if (!result.error) return result;
      const missingColumn = extractMissingColumnName(result.error);
      if (!missingColumn || missingColumn === 'id' || removedColumns.has(missingColumn) || !columns.includes(missingColumn)) {
        return result;
      }
      removedColumns.add(missingColumn);
      columns = columns.filter((column) => column !== missingColumn);
    }
    return supabase
      .from('patients')
      .select(columns.join(','))
      .in('id', patientIds)
      .limit(patientIds.length);
  };

  const canPortalUserAccessPatient = async (patientId: string, appointment: any, user: any) => {
    const role = sanitizeString(user?.role, 40).toLowerCase();
    const appointmentScope = readPortalAppointmentPatientScope(appointment);
    const scopedPatientId = sanitizeString(patientId || appointmentScope.patientId, 120);
    if (!isResponsiblePortalRole(role)) {
      if (!isUuid(scopedPatientId)) return false;
      return canAccessPatientInCurrentClinic(scopedPatientId, user);
    }
    const userId = sanitizeString(user?.id, 120);
    const userEmail = sanitizeEmail(user?.email);
    if (scopedPatientId === userId) return true;
    if (
      userEmail &&
      (appointmentScope.patientEmail === userEmail || appointmentScope.responsibleEmail === userEmail)
    ) return true;
    if (!isUuid(scopedPatientId)) return false;
    const patientIds = await getPortalPatientIdsForUser(user);
    return patientIds.includes(scopedPatientId);
  };

  const fetchPortalAppointmentForUser = async (
    appointmentId: string,
    user: any,
    persistedScope?: { patientId?: unknown; organizationId?: unknown }
  ) => {
    const safeAppointmentId = sanitizeString(appointmentId, 120);
    if (!isUuid(safeAppointmentId)) return { ok: false, status: 400, error: 'Sessão inválida.' };
    const { data, error } = await queryPortalAppointmentsWithSchemaFallback(
      (selectColumns) =>
        supabase
          .from('appointments')
          .select(selectColumns)
          .eq('id', safeAppointmentId)
          .limit(1)
          .maybeSingle(),
      'appointment_detail'
    );
    if (error) {
      if (hasMissingFinancialSchema(error)) return { ok: false, status: 503, error: 'Agenda indisponível.' };
      throw error;
    }
    if (!data?.id) return { ok: false, status: 404, error: 'Sessão não encontrada.' };
    const source = parseAppointmentSourcePayloadForFamilyView(data?.source_payload || data?.sourcePayload);
    const appointmentPatientId = sanitizeString(data.patient_id || source?.patient_id || source?.patientId, 120);
    const trustedPatientId = sanitizeString(persistedScope?.patientId, 120);
    const appointmentOrganizationId = sanitizeString(
      data.organization_id || data.clinic_id || source?.organization_id || source?.organizationId || source?.clinic_id || source?.clinicId,
      120
    );
    const trustedOrganizationId = sanitizeString(persistedScope?.organizationId, 120);
    if (
      (appointmentPatientId && trustedPatientId && appointmentPatientId !== trustedPatientId) ||
      (appointmentOrganizationId && trustedOrganizationId && appointmentOrganizationId !== trustedOrganizationId)
    ) {
      return { ok: false, status: 404, error: 'Sessão não encontrada.' };
    }
    const patientId = appointmentPatientId || trustedPatientId;
    const organizationId = appointmentOrganizationId || trustedOrganizationId;
    const clinicId = sanitizeString(
      data.clinic_id || source?.clinic_id || source?.clinicId || currentClinicId(user) || organizationId,
      120
    );
    const scopedAppointment = {
      ...data,
      patient_id: patientId || data.patient_id,
      organization_id: organizationId || data.organization_id,
      clinic_id: clinicId || data.clinic_id
    };
    if (!(await canPortalUserAccessPatient(patientId, scopedAppointment, user))) {
      return { ok: false, status: 404, error: 'Sessão não encontrada.' };
    }
    return { ok: true, appointment: scopedAppointment };
  };

  app.get('/api/portal/notifications', checkAuth, async (req: any, res) => {
    try {
      const userId = sanitizeString(req.session.user?.id, 120);
      const userEmail = sanitizeEmail(req.session.user?.email);
      const patientIds = await getPortalPatientIdsForUser(req.session.user);
      const limit = parseBoundedListLimit(req.query?.limit, 12, 50);
      if (patientIds.length === 0 || (!isUuid(userId) && !userEmail)) {
        return res.json({ success: true, data: [], pagination: { limit, hasMore: false } });
      }

      let query = supabase
        .from('portal_notifications')
        .select('id, organization_id, clinic_id, patient_id, appointment_id, type, title, message, read_at, acknowledged_at, sent_at, scheduled_for, created_at, metadata')
        .in('patient_id', patientIds)
        .is('acknowledged_at', null)
        .order('created_at', { ascending: false })
        .limit(Math.min(200, limit * 4 + 1));
      if (isUuid(userId) && userEmail) {
        query = query.or(`recipient_user_id.eq.${userId},recipient_email.eq.${userEmail}`);
      } else if (isUuid(userId)) {
        query = query.eq('recipient_user_id', userId);
      } else {
        query = query.eq('recipient_email', userEmail);
      }

      const { data, error } = await query;
      if (error) {
        if (isMissingRelationError(error)) {
          return res.json({ success: true, data: [], pagination: { limit, hasMore: false } });
        }
        throw error;
      }
      const rows = Array.isArray(data) ? data : [];
      const appointmentContextById = new Map<string, {
        clinicId: string;
        patientId: string;
        patientName: string;
        scheduledAt: string;
        appointment: any;
      }>();
      const notificationAppointmentIds = Array.from(new Set(
        rows.map((row: any) => sanitizeString(row?.appointment_id, 120)).filter((id: string) => isUuid(id))
      ));
      if (notificationAppointmentIds.length > 0) {
        const appointmentResult = await queryPortalAppointmentsWithSchemaFallback(
          (selectColumns) =>
            supabase
              .from('appointments')
              .select(selectColumns)
              .in('id', notificationAppointmentIds)
              .limit(Math.min(notificationAppointmentIds.length, 200)),
          'portal_notifications'
        );
        if (!appointmentResult.error) {
          for (const appointment of Array.isArray(appointmentResult.data) ? appointmentResult.data : []) {
            const id = sanitizeString(appointment?.id, 120);
            if (!isUuid(id)) continue;
            const source = parseAppointmentSourcePayloadForFamilyView(appointment?.source_payload || appointment?.sourcePayload);
            appointmentContextById.set(id, {
              clinicId: sanitizeString(appointment?.clinic_id || source?.clinic_id || source?.clinicId, 120),
              patientId: sanitizeString(appointment?.patient_id || source?.patient_id || source?.patientId, 120),
              patientName: sanitizeString(source?.patientName || source?.patient_name || source?.name, 160),
              scheduledAt: sanitizeString(appointment?.scheduled_at || appointment?.scheduled_start_at || source?.scheduledAt || source?.scheduled_at, 120),
              appointment
            });
          }
        } else if (!extractMissingColumnName(appointmentResult.error)) {
          throw appointmentResult.error;
        }
      }
      const patientNamesById = new Map<string, string>();
      const patientClinicIdsById = new Map<string, string>();
      const notificationPatientIds = Array.from(new Set(
        rows.flatMap((row: any) => {
          const metadata = parseStoredJsonObject(row?.metadata);
          const appointmentId = sanitizeString(row?.appointment_id, 120);
          const appointmentContext = appointmentContextById.get(appointmentId);
          return [
            row?.patient_id,
            metadata.patientId,
            metadata.patient_id,
            appointmentContext?.patientId
          ];
        }).map((id: any) => sanitizeString(id, 120)).filter((id: string) => isUuid(id))
      ));
      if (notificationPatientIds.length > 0) {
        const patientResult = await readPortalPatientContexts(notificationPatientIds);
        if (!patientResult.error) {
          for (const patient of Array.isArray(patientResult.data) ? patientResult.data : []) {
            const id = sanitizeString(patient?.id, 120);
            const name = resolvePortalPatientDisplayName(patient);
            const clinicId = sanitizeString(patient?.clinic_id, 120);
            if (id && name && !isGenericCalendarPatientName(name)) patientNamesById.set(id, name);
            if (id && isUuid(clinicId)) patientClinicIdsById.set(id, clinicId);
          }
        } else if (!extractMissingColumnName(patientResult.error)) {
          throw patientResult.error;
        }
      }

      const clinicBrandingById = new Map<string, { displayName: string; logoUrl: string | null }>();
      const resolveNotificationClinicBranding = async (rawClinicId: unknown) => {
        const clinicId = sanitizeString(rawClinicId, 120);
        if (!isUuid(clinicId)) return { displayName: 'Clínica', logoUrl: null };
        if (clinicBrandingById.has(clinicId)) return clinicBrandingById.get(clinicId)!;
        const branding = await readClinicBrandingForFamilyView(clinicId);
        const resolved = {
          displayName: sanitizeString(branding.displayName, 160) || 'Clínica',
          logoUrl: sanitizeClinicBrandImageUrl(branding.logoUrl) || null
        };
        clinicBrandingById.set(clinicId, resolved);
        return resolved;
      };

      const notificationClinicIds = Array.from(new Set(
        rows.map((row: any) => {
          const metadata = parseStoredJsonObject(row?.metadata);
          const appointmentContext = appointmentContextById.get(sanitizeString(row?.appointment_id, 120));
          const patientId = sanitizeString(row?.patient_id || metadata.patientId || appointmentContext?.patientId, 120);
          return sanitizeString(
            patientClinicIdsById.get(patientId) ||
              appointmentContext?.clinicId ||
              row?.clinic_id ||
              metadata.clinicId ||
              row?.organization_id,
            120
          );
        }).filter((clinicId: string) => isUuid(clinicId))
      ));
      const policyByClinicId = await readClinicPatientReschedulePolicies(notificationClinicIds);

      const formatPortalReminderMessage = (row: any, patientName: string, canRequestReschedule: boolean) => {
        const metadata = parseStoredJsonObject(row?.metadata);
        const scheduledAt = sanitizeString(metadata.scheduledAt || row?.scheduled_for, 120);
        const date = new Date(scheduledAt || '');
        const actionCopy = canRequestReschedule
          ? 'Toque aqui para confirmar, cancelar ou solicitar reagendamento.'
          : 'Toque aqui para confirmar ou cancelar a sessão.';
        if (Number.isNaN(date.getTime())) {
          return `Lembrete de sessão de ${patientName}. ${actionCopy}`;
        }
        const shortDate = date.toLocaleDateString('pt-BR', {
          timeZone: 'America/Sao_Paulo',
          day: '2-digit',
          month: '2-digit'
        });
        const todayKey = new Intl.DateTimeFormat('en-CA', {
          timeZone: 'America/Sao_Paulo',
          year: 'numeric',
          month: '2-digit',
          day: '2-digit'
        }).format(new Date());
        const targetKey = new Intl.DateTimeFormat('en-CA', {
          timeZone: 'America/Sao_Paulo',
          year: 'numeric',
          month: '2-digit',
          day: '2-digit'
        }).format(date);
        const todayStart = new Date(`${todayKey}T00:00:00-03:00`).getTime();
        const targetStart = new Date(`${targetKey}T00:00:00-03:00`).getTime();
        const diffDays = Math.round((targetStart - todayStart) / 86400000);
        const relative = diffDays === 0 ? ' (hoje)' : diffDays === 1 ? ' (amanhã)' : '';
        const time = date.toLocaleTimeString('pt-BR', {
          timeZone: 'America/Sao_Paulo',
          hour: '2-digit',
          minute: '2-digit'
        });
        return `Lembrete de sessão de ${patientName} dia ${shortDate}${relative} às ${time}. ${actionCopy}`;
      };

      const normalizedRows: any[] = [];
      for (const row of rows) {
        const metadata = parseStoredJsonObject(row?.metadata);
        const appointmentId = sanitizeString(row?.appointment_id, 120);
        const appointmentContext = appointmentContextById.get(appointmentId);
        if (
          normalizePortalNotificationType(row?.type) === 'appointment_reminder' &&
          (!appointmentContext?.appointment || !isPatientAppointmentNotificationActionable(appointmentContext.appointment, row))
        ) {
          continue;
        }
        const patientId = sanitizeString(row?.patient_id || metadata.patientId || metadata.patient_id || appointmentContext?.patientId, 120);
        const clinicId = sanitizeString(
          patientClinicIdsById.get(patientId) ||
            appointmentContext?.clinicId ||
            row?.clinic_id ||
            metadata.clinicId ||
            metadata.clinic_id ||
            row?.organization_id,
          120
        );
        const canRequestReschedule = policyByClinicId.get(clinicId) !== false;
        const branding = await resolveNotificationClinicBranding(clinicId);
        const metadataPatientName = sanitizeString(metadata.patientName || metadata.patient_name, 160);
        const appointmentPatientName = sanitizeString(appointmentContext?.patientName, 160);
        const patientName =
          patientNamesById.get(patientId) ||
          (!isGenericCalendarPatientName(appointmentPatientName) ? appointmentPatientName : '') ||
          (!isGenericCalendarPatientName(metadataPatientName) ? metadataPatientName : '') ||
          'Paciente não identificado';
        const scheduledAt = sanitizeString(appointmentContext?.scheduledAt || metadata.scheduledAt || row?.scheduled_for, 120);
        const normalizedMetadata = {
          ...metadata,
          clinicName: branding.displayName,
          clinicLogoUrl: branding.logoUrl || sanitizeClinicBrandImageUrl(metadata.clinicLogoUrl) || null,
          patientName,
          scheduledAt: scheduledAt || metadata.scheduledAt || null,
          allowedActions: portalAllowedActions(canRequestReschedule)
        };
        normalizedRows.push({
          ...row,
          patient_id: patientId || row?.patient_id,
          patientName,
          patient_name: patientName,
          clinic_id: isUuid(clinicId) ? clinicId : row?.clinic_id,
          clinicName: branding.displayName,
          clinic_name: branding.displayName,
          clinicLogoUrl: normalizedMetadata.clinicLogoUrl,
          clinic_logo_url: normalizedMetadata.clinicLogoUrl,
          clinic: {
            id: isUuid(clinicId) ? clinicId : null,
            displayName: branding.displayName,
            logoUrl: normalizedMetadata.clinicLogoUrl
          },
          scheduled_for: scheduledAt || row?.scheduled_for,
          title: branding.displayName,
          message: normalizePortalNotificationType(row?.type) === 'appointment_reminder'
            ? formatPortalReminderMessage({ ...row, scheduled_for: scheduledAt, metadata: normalizedMetadata }, patientName, canRequestReschedule)
            : sanitizeTextField(row?.message, 1000) || 'Atualização da sua sessão disponível.',
          metadata: normalizedMetadata
        });
      }

      const dedupedRowsByAppointment = new Map<string, any>();
      for (const row of normalizedRows) {
        const appointmentId = sanitizeString(row?.appointment_id, 120);
        const patientId = sanitizeString(row?.patient_id, 120);
        const type = sanitizeString(row?.type, 80).replace(/_(24h|12h)$/i, '');
        const metadata = parseStoredJsonObject(row?.metadata);
        const eventScheduledAt = sanitizeIsoDateTime(
          metadata.scheduledAt || metadata.scheduled_at || row?.scheduled_for
        );
        const groupKey = type === 'appointment_reschedule_approved' && patientId && eventScheduledAt
          ? [
              sanitizeString(row?.clinic_id || row?.organization_id, 120),
              patientId,
              type,
              eventScheduledAt
            ].join(':')
          : appointmentId
          ? [
              sanitizeString(row?.clinic_id || row?.organization_id, 120),
              patientId,
              appointmentId,
              type || 'appointment_reminder'
            ].join(':')
          : sanitizeString(row?.id, 120);
        if (!groupKey || dedupedRowsByAppointment.has(groupKey)) continue;
        dedupedRowsByAppointment.set(groupKey, row);
      }
      const dedupedRows = Array.from(dedupedRowsByAppointment.values())
        .sort((a: any, b: any) => new Date(b?.created_at || b?.sent_at || 0).getTime() - new Date(a?.created_at || a?.sent_at || 0).getTime());
      const latestPendingAppointmentReminder = dedupedRows.find((row: any) =>
        sanitizeString(row?.type, 80).replace(/_(24h|12h)$/i, '') === 'appointment_reminder'
      );
      const visibleRows = latestPendingAppointmentReminder
        ? [latestPendingAppointmentReminder]
        : dedupedRows.slice(0, limit);
      return res.json({
        success: true,
        data: visibleRows,
        pagination: { limit, hasMore: dedupedRows.length > limit || normalizedRows.length > limit * 4 }
      });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/portal/notifications [GET]', error, {
        requestId: requestIdForLogs(req)
      });
    }
  });

  app.patch('/api/portal/notifications/:notificationId', checkAuth, portalActionLimiter, async (req: any, res) => {
    try {
      const notificationId = sanitizeString(req.params.notificationId, 120);
      const userId = sanitizeString(req.session.user?.id, 120);
      const userEmail = sanitizeEmail(req.session.user?.email);
      if (!isUuid(notificationId)) {
        return res.status(400).json({ success: false, error: 'Notificação inválida.' });
      }
      const { data: existing, error: existingError } = await supabase
        .from('portal_notifications')
        .select('id, organization_id, clinic_id, patient_id, appointment_id, recipient_user_id, recipient_email, type, scheduled_for, read_at, acknowledged_at, metadata')
        .eq('id', notificationId)
        .limit(1)
        .maybeSingle();
      if (existingError) {
        if (isMissingRelationError(existingError)) {
          return res.status(404).json({ success: false, error: 'Notificação não encontrada.' });
        }
        throw existingError;
      }
      const patientIds = await getPortalPatientIdsForUser(req.session.user);
      const belongsToRecipient =
        (isUuid(userId) && sanitizeString(existing?.recipient_user_id, 120) === userId) ||
        (userEmail && sanitizeEmail(existing?.recipient_email) === userEmail);
      if (!existing?.id || !patientIds.includes(sanitizeString(existing.patient_id, 120)) || !belongsToRecipient) {
        return res.status(404).json({ success: false, error: 'Notificação não encontrada.' });
      }
      const now = new Date().toISOString();
      const acknowledge = req.body?.acknowledged === true;
      let targetNotificationIds = [notificationId];
      if (acknowledge && normalizePortalNotificationType(existing?.type) === 'appointment_reschedule_approved') {
        const existingMetadata = parseStoredJsonObject(existing?.metadata);
        const existingEventAt = sanitizeIsoDateTime(
          existingMetadata.scheduledAt || existingMetadata.scheduled_at || existing?.scheduled_for
        );
        if (existingEventAt) {
          let siblingQuery = supabase
            .from('portal_notifications')
            .select('id, scheduled_for, metadata')
            .eq('patient_id', existing.patient_id)
            .eq('type', existing.type)
            .is('acknowledged_at', null)
            .limit(50);
          const existingClinicId = sanitizeString(existing?.clinic_id, 120);
          const existingOrganizationId = sanitizeString(existing?.organization_id, 120);
          if (isUuid(existingClinicId)) {
            siblingQuery = siblingQuery.eq('clinic_id', existingClinicId);
          } else if (isUuid(existingOrganizationId)) {
            siblingQuery = siblingQuery.eq('organization_id', existingOrganizationId);
          }
          if (isUuid(userId) && userEmail) {
            siblingQuery = siblingQuery.or(`recipient_user_id.eq.${userId},recipient_email.eq.${userEmail}`);
          } else if (isUuid(userId)) {
            siblingQuery = siblingQuery.eq('recipient_user_id', userId);
          } else {
            siblingQuery = siblingQuery.eq('recipient_email', userEmail);
          }
          const siblingResult = await siblingQuery;
          if (siblingResult.error) throw siblingResult.error;
          targetNotificationIds = Array.from(new Set([
            notificationId,
            ...(Array.isArray(siblingResult.data) ? siblingResult.data : [])
              .filter((row: any) => {
                const metadata = parseStoredJsonObject(row?.metadata);
                return sanitizeIsoDateTime(
                  metadata.scheduledAt || metadata.scheduled_at || row?.scheduled_for
                ) === existingEventAt;
              })
              .map((row: any) => sanitizeString(row?.id, 120))
              .filter((id: string) => isUuid(id))
          ]));
        }
      }
      const { data, error } = await supabase
        .from('portal_notifications')
        .update({
          read_at: existing.read_at || now,
          ...(acknowledge ? { acknowledged_at: existing.acknowledged_at || now } : {}),
          updated_at: now
        })
        .in('id', targetNotificationIds)
        .select('id, patient_id, appointment_id, type, title, message, read_at, acknowledged_at, sent_at, scheduled_for, created_at, metadata');
      if (error) throw error;
      const updatedRows = Array.isArray(data) ? data : [];
      return res.json({
        success: true,
        data: updatedRows.find((row: any) => sanitizeString(row?.id, 120) === notificationId) || existing,
        acknowledgedIds: acknowledge ? targetNotificationIds : []
      });
    } catch (error: any) {
      return sendRouteDbError(res, '/api/portal/notifications/:notificationId [PATCH]', error, {
        notificationId: sanitizeString(req.params.notificationId, 120),
        requestId: requestIdForLogs(req)
      });
    }
  });

  const serializePortalAppointment = (row: any, extras: Record<string, any> = {}) => {
    const source = parseCalendarSourcePayload(row?.source_payload || row?.sourcePayload);
    const start = buildCalendarAppointmentStart(row);
    const scheduledDurationMinutes = getCalendarAppointmentDuration(row);
    const end = calculateAppointmentEnd(start, scheduledDurationMinutes) || new Date(start.getTime());
    const rawActualMinutes = Number(
      row?.actual_duration_minutes ||
      row?.actualDurationMinutes ||
      source?.actual_duration_minutes ||
      source?.actualDurationMinutes ||
      0
    );
    const actualStart = new Date(row?.actual_start_at || row?.actualStart || source?.actual_start_at || source?.actualStart || '');
    const actualEnd = new Date(row?.actual_end_at || row?.actualEnd || source?.actual_end_at || source?.actualEnd || '');
    const derivedActualMinutes =
      !Number.isNaN(actualStart.getTime()) && !Number.isNaN(actualEnd.getTime()) && actualEnd.getTime() > actualStart.getTime()
        ? Math.round((actualEnd.getTime() - actualStart.getTime()) / 60000)
        : 0;
    const actualDurationMinutes = Number.isFinite(rawActualMinutes) && rawActualMinutes > 0
      ? Math.min(360, Math.round(rawActualMinutes))
      : derivedActualMinutes > 0
        ? Math.min(360, derivedActualMinutes)
        : null;
    const roomName = sanitizePortalRoomName(row?.room_name || source?.room_name || source?.roomName);
    const locationType = normalizeScheduleLocationType(row?.location_type || source?.location_type || source?.locationType || (roomName ? 'clinica' : 'outro'));
    const locationLabel = locationType === 'online'
      ? 'Online'
      : locationType === 'clinica'
        ? roomName || 'Sala não informada'
        : sanitizeString(row?.location_notes || source?.locationLabel || source?.location_label, 180) || 'Local informado pela clínica';
    const serviceType = sanitizeString(row?.service_type || row?.approach || source?.service_type || source?.type, 120) || 'Sessão';
    const clinicId = sanitizeString(row?.clinic_id || row?.clinicId || row?.organization_id || row?.organizationId || source?.clinic_id || source?.clinicId, 120);
    const patientId = sanitizeString(row?.patient_id || row?.patientId || source?.patient_id || source?.patientId, 120);
    const patientName = sanitizeString(row?.patient_name || source?.patientName || source?.name, 180) || 'Paciente não identificado';
    const professionalId = sanitizeString(row?.therapist_id || row?.therapistId || row?.professional_id || row?.professionalId || source?.therapist_id || source?.therapistId || source?.professionalId, 120);
    const professionalName = sanitizeString(row?.therapist_name || source?.therapistName || source?.professionalName || source?.professional, 180) || 'Profissional a definir';
    const clinicName = sanitizeString(row?.clinic_display_name || row?.clinicDisplayName || row?.clinic_name || row?.clinicName || source?.clinic_display_name || source?.clinicDisplayName || source?.clinic_name || source?.clinicName, 160) || null;
    const clinicLogoUrl = sanitizeClinicBrandImageUrl(row?.clinic_logo_url || row?.clinicLogoUrl || source?.clinic_logo_url || source?.clinicLogoUrl) || null;
    const confirmationSnapshot = resolveAppointmentConfirmationSnapshot(row, source);
    const explicitPatientConfirmation = confirmationSnapshot.confirmationStatus ?? confirmationSnapshot.response;
    const appointmentStatus = normalizeOperationalAppointmentStatus(row?.status || source?.status);
    const patientConfirmationState = buildPatientConfirmationStateForAgenda({
      status: explicitPatientConfirmation ?? (appointmentStatus === 'CONFIRMED' ? appointmentStatus : null),
      response: confirmationSnapshot.response,
      respondedAt: confirmationSnapshot.respondedAt ?? confirmationSnapshot.confirmationAt,
      source: confirmationSnapshot.source
    });
    const terminalPatientConfirmationState = resolveCalendarCancellationState(row, patientConfirmationState);
    const resolvedPatientConfirmationState = terminalPatientConfirmationState || patientConfirmationState;
    return {
      id: sanitizeString(row?.id, 120),
      clinicId: isUuid(clinicId) ? clinicId : null,
      patientId: isUuid(patientId) ? patientId : null,
      patientName,
      patient: {
        id: isUuid(patientId) ? patientId : null,
        name: patientName
      },
      date: formatDateInAppointmentTimezone(start),
      scheduledAt: start.toISOString(),
      scheduledEnd: end.toISOString(),
      scheduledDurationMinutes,
      actualDurationMinutes,
      time: formatTimeInAppointmentTimezone(start),
      endTime: formatTimeInAppointmentTimezone(end),
      serviceType,
      professionalId: isUuid(professionalId) ? professionalId : null,
      professionalName,
      professionalRole: sanitizeString(row?.therapist_role || row?.professional_role || source?.therapistRole || source?.professionalRole, 80) || null,
      clinicName,
      clinicLogoUrl,
      clinic: clinicName || clinicLogoUrl || isUuid(clinicId)
        ? {
            id: isUuid(clinicId) ? clinicId : null,
            displayName: clinicName || 'Clínica',
            logoUrl: clinicLogoUrl,
            primaryColor: '#7C3AED'
          }
        : null,
      locationType,
      locationLabel,
      roomId: locationType === 'clinica' && isUuid(row?.room_id || source?.room_id || source?.roomId)
        ? sanitizeString(row?.room_id || source?.room_id || source?.roomId, 180)
        : null,
      roomName: locationType === 'clinica' ? roomName || 'Sala não informada' : null,
      status: appointmentStatus,
      patientConfirmationStatus: resolvedPatientConfirmationState.status,
      patientConfirmationLabel: resolvedPatientConfirmationState.label,
      patientConfirmationColor: resolvedPatientConfirmationState.color,
      patientResponse: resolvedPatientConfirmationState.response,
      patientRespondedAt: resolvedPatientConfirmationState.respondedAt,
      patientResponseSource: resolvedPatientConfirmationState.source,
      confirmedAt: row?.confirmed_at || row?.patient_confirmation_at || null,
      rescheduleRequestedAt: row?.reschedule_requested_at || null,
      cancelRequestedAt: row?.cancel_requested_at || null,
      notes: sanitizeTextField(row?.notes || source?.notes || source?.orientation || '', 800) || null,
      ...extras
    };
  };

  const serializePortalAppointmentForFamilyView = async (
    row: any,
    extras: Record<string, any> = {},
    preloaded: { patient?: any; clinicBranding?: any; allowPatientReschedule?: boolean } = {}
  ) => {
    const displayContext = await buildFamilyAppointmentDisplayContext(row, preloaded);
    const allowPatientReschedule =
      typeof preloaded.allowPatientReschedule === 'boolean'
        ? preloaded.allowPatientReschedule
        : await readClinicPatientReschedulePolicy(displayContext.clinicId);
    return serializePortalAppointment(row, {
      clinicId: displayContext.clinicId,
      clinicName: displayContext.clinicName,
      clinicLogoUrl: displayContext.clinicLogoUrl,
      clinic: displayContext.clinic,
      patientId: displayContext.patientId,
      patientName: displayContext.patientName,
      patient: displayContext.patient,
      professionalId: displayContext.professionalId,
      professionalName: displayContext.professionalName,
      professionalRole: displayContext.professionalRole,
      professionalAvatarUrl: displayContext.professionalAvatarUrl,
      allowPatientReschedule,
      allowedActions: portalAllowedActions(allowPatientReschedule),
      ...extras
    });
  };

  const acknowledgePortalAppointmentNotifications = async (params: {
    appointment: any;
    user: any;
    action: string;
    notificationId?: unknown;
  }) => {
    const appointmentId = sanitizeString(params.appointment?.id, 120);
    const patientId = sanitizeString(params.appointment?.patient_id || params.appointment?.patientId, 120);
    if (!isUuid(appointmentId) || !isUuid(patientId)) return { ok: true, notificationIds: [] as string[] };
    const userId = sanitizeString(params.user?.id, 120);
    const userEmail = sanitizeEmail(params.user?.email);
    const requestedNotificationId = sanitizeString(params.notificationId || '', 120);
    if (requestedNotificationId && !isUuid(requestedNotificationId)) {
      return { ok: false, status: 400, error: 'Notificação inválida.', notificationIds: [] as string[] };
    }
    const now = new Date().toISOString();
    let query = supabase
      .from('portal_notifications')
      .update({
        read_at: now,
        acknowledged_at: now,
        updated_at: now
      })
      .eq('appointment_id', appointmentId)
      .eq('patient_id', patientId);
    if (requestedNotificationId) query = query.eq('id', requestedNotificationId);
    if (isUuid(userId) && userEmail) {
      query = query.or(`recipient_user_id.eq.${userId},recipient_email.eq.${userEmail}`);
    } else if (isUuid(userId)) {
      query = query.eq('recipient_user_id', userId);
    } else if (userEmail) {
      query = query.eq('recipient_email', userEmail);
    } else {
      return { ok: true, notificationIds: [] as string[] };
    }
    let result = await query.select('id');
    if (result.error && extractMissingColumnName(result.error) === 'updated_at') {
      let fallbackQuery = supabase
        .from('portal_notifications')
        .update({
          read_at: now,
          acknowledged_at: now
        })
        .eq('appointment_id', appointmentId)
        .eq('patient_id', patientId);
      if (requestedNotificationId) fallbackQuery = fallbackQuery.eq('id', requestedNotificationId);
      if (isUuid(userId) && userEmail) {
        fallbackQuery = fallbackQuery.or(`recipient_user_id.eq.${userId},recipient_email.eq.${userEmail}`);
      } else if (isUuid(userId)) {
        fallbackQuery = fallbackQuery.eq('recipient_user_id', userId);
      } else if (userEmail) {
        fallbackQuery = fallbackQuery.eq('recipient_email', userEmail);
      }
      result = await fallbackQuery.select('id');
    }
    if (result.error) {
      if (isMissingRelationError(result.error) || hasMissingFinancialSchema(result.error)) {
        console.warn('[PortalAppointments] notification acknowledgement skipped:', result.error.message);
        return { ok: true, notificationIds: [] as string[] };
      }
      throw result.error;
    }
    const notificationIds = (Array.isArray(result.data) ? result.data : [])
      .map((row: any) => sanitizeString(row?.id, 120))
      .filter((id) => isUuid(id));
    if (requestedNotificationId && !notificationIds.includes(requestedNotificationId)) {
      return { ok: false, status: 404, error: 'Notificação não encontrada.', notificationIds: [] as string[] };
    }
    return { ok: true, notificationIds };
  };

  const acknowledgeStaleAppointmentReminderNotifications = async (appointmentOrAppointments: any) => {
    const appointments = (Array.isArray(appointmentOrAppointments) ? appointmentOrAppointments : [appointmentOrAppointments])
      .filter(Boolean);
    const appointmentIds = Array.from(new Set(
      appointments.map((appointment: any) => sanitizeString(appointment?.id, 120)).filter((id: string) => isUuid(id))
    ));
    const patientIds = Array.from(new Set(
      appointments
        .map((appointment: any) => sanitizeString(appointment?.patient_id || appointment?.patientId, 120))
        .filter((id: string) => isUuid(id))
    ));
    const organizationIds = Array.from(new Set(
      appointments
        .map((appointment: any) => sanitizeString(appointment?.organization_id || appointment?.clinic_id, 120))
        .filter((id: string) => isUuid(id))
    ));
    if (appointmentIds.length === 0 || patientIds.length === 0 || organizationIds.length !== 1) return [] as string[];
    const organizationId = organizationIds[0];
    const now = new Date().toISOString();
    const reminderTypes = ['appointment_reminder', 'appointment_reminder_24h', 'appointment_reminder_12h'];
    const buildQuery = (includeUpdatedAt: boolean) => {
      let query = supabase
        .from('portal_notifications')
        .update({
          read_at: now,
          acknowledged_at: now,
          ...(includeUpdatedAt ? { updated_at: now } : {})
        })
        .in('appointment_id', appointmentIds)
        .in('patient_id', patientIds)
        .in('type', reminderTypes)
        .is('acknowledged_at', null);
      query = query.or(`organization_id.eq.${organizationId},clinic_id.eq.${organizationId}`);
      return query.select('id');
    };
    let result = await buildQuery(true);
    if (result.error && extractMissingColumnName(result.error) === 'updated_at') result = await buildQuery(false);
    if (result.error) {
      if (!isMissingRelationError(result.error) && !hasMissingFinancialSchema(result.error)) throw result.error;
      return [] as string[];
    }
    return (Array.isArray(result.data) ? result.data : [])
      .map((row: any) => sanitizeString(row?.id, 120))
      .filter((id: string) => isUuid(id));
  };

  const buildPortalAppointmentActionResult = (params: {
    action: string;
    appointment: any;
    message: string;
    user: any;
    notificationIds?: string[];
    actionRequest?: any;
    alreadyAnswered?: boolean;
    events?: any[];
  }) => {
    const appointmentId = sanitizeString(params.appointment?.id, 120);
    const clinicId = sanitizeString(params.appointment?.clinicId || params.appointment?.clinic_id || params.appointment?.organizationId || params.appointment?.organization_id, 120);
    const patientId = sanitizeString(params.appointment?.patientId || params.appointment?.patient_id, 120);
    const professionalId = sanitizeString(params.appointment?.professionalId || params.appointment?.professional_id || params.appointment?.therapistId || params.appointment?.therapist_id, 120);
    const userId = sanitizeString(params.user?.id, 120);
    return buildActionResultPayload({
      entity: 'appointment',
      action: params.action,
      item: params.appointment,
      items: [params.appointment],
      affected: cleanObject({
        clinicId: isUuid(clinicId) ? clinicId : null,
        organizationId: isUuid(clinicId) ? clinicId : null,
        patientId: isUuid(patientId) ? patientId : null,
        patientIds: isUuid(patientId) ? [patientId] : [],
        professionalId: isUuid(professionalId) ? professionalId : null,
        professionalIds: isUuid(professionalId) ? [professionalId] : [],
        appointmentId: isUuid(appointmentId) ? appointmentId : null,
        appointmentIds: isUuid(appointmentId) ? [appointmentId] : [],
        userIds: isUuid(userId) ? [userId] : [],
        notificationIds: Array.from(new Set((params.notificationIds || []).filter((id) => isUuid(id)))),
        queryKeys: ['portalAppointments', 'portalNotifications', 'appointments']
      }),
      events: params.events || [],
      legacy: cleanObject({
        message: params.message,
        appointment: params.appointment,
        data: params.actionRequest || undefined,
        alreadyAnswered: params.alreadyAnswered || undefined
      })
    });
  };

  const writeAppointmentStatusAuditLog = async (params: {
    organizationId: string;
    appointmentId: string;
    patientId?: string | null;
    action: string;
    previousStatus?: string | null;
    newStatus?: string | null;
    performedBy?: string | null;
    performedByRole?: string | null;
    metadata?: Record<string, any>;
  }) => {
    const organizationId = sanitizeString(params.organizationId, 120);
    const appointmentId = sanitizeString(params.appointmentId, 120);
    if (!isUuid(organizationId) || !isUuid(appointmentId)) return;
    const payload = cleanObject({
      id: crypto.randomUUID(),
      organization_id: organizationId,
      appointment_id: appointmentId,
      patient_id: isUuid(sanitizeString(params.patientId, 120)) ? sanitizeString(params.patientId, 120) : null,
      action: sanitizeString(params.action, 80),
      previous_status: sanitizeString(params.previousStatus, 80) || null,
      new_status: sanitizeString(params.newStatus, 80) || null,
      performed_by: sanitizeString(params.performedBy, 120) || null,
      performed_by_role: sanitizeString(params.performedByRole, 40) || null,
      performed_at: new Date().toISOString(),
      metadata: sanitizeClinicalPayload(params.metadata || {})
    });
    const { error } = await supabase
      .from('appointment_status_audit_logs')
      .insert([payload]);
    if (error && !hasMissingFinancialSchema(error)) {
      console.warn('[AppointmentActions] audit log failed:', error?.message || String(error));
    }
  };

  const updateAppointmentOperationalPatch = async (appointmentId: string, patch: Record<string, any>) => {
    let safePatch: Record<string, any> = cleanObject(patch);
    let triedLegacyStatus = false;
    while (Object.keys(safePatch).length > 0) {
      const { data, error } = await supabase
        .from('appointments')
        .update(safePatch)
        .eq('id', appointmentId)
        .select('id')
        .maybeSingle();
      if (!error) return { data, error: null };
      const missingColumn = extractMissingColumnName(error);
      if (missingColumn && missingColumn in safePatch) {
        delete safePatch[missingColumn];
        continue;
      }
      if (!triedLegacyStatus && safePatch.status && /status|check constraint/i.test(String(error?.message || ''))) {
        triedLegacyStatus = true;
        safePatch.status = normalizeAppointmentStatusForTable(safePatch.status);
        continue;
      }
      return { data: null, error };
    }
    return { data: null, error: { message: 'Payload vazio.' } };
  };

  const appointmentScheduleMatches = (row: any, expected: { start: string; end: string; status: string }) => {
    const actualStart = sanitizeIsoDateTime(buildAppointmentScheduledAt(row)) || '';
    const actualEnd = sanitizeIsoDateTime(row?.scheduled_end_at || row?.scheduledEndAt) ||
      (actualStart
        ? calculateAppointmentEnd(new Date(actualStart), getCalendarAppointmentDuration(row))?.toISOString() || ''
        : '');
    return normalizeOperationalAppointmentStatus(row?.status) === expected.status &&
      actualStart === expected.start &&
      actualEnd === expected.end;
  };

  const createOrUpdateAppointmentActionRequest = async (params: {
    appointment: any;
    user: any;
    requestType: 'RESCHEDULE' | 'CANCEL';
    reason?: unknown;
    note?: unknown;
    metadata?: Record<string, unknown>;
    requestedStart?: unknown;
    requestedEnd?: unknown;
  }) => {
    const appointmentId = sanitizeString(params.appointment?.id, 120);
    const organizationId = sanitizeString(params.appointment?.organization_id || params.appointment?.clinic_id, 120);
    const patientId = sanitizeString(params.appointment?.patient_id, 120);
    const now = new Date().toISOString();
    const requestedStart = sanitizeIsoDateTime(params.requestedStart);
    const requestedEnd = sanitizeIsoDateTime(params.requestedEnd);
    const reason = sanitizeTextField(params.reason, 600) || null;
    const note = sanitizeTextField(params.note, 1000) || null;
    const requestedOptions = normalizeRescheduleOptions(
      params.metadata?.rescheduleOptions ||
        params.metadata?.reschedule_options ||
        params.metadata?.selectedSlots ||
        params.metadata?.selected_slots ||
        []
    );
    const originalScheduledStart = sanitizeIsoDateTime(
      params.appointment?.scheduled_start_at || params.appointment?.scheduled_at || params.appointment?.scheduledStartAt || params.appointment?.scheduledAt
    );
    const originalScheduledEnd = sanitizeIsoDateTime(
      params.appointment?.scheduled_end_at || params.appointment?.scheduledEndAt || params.appointment?.scheduledEnd
    );
    const metadata = requestedOptions.length > 0
      ? cleanObject({
          rescheduleOptions: requestedOptions,
          reschedulePayloadVersion: 1,
          originalScheduledStart: originalScheduledStart || undefined,
          originalScheduledEnd: originalScheduledEnd || undefined
        })
      : {};

    const existing = await supabase
      .from('appointment_action_requests')
      .select(APPOINTMENT_ACTION_REQUEST_SELECT)
      .eq('organization_id', organizationId)
      .eq('appointment_id', appointmentId)
      .eq('request_type', params.requestType)
      .eq('status', 'PENDING')
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle();
    if (existing.error) {
      if (hasMissingFinancialSchema(existing.error) || isMissingRelationError(existing.error)) return null;
      throw existing.error;
    }
    if (existing.data?.id) {
      const existingMetadata = existing.data?.metadata && typeof existing.data.metadata === 'object' && !Array.isArray(existing.data.metadata)
        ? existing.data.metadata
        : {};
      const { data, error } = await supabase
        .from('appointment_action_requests')
        .update(cleanObject({
          requested_start: requestedStart || existing.data.requested_start || null,
          requested_end: requestedEnd || existing.data.requested_end || null,
          reason: reason || existing.data.reason || null,
          note: note || existing.data.note || null,
          metadata: {
            ...metadata,
            ...existingMetadata,
            ...(requestedOptions.length > 0 ? { rescheduleOptions: requestedOptions, reschedulePayloadVersion: 1 } : {})
          },
          updated_at: now
        }))
        .eq('id', existing.data.id)
        .select(APPOINTMENT_ACTION_REQUEST_SELECT)
        .maybeSingle();
      if (error) {
        if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return null;
        throw error;
      }
      return data;
    }

    const payload = cleanObject({
      id: crypto.randomUUID(),
      organization_id: organizationId,
      appointment_id: appointmentId,
      patient_id: patientId,
      requested_by: sanitizeString(params.user?.id, 120) || null,
      request_type: params.requestType,
      status: 'PENDING',
      requested_start: requestedStart || null,
      requested_end: requestedEnd || null,
      reason,
      note,
      metadata,
      created_at: now,
      updated_at: now
    });
    const { data, error } = await supabase
      .from('appointment_action_requests')
      .insert([payload])
      .select(APPOINTMENT_ACTION_REQUEST_SELECT)
      .maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return null;
      throw error;
    }
    return data;
  };

  const serializeAppointmentActionRequestForResponse = (row: any) => {
    const parsed = parseRescheduleRequestPayload(row?.note, row?.metadata);
    const metadata = row?.metadata && typeof row.metadata === 'object' && !Array.isArray(row.metadata)
      ? row.metadata
      : {};
    return {
      ...row,
      metadata,
      note: parsed.note,
      rescheduleOptions: parsed.options,
      reschedule_options: parsed.options
    };
  };

  const resolveAppointmentRescheduleAssignment = (appointment: any) => {
    const source = parseCalendarSourcePayload(appointment?.source_payload || appointment?.sourcePayload);
    const roomId = sanitizeString(
      appointment?.room_id || appointment?.roomId || source?.room_id || source?.roomId || source?.room,
      180
    );
    return {
      clinicId: sanitizeString(
        appointment?.clinic_id || appointment?.clinicId || appointment?.organization_id || appointment?.organizationId || source?.clinic_id || source?.clinicId,
        120
      ),
      organizationId: sanitizeString(
        appointment?.organization_id || appointment?.organizationId || appointment?.clinic_id || appointment?.clinicId || source?.organization_id || source?.organizationId,
        120
      ),
      patientId: sanitizeString(appointment?.patient_id || appointment?.patientId || source?.patient_id || source?.patientId, 120),
      professionalId: sanitizeString(
        appointment?.therapist_id ||
          appointment?.therapistId ||
          appointment?.responsible_professional_id ||
          appointment?.responsibleProfessionalId ||
          appointment?.professional_id ||
          appointment?.professionalId ||
          source?.therapist_id ||
          source?.therapistId ||
          source?.professional_id ||
          source?.professionalId,
        120
      ),
      professionalName: sanitizeString(
        appointment?.therapist_name ||
          appointment?.therapistName ||
          appointment?.responsible_professional_name ||
          appointment?.responsibleProfessionalName ||
          appointment?.professional_name ||
          appointment?.professionalName ||
          source?.therapist_name ||
          source?.therapistName ||
          source?.professionalName ||
          source?.professional,
        180
      ) || 'Profissional não identificado',
      roomId,
      roomName: sanitizePortalRoomName(
        appointment?.room_name || appointment?.roomName || source?.room_name || source?.roomName || source?.roomDisplayName
      ),
      locationType: normalizeScheduleLocationType(
        appointment?.location_type || appointment?.locationType || appointment?.location || source?.location_type || source?.locationType || (roomId ? 'clinica' : 'outro')
      )
    };
  };

  const formatRescheduleProfessionalName = (profile: any, fallbackName = '') => {
    const metadata = profile?.metadata && typeof profile.metadata === 'object' ? profile.metadata : {};
    const name = sanitizeString(profile?.full_name || profile?.name || fallbackName, 180) || 'Profissional não identificado';
    const title = readProfessionalTitleFromSource(
      {
        specialty: profile?.specialty,
        metadata,
        professionalTitle:
          metadata?.professionalTitle || metadata?.professional_title
      },
      'Profissional'
    );
    if (name === 'Profissional não identificado') return name;
    const personalName = name
      .replace(/^(psicólogo|psicóloga|terapeuta ocupacional|acompanhante terapêutico|acompanhante terapêutica|aplicador aba|aplicadora aba|terapeuta|profissional)\s+/i, '')
      .trim() || name;
    return `${title || 'Profissional'} ${personalName}`;
  };

  const formatRescheduleRoom = (room: any, fallbackName = '') => {
    const name = sanitizePortalRoomName(room?.name || room?.room_name || room?.roomName || fallbackName) || null;
    const specialties = normalizeClinicRoomSpecialties(room?.specialties || room?.specialty);
    const specialtyName = sanitizeString(String(specialties || '').split(',')[0], 120) || null;
    return {
      id: sanitizeString(room?.id || room?.room_id || room?.roomId, 180) || null,
      name,
      specialtyName,
      displayName: name ? `${name}${specialtyName ? ` - ${specialtyName}` : ''}` : 'Sala não definida'
    };
  };

  const buildRescheduleApprovalPreview = async (params: { appointment: any; request: any; user: any }) => {
    const appointment = params.appointment || {};
    const assignment = resolveAppointmentRescheduleAssignment(appointment);
    const parsed = parseRescheduleRequestPayload(params.request?.note, params.request?.metadata);
    const options = parsed.options.slice(0, Math.min(24, parsed.options.length));
    const clinicTimeZone = currentClinicTimeZone(params.user);
    if (!isUuid(assignment.clinicId) || !isUuid(assignment.organizationId) || !isUuid(assignment.patientId)) {
      return {
        requestId: sanitizeString(params.request?.id, 120),
        appointmentId: sanitizeString(appointment?.id, 120),
        options: options.map((option, index) => ({
          index,
          ...option,
          available: false,
          approvalAllowed: false,
          recommendation: 'unavailable',
          recommendationLabel: 'Indisponível',
          message: 'Não foi possível confirmar clínica e paciente desta sessão.'
        }))
      };
    }

    const requestMetadata = params.request?.metadata && typeof params.request.metadata === 'object' && !Array.isArray(params.request.metadata)
      ? params.request.metadata
      : {};
    const allowProfessionalSubstitution = requestMetadata?.allowProfessionalSubstitution === true || requestMetadata?.allow_professional_substitution === true;
    const dates = Array.from(new Set(options.map((option) => formatDateInAppointmentTimezone(new Date(option.scheduledStart), clinicTimeZone)).filter(Boolean)));
    const conflictInput = { recurrenceDates: dates };

    const membershipResult = await supabase
      .from('clinic_memberships')
      .select('user_id,role,status')
      .eq('clinic_id', assignment.clinicId)
      .eq('status', 'active')
      .limit(200);
    if (membershipResult.error) throw membershipResult.error;
    const memberships = Array.isArray(membershipResult.data) ? membershipResult.data : [];
    const activeMemberIds = Array.from(new Set(
      memberships.map((row: any) => sanitizeString(row?.user_id, 120)).filter((id: string) => isUuid(id))
    ));

    const [profileResult, userResult, rooms, tableAppointments, stateAppointments, billingContextRow, competingRequestsResult] = await Promise.all([
      activeMemberIds.length > 0
        ? supabase.from('professional_profiles').select('user_id,full_name,metadata').in('user_id', activeMemberIds).limit(activeMemberIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      activeMemberIds.length > 0
        ? supabase.from('users').select('id,name').in('id', activeMemberIds).limit(activeMemberIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      fetchConflictRooms(assignment.clinicId, assignment.organizationId),
      fetchConflictAppointmentsFromTable({
        clinicId: assignment.clinicId,
        organizationId: assignment.organizationId,
        input: conflictInput
      }),
      fetchConflictAppointmentsFromState(assignment.clinicId, conflictInput).catch(() => []),
      fetchAppointmentBillingContextRow(assignment.organizationId, sanitizeString(appointment?.id, 120)),
      supabase
        .from('appointment_action_requests')
        .select('id,appointment_id,note,metadata,requested_start,requested_end,status,request_type,created_at')
        .eq('organization_id', assignment.organizationId)
        .eq('request_type', 'RESCHEDULE')
        .eq('status', 'PENDING')
        .neq('id', sanitizeString(params.request?.id, 120))
        .limit(200)
    ]);
    if (profileResult.error && !isMissingRelationError(profileResult.error)) throw profileResult.error;
    if (userResult.error && !isMissingRelationError(userResult.error)) throw userResult.error;
    if (competingRequestsResult.error && !hasMissingFinancialSchema(competingRequestsResult.error) && !isMissingRelationError(competingRequestsResult.error)) {
      throw competingRequestsResult.error;
    }

    const profilesById = new Map<string, any>();
    for (const profile of Array.isArray(profileResult.data) ? profileResult.data : []) {
      const userId = sanitizeString(profile?.user_id, 120);
      if (userId) profilesById.set(userId, profile);
    }
    const usersById = new Map<string, any>();
    for (const user of Array.isArray(userResult.data) ? userResult.data : []) {
      const userId = sanitizeString(user?.id, 120);
      if (userId) usersById.set(userId, user);
    }

    const normalizeCompatibilityTokens = (value: any) => {
      const rawValues = Array.isArray(value) ? value : String(value || '').split(/[;,|]/g);
      return Array.from(new Set(rawValues
        .map((item: any) => sanitizeString(item, 160)
          .normalize('NFD')
          .replace(/[\u0300-\u036f]/g, '')
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, ' ')
          .trim())
        .filter(Boolean)));
    };
    const normalizeMetadataIdList = (value: any) => (Array.isArray(value) ? value : [])
      .map((item: any) => sanitizeString(item, 120))
      .filter((item: string) => isUuid(item));

    const professionalCandidates = memberships
      .filter((membership: any) => {
        const id = sanitizeString(membership?.user_id, 120);
        return id === assignment.professionalId || sanitizeString(membership?.role, 40).toLowerCase() === 'therapist';
      })
      .map((membership: any) => {
        const id = sanitizeString(membership?.user_id, 120);
        const profile = profilesById.get(id) || {};
        const user = usersById.get(id) || {};
        const metadata = profile?.metadata && typeof profile.metadata === 'object' ? profile.metadata : {};
        const fallbackDuration = asSafeNumber(metadata?.sessionDurationMinutes ?? metadata?.defaultSessionDurationMinutes, 15, 360) || getCalendarAppointmentDuration(appointment);
        return {
          id,
          name: formatRescheduleProfessionalName(profile, user?.name || (id === assignment.professionalId ? assignment.professionalName : '')),
          workSchedule: readProfessionalWorkingScheduleFromMetadata(metadata, fallbackDuration) || buildDefaultProfessionalWorkingSchedule(fallbackDuration),
          role: sanitizeString(membership?.role, 40),
          specialties: normalizeCompatibilityTokens(metadata?.specialties || metadata?.specialty),
          serviceCatalogIds: normalizeMetadataIdList(
            metadata?.service_catalog_ids || metadata?.serviceCatalogIds || metadata?.allowed_service_catalog_ids || metadata?.allowedServiceCatalogIds
          )
        };
      })
      .filter((professional: any) => isUuid(professional.id));
    professionalCandidates.sort((left: any, right: any) =>
      left.id === assignment.professionalId ? -1 : right.id === assignment.professionalId ? 1 : left.name.localeCompare(right.name, 'pt-BR')
    );

    const activeRooms = rooms.filter((room: any) => room?.is_active !== false && room?.isActive !== false).slice(0, 80);
    const appointmentsById = new Map<string, any>();
    [...stateAppointments, ...tableAppointments].forEach((item: any, index: number) => {
      appointmentsById.set(sanitizeString(item?.id, 180) || `idx-${index}`, item);
    });
    const existingAppointments = Array.from(appointmentsById.values());

    const competingRequests = Array.isArray(competingRequestsResult.data) ? competingRequestsResult.data : [];
    const competingAppointmentIds = Array.from(new Set(
      competingRequests.map((row: any) => sanitizeString(row?.appointment_id, 120)).filter((id: string) => isUuid(id))
    ));
    const competingAppointmentsResult = competingAppointmentIds.length > 0
      ? await supabase
          .from('appointments')
          .select('id,therapist_id,room_id,scheduled_at,scheduled_start_at,scheduled_end_at,duration_minutes,scheduled_duration_minutes,status')
          .eq('organization_id', assignment.organizationId)
          .in('id', competingAppointmentIds)
          .limit(competingAppointmentIds.length)
      : { data: [], error: null } as any;
    if (competingAppointmentsResult.error && !hasMissingFinancialSchema(competingAppointmentsResult.error)) throw competingAppointmentsResult.error;
    const competingAppointmentsById = new Map<string, any>(
      (Array.isArray(competingAppointmentsResult.data) ? competingAppointmentsResult.data : []).map((row: any) => [sanitizeString(row?.id, 120), row])
    );
    const competingOptionRows = competingRequests.flatMap((row: any) => {
      const requestOptions = parseRescheduleRequestPayload(row?.note, row?.metadata).options;
      return requestOptions.flatMap((option: any) => normalizeRescheduleOptions([{
        scheduledStart: option?.scheduledStart,
        scheduledEnd: option?.scheduledEnd
      }]).map((normalized: any) => ({
        requestId: sanitizeString(row?.id, 120),
        appointmentId: sanitizeString(row?.appointment_id, 120),
        appointment: competingAppointmentsById.get(sanitizeString(row?.appointment_id, 120)) || null,
        ...normalized
      })));
    });

    const mergedBillingContext = mergeAppointmentBillingPayload({ ...appointment, ...(billingContextRow || {}) });
    const financialContextType = readAppointmentFinancialContextType(mergedBillingContext);
    const billingMetadata = parseStoredJsonObject(billingContextRow?.metadata);
    const allowedProfessionalIds = Array.isArray(billingMetadata?.allowed_professional_ids)
      ? billingMetadata.allowed_professional_ids.map((value: any) => sanitizeString(value, 120)).filter((value: string) => isUuid(value))
      : [];
    const billingServiceCatalogId = sanitizeString(billingContextRow?.service_catalog_id || billingMetadata?.service_catalog_id || billingMetadata?.serviceCatalogId, 120);
    const authorizationId = sanitizeString(
      readTissAuthorizationIdFromBillingMetadata(billingContextRow?.metadata) ||
        mergedBillingContext?.patient_tiss_authorization_id ||
        mergedBillingContext?.patientTissAuthorizationId,
      120
    );
    let authorization: any = null;
    let authorizationBalance: ConfirmedTissAuthorizationBalance | null = null;
    if (financialContextType === 'INSURANCE' && isUuid(authorizationId)) {
      const authorizationResult = await supabase
        .from('patient_payer_authorizations')
        .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
        .eq('organization_id', assignment.organizationId)
        .eq('patient_id', assignment.patientId)
        .eq('id', authorizationId)
        .limit(1)
        .maybeSingle();
      if (authorizationResult.error && !hasMissingFinancialSchema(authorizationResult.error) && !isMissingRelationError(authorizationResult.error)) {
        throw authorizationResult.error;
      }
      authorization = authorizationResult.data || null;
      if (authorization) {
        const balances = await fetchPatientTissAuthorizationBalances({
          organizationId: assignment.organizationId,
          authorizations: [authorization],
          currentAppointmentId: appointment?.id
        });
        authorizationBalance = balances.get(authorizationId) || null;
      }
    }

    const evaluateFinancialContext = (option: PortalRescheduleOption, professionalId: string) => {
      const warnings: string[] = [];
      if (!appointmentRequiresFinancialContext(mergedBillingContext)) {
        return { reusable: true, valid: true, reviewRequired: false, warnings, reasonCode: null };
      }
      if (!financialContextType) {
        return {
          reusable: false,
          valid: false,
          reviewRequired: true,
          warnings: ['O contexto financeiro desta sessão não pôde ser confirmado.'],
          reasonCode: 'FINANCIAL_CONTEXT_UNAVAILABLE'
        };
      }
      if (financialContextType !== 'INSURANCE') {
        return { reusable: true, valid: true, reviewRequired: false, warnings, reasonCode: null };
      }
      if (!authorization || !isUuid(authorizationId)) {
        return {
          reusable: false,
          valid: false,
          reviewRequired: true,
          warnings: ['A autorização vinculada à sessão não foi localizada.'],
          reasonCode: 'AUTHORIZATION_NOT_FOUND'
        };
      }
      const optionDate = formatDateInAppointmentTimezone(new Date(option.scheduledStart), clinicTimeZone);
      const validFrom = sanitizeString(authorization?.valid_from, 40).slice(0, 10);
      const validUntil = sanitizeString(authorization?.valid_until, 40).slice(0, 10);
      const status = sanitizeString(authorization?.status, 40).toLowerCase();
      if (authorization?.active === false || ['cancelled', 'canceled', 'expired', 'inactive', 'revoked'].includes(status)) {
        warnings.push('A autorização vinculada está inativa.');
      }
      if (validFrom && optionDate && optionDate < validFrom) warnings.push('A autorização ainda não estará vigente na data selecionada.');
      if (validUntil && optionDate && optionDate > validUntil) warnings.push('A guia estará vencida na data selecionada.');
      if (!authorizationBalance?.confirmed) warnings.push('Não foi possível confirmar o saldo da autorização.');
      if (
        authorizationBalance?.confirmed &&
        authorizationBalance.available !== null &&
        Number(authorizationBalance.available) <= 0 &&
        authorizationBalance.currentAppointmentReserved !== true
      ) warnings.push('A autorização não possui saldo disponível para esta sessão.');

      if (professionalId !== assignment.professionalId && !allowedProfessionalIds.includes(professionalId)) {
        warnings.push('A autorização não confirma atendimento por um profissional substituto.');
      }
      return {
        reusable: warnings.length === 0,
        valid: warnings.length === 0,
        reviewRequired: warnings.length > 0,
        warnings,
        reasonCode: warnings.length > 0 ? 'FINANCIAL_REVIEW_REQUIRED' : null
      };
    };

    const durationMinutes = getCalendarAppointmentDuration(appointment);
    const originalProfessional = professionalCandidates.find((professional: any) => professional.id === assignment.professionalId) || null;
    const originalRoom = activeRooms.find((room: any) => sanitizeString(room?.id, 180) === assignment.roomId) || null;
    const requiredProfessionalSpecialties = new Set<string>(originalProfessional?.specialties || []);
    const requiredRoomSpecialties = new Set<string>(normalizeCompatibilityTokens(originalRoom?.specialties || originalRoom?.specialty));
    const professionalAlternativeEligible = (professional: any) => {
      if (!professional?.id || professional.id === assignment.professionalId) return true;
      if (!allowProfessionalSubstitution) return false;
      if (financialContextType === 'INSURANCE' && !allowedProfessionalIds.includes(professional.id)) return false;
      if (requiredProfessionalSpecialties.size > 0) {
        const candidateSpecialties = new Set<string>(professional?.specialties || []);
        if (![...requiredProfessionalSpecialties].some((item) => candidateSpecialties.has(item))) return false;
      }
      if (isUuid(billingServiceCatalogId) && Array.isArray(professional?.serviceCatalogIds) && professional.serviceCatalogIds.length > 0
        && !professional.serviceCatalogIds.includes(billingServiceCatalogId)) return false;
      return true;
    };
    const roomAlternativeEligible = (room: any) => {
      if (!room?.id || sanitizeString(room.id, 180) === assignment.roomId) return true;
      if (requiredRoomSpecialties.size === 0) return true;
      const candidateSpecialties = new Set<string>(normalizeCompatibilityTokens(room?.specialties || room?.specialty));
      return [...requiredRoomSpecialties].some((item) => candidateSpecialties.has(item));
    };

    const evaluateCandidate = (option: PortalRescheduleOption, professional: any, room: any) => {
      const issues: any[] = [];
      if (!professional?.id) {
        issues.push({ type: 'professional_unavailable', professionalId: assignment.professionalId, professionalName: assignment.professionalName });
        return { operationalAvailable: false, approvalAllowed: false, message: 'O profissional responsável não está ativo na equipe desta clínica.', conflictTypes: ['professional'], issues, financialContext: evaluateFinancialContext(option, assignment.professionalId) };
      }
      if (assignment.locationType === 'clinica' && !room?.id) {
        issues.push({ type: 'room_conflict', roomId: assignment.roomId || null, roomName: assignment.roomName || 'Sala não definida', roomSpecialtyName: null });
        return { operationalAvailable: false, approvalAllowed: false, message: 'A sala anterior não está disponível. Escolha uma das salas sugeridas.', conflictTypes: ['room'], issues, financialContext: evaluateFinancialContext(option, professional.id) };
      }
      const roomInfo = formatRescheduleRoom(room, assignment.roomName);
      const startDate = new Date(option.scheduledStart);
      const dateKey = formatDateInAppointmentTimezone(startDate, clinicTimeZone);
      const startTime = formatTimeInAppointmentTimezone(startDate, clinicTimeZone);
      const sessionBufferMinutes = Math.round(asSafeNumber(
        professional?.workSchedule?.sessionBufferMinutes ?? professional?.workSchedule?.session_buffer_minutes,
        0,
        120
      ) ?? 0);
      const conflict = checkLocalScheduleConflicts({
        appointments: existingAppointments,
        patient_id: assignment.patientId,
        professional_ids: [professional.id],
        professional_names: [professional.name],
        room_id: assignment.locationType === 'clinica' ? room?.id : null,
        room_name: roomInfo.displayName,
        rooms: activeRooms,
        location_type: assignment.locationType,
        date: dateKey,
        start_time: startTime,
        duration_minutes: durationMinutes,
        session_buffer_minutes: sessionBufferMinutes,
        exclude_event_id: appointment.id
      });
      for (const item of conflict.conflicts || []) {
        if (item.conflictType === 'professional' || item.conflictType === 'team') {
          issues.push({
            type: 'professional_conflict',
            professionalId: professional.id,
            professionalName: professional.name,
            conflictingStartAt: item.startTime,
            conflictingEndAt: item.endTime
          });
        } else if (item.conflictType === 'room') {
          issues.push({
            type: 'room_conflict',
            roomId: roomInfo.id,
            roomName: roomInfo.name,
            roomSpecialtyName: roomInfo.specialtyName,
            conflictingStartAt: item.startTime,
            conflictingEndAt: item.endTime
          });
        } else if (item.conflictType === 'patient') {
          issues.push({ type: 'patient_conflict', conflictingStartAt: item.startTime, conflictingEndAt: item.endTime });
        }
      }
      const scheduleEvaluation = !conflict.blocking
        ? evaluateRequestedRescheduleSlot({
            scheduledStart: option.scheduledStart,
            durationMinutes,
            roomId: assignment.locationType === 'clinica' ? room?.id : null,
            locationType: assignment.locationType,
            workingSchedule: professional.workSchedule,
            now: new Date()
          })
        : null;
      if (scheduleEvaluation && !scheduleEvaluation.available) {
        issues.push({
          type: 'professional_schedule_unavailable',
          professionalId: professional.id,
          professionalName: professional.name,
          reasonCode: scheduleEvaluation.reasonCode,
          constraint: scheduleEvaluation.constraint,
          message: scheduleEvaluation.message
        });
      }
      const financialContext = evaluateFinancialContext(option, professional.id);
      if (financialContext.reviewRequired) {
        issues.push({ type: 'financial_context_invalid', reasonCode: financialContext.reasonCode, message: financialContext.warnings[0] || 'Revise o contexto financeiro.' });
      }
      const conflictTypes = Array.from(new Set([
        ...(conflict.conflicts || []).map((item: any) => item.conflictType).filter(Boolean),
        ...(scheduleEvaluation?.available === false && scheduleEvaluation.constraint ? [scheduleEvaluation.constraint] : [])
      ]));
      const operationalAvailable = !conflict.blocking && !issues.some((issue) => issue.type === 'professional_schedule_unavailable');
      const approvalAllowed = operationalAvailable && financialContext.valid === true && financialContext.reviewRequired !== true;
      const messages: string[] = [];
      const professionalConflict = issues.find((issue) => issue.type === 'professional_conflict');
      const roomConflict = issues.find((issue) => issue.type === 'room_conflict');
      const scheduleIssue = issues.find((issue) => issue.type === 'professional_schedule_unavailable');
      if (professionalConflict) messages.push(`${professional.name} já possui outra sessão das ${professionalConflict.conflictingStartAt} às ${professionalConflict.conflictingEndAt}.`);
      else if (scheduleIssue?.message) messages.push(scheduleIssue.message);
      else messages.push(`${professional.name} está disponível.`);
      if (assignment.locationType === 'clinica') {
        if (roomConflict) messages.push(`A ${roomInfo.displayName} já está ocupada nesse horário.`);
        else if (!scheduleIssue) messages.push(`A ${roomInfo.displayName} está disponível.`);
      }
      if (financialContext.warnings.length > 0) messages.push(financialContext.warnings[0]);
      return {
        operationalAvailable,
        approvalAllowed,
        message: messages.join(' '),
        conflictTypes,
        conflicts: conflict.conflicts,
        issues,
        financialContext
      };
    };

    const serializeAssignment = (optionIndex: number, professional: any, room: any, kind: 'current' | 'alternative', result: any) => {
      const roomInfo = formatRescheduleRoom(room, assignment.roomName);
      return {
        id: buildRescheduleAssignmentId(optionIndex, professional?.id || '', assignment.locationType === 'clinica' ? roomInfo.id : null),
        kind,
        professionalId: professional?.id || null,
        professionalName: professional?.name || 'Profissional não identificado',
        professional: { id: professional?.id || null, name: professional?.name || 'Profissional não identificado', available: result?.operationalAvailable === true },
        sessionBufferMinutes: Math.max(0, Math.round(Number(professional?.workSchedule?.sessionBufferMinutes ?? professional?.workSchedule?.session_buffer_minutes ?? 0) || 0)),
        roomId: assignment.locationType === 'clinica' ? roomInfo.id : null,
        roomName: assignment.locationType === 'clinica' ? roomInfo.name : null,
        roomSpecialtyName: assignment.locationType === 'clinica' ? roomInfo.specialtyName : null,
        roomDisplayName: assignment.locationType === 'clinica' ? roomInfo.displayName : null,
        room: assignment.locationType === 'clinica' ? { ...roomInfo, available: result?.operationalAvailable === true } : { id: null, name: null, specialtyName: null, displayName: null, available: true },
        locationType: assignment.locationType,
        available: result?.operationalAvailable === true,
        approvalAllowed: result?.approvalAllowed === true,
        financialContext: result?.financialContext || null,
        issues: result?.issues || [],
        message: result?.message || null
      };
    };

    const rawPreviewOptions = options.map((option, optionIndex) => {
      const directResult = evaluateCandidate(option, originalProfessional, originalRoom);
      const directAssignment = serializeAssignment(optionIndex, originalProfessional, originalRoom, 'current', directResult);
      const alternatives: any[] = [];
      const seen = new Set([directAssignment.id]);
      const tryAlternative = (professional: any, room: any) => {
        if (alternatives.length >= 3 || !professional?.id) return;
        if (!professionalAlternativeEligible(professional) || !roomAlternativeEligible(room)) return;
        const result = evaluateCandidate(option, professional, room);
        const serialized = serializeAssignment(optionIndex, professional, room, 'alternative', result);
        if (!serialized.id || seen.has(serialized.id)) return;
        seen.add(serialized.id);
        if (result.operationalAvailable) alternatives.push(serialized);
      };
      const conflictTypes = new Set(directResult.conflictTypes || []);
      if (!directResult.operationalAvailable && !conflictTypes.has('patient')) {
        if (assignment.locationType === 'clinica' && originalProfessional && conflictTypes.has('room')) {
          for (const room of activeRooms) {
            if (sanitizeString(room?.id, 180) !== assignment.roomId) tryAlternative(originalProfessional, room);
            if (alternatives.length >= 3) break;
          }
        }
        if (allowProfessionalSubstitution && alternatives.length < 3 && conflictTypes.has('professional')) {
          for (const professional of professionalCandidates) {
            if (professional.id === assignment.professionalId) continue;
            if (assignment.locationType === 'clinica') {
              if (originalRoom) tryAlternative(professional, originalRoom);
              if (conflictTypes.has('room')) {
                for (const room of activeRooms) {
                  tryAlternative(professional, room);
                  if (alternatives.length >= 3) break;
                }
              }
            } else {
              tryAlternative(professional, null);
            }
            if (alternatives.length >= 3) break;
          }
        }
      }
      const substitutionRestricted = conflictTypes.has('professional') && (
        !allowProfessionalSubstitution || (financialContextType === 'INSURANCE' && allowedProfessionalIds.length === 0)
      );
      const directMessage = substitutionRestricted
        ? `${directResult.message} Esta sessão deve permanecer com o profissional responsável.`
        : directResult.message;
      const assignments = [directAssignment, ...alternatives];
      const availableAssignments = assignments.filter((candidate) => candidate.available);
      const approvableAssignments = assignments.filter((candidate) => candidate.approvalAllowed);
      const competitionRows = competingOptionRows.filter((candidate: any) => {
        const delta = Math.abs(new Date(candidate?.scheduledStart).getTime() - new Date(option.scheduledStart).getTime());
        return Number.isFinite(delta) && delta < 60_000;
      });
      return {
        index: optionIndex,
        ...option,
        available: availableAssignments.length > 0,
        approvalAllowed: approvableAssignments.length > 0,
        message: directMessage,
        conflictTypes: directResult.conflictTypes || [],
        issues: directResult.issues || [],
        financialContext: directResult.financialContext,
        assignment: directAssignment,
        alternatives,
        assignments,
        alternativeRooms: alternatives.filter((candidate) => candidate.professionalId === assignment.professionalId).map((candidate) => candidate.room),
        alternativeProfessionals: alternatives.filter((candidate) => candidate.professionalId !== assignment.professionalId).map((candidate) => ({
          id: candidate.professionalId,
          name: candidate.professionalName,
          roomOptions: candidate.room?.id ? [candidate.room] : []
        })),
        competition: { total: competitionRows.length, exact: competitionRows.length },
        evaluationInput: {
          index: optionIndex,
          availableAssignmentCount: availableAssignments.length,
          directAssignmentAvailable: directAssignment.approvalAllowed === true,
          keepsOriginalProfessional: approvableAssignments.some((candidate) => candidate.professionalId === assignment.professionalId),
          keepsOriginalRoom: assignment.locationType !== 'clinica' || approvableAssignments.some((candidate) => candidate.roomId === assignment.roomId),
          financialContextCompatible: directResult.financialContext?.valid === true,
          financialReviewRequired: directResult.financialContext?.reviewRequired === true,
          competingRequestCount: competitionRows.length,
          exactCompetitionCount: competitionRows.length,
          reasons: [directMessage, ...(directResult.financialContext?.warnings || [])]
        }
      };
    });
    const ranked = rankRescheduleOptions(rawPreviewOptions.map((option) => option.evaluationInput));
    const rankingByIndex = new Map(ranked.map((option) => [option.index, option]));
    const previewOptions = rawPreviewOptions.map(({ evaluationInput, ...option }) => {
      const ranking = rankingByIndex.get(option.index);
      return {
        ...option,
        recommendation: option.approvalAllowed ? ranking?.recommendation || 'good' : option.available ? 'attention' : 'unavailable',
        recommendationLabel: option.approvalAllowed ? ranking?.recommendationLabel || 'Boa opção' : option.available ? 'Disponível com atenção' : 'Indisponível',
        score: ranking?.score || 0,
        reasons: ranking?.reasons || [option.message]
      };
    });

    return {
      requestId: sanitizeString(params.request?.id, 120),
      appointmentId: sanitizeString(appointment?.id, 120),
      checkedAt: new Date().toISOString(),
      allowProfessionalSubstitution,
      options: previewOptions
    };
  };

  const buildPortalRescheduleDateWindow = (rawDateFrom: unknown, rawMaxDays: unknown, currentScheduledStart?: unknown) => {
    const safeMaxDays = Math.min(7, Math.max(1, Math.round(Number(rawMaxDays || PORTAL_RESCHEDULE_WEEK_WINDOW_DAYS) || PORTAL_RESCHEDULE_WEEK_WINDOW_DAYS)));
    const explicitDateFrom = sanitizeDate(rawDateFrom);
    const originalDate = sanitizeIsoDateTime(currentScheduledStart) ? formatDateInAppointmentTimezone(new Date(sanitizeIsoDateTime(currentScheduledStart)!)) : formatDateInAppointmentTimezone(new Date());
    const originalWeekday = portalDateKeyWeekday(originalDate);
    const defaultFirstDate = originalWeekday >= 5 ? nextPortalWeekStart(originalDate) : startOfPortalWeek(originalDate);
    const firstDate = explicitDateFrom || defaultFirstDate;
    const firstDateTime = buildAppointmentDateTime(firstDate, '12:00') || new Date();
    const dates: string[] = [];
    for (let index = 0; index < safeMaxDays; index += 1) {
      const date = new Date(firstDateTime.getTime());
      date.setUTCDate(date.getUTCDate() + index);
      dates.push(formatDateInAppointmentTimezone(date));
    }
    return {
      firstDate,
      maxDays: safeMaxDays,
      dates,
      explicitDateFrom: Boolean(explicitDateFrom),
      weekStart: firstDate,
      weekEnd: dates[dates.length - 1] || firstDate,
      nextDateFrom: addPortalDateKeyDays(firstDate, 7)
    };
  };

  const buildPortalRescheduleAvailabilityForAppointment = async (appointment: any, user: any, rawOptions: any = {}) => {
    const organizationId = sanitizeString(appointment?.organization_id || appointment?.clinic_id, 120);
    const clinicId = sanitizeString(appointment?.clinic_id || organizationId || currentClinicId(user), 120);
    const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId, 120);
    const professionalId = sanitizeString(
      appointment?.therapist_id ||
        appointment?.therapistId ||
        appointment?.responsible_professional_id ||
        appointment?.responsibleProfessionalId ||
        appointment?.professional_id ||
        appointment?.professionalId,
      120
    );
    const roomId = sanitizeString(appointment?.room_id || appointment?.roomId, 180);
    const locationType = normalizeScheduleLocationType(appointment?.location_type || appointment?.locationType || appointment?.location);
    const durationMinutes = getCalendarAppointmentDuration(appointment);
    const currentScheduledStart = appointment?.scheduled_start_at || appointment?.scheduledStartAt || appointment?.scheduled_at || appointment?.scheduledAt;
    const initialWindow = buildPortalRescheduleDateWindow(rawOptions?.dateFrom || rawOptions?.date_from, rawOptions?.maxDays || rawOptions?.max_days, currentScheduledStart);
    let maxDays = initialWindow.maxDays;
    if (!professionalId) {
      return {
        success: true,
        data: {
          days: [],
          totalSlots: 0,
          windowDays: maxDays,
          maxSelectable: 3,
          professionalName: '',
          message: 'Não foi possível identificar o profissional responsável para calcular horários disponíveis.'
        }
      };
    }
    if (locationType === 'clinica' && !roomId) {
      return {
        success: true,
        data: {
          days: [],
          totalSlots: 0,
          windowDays: maxDays,
          maxSelectable: 3,
          professionalName: sanitizeString(appointment?.therapist_name || appointment?.therapistName || appointment?.professionalName, 180),
          message: 'Esta sessão precisa de sala/local confirmado pela clínica para sugerir horários.'
        }
      };
    }

    const scheduleData = await fetchProfessionalWorkingSchedule(clinicId, professionalId).catch((error: any) => {
      console.warn('[PortalReschedule] professional schedule fallback used:', error?.message || String(error));
      return null;
    });
    const workingSchedule = (scheduleData?.workSchedule || buildDefaultProfessionalWorkingSchedule(durationMinutes)) as PortalProfessionalWorkingSchedule;
    const buildAvailabilityForWindow = async (window: ReturnType<typeof buildPortalRescheduleDateWindow>) => {
      const input = {
        recurrenceDates: window.dates,
        patientId,
        professionalIds: [professionalId],
        roomId
      };
      const [tableAppointments, stateAppointments] = await Promise.all([
        fetchConflictAppointmentsFromTable({ clinicId, organizationId, input }).catch((error: any) => {
          console.warn('[PortalReschedule] table availability query skipped:', error?.message || String(error));
          return [];
        }),
        fetchConflictAppointmentsFromState(clinicId, input).catch(() => [])
      ]);
      const appointmentsById = new Map<string, any>();
      [...stateAppointments, ...tableAppointments].forEach((item: any, index: number) => {
        appointmentsById.set(sanitizeString(item?.id, 180) || `idx-${index}`, item);
      });
      return buildAvailableRescheduleSlots({
        appointmentId: appointment?.id,
        patientId,
        professionalId,
        roomId,
        locationType,
        currentScheduledStart,
        durationMinutes,
        existingAppointments: Array.from(appointmentsById.values()),
        dateFrom: window.firstDate,
        maxDays: window.maxDays,
        now: new Date(),
        workdayStart: rawOptions?.workdayStart || rawOptions?.workday_start || '08:00',
        workdayEnd: rawOptions?.workdayEnd || rawOptions?.workday_end || '18:00',
        workingSchedule,
        weekStart: window.weekStart,
        weekEnd: window.weekEnd,
        nextDateFrom: window.nextDateFrom
      });
    };
    let availability = await buildAvailabilityForWindow(initialWindow);
    if (availability.totalSlots === 0 && !initialWindow.explicitDateFrom) {
      const nextWindow = buildPortalRescheduleDateWindow(initialWindow.nextDateFrom, maxDays, currentScheduledStart);
      maxDays = nextWindow.maxDays;
      availability = await buildAvailabilityForWindow(nextWindow);
    }
    return {
      success: true,
      data: {
        ...availability,
        professionalName: sanitizeString(appointment?.therapist_name || appointment?.therapistName || appointment?.professionalName, 180),
        scheduleConfigured: Boolean(scheduleData?.configured),
        appointment: {
          id: appointment?.id,
          scheduledStart: appointment?.scheduled_start_at || appointment?.scheduledAt || appointment?.scheduled_at || null,
          scheduledEnd: appointment?.scheduled_end_at || appointment?.scheduledEndAt || null,
          durationMinutes
        }
      }
    };
  };

  const resolveValidPortalRescheduleOptions = async (appointment: any, user: any, body: any) => {
    const durationMinutes = getCalendarAppointmentDuration(appointment);
    const selectedOptions = normalizeRescheduleOptions(
      body?.rescheduleOptions ||
        body?.reschedule_options ||
        body?.selectedSlots ||
        body?.selected_slots ||
        (body?.requestedStart || body?.requested_start ? [{
          scheduledStart: body?.requestedStart || body?.requested_start,
          scheduledEnd: body?.requestedEnd || body?.requested_end
        }] : []),
      durationMinutes
    );
    if (selectedOptions.length === 0) return { ok: false, status: 400, error: 'Escolha pelo menos um horário disponível.' };
    const availabilityResult = await buildPortalRescheduleAvailabilityForAppointment(appointment, user, body);
    const availableSlots = flattenRescheduleSlotGroups(availabilityResult.data?.days || []);
    const validOptions: PortalRescheduleOption[] = [];
    for (const option of selectedOptions) {
      const selectedStart = new Date(option.scheduledStart).getTime();
      const match = availableSlots.find((slot) => Math.abs(new Date(slot.scheduledStart).getTime() - selectedStart) < 60_000);
      if (!match) {
        return { ok: false, status: 409, error: 'Este horário não está mais disponível. Escolha outra opção.' };
      }
      validOptions.push({
        scheduledStart: match.scheduledStart,
        scheduledEnd: match.scheduledEnd,
        date: match.date,
        dateLabel: match.dateLabel,
        start: match.start,
        end: match.end,
        label: match.label
      });
    }
    return { ok: true, options: validOptions };
  };

  const notifyPortalRescheduleApproval = async (params: {
    appointment: any;
    originalAppointment: any;
    organizationId: string;
    scheduledStart: string;
  }) => {
    try {
      const appointment = params.appointment || {};
      const patientId = sanitizeString(appointment?.patient_id || appointment?.patientId || params.originalAppointment?.patient_id || params.originalAppointment?.patientId, 120);
      if (!isUuid(patientId)) return;
      const patientResult = await readPortalPatientContexts([patientId]);
      if (patientResult.error && !extractMissingColumnName(patientResult.error)) throw patientResult.error;
      const patient = (Array.isArray(patientResult.data) ? patientResult.data[0] : null) || {};
      const clinicId = sanitizeString(appointment?.clinic_id || appointment?.clinicId || patient?.clinic_id || params.organizationId, 120);
      const clinicBranding = await readClinicBrandingForFamilyView(clinicId);
      const pushClinicLogoUrl = await resolvePushSafeClinicLogoUrl(
        { supabase, logger: console },
        [clinicBranding.logoUrl],
        clinicBranding.id || clinicId,
      ) || null;
      const scheduledAt = sanitizeIsoDateTime(params.scheduledStart) || sanitizeString(appointment?.scheduled_at || appointment?.scheduledAt, 80);
      const date = scheduledAt ? new Date(scheduledAt) : new Date();
      const dateLabel = formatDateInAppointmentTimezone(date).split('-').reverse().join('/');
      const timeLabel = formatTimeInAppointmentTimezone(date);
      const patientName = resolvePortalPatientDisplayName(
        patient,
        appointment?.patient_name || appointment?.patientName
      );
      const clinicName = clinicBranding.displayName || 'Clínica';
      const message = `Sessão de ${patientName} remarcada para ${dateLabel} às ${timeLabel}.`;
      const recipientUserId = sanitizeString(patient?.responsible_user_id, 120);
      const recipientEmail = sanitizeEmail(patient?.responsible_email || patient?.email);
      const sentAt = new Date().toISOString();
      if (recipientUserId || recipientEmail) {
        const notificationPayload = cleanObject({
          organization_id: isUuid(params.organizationId) ? params.organizationId : clinicBranding.id || clinicId || null,
          clinic_id: clinicBranding.id || (isUuid(clinicId) ? clinicId : null),
          recipient_user_id: isUuid(recipientUserId) ? recipientUserId : null,
          recipient_email: recipientEmail || null,
          patient_id: patientId,
          appointment_id: sanitizeString(appointment?.id || params.originalAppointment?.id, 120) || null,
          type: 'appointment_reschedule_approved',
          title: clinicName,
          message,
          sent_at: sentAt,
          scheduled_for: scheduledAt || sentAt,
          idempotency_key: `${sanitizeString(appointment?.id || params.originalAppointment?.id, 120)}:reschedule_approved:${scheduledAt || sentAt}`,
          metadata: sanitizeClinicalPayload({
            reminderKind: 'reschedule_approved',
            scheduledAt,
            clinicName,
            clinicLogoUrl: clinicBranding.logoUrl || null,
            patientName,
            appointmentStatus: 'SCHEDULED'
          })
        });
        const { error } = await supabase
          .from('portal_notifications')
          .upsert(notificationPayload, { onConflict: 'idempotency_key' });
        if (error && !isMissingRelationError(error)) {
          console.warn('[PortalReschedule] internal notification skipped:', error.message);
        }
      }
      await sendAppointmentNotification({
        supabase,
        patientId,
        patientEmail: recipientEmail || sanitizeEmail(patient?.email) || null,
        appointment: {
          id: sanitizeString(appointment?.id || params.originalAppointment?.id, 120),
          clinicId: clinicBranding.id || clinicId || null,
          scheduledAt,
          dateLabel,
          timeLabel,
          reminderKind: 'reschedule_approved',
          clinicName,
          clinicLogoUrl: pushClinicLogoUrl,
          patientName
        },
        clinicId: clinicBranding.id || clinicId || null,
        clinicName,
        clinicLogoUrl: pushClinicLogoUrl,
        patientName,
        title: clinicName,
        body: message,
        reminderKind: 'reschedule_approved',
        logger: console
      });
    } catch (error: any) {
      console.warn('[PortalReschedule] approval notification skipped:', error?.message || String(error));
    }
  };

  const fetchAppointmentActionRequestForAdmin = async (requestId: string, user: any) => {
    const safeRequestId = sanitizeString(requestId, 120);
    if (!isUuid(safeRequestId)) return { ok: false, status: 400, error: 'Solicitação inválida.' };
    const { data, error } = await supabase
      .from('appointment_action_requests')
      .select(APPOINTMENT_ACTION_REQUEST_SELECT)
      .eq('id', safeRequestId)
      .limit(1)
      .maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error)) return { ok: false, status: 503, error: 'Solicitações indisponíveis.' };
      throw error;
    }
    if (!data?.id) return { ok: false, status: 404, error: 'Solicitação não encontrada.' };
    const requestOrganizationId = sanitizeString(data.organization_id, 120);
    const activeClinicId = currentClinicId(user);
    if (
      !hasGlobalClinicAccess(user) &&
      (!isUuid(requestOrganizationId) || !isUuid(activeClinicId) || requestOrganizationId !== activeClinicId)
    ) {
      return { ok: false, status: 404, error: 'Solicitação não encontrada.' };
    }
    const appointmentContext = await fetchPortalAppointmentForUser(data.appointment_id, user, {
      patientId: data.patient_id,
      organizationId: requestOrganizationId
    });
    if (!appointmentContext.ok) return appointmentContext;
    return { ok: true, request: data, appointment: (appointmentContext as any).appointment };
  };

  const mapAuditLogToHumanHistory = (row: any) => ({
    id: sanitizeString(row?.id, 120) || null,
    action: sanitizeString(row?.action, 80),
    label: (() => {
      const action = sanitizeString(row?.action, 80);
      const metadata = row?.metadata && typeof row.metadata === 'object' && !Array.isArray(row.metadata)
        ? row.metadata
        : {};
      if (action === 'CANCEL_REJECTED' && sanitizeString(metadata?.resolutionReason, 80) === 'reschedule_approved') {
        return 'Solicitação de cancelamento encerrada após a remarcação';
      }
      const labels: Record<string, string> = {
        CONFIRMED_BY_RESPONSIBLE: 'Responsável confirmou a sessão',
        RESCHEDULE_REQUESTED: 'Responsável solicitou remarcação',
        RESCHEDULE_APPROVED: 'Remarcação aprovada pela clínica',
        RESCHEDULE_REJECTED: 'Remarcação recusada pela clínica',
        CANCEL_REQUESTED: 'Responsável solicitou cancelamento da sessão',
        CANCEL_APPROVED: 'Clínica aprovou o cancelamento solicitado pelo responsável',
        CANCEL_REJECTED: 'Cancelamento de sessão recusado pela clínica',
        CANCELLED: 'Sessão cancelada pela clínica',
        SIGNATURE_CREATED: 'Sessão assinada',
        SIGNATURE_REVOKED: 'Assinatura revogada'
      };
      return labels[action] || 'Ação registrada';
    })(),
    performedAt: row?.performed_at || null,
    role: sanitizeString(row?.performed_by_role, 40) || null,
    metadata: sanitizeClinicalPayload(row?.metadata || {})
  });

  const buildPortalAppointmentHistory = (rows: any[]) => {
    const orderedRows = Array.isArray(rows) ? rows : [];
    const latestRescheduleApprovalAt = orderedRows
      .filter((row: any) => sanitizeString(row?.action, 80).toUpperCase() === 'RESCHEDULE_APPROVED')
      .map((row: any) => new Date(row?.performed_at || 0).getTime())
      .filter((value: number) => Number.isFinite(value))
      .sort((a: number, b: number) => b - a)[0] || 0;
    return orderedRows
      .filter((row: any) => {
        if (sanitizeString(row?.action, 80).toUpperCase() !== 'RESCHEDULE_REQUESTED') return true;
        const requestedAt = new Date(row?.performed_at || 0).getTime();
        return !latestRescheduleApprovalAt || !Number.isFinite(requestedAt) || requestedAt > latestRescheduleApprovalAt;
      })
      .map(mapAuditLogToHumanHistory);
  };

  app.get('/api/portal/appointments', noStoreDynamicResponse, checkAuth, async (req: any, res) => {
    try {
      const role = sanitizeString(req.session.user?.role, 40).toLowerCase();
      const patientIds = await getPortalPatientIdsForUser(req.session.user);
      const authorizedPatientIdSet = new Set(patientIds.filter((patientId) => isUuid(patientId)));
      if (isResponsiblePortalRole(role) && patientIds.length === 0) {
        return res.json({ success: true, data: [] });
      }
      const patientEmails = new Set<string>();
      const patientClinicIds = new Set<string>();
      const portalPatientContextsById = new Map<string, any>();
      const sessionPatientEmail = sanitizeEmail(req.session.user?.email);
      const sessionClinicId = sanitizeString(currentClinicId(req.session.user), 120);
      if (sessionPatientEmail) patientEmails.add(sessionPatientEmail);
      if (isUuid(sessionClinicId)) patientClinicIds.add(sessionClinicId);
      if (patientIds.length > 0) {
        const patientContextResult = await readPortalPatientContexts(patientIds);
        if (patientContextResult.error && !extractMissingColumnName(patientContextResult.error)) {
          throw patientContextResult.error;
        }
        for (const patient of Array.isArray(patientContextResult.data) ? patientContextResult.data : []) {
          const patientId = sanitizeString(patient?.id, 120);
          const email = sanitizeEmail(patient?.email);
          const responsibleEmail = sanitizeEmail(patient?.responsible_email);
          const clinicId = sanitizeString(patient?.clinic_id, 120);
          if (isUuid(patientId)) portalPatientContextsById.set(patientId, patient);
          if (email) patientEmails.add(email);
          if (responsibleEmail) patientEmails.add(responsibleEmail);
          if (isUuid(clinicId)) patientClinicIds.add(clinicId);
        }
      }
      const fromIso = sanitizeIsoDateTime(req.query?.from || new Date(Date.now() - 7 * 86400000).toISOString());
      const toIso = sanitizeIsoDateTime(req.query?.to || new Date(Date.now() + 90 * 86400000).toISOString());
      const limit = parseBoundedListLimit(req.query?.limit, 40, 100);

      const applyPortalAppointmentScope = (query: any) => {
        if (patientIds.length > 0) return query.in('patient_id', patientIds);
        if (!isResponsiblePortalRole(role)) {
          const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
          if (clinicId) return query.eq('clinic_id', clinicId);
        }
        return query;
      };
      const buildPortalAppointmentRangeQuery = (dateColumn: 'scheduled_at' | 'scheduled_start_at') =>
        queryPortalAppointmentsWithSchemaFallback(
          (selectColumns) =>
            applyPortalAppointmentScope(
              supabase
                .from('appointments')
                .select(selectColumns)
                .gte(dateColumn, fromIso)
                .lte(dateColumn, toIso)
                .order(dateColumn, { ascending: true })
                .limit(limit)
            ),
          `patient_range_${dateColumn}`
        );

      const [scheduledAtResult, scheduledStartResult] = await Promise.all([
        buildPortalAppointmentRangeQuery('scheduled_at'),
        buildPortalAppointmentRangeQuery('scheduled_start_at')
      ]);
      const queryResults = [scheduledAtResult, scheduledStartResult];
      const rowsById = new Map<string, any>();
      for (const result of queryResults) {
        const error = (result as any).error;
        if (error) {
          if (hasMissingFinancialSchema(error)) continue;
          throw error;
        }
        for (const row of Array.isArray((result as any).data) ? (result as any).data : []) {
          const rowId = sanitizeString(row?.id, 120);
          if (rowId && !rowsById.has(rowId)) rowsById.set(rowId, row);
        }
      }
      if (patientEmails.size > 0 && patientClinicIds.size > 0) {
        const emailList = Array.from(patientEmails).slice(0, 10);
        const clinicList = Array.from(patientClinicIds).slice(0, 10);
        const buildPortalAppointmentEmailRangeQuery = (dateColumn: 'scheduled_at' | 'scheduled_start_at') =>
          queryPortalAppointmentsWithSchemaFallback(
            (selectColumns) =>
              supabase
                .from('appointments')
                .select(selectColumns)
                .in('patient_email', emailList)
                .in('clinic_id', clinicList)
                .gte(dateColumn, fromIso)
                .lte(dateColumn, toIso)
                .order(dateColumn, { ascending: true })
                .limit(limit),
            `patient_email_range_${dateColumn}`
          );
        const [emailScheduledAtResult, emailScheduledStartResult] = await Promise.all([
          buildPortalAppointmentEmailRangeQuery('scheduled_at'),
          buildPortalAppointmentEmailRangeQuery('scheduled_start_at')
        ]);
        for (const result of [emailScheduledAtResult, emailScheduledStartResult]) {
          const error = (result as any).error;
          if (error) {
            if (hasMissingFinancialSchema(error) || extractMissingColumnName(error) === 'patient_email') continue;
            throw error;
          }
          for (const row of Array.isArray((result as any).data) ? (result as any).data : []) {
            const rowId = sanitizeString(row?.id, 120);
            if (rowId && !rowsById.has(rowId)) rowsById.set(rowId, row);
          }
        }
      }
      if (rowsById.size < limit && patientClinicIds.size > 0) {
        const clinicList = Array.from(patientClinicIds).slice(0, 10);
        const buildPortalAppointmentClinicRangeQuery = (dateColumn: 'scheduled_at' | 'scheduled_start_at') =>
          queryPortalAppointmentsWithSchemaFallback(
            (selectColumns) =>
              supabase
                .from('appointments')
                .select(selectColumns)
                .in('clinic_id', clinicList)
                .gte(dateColumn, fromIso)
                .lte(dateColumn, toIso)
                .order(dateColumn, { ascending: true })
                .limit(Math.min(200, limit * 4)),
            `clinic_range_${dateColumn}`
          );
        const [clinicScheduledAtResult, clinicScheduledStartResult] = await Promise.all([
          buildPortalAppointmentClinicRangeQuery('scheduled_at'),
          buildPortalAppointmentClinicRangeQuery('scheduled_start_at')
        ]);
        for (const result of [clinicScheduledAtResult, clinicScheduledStartResult]) {
          const error = (result as any).error;
          if (error) {
            if (hasMissingFinancialSchema(error)) continue;
            throw error;
          }
          for (const row of Array.isArray((result as any).data) ? (result as any).data : []) {
            const rowId = sanitizeString(row?.id, 120);
            if (rowId && !rowsById.has(rowId)) rowsById.set(rowId, row);
          }
        }
      }
      const notificationScopedAppointmentIds = new Set<string>();
      if (patientIds.length > 0) {
        const notificationResult = await supabase
          .from('portal_notifications')
          .select('appointment_id')
          .in('patient_id', patientIds)
          .is('acknowledged_at', null)
          .limit(Math.min(200, limit * 4));
        if (!notificationResult.error) {
          const scopedNotificationAppointmentIds = Array.from(new Set(
            (notificationResult.data || [])
              .map((row: any) => sanitizeString(row?.appointment_id, 120))
              .filter((id: string) => isUuid(id))
          ));
          for (const id of scopedNotificationAppointmentIds) notificationScopedAppointmentIds.add(id);
          const notificationAppointmentIds = scopedNotificationAppointmentIds.filter((id) => !rowsById.has(id));
          if (notificationAppointmentIds.length > 0) {
            const notificationAppointments = await queryPortalAppointmentsWithSchemaFallback(
              (selectColumns) =>
                supabase
                  .from('appointments')
                  .select(selectColumns)
                  .in('id', notificationAppointmentIds)
                  .limit(Math.min(100, notificationAppointmentIds.length)),
              'notification_appointments'
            );
            if (notificationAppointments.error) {
              if (!hasMissingFinancialSchema(notificationAppointments.error)) throw notificationAppointments.error;
            } else {
              const fromTime = new Date(fromIso).getTime();
              const toTime = new Date(toIso).getTime();
              for (const row of Array.isArray(notificationAppointments.data) ? notificationAppointments.data : []) {
                const rowId = sanitizeString(row?.id, 120);
                const startsAt = buildCalendarAppointmentStart(row).getTime();
                if (!rowId || rowsById.has(rowId)) continue;
                if (Number.isFinite(fromTime) && startsAt < fromTime) continue;
                if (Number.isFinite(toTime) && startsAt > toTime) continue;
                rowsById.set(rowId, row);
              }
            }
          }
        } else if (!isMissingRelationError(notificationResult.error)) {
          throw notificationResult.error;
        }
      }
      if (rowsById.size === 0) {
        const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
        if (!clinicId && !isResponsiblePortalRole(role)) {
          return res.json({ success: true, data: [] });
        }
      }
      const rows = Array.from(rowsById.values())
        .sort((a, b) => buildCalendarAppointmentStart(a).getTime() - buildCalendarAppointmentStart(b).getTime());
      const visibleRows = [];
      for (const row of rows) {
        if (visibleRows.length >= limit) break;
        const rowId = sanitizeString(row?.id, 120);
        const rowPatientId = sanitizeString(row?.patient_id, 120);
        if (
          notificationScopedAppointmentIds.has(rowId) ||
          authorizedPatientIdSet.has(rowPatientId) ||
          await canPortalUserAccessPatient(rowPatientId, row, req.session.user)
        ) {
          visibleRows.push(row);
        }
      }
      const clinicBrandingById = new Map<string, any>();
      await Promise.all(Array.from(patientClinicIds).map(async (clinicId) => {
        clinicBrandingById.set(clinicId, await readClinicBrandingForFamilyView(clinicId));
      }));
      const policyByClinicId = await readClinicPatientReschedulePolicies(
        visibleRows.map((row: any) => {
          const source = parseAppointmentSourcePayloadForFamilyView(row?.source_payload || row?.sourcePayload);
          return row?.clinic_id || row?.clinicId || source?.clinic_id || source?.clinicId;
        })
      );
      return res.json({
        success: true,
        data: await Promise.all(visibleRows.map((row) => {
          const source = parseAppointmentSourcePayloadForFamilyView(row?.source_payload || row?.sourcePayload);
          const patientId = sanitizeString(row?.patient_id || row?.patientId || source?.patient_id || source?.patientId, 120);
          const clinicId = sanitizeString(row?.clinic_id || row?.clinicId || source?.clinic_id || source?.clinicId, 120);
          return serializePortalAppointmentForFamilyView(row, {}, {
            patient: portalPatientContextsById.get(patientId) || null,
            clinicBranding: clinicBrandingById.get(clinicId) || null,
            allowPatientReschedule: policyByClinicId.get(clinicId) !== false
          });
        }))
      });
    } catch (error: any) {
      console.warn('[PortalAppointments] list failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  app.get('/api/portal/appointments/:appointmentId', checkAuth, async (req: any, res) => {
    try {
      const context = await fetchPortalAppointmentForUser(req.params.appointmentId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(portalSafeError((context as any).status || 404));
      const appointment = (context as any).appointment;
      const appointmentId = sanitizeString(appointment.id, 120);
      const organizationId = sanitizeString(appointment.organization_id || appointment.clinic_id, 120);
      const patientId = sanitizeString(appointment.patient_id, 120);

      const [requestsResult, signaturesResult, auditResult, closureResult, sessionResult] = await Promise.all([
        supabase
          .from('appointment_action_requests')
          .select(APPOINTMENT_ACTION_REQUEST_SELECT)
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .order('created_at', { ascending: false })
          .limit(20),
        supabase
          .from('session_signatures')
          .select(SESSION_SIGNATURE_SELECT)
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .eq('status', 'SIGNED')
          .order('signed_at', { ascending: false })
          .limit(5),
        supabase
          .from('appointment_status_audit_logs')
          .select(APPOINTMENT_STATUS_AUDIT_SELECT)
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .order('performed_at', { ascending: false })
          .limit(20),
        supabase
          .from('appointment_closure_checks')
          .select(APPOINTMENT_CLOSURE_CHECK_SELECT)
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .limit(1)
          .maybeSingle(),
        supabase
          .from('aba_sessions')
          .select(CLOSURE_ABA_SESSION_SELECT)
          .eq('appointment_id', appointmentId)
          .eq('patient_id', patientId)
          .order('updated_at', { ascending: false })
          .limit(1)
          .maybeSingle()
      ]);
      for (const result of [requestsResult, signaturesResult, auditResult, closureResult, sessionResult]) {
        if ((result as any).error && !hasMissingFinancialSchema((result as any).error)) throw (result as any).error;
      }

      const signatures = signaturesResult.error ? [] : signaturesResult.data || [];
      const closure = closureResult.error ? null : closureResult.data || null;
      const checklist = Array.isArray(closure?.checklist) ? closure.checklist : [];
      const signaturePending = checklist.some((item: any) => item?.key === 'signature_present' && item?.status === 'FAILED');
      const session = sessionResult.error ? null : sessionResult.data || null;

      return res.json({
        success: true,
        data: {
          appointment: await serializePortalAppointmentForFamilyView(appointment, {
            signatureStatus: signatures.length > 0 ? 'SIGNED' : signaturePending ? 'PENDING' : 'NOT_REQUIRED',
            signedAt: signatures[0]?.signed_at || null
          }),
          actionRequests: requestsResult.error ? [] : requestsResult.data || [],
          signatures: signatures.map((signature: any) => ({
            signedByName: sanitizeString(signature?.signed_by_name, 180) || 'Responsável',
            signedByRole: sanitizeString(signature?.signed_by_role, 40) || 'responsible',
            signatureType: signature?.signature_type || 'DIGITAL_ACCEPTANCE',
            signedAt: signature?.signed_at || null,
            status: signature?.status || 'SIGNED'
          })),
          history: buildPortalAppointmentHistory(auditResult.error ? [] : auditResult.data || []),
          closure: closure ? {
            readinessStatus: closure.readiness_status || 'UNKNOWN',
            blockingIssuesCount: Number(closure.blocking_issues_count || 0),
            warningIssuesCount: Number(closure.warning_issues_count || 0),
            mainIssues: Array.isArray(closure.main_issues) ? closure.main_issues.slice(0, 4) : [],
            signaturePending
          } : null,
          session: session?.id ? {
            id: sanitizeString(session.id, 180),
            status: session.status || null,
            startedAt: session.started_at || session.actual_start_at || null,
            endedAt: session.ended_at || session.actual_end_at || null,
            durationMinutes: session.duration_minutes || session.actual_duration_minutes || null
          } : null,
          consentText: PORTAL_SESSION_CONSENT_TEXT,
          consentTextVersion: PORTAL_SESSION_CONSENT_TEXT_VERSION
        }
      });
    } catch (error: any) {
      console.warn('[PortalAppointments] detail failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

  app.post('/api/portal/appointments/:appointmentId/confirm', portalActionLimiter, checkAuth, async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 16 * 1024, 'Payload de confirmação de sessão')) return;
      const context = await fetchPortalAppointmentForUser(req.params.appointmentId, req.session.user);
      if (!context.ok) return res.status((context as any).status || 404).json(portalSafeError((context as any).status || 404));
      const appointment = (context as any).appointment;
      const previousStatus = normalizeOperationalAppointmentStatus(appointment.status);
      if (previousStatus === 'CONFIRMED') {
        const serializedAppointment = await serializePortalAppointmentForFamilyView(appointment);
        return res.json(buildPortalAppointmentActionResult({
          action: 'confirmed_by_family',
          appointment: serializedAppointment,
          message: 'Essa presença já estava confirmada.',
          user: req.session.user,
          alreadyAnswered: true
        }));
      }
      if (isAppointmentTerminalForPortalAction(previousStatus) || previousStatus === 'CANCEL_REQUESTED') {
        return res.status(409).json(portalSafeError(409));
      }

      const now = new Date().toISOString();
      const actorId = sanitizeString(req.session.user?.id, 120);
      const actorRole = sanitizeString(req.session.user?.role, 40) || 'responsible';
      const update = await updateAppointmentOperationalPatch(appointment.id, {
        status: 'confirmed',
        confirmed_at: now,
        confirmed_by: actorId || null,
        confirmed_by_role: actorRole,
        patient_response: 'confirmed',
        patient_responded_at: now,
        patient_confirmation_status: 'confirmed',
        patient_confirmation_at: now,
        patient_confirmation_by: actorId || null,
        patient_confirmation_source: 'portal',
        updated_at: now
      });
      if (update.error) throw update.error;
      const persistedRows = await readPersistedAppointmentRows([appointment.id], sanitizeString(appointment.clinic_id, 120));
      const persistedAppointment = persistedRows.find((row: any) => sanitizeString(row?.id, 120) === sanitizeString(appointment.id, 120));
      if (!persistedAppointment || normalizeOperationalAppointmentStatus(persistedAppointment.status) !== 'CONFIRMED') {
        return res.status(500).json({ success: false, error: 'Não foi possível confirmar a persistência da resposta.' });
      }
      const notificationUpdate = await acknowledgePortalAppointmentNotifications({
        appointment: persistedAppointment,
        user: req.session.user,
        action: 'confirmed_by_family',
        notificationId: req.body?.notificationId || req.body?.notification_id
      });
      if (!notificationUpdate.ok) {
        return res.status((notificationUpdate as any).status || 404).json(portalSafeError((notificationUpdate as any).status || 404));
      }
      await writeAppointmentStatusAuditLog({
        organizationId: appointment.organization_id || appointment.clinic_id,
        appointmentId: appointment.id,
        patientId: appointment.patient_id,
        action: 'CONFIRMED_BY_RESPONSIBLE',
        previousStatus,
        newStatus: 'CONFIRMED',
        performedBy: actorId,
        performedByRole: actorRole,
        metadata: { source: 'portal' }
      });
      void regenerateClosureForAppointments([appointment.id], req.session.user, 'appointment_confirmed_by_responsible');
      const serializedAppointment = await serializePortalAppointmentForFamilyView(persistedAppointment);
      return res.json(buildPortalAppointmentActionResult({
        action: 'confirmed_by_family',
        appointment: serializedAppointment,
        message: 'Sessão confirmada.',
        user: req.session.user,
        notificationIds: notificationUpdate.notificationIds
      }));
    } catch (error: any) {
      console.warn('[PortalAppointments] confirm failed:', error?.message || String(error));
      return res.status(500).json(portalSafeError(500));
    }
  });

