  function normalizeHydratedClosureChecklist(checklist: any[], hydratedRow: any) {
    const items = Array.isArray(checklist) ? checklist : [];
    const payerName = sanitizeString(hydratedRow?.payer_name || hydratedRow?.payer_name_snapshot, 180);
    const hasRealPayer = isUuid(sanitizeString(hydratedRow?.payer_id, 120)) || Boolean(payerName && payerName !== 'Sem pagador');
    const suggestedPayerName = sanitizeString(hydratedRow?.suggested_payer_name, 180);
    return items.map((item: any) => {
      const normalizedItem = {
        ...item,
        label: repairChecklistDisplayText(item?.label, 180) || item?.label,
        message: repairChecklistDisplayText(item?.message, 800) || item?.message
      };
      if (normalizedItem?.key !== 'payer_linked') return normalizedItem;
      return {
        ...normalizedItem,
        status: hasRealPayer ? 'PASSED' : 'FAILED',
        required: true,
        severity: hasRealPayer ? 'LOW' : 'HIGH',
        message: hasRealPayer
          ? `Pagador ${payerName || 'informado'} aplicado ao atendimento.`
          : suggestedPayerName
            ? `Pagador sugerido pelo plano financeiro: ${suggestedPayerName}. Ainda não aplicado ao atendimento.`
            : 'Pagador não configurado para esta conferência.',
        section: 'preSession',
        operationalStatus: hasRealPayer ? 'passed' : 'blocking_now',
        evidence: {
          ...(item?.evidence || {}),
          present: hasRealPayer,
          suggested: Boolean(!hasRealPayer && suggestedPayerName),
          suggestedPayerName: suggestedPayerName || null,
          payerName: hasRealPayer ? payerName || null : null
        }
      };
    });
  }

  const setAppointmentPatientConfirmationStateCandidate = (
    states: Map<string, any>,
    appointmentId: string,
    state: any
  ) => {
    if (!isUuid(appointmentId) || !state || state.status === 'pending') return;
    const previous = states.get(appointmentId);
    const previousTime = previous?.respondedAt ? new Date(previous.respondedAt).getTime() : 0;
    const nextTime = state?.respondedAt ? new Date(state.respondedAt).getTime() : 0;
    if (!previous || nextTime >= previousTime) states.set(appointmentId, state);
  };

  const mapAppointmentAuditRowToPatientConfirmationState = (row: any) => {
    const action = sanitizeString(row?.action, 80).toUpperCase();
    const newStatus = sanitizeString(row?.new_status || row?.newStatus, 80);
    let status: any = newStatus || action;
    if (action === 'CONFIRMED_BY_RESPONSIBLE') status = 'confirmed';
    else if (action === 'RESCHEDULE_REQUESTED') status = 'reschedule_requested';
    else if (action === 'CANCEL_REQUESTED') status = 'declined';
    return buildPatientConfirmationStateForAgenda({
      status,
      response: status,
      respondedAt: row?.performed_at || row?.performedAt || row?.created_at || row?.createdAt,
      source: 'appointment_status_audit_logs'
    });
  };

  const resolveAppointmentPatientConfirmationStates = async (
    appointmentIds: string[],
    clinicId: string,
    organizationId?: string
  ) => {
    const ids = Array.from(new Set((appointmentIds || []).map((id) => sanitizeString(id, 120)).filter((id) => isUuid(id))));
    const states = new Map<string, any>();
    if (ids.length === 0) return states;

    try {
      const rows = await readPersistedAppointmentRows(ids, clinicId);
      for (const row of rows || []) {
        const appointmentId = sanitizeString(row?.id, 120);
        const appointmentStatus = normalizeOperationalAppointmentStatus(row?.status);
        const hasAppointmentResponseStatus = [
          'CONFIRMED',
          'RESCHEDULE_REQUESTED',
          'CANCEL_REQUESTED'
        ].includes(appointmentStatus);
        const hasExplicitResponse = Boolean(
          row?.patient_confirmation_status ||
            row?.patientConfirmationStatus ||
            row?.patient_response ||
            row?.patientResponse ||
            row?.patient_confirmation_at ||
            row?.patient_responded_at ||
            hasAppointmentResponseStatus
        );
        const state = buildPatientConfirmationStateForAgenda({
          status:
            row?.patient_confirmation_status ||
            row?.patientConfirmationStatus ||
            row?.patient_response ||
            row?.patientResponse ||
            (hasExplicitResponse ? row?.status : null),
          response: row?.patient_response || row?.patientResponse || null,
          respondedAt:
            row?.patient_responded_at ||
            row?.patientRespondedAt ||
            row?.patient_confirmation_at ||
            row?.patientConfirmationAt ||
            row?.updated_at ||
            null,
          source: hasExplicitResponse
            ? row?.patient_confirmation_source || row?.patientConfirmationSource || 'appointments'
            : null
        });
        if (hasExplicitResponse) setAppointmentPatientConfirmationStateCandidate(states, appointmentId, state);
      }
    } catch (error: any) {
      if (!hasMissingFinancialSchema(error) && !isMissingRelationError(error)) {
        console.warn('[Calendar] appointment patient confirmation table enrichment skipped:', error?.message || String(error));
      }
    }

    try {
      const organizationIds = Array.from(new Set([
        sanitizeString(organizationId, 120),
        sanitizeString(clinicId, 120)
      ].filter((id) => isUuid(id))));
      let auditQuery = supabase
        .from('appointment_status_audit_logs')
        .select(APPOINTMENT_STATUS_AUDIT_SELECT)
        .in('appointment_id', ids)
        .in('action', ['CONFIRMED_BY_RESPONSIBLE', 'RESCHEDULE_REQUESTED', 'RESCHEDULE_APPROVED', 'CANCEL_REQUESTED', 'CANCEL_APPROVED'])
        .order('performed_at', { ascending: false })
        .limit(Math.min(ids.length * 8, 1000));
      if (organizationIds.length === 1) auditQuery = auditQuery.eq('organization_id', organizationIds[0]);
      else if (organizationIds.length > 1) auditQuery = auditQuery.in('organization_id', organizationIds);
      const auditResult = await auditQuery;
      if (auditResult.error) {
        if (!hasMissingFinancialSchema(auditResult.error) && !isMissingRelationError(auditResult.error)) throw auditResult.error;
      } else {
        const resolvedAppointmentIds = new Set<string>();
        for (const row of auditResult.data || []) {
          const appointmentId = sanitizeString(row?.appointment_id, 120);
          const action = sanitizeString(row?.action, 80).toUpperCase();
          if (action === 'RESCHEDULE_APPROVED' || action === 'CANCEL_APPROVED') {
            resolvedAppointmentIds.add(appointmentId);
            states.delete(appointmentId);
            continue;
          }
          if (resolvedAppointmentIds.has(appointmentId)) continue;
          setAppointmentPatientConfirmationStateCandidate(
            states,
            appointmentId,
            mapAppointmentAuditRowToPatientConfirmationState(row)
          );
        }
      }
    } catch (error: any) {
      console.warn('[Calendar] appointment patient confirmation audit enrichment skipped:', error?.message || String(error));
    }

    try {
      const organizationIds = Array.from(new Set([
        sanitizeString(organizationId, 120),
        sanitizeString(clinicId, 120)
      ].filter((id) => isUuid(id))));
      let requestQuery = supabase
        .from('appointment_action_requests')
        .select(CALENDAR_ACTION_REQUEST_STATE_SELECT)
        .in('appointment_id', ids)
        .eq('request_type', 'RESCHEDULE')
        .eq('status', 'PENDING')
        .order('created_at', { ascending: false });
      if (organizationIds.length === 1) requestQuery = requestQuery.eq('organization_id', organizationIds[0]);
      else if (organizationIds.length > 1) requestQuery = requestQuery.in('organization_id', organizationIds);
      const requestResult = await requestQuery;
      if (requestResult.error) {
        if (!hasMissingFinancialSchema(requestResult.error) && !isMissingRelationError(requestResult.error)) throw requestResult.error;
      } else {
        const latestByAppointment = new Map<string, any>();
        for (const row of requestResult.data || []) {
          const appointmentId = sanitizeString(row?.appointment_id, 120);
          if (isUuid(appointmentId) && !latestByAppointment.has(appointmentId)) latestByAppointment.set(appointmentId, row);
        }
        for (const appointmentId of ids) {
          const row = latestByAppointment.get(appointmentId);
          const current = states.get(appointmentId);
          if (row) {
            states.set(appointmentId, {
              ...buildPatientConfirmationStateForAgenda({
                status: 'reschedule_requested',
                response: 'reschedule_requested',
                respondedAt: row?.updated_at || row?.created_at || null,
                source: 'appointment_action_requests'
              }),
              hasPendingReschedule: true,
              rescheduleStatus: 'PENDING',
              rescheduleRequestId: sanitizeString(row?.id, 120) || null
            });
            continue;
          }
          const resolvedState = current?.status && current.status !== 'reschedule_requested'
            ? current
            : buildPatientConfirmationStateForAgenda({ status: 'pending', source: 'appointment_action_requests' });
          states.set(appointmentId, {
            ...resolvedState,
            hasPendingReschedule: false,
            rescheduleStatus: 'NONE',
            rescheduleRequestId: null
          });
        }
      }
    } catch (error: any) {
      console.warn('[Calendar] appointment reschedule request enrichment skipped:', error?.message || String(error));
    }

    return states;
  };

  const resolveAppointmentPatientConfirmationState = async (
    appointmentId: string,
    clinicId: string,
    organizationId?: string
  ) => {
    const states = await resolveAppointmentPatientConfirmationStates([appointmentId], clinicId, organizationId);
    return states.get(sanitizeString(appointmentId, 120)) || null;
  };

  const enrichCalendarEventsWithPatientConfirmationState = async (
    events: any[],
    clinicId: string,
    organizationId?: string
  ) => {
    const appointmentIds = (events || [])
      .map((event: any) => sanitizeString(event?.id || event?.appointment_id || event?.appointmentId, 120))
      .filter((id: string) => isUuid(id));
    if (appointmentIds.length === 0) return events;
    const states = await resolveAppointmentPatientConfirmationStates(appointmentIds, clinicId, organizationId || clinicId);
    return (events || []).map((event: any) => {
      const appointmentId = sanitizeString(event?.id || event?.appointment_id || event?.appointmentId, 120);
      return applyPatientConfirmationStateToCalendarEvent(event, states.get(appointmentId));
    });
  };

  const fetchCalendarEventsFromClinicState = async (clinicId: string, range: any, filters: any, counters: any = {}, organizationId?: string) => {
    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId, logger: console });
    if (stateResult.error) {
      if (hasMissingFinancialSchema(stateResult.error)) return [];
      throw stateResult.error;
    }
    const fromTime = new Date(range.fromIso).getTime();
    const toTime = new Date(range.toIso).getTime();
    const sourceRows = await hydrateCalendarPatientNames(
      (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
        .map((appointment: any) => ({ ...appointment, source_payload: appointment })),
      clinicId
    );
    const events = sourceRows
      .map((appointment: any) => normalizeCalendarAppointmentRow(appointment, counters))
      .filter((event: any) => {
        const start = new Date(event.start_time).getTime();
        return start >= fromTime && start <= toTime && calendarEventMatchesFilters(event, filters);
      })
      .slice(0, range.limit);
    return enrichCalendarEventsWithPatientConfirmationState(events, clinicId, organizationId || clinicId);
  };

  const fetchCalendarAppointmentDetailRow = async (eventId: string, clinicId: string, user: any) => {
    if (isUuid(eventId)) {
      let query = supabase
        .from('appointments')
        .select(CALENDAR_EVENT_DETAIL_SELECT)
        .eq('id', eventId)
        .limit(1);
      if (!hasGlobalClinicAccess(user) && clinicId) query = query.eq('clinic_id', clinicId);
      const { data, error } = await query.maybeSingle();
      if (!error && data) return data;
      if (error && !hasMissingFinancialSchema(error)) throw error;
    }
    const stateResult = await fetchClinicStateWithSchemaFallback({ supabase, clinicId, logger: console });
    if (stateResult.error) {
      if (hasMissingFinancialSchema(stateResult.error)) return null;
      throw stateResult.error;
    }
    const appointment = (Array.isArray(stateResult.data?.appointments) ? stateResult.data.appointments : [])
      .find((item: any) => String(item?.id) === eventId);
    return appointment ? { ...appointment, source_payload: appointment } : null;
  };

  app.get('/api/calendar/events', noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'receptionist', 'therapist', 'admin', 'owner'), async (req: any, res) => {
    try {
      const range = parseCalendarRangeParams(req.query);
      if (!range.ok) return res.status(400).json({ success: false, error: 'Intervalo da agenda inválido.' });
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const filters = {
        therapistIds: parseCalendarFilterList(req.query?.therapistId || req.query?.therapistIds).filter((id) => id !== 'all'),
        patientIds: parseCalendarFilterList(req.query?.patientId || req.query?.patientIds).filter((id) => id !== 'all'),
        types: parseCalendarFilterList(req.query?.type || req.query?.types),
        statuses: parseCalendarFilterList(req.query?.status || req.query?.statuses),
        roomIds: parseCalendarFilterList(req.query?.roomId || req.query?.roomIds).filter((id) => id !== 'all'),
        locationTypes: parseCalendarFilterList(req.query?.locationType || req.query?.locationTypes).filter((id) => id !== 'all'),
        schoolIds: parseCalendarFilterList(req.query?.schoolId || req.query?.schoolIds).filter((id) => id !== 'all'),
        schoolUnitIds: parseCalendarFilterList(req.query?.schoolUnitId || req.query?.schoolUnitIds).filter((id) => id !== 'all')
      };

      let query = supabase
        .from('appointments')
        .select(CALENDAR_EVENT_SELECT)
        .gte('scheduled_at', range.fromIso)
        .lte('scheduled_at', range.toIso)
        .is('deleted_at', null)
        .neq('status', 'deleted')
        .order('scheduled_at', { ascending: true })
        .limit(range.limit);
      if (!hasGlobalClinicAccess(req.session.user) && clinicId) query = query.eq('clinic_id', clinicId);
      if (organizationId && isUuid(organizationId)) query = query.eq('organization_id', organizationId);
      if (filters.therapistIds.length > 0) query = query.in('therapist_id', filters.therapistIds);
      if (filters.patientIds.length > 0) query = query.in('patient_id', filters.patientIds);
      if (filters.roomIds.length > 0) query = query.in('room_id', filters.roomIds);
      if (filters.schoolIds.length > 0) query = query.in('school_id', filters.schoolIds);
      if (filters.schoolUnitIds.length > 0) query = query.in('school_unit_id', filters.schoolUnitIds);
      if (filters.statuses.length === 1 && !filters.statuses[0].includes('_')) query = query.eq('status', filters.statuses[0]);

      const { data, error } = await query;
      if (error) {
        if (hasMissingFinancialSchema(error)) {
          const fallback = await fetchCalendarEventsFromClinicState(clinicId, range, filters, {}, organizationId);
          return res.json({ success: true, data: fallback, source: 'clinic_state_fallback' });
        }
        throw error;
      }

      const rows = Array.isArray(data) ? data : [];
      const hydratedRows = await hydrateCalendarPatientNames(rows, clinicId);
      const patientIds = rows.map((row: any) => sanitizeString(row?.patient_id, 120)).filter(Boolean);
      const appointmentIds = rows.map((row: any) => sanitizeString(row?.id, 180)).filter(Boolean);
      const [planCountByPatient, probeCountByAppointment] = await Promise.all([
        countCalendarPlanItemsByPatient(patientIds, clinicId, organizationId, req.session.user),
        countCalendarMaintenanceProbesByAppointment(appointmentIds, clinicId, organizationId, req.session.user)
      ]);
      const closureByAppointment = await fetchClosureSummariesByAppointment(appointmentIds, organizationId, req.session.user);
      const counters = { planCountByPatient, probeCountByAppointment };
      const normalizedEvents = hydratedRows
        .map((row: any) => {
          const closure = closureByAppointment.get(sanitizeString(row?.id, 120));
          return normalizeCalendarAppointmentRow(
            closure ? { ...row, ...mapClosureRowToCalendarFields(closure) } : row,
            counters
          );
        })
        .filter((event: any) => calendarEventMatchesFilters(event, filters))
        .slice(0, range.limit);
      const events = await enrichCalendarEventsWithPatientConfirmationState(
        normalizedEvents,
        clinicId,
        organizationId
      );
      return res.json({ success: true, data: events, source: 'appointments' });
    } catch (error: any) {
      console.warn('[Calendar] event list failed:', error?.message || String(error));
      return res.status(500).json({ success: false, error: 'Não foi possível carregar a agenda agora.' });
    }
  });

  app.get('/api/calendar/events/:eventId/detail', noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'receptionist', 'therapist', 'admin', 'owner'), async (req: any, res) => {
    try {
      const eventId = sanitizeString(req.params.eventId, 180);
      if (!eventId) return res.status(400).json({ success: false, error: 'Sessão inválida.' });
      const clinicId = sanitizeString(currentClinicId(req.session.user), 120);
      const organizationId = sanitizeString(req.session.user?.organizationId || req.session.user?.organization_id || clinicId, 120);
      const row = await fetchCalendarAppointmentDetailRow(eventId, clinicId, req.session.user);
      if (!row) return res.status(404).json({ success: false, error: 'Sessão não encontrada.' });
      try {
        await persistAppointmentClosureCheck({
          appointmentId: eventId,
          user: req.session.user,
          force: true,
          scopedAppointment: row
        });
      } catch (closureRefreshError: any) {
        console.warn('[Calendar] detail closure refresh skipped:', {
          appointmentId: eventId,
          message: closureRefreshError?.message || String(closureRefreshError)
        });
      }
      const closureByAppointment = await fetchClosureSummariesByAppointment([eventId], organizationId, req.session.user);
      const closure = closureByAppointment.get(eventId);
      const [hydratedRow] = await hydrateCalendarPatientNames([closure ? { ...row, ...mapClosureRowToCalendarFields(closure) } : row], clinicId);
      const baseEvent = normalizeCalendarAppointmentRow(hydratedRow || row);
      const event = applyPatientConfirmationStateToCalendarEvent(
        baseEvent,
        await resolveAppointmentPatientConfirmationState(eventId, clinicId, organizationId)
      );
      const patientId = sanitizeString(event.patient_id, 120);

      let planItems: any[] = [];
      let maintenanceProbes: any[] = [];
      let overdueMaintenanceProbes: any[] = [];
      let acceptedRecommendations: any[] = [];
      let actionRequests: any[] = [];
      let statusHistory: any[] = [];
      let signatures: any[] = [];
      let billingContext: any = null;
      let billingDocuments: any[] = [];
      let patientFinance: any = null;

      if (isUuid(eventId) && isUuid(organizationId)) {
        const [requestsResult, auditResult, signaturesResult, billingResult, documentsResult, patientFinanceResult] = await Promise.all([
          supabase
            .from('appointment_action_requests')
            .select(APPOINTMENT_ACTION_REQUEST_SELECT)
            .eq('organization_id', organizationId)
            .eq('appointment_id', eventId)
            .order('created_at', { ascending: false })
            .limit(20),
          supabase
            .from('appointment_status_audit_logs')
            .select(APPOINTMENT_STATUS_AUDIT_SELECT)
            .eq('organization_id', organizationId)
            .eq('appointment_id', eventId)
            .order('performed_at', { ascending: false })
            .limit(20),
          supabase
            .from('session_signatures')
            .select(SESSION_SIGNATURE_SELECT)
            .eq('organization_id', organizationId)
            .eq('appointment_id', eventId)
            .eq('status', 'SIGNED')
            .order('signed_at', { ascending: false })
            .limit(5),
          supabase
            .from('appointment_billing_contexts')
            .select(APPOINTMENT_BILLING_CONTEXT_SELECT)
            .eq('organization_id', organizationId)
            .eq('appointment_id', eventId)
            .limit(1)
            .maybeSingle(),
          supabase
            .from('appointment_required_documents')
            .select(APPOINTMENT_REQUIRED_DOCUMENT_SELECT)
            .eq('organization_id', organizationId)
            .eq('appointment_id', eventId)
            .order('created_at', { ascending: false })
            .limit(20),
          supabase
            .from('patient_financial_appointment_summaries')
            .select('organization_id,clinic_id,appointment_id,patient_id,professional_id,patient_name_snapshot,professional_name_snapshot,service_type_snapshot,specialty_snapshot,appointment_scheduled_at,quantity,unit_amount,subtotal,payment_id,original_amount,additional_amount,discount_amount,total_amount,paid_amount,refunded_amount,balance_amount,due_date,method,last_payment_at,financial_status,source,notes,created_at,updated_at')
            .eq('organization_id', organizationId)
            .eq('appointment_id', eventId)
            .limit(1)
            .maybeSingle()
        ]);
        if (!requestsResult.error) actionRequests = requestsResult.data || [];
        else if (!hasMissingFinancialSchema(requestsResult.error)) throw requestsResult.error;
        if (!auditResult.error) statusHistory = (auditResult.data || []).map(mapAuditLogToHumanHistory);
        else if (!hasMissingFinancialSchema(auditResult.error)) throw auditResult.error;
        if (!signaturesResult.error) signatures = (signaturesResult.data || []).map((signature: any) => ({
          signedByName: sanitizeString(signature?.signed_by_name, 180) || 'Responsável',
          signedByRole: sanitizeString(signature?.signed_by_role, 40) || 'responsible',
          signedAt: signature?.signed_at || null,
          signatureType: signature?.signature_type || 'DIGITAL_ACCEPTANCE',
          status: signature?.status || 'SIGNED'
        }));
        else if (!hasMissingFinancialSchema(signaturesResult.error)) throw signaturesResult.error;
        if (!billingResult.error) billingContext = billingResult.data || null;
        else if (!hasMissingFinancialSchema(billingResult.error)) throw billingResult.error;
        if (!documentsResult.error) billingDocuments = documentsResult.data || [];
        else if (!hasMissingFinancialSchema(documentsResult.error)) throw documentsResult.error;
        if (!patientFinanceResult.error) patientFinance = patientFinanceResult.data || null;
        else if (!hasMissingFinancialSchema(patientFinanceResult.error) && !isMissingRelationError(patientFinanceResult.error)) throw patientFinanceResult.error;
      }

      if (isUuid(patientId)) {
        let planQuery = supabase
          .from('aba_next_session_plan_items')
          .select(ABA_NEXT_SESSION_PLAN_ITEM_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .eq('status', 'PLANNED')
          .order('created_at', { ascending: false })
          .limit(20);
        planQuery = applyAbaTenantScope(planQuery, req.session.user, clinicId, organizationId);
        const planResult = await planQuery;
        if (!planResult.error) planItems = planResult.data || [];
        else if (!hasMissingFinancialSchema(planResult.error)) throw planResult.error;

        let recommendationQuery = supabase
          .from('aba_clinical_recommendations')
          .select(ABA_CLINICAL_RECOMMENDATION_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .in('status', ['ACCEPTED', 'APPLIED_TO_NEXT_SESSION'])
          .order('updated_at', { ascending: false })
          .limit(20);
        recommendationQuery = applyAbaTenantScope(recommendationQuery, req.session.user, clinicId, organizationId);
        const recommendationResult = await recommendationQuery;
        if (!recommendationResult.error) acceptedRecommendations = recommendationResult.data || [];
        else if (!hasMissingFinancialSchema(recommendationResult.error)) throw recommendationResult.error;

        if (isUuid(eventId)) {
          let linkedProbeQuery = supabase
            .from('aba_maintenance_schedules')
            .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
            .eq('organization_id', organizationId)
            .eq('patient_id', patientId)
            .eq('appointment_id', eventId)
            .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES)
            .order('target_due_date', { ascending: true })
            .limit(20);
          linkedProbeQuery = applyAbaTenantScope(linkedProbeQuery, req.session.user, clinicId, organizationId);
          const linkedProbeResult = await linkedProbeQuery;
          if (!linkedProbeResult.error) maintenanceProbes = linkedProbeResult.data || [];
          else if (!hasMissingFinancialSchema(linkedProbeResult.error)) throw linkedProbeResult.error;

          let candidateProbeQuery = supabase
            .from('aba_maintenance_schedules')
            .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
            .eq('organization_id', organizationId)
            .eq('patient_id', patientId)
            .eq('candidate_appointment_id', eventId)
            .eq('status', 'PENDING_CONFIRMATION')
            .order('target_due_date', { ascending: true })
            .limit(20);
          candidateProbeQuery = applyAbaTenantScope(candidateProbeQuery, req.session.user, clinicId, organizationId);
          const candidateProbeResult = await candidateProbeQuery;
          if (!candidateProbeResult.error) {
            const byId = new Map<string, any>();
            [...maintenanceProbes, ...(candidateProbeResult.data || [])].forEach((probe: any) => {
              const id = sanitizeString(probe?.id, 180);
              if (id) byId.set(id, probe);
            });
            maintenanceProbes = Array.from(byId.values());
          } else if (!hasMissingFinancialSchema(candidateProbeResult.error) && extractMissingColumnName(candidateProbeResult.error) !== 'candidate_appointment_id') {
            throw candidateProbeResult.error;
          }
        }

        let overdueProbeQuery = supabase
          .from('aba_maintenance_schedules')
          .select(ABA_MAINTENANCE_SCHEDULE_SELECT)
          .eq('organization_id', organizationId)
          .eq('patient_id', patientId)
          .is('appointment_id', null)
          .in('status', ABA_ACTIVE_MAINTENANCE_SCHEDULE_STATUSES)
          .lte('target_due_date', event.start_time)
          .order('target_due_date', { ascending: true })
          .limit(20);
        overdueProbeQuery = applyAbaTenantScope(overdueProbeQuery, req.session.user, clinicId, organizationId);
        const overdueProbeResult = await overdueProbeQuery;
        if (!overdueProbeResult.error) overdueMaintenanceProbes = overdueProbeResult.data || [];
        else if (!hasMissingFinancialSchema(overdueProbeResult.error)) throw overdueProbeResult.error;
      }

      const enrichedMaintenanceRows = await enrichMaintenanceRowsWithTargetDisplay(
        [...maintenanceProbes, ...overdueMaintenanceProbes],
        clinicId,
        organizationId,
        req.session.user
      );
      const enrichedMaintenanceById = new Map<string, any>();
      enrichedMaintenanceRows.forEach((row: any) => {
        const id = sanitizeString(row?.id, 180);
        if (id) enrichedMaintenanceById.set(id, row);
      });
      maintenanceProbes = maintenanceProbes.map((row: any) => enrichedMaintenanceById.get(sanitizeString(row?.id, 180)) || row);
      overdueMaintenanceProbes = overdueMaintenanceProbes.map((row: any) => enrichedMaintenanceById.get(sanitizeString(row?.id, 180)) || row);

      return res.json({
        success: true,
        data: {
          event: {
            ...event,
            notes: sanitizeTextField(row?.notes || parseCalendarSourcePayload(row?.source_payload)?.notes || parseCalendarSourcePayload(row?.source_payload)?.note, 1200) || null,
            duration_minutes: getCalendarAppointmentDuration(row)
          },
          team: event.therapist_name ? [{ id: event.therapist_id, name: event.therapist_name, role: 'Responsável' }] : [],
          nextSessionPlanItems: planItems,
          acceptedRecommendations,
          maintenanceProbes,
          overdueMaintenanceProbes,
          sessionRecord: event.has_session_record ? { label: 'Sessão registrada', status: 'registered' } : null,
          report: event.has_report ? { label: 'Relatório disponível', status: 'ready' } : null,
          pendingSignature: event.has_pending_signature,
          closure: closure ? mapClosureRowToCalendarFields(closure) : null,
          billingContext: serializeBillingContext(billingContext || {
            appointment_id: eventId,
            patient_id: event.patient_id,
            service_type: event.type || event.service_type || null
          }, null, billingDocuments, await resolveAppointmentBillingSuggestion({
            organizationId,
            patientId: event.patient_id,
            serviceType: event.type || event.service_type || null,
            payerId: event.payer_id || billingContext?.payer_id || null,
            payerName: event.payer_name_snapshot || billingContext?.payer_name_snapshot || null,
            appointmentDate: event.scheduled_start_at || event.scheduled_at || event.date || null,
            procedureCode: event.procedure_code || billingContext?.procedure_code || null
          })),
          patientFinance,
          actionRequests,
          statusHistory,
          signatures
        }
      });
    } catch (error: any) {
      console.warn('[Calendar] event detail failed:', error?.message || String(error));
      return res.status(500).json({ success: false, error: 'Não foi possível carregar os detalhes da sessão agora.' });
    }
  });

  const payerSafeError = (status = 500) => ({
    success: false,
    error: status === 400
      ? 'Dados inválidos para pagadores e conferência.'
      : status === 403
        ? 'Você não tem permissão para esta ação.'
        : status === 404
          ? 'Registro não encontrado.'
          : 'Não foi possível concluir a ação agora.'
  });

  const normalizePayerType = (value: unknown) => {
    const safe = sanitizeString(value, 40).toUpperCase();
    return ['INSURANCE', 'PRIVATE', 'PUBLIC', 'COURTESY', 'OTHER'].includes(safe) ? safe : 'PRIVATE';
  };

  const normalizeBillingContextSource = (value: unknown) => {
    const safe = sanitizeString(value, 60).toUpperCase();
    return ['PATIENT_DEFAULT', 'PATIENT_TISS_AUTHORIZATION', 'MANUAL', 'APPOINTMENT_CONTEXT'].includes(safe) ? safe : 'MANUAL';
  };

  const normalizePayerStatus = (value: unknown) => {
    const safe = sanitizeString(value, 40).toUpperCase();
    return safe === 'INACTIVE' ? 'INACTIVE' : 'ACTIVE';
  };

  const normalizeDocumentStatus = (value: unknown) => {
    const safe = sanitizeString(value, 40).toUpperCase();
    return ['REQUIRED', 'PENDING', 'PROVIDED', 'WAIVED', 'EXPIRED', 'NOT_APPLICABLE'].includes(safe) ? safe : 'PENDING';
  };

  const normalizeDocumentType = (value: unknown) => {
    const safe = sanitizeString(value, 60).toUpperCase();
    return ['SIGNATURE', 'SESSION_REPORT', 'AUTHORIZATION', 'GUIDE', 'PATIENT_DOCUMENT', 'PROFESSIONAL_DOCUMENT', 'OTHER'].includes(safe) ? safe : 'OTHER';
  };

  const serializePayer = (row: any) => ({
    id: sanitizeString(row?.id, 120),
    name: sanitizeString(row?.name, 180) || 'Pagador',
    payerType: normalizePayerType(row?.payer_type),
    status: normalizePayerStatus(row?.status),
    notes: sanitizeTextField(row?.notes, 1200) || null,
    updatedAt: row?.updated_at || null,
    createdAt: row?.created_at || null
  });

  const serializePayerRequirement = (row: any) => ({
    id: sanitizeString(row?.id, 120),
    payerId: sanitizeString(row?.payer_id, 120),
    serviceType: sanitizeString(row?.service_type, 120) || null,
    requireSignature: row?.require_signature !== false,
    requireReport: row?.require_report !== false,
    requireActualDuration: row?.require_actual_duration !== false,
    requireAuthorization: Boolean(row?.require_authorization),
    requireGuide: Boolean(row?.require_guide),
    requireProfessionalRegistry: Boolean(row?.require_professional_registry),
    requirePatientDocument: Boolean(row?.require_patient_document),
    minDurationMinutes: row?.min_duration_minutes ?? null,
    maxDurationVarianceMinutes: row?.max_duration_variance_minutes ?? null,
    allowManualOverride: row?.allow_manual_override !== false,
    isActive: row?.is_active !== false,
    updatedAt: row?.updated_at || null
  });

  const serializeBillingSuggestion = (suggestion: any) => suggestion ? {
    payerId: sanitizeString(suggestion?.payerId || suggestion?.payer_id, 120) || null,
    payerName: sanitizeString(suggestion?.payerName || suggestion?.payer_name_snapshot, 180) || null,
    payerType: normalizeAppointmentFinancialContextType(suggestion?.payerType || suggestion?.payer_type) || null,
    financialContextType: normalizeAppointmentFinancialContextType(suggestion?.financialContextType || suggestion?.financial_context_type || suggestion?.payerType || suggestion?.payer_type) || null,
    serviceType: sanitizeString(suggestion?.serviceType || suggestion?.service_type, 120) || null,
    insuranceCardNumber: sanitizeString(suggestion?.insuranceCardNumber || suggestion?.insurance_card_number, 120) || null,
    insurancePlanName: sanitizeString(suggestion?.insurancePlanName || suggestion?.insurance_plan_name, 160) || null,
    insuranceHolderName: sanitizeString(suggestion?.insuranceHolderName || suggestion?.insurance_holder_name, 160) || null,
    insuranceCardValidUntil: sanitizeIsoDateOnly(suggestion?.insuranceCardValidUntil || suggestion?.insurance_card_valid_until) || null,
    authorizationCode: sanitizeString(suggestion?.authorizationCode || suggestion?.authorization_code, 120) || null,
    guideNumber: sanitizeString(suggestion?.guideNumber || suggestion?.guide_number, 120) || null,
    patientTissAuthorizationId: sanitizeString(suggestion?.patientTissAuthorizationId || suggestion?.patient_tiss_authorization_id || suggestion?.authorizationId || suggestion?.authorization_id, 120) || null,
    tissAuthorization: suggestion?.tissAuthorization && typeof suggestion.tissAuthorization === 'object' ? suggestion.tissAuthorization : null,
    notes: sanitizeTextField(suggestion?.notes, 1200) || null,
    source: sanitizeString(suggestion?.source, 60) || 'PATIENT_DEFAULT'
  } : null;

  const serializeBillingContext = (row: any, payer: any = null, documents: any[] = [], suggestion: any = null) => {
    const patientDefault = serializeBillingSuggestion(suggestion);
    const hasContext = Boolean(row?.id);
    return {
      id: sanitizeString(row?.id, 120) || null,
      hasContext,
      payerId: sanitizeString(row?.payer_id, 120) || null,
      payerName: sanitizeString(payer?.name || row?.payer_name_snapshot, 180) || null,
      payerType: normalizeAppointmentFinancialContextType(row?.payer_type) || (payer ? normalizePayerType(payer?.payer_type) : null),
      financialContextType: normalizeAppointmentFinancialContextType(row?.payer_type) || (payer ? 'INSURANCE' : null),
      serviceType: sanitizeString(row?.service_type, 120) || patientDefault?.serviceType || null,
      insuranceCardNumber: sanitizeString(row?.insurance_card_number, 120) || patientDefault?.insuranceCardNumber || null,
      insurancePlanName: sanitizeString(row?.insurance_plan_name, 160) || patientDefault?.insurancePlanName || null,
      insuranceHolderName: sanitizeString(row?.insurance_holder_name || row?.metadata?.insurance_holder_name || row?.metadata?.insuranceHolderName, 160) || patientDefault?.insuranceHolderName || null,
      insuranceCardValidUntil: sanitizeIsoDateOnly(row?.insurance_card_valid_until || row?.metadata?.insurance_card_valid_until || row?.metadata?.insuranceCardValidUntil) || patientDefault?.insuranceCardValidUntil || null,
      authorizationCode: sanitizeString(row?.authorization_code, 120) || (!hasContext ? patientDefault?.authorizationCode : null),
      guideNumber: sanitizeString(row?.guide_number, 120) || (!hasContext ? patientDefault?.guideNumber : null),
      patientTissAuthorizationId: sanitizeString(row?.metadata?.patient_tiss_authorization_id || row?.metadata?.patientTissAuthorizationId, 120) || null,
      tissAuthorization: row?.metadata?.tiss_authorization && typeof row.metadata.tiss_authorization === 'object' ? row.metadata.tiss_authorization : null,
      procedureCode: sanitizeString(row?.procedure_code, 80) || null,
      notes: sanitizeTextField(row?.notes, 1200) || (!hasContext ? patientDefault?.notes : null),
      source: sanitizeString(row?.source, 60) || (!hasContext ? patientDefault?.source : null),
      documents: documents.map((doc: any) => ({
        id: sanitizeString(doc?.id, 120),
        documentType: normalizeDocumentType(doc?.document_type),
        status: normalizeDocumentStatus(doc?.status),
        requiredForServiceType: sanitizeString(doc?.required_for_service_type, 120) || null,
        dueDate: doc?.due_date || null,
        uploadedAt: doc?.uploaded_at || null
      })),
      suggestion: patientDefault
    };
  };

  const normalizeTussActiveFlag = (value: unknown) => value !== false && sanitizeString(value, 20).toLowerCase() !== 'false';
  const payerTussMappingMetadata = (row: any) =>
    row?.metadata && typeof row.metadata === 'object' && !Array.isArray(row.metadata) ? row.metadata : {};
  const firstTussMappingText = (...values: unknown[]) => {
    for (const value of values) {
      const candidate = sanitizeString(value, 240);
      if (candidate) return candidate;
    }
    return '';
  };
  const hasOwnField = (value: any, key: string) => Object.prototype.hasOwnProperty.call(value || {}, key);
  const normalizeTussMappingMetadataText = (value: unknown, maxLength = 240) => sanitizeString(value, maxLength) || null;
  const mergePayerTussMappingCodeMetadata = (body: any, existingMetadata: any = {}) => {
    const base = sanitizeClinicalPayload(existingMetadata && typeof existingMetadata === 'object' ? existingMetadata : {});
    const incomingMetadata = body?.metadata !== undefined ? sanitizeClinicalPayload(body.metadata || {}) : {};
    const metadata = { ...base, ...incomingMetadata };
    const assignText = (camelKey: string, snakeKey: string, maxLength = 240) => {
      const provided = hasOwnField(body, camelKey) || hasOwnField(body, snakeKey);
      if (!provided) return;
      metadata[snakeKey] = normalizeTussMappingMetadataText(body?.[camelKey] ?? body?.[snakeKey], maxLength);
    };
    assignText('authorizedCode', 'authorized_code', 80);
    assignText('authorizedCodeDescription', 'authorized_code_description', 600);
    assignText('billingCode', 'billing_code', 80);
    assignText('billingCodeDescription', 'billing_code_description', 600);
    assignText('operatorPackageCode', 'operator_package_code', 120);
    assignText('operatorPackageDescription', 'operator_package_description', 600);
    assignText('billingCodeSource', 'billing_code_source', 120);
    return cleanObject(metadata);
  };
  const resolvePayerTussAuthorizedCode = (mapping: any, officialTussCode: unknown) => {
    const metadata = payerTussMappingMetadata(mapping);
    return firstTussMappingText(
      mapping?.authorized_code,
      mapping?.authorizedCode,
      metadata.authorized_code,
      metadata.authorizedCode,
      officialTussCode
    ) || null;
  };
  const resolvePayerTussBillingCode = (mapping: any, officialTussCode: unknown) => {
    const metadata = payerTussMappingMetadata(mapping);
    return firstTussMappingText(
      mapping?.billing_code,
      mapping?.billingCode,
      metadata.billing_code,
      metadata.billingCode,
      officialTussCode
    ) || null;
  };
  const resolvePayerTussOperatorPackageCode = (mapping: any) => {
    const metadata = payerTussMappingMetadata(mapping);
    return firstTussMappingText(
      mapping?.operator_package_code,
      mapping?.operatorPackageCode,
      metadata.operator_package_code,
      metadata.operatorPackageCode,
      mapping?.contract_code
    ) || null;
  };

  const serializeTussServiceCatalog = (row: any) => ({
    id: sanitizeString(row?.id, 120),
    internalCode: sanitizeString(row?.internal_code, 80) || null,
    name: sanitizeString(row?.name, 180) || 'Procedimento',
    description: sanitizeTextField(row?.description, 1200) || null,
    specialty: sanitizeString(row?.specialty, 120) || null,
    serviceType: sanitizeString(row?.service_type, 120) || null,
    defaultDurationMinutes: row?.default_duration_minutes ?? null,
    billingUnit: normalizeTussBillingUnit(row?.billing_unit),
    defaultQuantity: Number(row?.default_quantity || 1) || 1,
    defaultAmountCents: row?.default_amount_cents ?? null,
    active: normalizeTussActiveFlag(row?.active),
    createdAt: row?.created_at || null,
    updatedAt: row?.updated_at || null
  });

  const serializeTussCode = (row: any) => ({
    id: sanitizeString(row?.id, 120),
    code: sanitizeString(row?.code, 80) || '',
    description: sanitizeTextField(row?.description, 600) || '',
    termType: sanitizeString(row?.term_type, 120) || null,
    version: sanitizeString(row?.version, 80) || null,
    validFrom: row?.valid_from || null,
    validTo: row?.valid_to || null,
    active: normalizeTussActiveFlag(row?.active),
    source: sanitizeString(row?.source, 120) || null,
    createdAt: row?.created_at || null,
    updatedAt: row?.updated_at || null
  });

  const serializePayerTussMapping = (row: any, service: any = null, code: any = null) => {
    const metadata = payerTussMappingMetadata(row);
    const officialTussCode = sanitizeString(code?.code, 80) || null;
    const authorizedCode = resolvePayerTussAuthorizedCode(row, officialTussCode);
    const billingCode = resolvePayerTussBillingCode(row, officialTussCode);
    const operatorPackageCode = resolvePayerTussOperatorPackageCode(row);
    return {
      id: sanitizeString(row?.id, 120),
      payerId: sanitizeString(row?.payer_id, 120),
      serviceCatalogId: sanitizeString(row?.service_catalog_id, 120),
      tussCodeId: sanitizeString(row?.tuss_code_id, 120) || null,
      serviceName: sanitizeString(service?.name, 180) || null,
      internalCode: sanitizeString(service?.internal_code, 80) || null,
      tussCode: officialTussCode,
      officialTussCode,
      tussDescription: sanitizeTextField(code?.description, 600) || null,
      tussVersion: sanitizeString(code?.version, 80) || null,
      authorizedCode,
      authorizedCodeDescription: sanitizeTextField(metadata.authorized_code_description || metadata.authorizedCodeDescription || code?.description, 600) || null,
      billingCode,
      billingCodeDescription: sanitizeTextField(metadata.billing_code_description || metadata.billingCodeDescription || code?.description, 600) || null,
      operatorPackageCode,
      operatorPackageDescription: sanitizeTextField(metadata.operator_package_description || metadata.operatorPackageDescription || row?.contract_description || row?.payer_specific_description, 600) || null,
      billingCodeSource: sanitizeString(metadata.billing_code_source || metadata.billingCodeSource || (billingCode && officialTussCode && billingCode !== officialTussCode ? 'payer_mapping_billing_code' : 'official_tuss'), 120) || null,
      contractCode: sanitizeString(row?.contract_code, 120) || null,
      contractDescription: sanitizeTextField(row?.contract_description || row?.payer_specific_description, 600) || null,
      payerSpecificDescription: sanitizeTextField(row?.payer_specific_description || row?.contract_description, 600) || null,
      specialty: sanitizeString(row?.specialty || service?.specialty, 120) || null,
      guideType: normalizeTussGuideType(row?.guide_type),
      billingUnit: normalizeTussBillingUnit(row?.billing_unit),
      quantityRule: normalizeTussQuantityRule(row?.quantity_rule),
      defaultQuantity: Number(row?.default_quantity || 1) || 1,
      amountCents: row?.amount_cents ?? null,
      negotiatedAmountCents: row?.negotiated_amount_cents ?? row?.amount_cents ?? null,
      standardDurationMinutes: row?.standard_duration_minutes ?? null,
      requiresAuthorization: Boolean(row?.requires_authorization),
      requiresGuide: Boolean(row?.requires_guide),
      requiresReport: Boolean(row?.requires_report),
      requiresSignature: Boolean(row?.requires_signature),
      requiresProfessionalRegistry: Boolean(row?.requires_professional_registry),
      requiresPatientDocument: Boolean(row?.requires_patient_document),
      useActualDuration: Boolean(row?.use_actual_duration),
      active: normalizeTussActiveFlag(row?.active),
      validFrom: row?.valid_from || null,
      validTo: row?.valid_to || null,
      source: sanitizeString(row?.source, 120) || null,
      notes: sanitizeTextField(row?.notes, 1200) || null,
      metadata,
      createdAt: row?.created_at || null,
      updatedAt: row?.updated_at || null
    };
  };

  const serializePayerProcedurePrice = (row: any, service: any = null, code: any = null, mapping: any = null) => ({
    id: sanitizeString(row?.id, 120),
    payerId: sanitizeString(row?.payer_id, 120),
    serviceCatalogId: sanitizeString(row?.service_catalog_id, 120) || null,
    tussCodeId: sanitizeString(row?.tuss_code_id, 120) || null,
    payerTussMappingId: sanitizeString(row?.payer_tuss_mapping_id, 120) || null,
    serviceName: sanitizeString(service?.name, 180) || null,
    internalCode: sanitizeString(service?.internal_code, 80) || null,
    tussCode: sanitizeString(code?.code || row?.tuss_code, 80) || null,
    tussDescription: sanitizeTextField(code?.description, 600) || null,
    mappingContractCode: sanitizeString(mapping?.contract_code, 120) || null,
    amountCents: Number.isFinite(Number(row?.amount_cents)) ? Number(row.amount_cents) : null,
    currency: sanitizeString(row?.currency, 12) || 'BRL',
    validFrom: row?.valid_from || null,
    validUntil: row?.valid_until || null,
    active: normalizeTussActiveFlag(row?.active),
    source: sanitizeString(row?.source, 120) || 'manual',
    notes: sanitizeTextField(row?.notes, 1200) || null,
    createdAt: row?.created_at || null,
    updatedAt: row?.updated_at || null
  });

  const serializePatientPayerAuthorization = (
    row: any,
    context: {
      payer?: any;
      service?: any;
      code?: any;
      mapping?: any;
      price?: any;
      preGuideCount?: number;
      officialPreGuideCount?: number;
      futurePreGuideCount?: number;
      historicalOfficialPreGuideCount?: number;
      balance?: ConfirmedTissAuthorizationBalance;
    } = {}
  ) => {
    const authorizedQuantity = Number(row?.authorized_quantity ?? 0) || 0;
    const usedQuantity = Number(row?.used_quantity ?? 0) || 0;
    const service = context.service || null;
    const code = context.code || null;
    const mapping = context.mapping || null;
    const price = context.price || null;
    const resolvedBalance = context.balance || null;
    const preGuideCount = resolvedBalance?.preGuideCount ?? Number(context.preGuideCount || 0);
    const hasSeparatedCommitmentCounts =
      context.futurePreGuideCount !== undefined || context.historicalOfficialPreGuideCount !== undefined;
    const futurePreGuideCount = resolvedBalance?.futureReservations ?? Math.max(0, Number(context.futurePreGuideCount || 0) || 0);
    const historicalOfficialPreGuideCount = resolvedBalance?.historicalOfficialCommitments ?? Math.max(0, Number(context.historicalOfficialPreGuideCount || 0) || 0);
    const fallbackReservedQuantity = hasSeparatedCommitmentCounts
      ? futurePreGuideCount + Math.max(0, historicalOfficialPreGuideCount - usedQuantity)
      : Math.max(0, preGuideCount - usedQuantity);
    const reservedQuantity = resolvedBalance
      ? resolvedBalance.confirmed ? resolvedBalance.reserved : null
      : fallbackReservedQuantity;
    const availableQuantity = resolvedBalance
      ? resolvedBalance.confirmed ? resolvedBalance.available : null
      : authorizedQuantity > 0
        ? Math.max(0, authorizedQuantity - usedQuantity - fallbackReservedQuantity)
        : null;
    return {
      id: sanitizeString(row?.id, 120),
      patientId: sanitizeString(row?.patient_id, 120),
      payerId: sanitizeString(row?.payer_id, 120),
      payerName: sanitizeString(context.payer?.name, 180) || null,
      authorizationNumber: sanitizeString(row?.authorization_number || row?.authorization_code, 120) || null,
      authorizationCode: sanitizeString(row?.authorization_code || row?.authorization_number, 120) || null,
      guideNumber: sanitizeString(row?.guide_number, 120) || null,
      issueDate: row?.issue_date || row?.issued_at || null,
      validFrom: row?.valid_from || null,
      validUntil: row?.valid_until || null,
      authorizedQuantity,
      quantityAuthorized: authorizedQuantity,
      authorizedUnit: sanitizeString(row?.authorized_unit || mapping?.billing_unit || service?.billing_unit, 40) || 'sessions',
      usedQuantity,
      quantityConsumed: usedQuantity,
      reservedQuantity,
      quantityReserved: reservedQuantity,
      availableQuantity,
      quantityAvailable: availableQuantity,
      balanceConfirmed: resolvedBalance ? resolvedBalance.confirmed : true,
      balanceErrorCode: resolvedBalance?.errorCode || null,
      serviceCatalogId: sanitizeString(row?.service_catalog_id, 120) || null,
      serviceName: sanitizeString(service?.name || row?.procedure_name_snapshot, 180) || null,
      internalCode: sanitizeString(service?.internal_code || row?.procedure_code || row?.procedure_code_snapshot, 80) || null,
      tussCodeId: sanitizeString(row?.tuss_code_id, 120) || null,
      tussCode: sanitizeString(code?.code || row?.procedure_tuss_code, 80) || null,
      tussDescription: sanitizeTextField(code?.description || row?.procedure_name_snapshot, 600) || null,
      payerTussMappingId: sanitizeString(row?.payer_tuss_mapping_id, 120) || null,
      tussSource: sanitizeString(row?.tuss_source, 80) || null,
      manualTussOverride: row?.manual_tuss_override === true,
      overrideReason: sanitizeTextField(row?.override_reason, 600) || null,
      amountCents: Number.isFinite(Number(price?.amount_cents)) ? Number(price.amount_cents) : null,
      priceId: sanitizeString(price?.id, 120) || null,
      status: sanitizeString(row?.status, 40) || 'active',
      active: row?.active !== false,
      notes: sanitizeTextField(row?.notes, 2000) || null,
      preGuideCount,
      officialPreGuideCount: resolvedBalance?.officialPreGuideCount ?? Number(context.officialPreGuideCount || 0),
      futurePreGuideCount,
      historicalOfficialPreGuideCount,
      createdAt: row?.created_at || null,
      updatedAt: row?.updated_at || null
    };
  };

  const hydratePatientPayerAuthorizations = async (
    organizationId: string,
    rows: any[],
    options: { includePatients?: boolean } = {}
  ) => {
    const safeRows = Array.isArray(rows) ? rows : [];
    const payerIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.payer_id, 120)).filter((id: string) => isUuid(id))));
    const serviceIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.service_catalog_id, 120)).filter((id: string) => isUuid(id))));
    const codeIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.tuss_code_id, 120)).filter((id: string) => isUuid(id))));
    const mappingIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.payer_tuss_mapping_id, 120)).filter((id: string) => isUuid(id))));
    const patientIds = Array.from(new Set(safeRows.map((row: any) => sanitizeString(row?.patient_id, 120)).filter((id: string) => isUuid(id))));
    const [payersResult, servicesResult, codesResult, mappingsResult, pricesResult, patientsResult, authorizationBalances] = await Promise.all([
      payerIds.length > 0
        ? supabase.from('clinic_payers').select(CLINIC_PAYER_SELECT).eq('organization_id', organizationId).in('id', payerIds).limit(payerIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      serviceIds.length > 0
        ? supabase.from('tuss_service_catalog').select(TUSS_SERVICE_CATALOG_SELECT).eq('organization_id', organizationId).in('id', serviceIds).limit(serviceIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      codeIds.length > 0
        ? supabase.from('tuss_codes').select(TUSS_CODE_SELECT).eq('organization_id', organizationId).in('id', codeIds).limit(codeIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      mappingIds.length > 0
        ? supabase.from('payer_tuss_mappings').select(PAYER_TUSS_MAPPING_SELECT).eq('organization_id', organizationId).in('id', mappingIds).limit(mappingIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      payerIds.length > 0
        ? supabase.from('payer_procedure_prices').select(PAYER_PROCEDURE_PRICE_SELECT).eq('organization_id', organizationId).in('payer_id', payerIds).eq('active', true).limit(400)
        : Promise.resolve({ data: [], error: null } as any),
      options.includePatients && patientIds.length > 0
        ? supabase.from('patients').select('id,name,email,clinic_id,insurance_name,insurance_card_number,insurance_plan_category').eq('clinic_id', organizationId).in('id', patientIds).limit(patientIds.length)
        : Promise.resolve({ data: [], error: null } as any),
      fetchPatientTissAuthorizationBalances({
        organizationId,
        authorizations: safeRows
      })
    ]);
    for (const result of [payersResult, servicesResult, codesResult, mappingsResult, pricesResult, patientsResult]) {
      if (result.error && !hasMissingFinancialSchema(result.error) && !isMissingRelationError(result.error)) throw result.error;
    }
    const payersById = new Map<string, any>((payersResult.error ? [] : payersResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
    const servicesById = new Map<string, any>((servicesResult.error ? [] : servicesResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
    const codesById = new Map<string, any>((codesResult.error ? [] : codesResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
    const mappingsById = new Map<string, any>((mappingsResult.error ? [] : mappingsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
    const patientsById = new Map<string, any>((patientsResult.error ? [] : patientsResult.data || []).map((row: any) => [sanitizeString(row.id, 120), row]));
    const prices = pricesResult.error ? [] : (pricesResult.data || []);
    const findPriceForAuthorization = (row: any) => {
      const referenceDate = row?.valid_from || row?.issue_date || row?.issued_at || new Date().toISOString();
      const mappingId = sanitizeString(row?.payer_tuss_mapping_id, 120);
      const serviceId = sanitizeString(row?.service_catalog_id, 120);
      const codeId = sanitizeString(row?.tuss_code_id, 120);
      const tussCode = sanitizeString(row?.procedure_tuss_code, 80).toLowerCase();
      const candidates = prices.filter((price: any) =>
        sanitizeString(price?.payer_id, 120) === sanitizeString(row?.payer_id, 120) &&
        priceIsValidForDate(price, referenceDate)
      );
      return candidates.find((price: any) => mappingId && sanitizeString(price?.payer_tuss_mapping_id, 120) === mappingId) ||
        candidates.find((price: any) => serviceId && codeId && sanitizeString(price?.service_catalog_id, 120) === serviceId && sanitizeString(price?.tuss_code_id, 120) === codeId) ||
        candidates.find((price: any) => serviceId && sanitizeString(price?.service_catalog_id, 120) === serviceId && tussCode && sanitizeString(price?.tuss_code, 80).toLowerCase() === tussCode) ||
        null;
    };
    return safeRows.map((row: any) => {
      const authorizationId = sanitizeString(row?.id, 120);
      const patientId = sanitizeString(row?.patient_id, 120);
      const patient = patientsById.get(patientId);
      const resolvedAuthorizationBalance = authorizationBalances.get(authorizationId) || {
        authorized: Math.max(0, Number(row?.authorized_quantity || 0) || 0),
        consumed: Math.max(0, Number(row?.used_quantity || 0) || 0),
        reserved: 0,
        available: null,
        futureReservations: 0,
        historicalOfficialCommitments: 0,
        currentAppointmentReserved: false,
        confirmed: false,
        errorCode: 'TISS_AUTHORIZATION_BALANCE_NOT_RESOLVED',
        preGuideCount: 0,
        officialPreGuideCount: 0
      };
      const serialized = serializePatientPayerAuthorization(row, {
        payer: payersById.get(sanitizeString(row?.payer_id, 120)),
        service: servicesById.get(sanitizeString(row?.service_catalog_id, 120)),
        code: codesById.get(sanitizeString(row?.tuss_code_id, 120)),
        mapping: mappingsById.get(sanitizeString(row?.payer_tuss_mapping_id, 120)),
        price: findPriceForAuthorization(row),
        balance: resolvedAuthorizationBalance
      });
      if (!options.includePatients) return serialized;
      return {
        ...serialized,
        patientName: sanitizeString(patient?.name, 180) || 'Paciente',
        patientEmail: sanitizeString(patient?.email, 180) || null,
        patientInsuranceName: sanitizeString(patient?.insurance_name, 180) || null,
        patientInsuranceCardNumber: sanitizeString(patient?.insurance_card_number, 120) || null,
        patientInsurancePlan: sanitizeString(patient?.insurance_plan_category, 180) || null
      };
    });
  };

  const serializeAppointmentBillingItem = (row: any, service: any = null, code: any = null, mapping: any = null) => {
    const readinessReasons = Array.isArray(row?.readiness_reasons)
      ? row.readiness_reasons.map((reason: any) => sanitizeString(reason, 80)).filter(Boolean)
      : [];
    return {
      id: sanitizeString(row?.id, 120) || null,
      appointmentId: sanitizeString(row?.appointment_id, 120) || null,
      patientId: sanitizeString(row?.patient_id, 120) || null,
      professionalId: sanitizeString(row?.professional_id, 120) || null,
      payerId: sanitizeString(row?.payer_id, 120) || null,
      serviceCatalogId: sanitizeString(row?.service_catalog_id, 120) || null,
      internalProcedureCode: sanitizeString(service?.internal_code, 80) || null,
      internalProcedureName: sanitizeString(service?.name, 180) || null,
      tussCodeId: sanitizeString(row?.tuss_code_id, 120) || null,
      tussCode: sanitizeString(code?.code, 80) || null,
      tussDescription: sanitizeTextField(code?.description, 600) || null,
      tussVersion: sanitizeString(code?.version, 80) || null,
      payerTussMappingId: sanitizeString(row?.payer_tuss_mapping_id, 120) || null,
      guideType: sanitizeString(row?.guide_type, 40) || null,
      billingUnit: sanitizeString(row?.billing_unit, 40) || null,
      quantity: Number(row?.quantity || 0) || 0,
      durationMinutes: row?.duration_minutes ?? null,
      unitAmountCents: row?.unit_amount_cents ?? null,
      amountCents: row?.amount_cents ?? null,
      authorizationNumber: sanitizeString(row?.authorization_number, 120) || null,
      guideNumber: sanitizeString(row?.guide_number, 120) || null,
      cardNumber: sanitizeString(row?.card_number, 120) || null,
      status: sanitizeString(row?.status, 40) || 'draft',
      readinessReason: sanitizeTextField(row?.readiness_reason, 1200) || null,
      readinessReasons,
      readinessLabels: readinessReasons.map((reason: any) => humanizeTussPendingReason(reason as any)),
      mappingStatus: row?.payer_tuss_mapping_id || mapping?.id ? 'configured' : 'pending_configuration',
      mappingValidFrom: mapping?.valid_from || null,
      mappingValidTo: mapping?.valid_to || null,
      resolvedAt: row?.resolved_at || null,
      updatedAt: row?.updated_at || null
    };
  };

  const fetchTussServiceCatalogById = async (organizationId: string, serviceId: string) => {
    if (!isUuid(organizationId) || !isUuid(serviceId)) return null;
    const { data, error } = await supabase
      .from('tuss_service_catalog')
      .select(TUSS_SERVICE_CATALOG_SELECT)
      .eq('organization_id', organizationId)
      .eq('id', serviceId)
      .limit(1)
      .maybeSingle();
    if (error) {
      if (hasMissingFinancialSchema(error)) return null;
      throw error;
    }
    return data || null;
  };

