  app.patch('/api/admin/tiss/provider-profile', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 48 * 1024, 'Perfil TISS do prestador')) return;
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(organizationId)) return res.status(400).json(payerSafeError(400));
      const now = new Date().toISOString();
      const userId = sanitizeString(req.session.user?.id, 120);
      const existingProfile = await fetchTissPreGuideProfile('clinic_tiss_profiles', CLINIC_TISS_PROFILE_SELECT, organizationId);
      const providerCode = sanitizeString(req.body?.providerCode ?? req.body?.provider_code, 200);
      const ansProviderCode = sanitizeString(req.body?.ansProviderCode ?? req.body?.ans_provider_code, 200);
      if (providerCode.length > TISS_PROVIDER_CODE_MAX_LENGTH || ansProviderCode.length > TISS_PROVIDER_CODE_MAX_LENGTH) {
        const invalidCode = providerCode.length > TISS_PROVIDER_CODE_MAX_LENGTH ? providerCode : ansProviderCode;
        return res.status(422).json({
          success: false,
          code: 'TISS_PROVIDER_CODE_TOO_LONG',
          error: getTissProviderCodeLengthError(invalidCode)
        });
      }
      const payload = cleanObject({
        organization_id: organizationId,
        clinic_id: organizationId,
        legal_name: sanitizeString(req.body?.legalName ?? req.body?.legal_name, 180) || null,
        trade_name: sanitizeString(req.body?.tradeName ?? req.body?.trade_name, 180) || null,
        document_type: ['CPF', 'CNPJ'].includes(sanitizeString(req.body?.documentType ?? req.body?.document_type, 10).toUpperCase())
          ? sanitizeString(req.body?.documentType ?? req.body?.document_type, 10).toUpperCase()
          : null,
        document_number: sanitizeString(req.body?.documentNumber ?? req.body?.document_number, 40).replace(/\D/g, '') || null,
        cnes_code: sanitizeString(req.body?.cnesCode ?? req.body?.cnes_code, 40).replace(/\D/g, '') || null,
        provider_code: providerCode || null,
        ans_provider_code: ansProviderCode || null,
        address_line: sanitizeString(req.body?.addressLine ?? req.body?.address_line, 180) || null,
        address_number: sanitizeString(req.body?.addressNumber ?? req.body?.address_number, 40) || null,
        address_complement: sanitizeString(req.body?.addressComplement ?? req.body?.address_complement, 120) || null,
        district: sanitizeString(req.body?.district, 120) || null,
        city: sanitizeString(req.body?.city, 120) || null,
        state: sanitizeString(req.body?.state, 2).toUpperCase() || null,
        postal_code: sanitizeString(req.body?.postalCode ?? req.body?.postal_code, 20).replace(/\D/g, '') || null,
        phone: sanitizePhone(req.body?.phone) || null,
        email: sanitizeEmail(req.body?.email) || null,
        active: req.body?.active !== false,
        created_at: existingProfile?.created_at || now,
        updated_by: isUuid(userId) ? userId : null,
        updated_at: now
      });
      const { data, error } = await supabase
        .from('clinic_tiss_profiles')
        .upsert(payload, { onConflict: 'organization_id' })
        .select(CLINIC_TISS_PROFILE_SELECT)
        .maybeSingle();
      if (error) throw error;
      const tissPipeline = queueTissProfileRevalidation({
        organizationId,
        user: req.session.user,
        reason: 'clinic_tiss_profile_changed'
      });
      return sendNoStoreJson(res, { success: true, data, tissPipeline });
    } catch (error: any) {
      console.warn('[TissPreGuide] provider profile update failed:', error?.message || String(error));
      return res.status(500).json(payerSafeError(500));
    }
  });

  app.get('/api/admin/tiss/payer-profiles', noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(organizationId)) return res.status(400).json(payerSafeError(400));
      const { data, error } = await supabase
        .from('payer_tiss_profiles')
        .select(PAYER_TISS_PROFILE_SELECT)
        .eq('organization_id', organizationId)
        .eq('active', true)
        .order('updated_at', { ascending: false })
        .limit(500);
      if (error) {
        if (PAYER_TISS_PROFILE_OPTIONAL_REVIEW_COLUMNS.includes(String(extractMissingColumnName(error) || ''))) {
          const fallback = await supabase
            .from('payer_tiss_profiles')
            .select(PAYER_TISS_PROFILE_BASE_SELECT)
            .eq('organization_id', organizationId)
            .eq('active', true)
            .order('updated_at', { ascending: false })
            .limit(500);
          if (!fallback.error) {
            return sendNoStoreJson(res, { success: true, data: Array.isArray(fallback.data) ? fallback.data : [] });
          }
          if (hasMissingFinancialSchema(fallback.error) || isMissingRelationError(fallback.error)) {
            return sendNoStoreJson(res, { success: true, data: [] });
          }
          throw fallback.error;
        }
        if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) {
          return sendNoStoreJson(res, { success: true, data: [] });
        }
        throw error;
      }
      return sendNoStoreJson(res, { success: true, data: Array.isArray(data) ? data : [] });
    } catch (error: any) {
      console.warn('[TissPreGuide] payer profiles list failed:', error?.message || String(error));
      return res.status(500).json(payerSafeError(500));
    }
  });

