  app.patch('/api/admin/tiss/payer-profiles/:payerId', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Perfil TISS do pagador')) return;
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      const payerId = sanitizeString(req.params.payerId, 120);
      if (!isUuid(organizationId) || !isUuid(payerId)) return res.status(400).json(payerSafeError(400));
      if (!(await fetchPayerForAdmin(payerId, organizationId))) return res.status(404).json(payerSafeError(404));
      const now = new Date().toISOString();
      const userId = sanitizeString(req.session.user?.id, 120);
      const existingProfile = await fetchTissPreGuideProfile('payer_tiss_profiles', PAYER_TISS_PROFILE_SELECT, organizationId, 'payer_id', payerId);
      const contractedProviderCode = sanitizeString(req.body?.contractedProviderCode ?? req.body?.contracted_provider_code, 200);
      const operatorProviderCode = sanitizeString(req.body?.operatorProviderCode ?? req.body?.operator_provider_code, 200);
      if (contractedProviderCode.length > TISS_PROVIDER_CODE_MAX_LENGTH || operatorProviderCode.length > TISS_PROVIDER_CODE_MAX_LENGTH) {
        const invalidCode = contractedProviderCode.length > TISS_PROVIDER_CODE_MAX_LENGTH ? contractedProviderCode : operatorProviderCode;
        const invalidLabel = contractedProviderCode.length > TISS_PROVIDER_CODE_MAX_LENGTH ? 'Código do prestador' : 'Código operacional na operadora';
        return res.status(422).json({
          success: false,
          code: 'TISS_PROVIDER_CODE_TOO_LONG',
          error: getTissProviderCodeLengthError(invalidCode, invalidLabel)
        });
      }
      const guideType = sanitizeString(req.body?.defaultGuideType ?? req.body?.default_guide_type, 40).toLowerCase();
      const attendanceType = normalizeAttendanceType040300(req.body?.defaultAttendanceType ?? req.body?.default_attendance_type);
      const attendanceRegime = normalizeAttendanceRegime040300(req.body?.defaultAttendanceRegime ?? req.body?.default_attendance_regime);
      const attendanceCharacter = normalizeAttendanceCharacter040300(req.body?.defaultAttendanceCharacter ?? req.body?.default_attendance_character);
      const supportedGuideTypes = new Set(guideTypes040300.map((item) => item.code));
      const unsupportedCodes = [
        attendanceType && !isSupportedAttendanceType040300(attendanceType) ? 'Tipo de atendimento padrão' : '',
        attendanceRegime && !isSupportedAttendanceRegime040300(attendanceRegime) ? 'Regime de atendimento padrão' : '',
        attendanceCharacter && !isSupportedAttendanceCharacter040300(attendanceCharacter) ? 'Caráter de atendimento padrão' : '',
        guideType && !supportedGuideTypes.has(guideType) ? 'Tipo de guia' : '',
      ].filter(Boolean);
      if (unsupportedCodes.length > 0) {
        return res.status(422).json({
          success: false,
          code: 'TISS_PROFILE_OFFICIAL_CODE_UNSUPPORTED',
          error: `Selecione opções oficiais suportadas pelo XML TISS 04.03.00: ${unsupportedCodes.join(', ')}.`
        });
      }
      const hasAntiGlosaReviewedInput = Object.prototype.hasOwnProperty.call(req.body || {}, 'antiGlosaReviewed') ||
        Object.prototype.hasOwnProperty.call(req.body || {}, 'anti_glosa_reviewed');
      const hasNoAdditionalInput = Object.prototype.hasOwnProperty.call(req.body || {}, 'operatorHasNoAdditionalRequirements') ||
        Object.prototype.hasOwnProperty.call(req.body || {}, 'operator_has_no_additional_requirements');
      const operatorHasNoAdditionalRequirements = hasNoAdditionalInput
        ? Boolean(req.body?.operatorHasNoAdditionalRequirements ?? req.body?.operator_has_no_additional_requirements)
        : Boolean(existingProfile?.operator_has_no_additional_requirements);
      const antiGlosaReviewed = operatorHasNoAdditionalRequirements || (hasAntiGlosaReviewedInput
        ? Boolean(req.body?.antiGlosaReviewed ?? req.body?.anti_glosa_reviewed)
        : Boolean(existingProfile?.anti_glosa_reviewed));
      const previousAntiGlosaReviewed = Boolean(existingProfile?.anti_glosa_reviewed);
      const antiGlosaReviewedAt = antiGlosaReviewed
        ? sanitizeString(existingProfile?.anti_glosa_reviewed_at, 40) || now
        : null;
      const payload = cleanObject({
        organization_id: organizationId,
        clinic_id: organizationId,
        payer_id: payerId,
        ans_registration: sanitizeString(req.body?.ansRegistration ?? req.body?.ans_registration, 80) || null,
        operator_code: sanitizeString(req.body?.operatorCode ?? req.body?.operator_code, 80) || null,
        tiss_version: sanitizeString(req.body?.tissVersion ?? req.body?.tiss_version, 80) || null,
        default_guide_type: supportedGuideTypes.has(guideType) ? guideType : 'sp_sadt',
        beneficiary_identification_type: sanitizeString(req.body?.beneficiaryIdentificationType ?? req.body?.beneficiary_identification_type, 80) || null,
        requires_authorization: Boolean(req.body?.requiresAuthorization ?? req.body?.requires_authorization),
        requires_authorized_procedure: Boolean(req.body?.requiresAuthorizedProcedure ?? req.body?.requires_authorized_procedure),
        requires_authorization_password: Boolean(req.body?.requiresAuthorizationPassword ?? req.body?.requires_authorization_password),
        requires_guide_number: Boolean(req.body?.requiresGuideNumber ?? req.body?.requires_guide_number),
        requires_cid: Boolean(req.body?.requiresCid ?? req.body?.requires_cid),
        requires_responsible_signature: Boolean(req.body?.requiresResponsibleSignature ?? req.body?.requires_responsible_signature),
        requires_provider_code: Boolean(req.body?.requiresProviderCode ?? req.body?.requires_provider_code),
        requires_cnes: Boolean(req.body?.requiresCnes ?? req.body?.requires_cnes),
        requires_cbo: Boolean(req.body?.requiresCbo ?? req.body?.requires_cbo),
        requires_executant_registry: Boolean(req.body?.requiresExecutantRegistry ?? req.body?.requires_executant_registry),
        requires_beneficiary_card: req.body?.requiresBeneficiaryCard ?? req.body?.requires_beneficiary_card ?? true,
        requires_beneficiary_card_validity: Boolean(req.body?.requiresBeneficiaryCardValidity ?? req.body?.requires_beneficiary_card_validity),
        contracted_executant: sanitizeString(req.body?.contractedExecutant ?? req.body?.contracted_executant, 160) || null,
        contracted_provider_code: contractedProviderCode || null,
        operator_provider_code: operatorProviderCode || null,
        operator_document_number: sanitizeString(req.body?.operatorDocumentNumber ?? req.body?.operator_document_number, 32) || null,
        auditor_contact_name: sanitizeString(req.body?.auditorContactName ?? req.body?.auditor_contact_name, 160) || null,
        billing_email: sanitizeString(req.body?.billingEmail ?? req.body?.billing_email, 180) || null,
        billing_phone: sanitizeString(req.body?.billingPhone ?? req.body?.billing_phone, 40) || null,
        operator_portal_url: sanitizeString(req.body?.operatorPortalUrl ?? req.body?.operator_portal_url, 300) || null,
        default_attendance_type: attendanceType || null,
        default_attendance_regime: attendanceRegime || null,
        default_attendance_character: attendanceCharacter || null,
        requires_physical_guide: Boolean(req.body?.requiresPhysicalGuide ?? req.body?.requires_physical_guide),
        requires_signed_guide: Boolean(req.body?.requiresSignedGuide ?? req.body?.requires_signed_guide),
        requires_stamped_dated_guide: Boolean(req.body?.requiresStampedDatedGuide ?? req.body?.requires_stamped_dated_guide),
        requires_administrative_report: Boolean(req.body?.requiresAdministrativeReport ?? req.body?.requires_administrative_report),
        anti_glosa_reviewed: antiGlosaReviewed,
        anti_glosa_reviewed_at: antiGlosaReviewed ? (previousAntiGlosaReviewed ? antiGlosaReviewedAt : now) : null,
        anti_glosa_reviewed_by: antiGlosaReviewed && isUuid(userId) ? userId : null,
        operator_has_no_additional_requirements: operatorHasNoAdditionalRequirements,
        allows_mixed_multidisciplinary_guide: Boolean(req.body?.allowsMixedMultidisciplinaryGuide ?? req.body?.allows_mixed_multidisciplinary_guide),
        requires_separate_guide_by_specialty: Boolean(req.body?.requiresSeparateGuideBySpecialty ?? req.body?.requires_separate_guide_by_specialty),
        administrative_notes: sanitizeTextField(req.body?.administrativeNotes ?? req.body?.administrative_notes, 2000) || null,
        specific_rules: sanitizeTextField(req.body?.specificRules ?? req.body?.specific_rules, 2000) || null,
        active: req.body?.active !== false,
        created_at: existingProfile?.created_at || now,
        updated_by: isUuid(userId) ? userId : null,
        updated_at: now
      });
      let upsertResult = await supabase
        .from('payer_tiss_profiles')
        .upsert(payload, { onConflict: 'organization_id,payer_id' })
        .select(PAYER_TISS_PROFILE_SELECT)
        .maybeSingle();
      if (upsertResult.error && PAYER_TISS_PROFILE_OPTIONAL_REVIEW_COLUMNS.includes(String(extractMissingColumnName(upsertResult.error) || ''))) {
        const fallbackPayload = { ...payload };
        for (const column of PAYER_TISS_PROFILE_OPTIONAL_REVIEW_COLUMNS) delete (fallbackPayload as any)[column];
        upsertResult = await supabase
          .from('payer_tiss_profiles')
          .upsert(fallbackPayload, { onConflict: 'organization_id,payer_id' })
          .select(PAYER_TISS_PROFILE_BASE_SELECT)
          .maybeSingle();
      }
      if (upsertResult.error) throw upsertResult.error;
      await markTissPreGuidesStale({ organizationId, payerId, reason: 'Dados TISS do pagador alterados.' });
      const tissPipeline = await runAffectedTissPipeline({
        organizationId,
        payerId,
        user: req.session.user,
        reason: 'payer_tiss_profile_changed',
        limit: 200
      });
      return sendNoStoreJson(res, { success: true, data: upsertResult.data, tissPipeline });
    } catch (error: any) {
      console.warn('[TissPreGuide] payer profile update failed:', error?.message || String(error));
      return res.status(500).json(payerSafeError(500));
    }
  });

  app.get('/api/patients/tiss-authorizations', noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      if (!isUuid(organizationId)) return res.status(400).json(payerSafeError(400));
      const patientId = sanitizeString(req.query?.patientId ?? req.query?.patient_id, 120);
      const payerId = sanitizeString(req.query?.payerId ?? req.query?.payer_id, 120);
      const rawLimit = Number(req.query?.limit || 500);
      const limit = Math.min(1000, Math.max(1, Number.isFinite(rawLimit) ? rawLimit : 500));
      let query = supabase
        .from('patient_payer_authorizations')
        .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
        .eq('organization_id', organizationId)
        .order('updated_at', { ascending: false })
        .limit(limit);
      if (patientId) {
        if (!isUuid(patientId) || !(await canAccessPatientInCurrentClinic(patientId, req.session.user))) {
          return res.status(404).json(payerSafeError(404));
        }
        query = query.eq('patient_id', patientId);
      }
      if (payerId) {
        if (!isUuid(payerId) || !(await fetchPayerForAdmin(payerId, organizationId))) {
          return res.status(404).json(payerSafeError(404));
        }
        query = query.eq('payer_id', payerId);
      }
      const { data, error } = await query;
      if (error) {
        if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) return sendNoStoreJson(res, { success: true, data: [] });
        throw error;
      }
      const rows = Array.isArray(data) ? data : [];
      return sendNoStoreJson(res, {
        success: true,
        data: await hydratePatientPayerAuthorizations(organizationId, rows, { includePatients: true })
      });
    } catch (error: any) {
      console.warn('[TissPreGuide] patient authorization overview failed:', {
        code: sanitizeString(error?.code, 40) || null,
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return res.status(500).json({ success: false, error: 'Não foi possível carregar as autorizações TISS dos pacientes.', code: 'AUTHORIZATION_OVERVIEW_FAILED' });
    }
  });

