  app.post('/api/tiss/patient-payer-authorizations', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 32 * 1024, 'Autorização do paciente')) return;
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      const authorizationId = sanitizeString(req.body?.id, 120);
      const patientId = sanitizeString(req.body?.patientId ?? req.body?.patient_id, 120);
      const payerId = sanitizeString(req.body?.payerId ?? req.body?.payer_id, 120);
      const appointmentId = sanitizeString(req.body?.appointmentId ?? req.body?.appointment_id, 120);
      if (!isUuid(organizationId) || !isUuid(patientId) || !isUuid(payerId)) {
        return res.status(400).json({ success: false, error: 'Informe paciente e pagador válidos.', code: 'INVALID_AUTHORIZATION_SCOPE' });
      }
      if (!(await canAccessPatientInCurrentClinic(patientId, req.session.user))) {
        return res.status(404).json(payerSafeError(404));
      }
      if (!(await fetchPayerForAdmin(payerId, organizationId))) {
        return res.status(404).json({ success: false, error: 'Pagador não encontrado para esta clínica.', code: 'PAYER_NOT_FOUND' });
      }
      let scopedAuthorizationAppointment: any = null;
      let scopedAuthorizationBillingItem: any = null;
      if (isUuid(appointmentId)) {
        const appointmentScope = await fetchAppointmentForBillingContext(appointmentId, req.session.user);
        if (!appointmentScope.ok) return res.status(appointmentScope.status || 404).json(payerSafeError(appointmentScope.status || 404));
        scopedAuthorizationAppointment = (appointmentScope as any).appointment || null;
        const appointmentPatientId = sanitizeString(scopedAuthorizationAppointment?.patient_id, 120);
        if (appointmentPatientId && appointmentPatientId !== patientId) {
          return res.status(400).json({ success: false, error: 'A autorização deve pertencer ao mesmo paciente do atendimento.', code: 'AUTHORIZATION_PATIENT_MISMATCH' });
        }
        const billingItemResult = await supabase
          .from('appointment_billing_items')
          .select(APPOINTMENT_BILLING_ITEM_SELECT)
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId)
          .limit(1)
          .maybeSingle();
        if (billingItemResult.error && !hasMissingFinancialSchema(billingItemResult.error) && !isMissingRelationError(billingItemResult.error)) {
          throw billingItemResult.error;
        }
        scopedAuthorizationBillingItem = billingItemResult.error ? null : billingItemResult.data;
      }

      let existingAuthorization: any = null;
      if (isUuid(authorizationId)) {
        const { data, error } = await supabase
          .from('patient_payer_authorizations')
          .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
          .eq('organization_id', organizationId)
          .eq('id', authorizationId)
          .limit(1)
          .maybeSingle();
        if (error) {
          if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) {
            return res.status(503).json({ success: false, error: 'Cadastro de autorizações indisponível. Verifique a migration e o cache do banco.', code: 'AUTHORIZATION_SCHEMA_UNAVAILABLE' });
          }
          throw error;
        }
        if (!data?.id) return res.status(404).json(payerSafeError(404));
        existingAuthorization = data;
      }

      const now = new Date().toISOString();
      const actorId = sanitizeString(req.session.user?.id, 120);
      const rawStatus = sanitizeString(req.body?.status, 40).toLowerCase();
      const status = ['active', 'expired', 'exhausted', 'cancelled'].includes(rawStatus) ? rawStatus : 'active';
      const authorizationNumber = sanitizeString(
        req.body?.authorizationNumber ??
          req.body?.authorization_number ??
          req.body?.authorizationCode ??
          req.body?.authorization_code,
        120
      ) || null;
      const guideNumber = sanitizeString(req.body?.guideNumber ?? req.body?.guide_number, 120) || null;
      const issueDate = sanitizeIsoDateOnly(req.body?.issueDate ?? req.body?.issue_date ?? req.body?.issuedAt ?? req.body?.issued_at);
      const validFrom = sanitizeIsoDateOnly(req.body?.validFrom ?? req.body?.valid_from);
      const validUntil = sanitizeIsoDateOnly(req.body?.validUntil ?? req.body?.valid_until);
      const authorizedQuantity = asSafeNumber(req.body?.authorizedQuantity ?? req.body?.authorized_quantity, 0, 1_000_000);
      const usedQuantity = asSafeNumber(req.body?.usedQuantity ?? req.body?.used_quantity, 0, 1_000_000);
      const serviceCatalogId = sanitizeString(req.body?.serviceCatalogId ?? req.body?.service_catalog_id, 120);
      const tussCodeId = sanitizeString(req.body?.tussCodeId ?? req.body?.tuss_code_id, 120);
      const payerTussMappingId = sanitizeString(req.body?.payerTussMappingId ?? req.body?.payer_tuss_mapping_id, 120);
      const manualTussOverride = req.body?.manualTussOverride === true || req.body?.manual_tuss_override === true;
      const overrideTussCodeId = sanitizeString(req.body?.overrideTussCodeId ?? req.body?.override_tuss_code_id ?? tussCodeId, 120);
      const overrideReason = sanitizeTextField(req.body?.overrideReason ?? req.body?.override_reason, 600);
      const submittedProcedureCode = sanitizeString(req.body?.procedureCode ?? req.body?.procedure_code ?? req.body?.procedureCodeSnapshot ?? req.body?.procedure_code_snapshot, 80) || null;
      const submittedProcedureName = sanitizeString(req.body?.procedureNameSnapshot ?? req.body?.procedure_name_snapshot ?? req.body?.procedureName ?? req.body?.procedure_name, 180) || null;
      const submittedServiceResult = submittedProcedureCode
        ? await supabase
            .from('tuss_service_catalog')
            .select(TUSS_SERVICE_CATALOG_SELECT)
            .eq('organization_id', organizationId)
            .ilike('internal_code', submittedProcedureCode)
            .limit(1)
            .maybeSingle()
        : { data: null, error: null } as any;
      if (submittedServiceResult.error && !hasMissingFinancialSchema(submittedServiceResult.error) && !isMissingRelationError(submittedServiceResult.error)) {
        throw submittedServiceResult.error;
      }
      const requestedMapping = isUuid(payerTussMappingId) ? await fetchPayerTussMappingById(organizationId, payerTussMappingId) : null;
      if (isUuid(payerTussMappingId) && (!requestedMapping?.id || requestedMapping.payer_id !== payerId)) {
        return res.status(404).json(payerSafeError(404));
      }
      const resolvedServiceCatalogId = [
        serviceCatalogId,
        sanitizeString(existingAuthorization?.service_catalog_id, 120),
        sanitizeString(scopedAuthorizationBillingItem?.service_catalog_id, 120),
        sanitizeString(submittedServiceResult.data?.id, 120),
        sanitizeString(requestedMapping?.service_catalog_id, 120)
      ].find((value) => isUuid(value)) || '';
      if (!isUuid(resolvedServiceCatalogId)) {
        return res.status(422).json({
          success: false,
          code: 'AUTHORIZATION_TUSS_MAPPING_MISSING',
          error: 'Nenhum procedimento interno foi encontrado para resolver o código TUSS autorizado.'
        });
      }
      if (manualTussOverride && !isUuid(overrideTussCodeId)) {
        return res.status(422).json({
          success: false,
          code: 'AUTHORIZATION_TUSS_OVERRIDE_CODE_REQUIRED',
          error: 'Selecione um código TUSS cadastrado para usar uma exceção de autorização.'
        });
      }
      if (manualTussOverride && !overrideReason) {
        return res.status(422).json({
          success: false,
          code: 'AUTHORIZATION_TUSS_OVERRIDE_REASON_REQUIRED',
          error: 'Informe a justificativa para usar um código autorizado diferente do De/Para.'
        });
      }
      if (existingAuthorization?.id) {
        const protectedPreGuides = await fetchOfficialPreGuidesLinkedToAuthorization(organizationId, sanitizeString(existingAuthorization.id, 120));
        if (protectedPreGuides.length > 0) {
          return res.status(409).json({
            success: false,
            code: 'AUTHORIZATION_HISTORICAL_PROTECTED',
            error: 'Autorização histórica protegida por XML oficial validado. Crie uma nova autorização para próximas competências.'
          });
        }
      }
      const referenceDate =
        scopedAuthorizationAppointment?.scheduled_start_at ||
        scopedAuthorizationAppointment?.scheduled_at ||
        scopedAuthorizationAppointment?.date ||
        validFrom ||
        issueDate ||
        new Date().toISOString();
      const guideType = sanitizeString(req.body?.guideType ?? req.body?.guide_type ?? scopedAuthorizationBillingItem?.guide_type ?? requestedMapping?.guide_type, 40) || 'sp_sadt';
      const automaticResolution = await resolveAuthorizationTussFromMapping({
        organizationId,
        payerId,
        serviceCatalogId: resolvedServiceCatalogId,
        referenceDate,
        guideType
      });
      if (automaticResolution.status !== 'resolved') {
        return res.status(409).json({
          success: false,
          code: authorizationTussResolutionCode(String(automaticResolution.status || 'missing')),
          error: authorizationTussResolutionMessage(String(automaticResolution.status || 'missing')),
          data: {
            status: automaticResolution.status,
            candidateCount: Array.isArray(automaticResolution.candidates) ? automaticResolution.candidates.length : 0
          }
        });
      }
      const overrideTussCode = manualTussOverride ? await fetchTussCodeById(organizationId, overrideTussCodeId) : null;
      if (manualTussOverride && (!overrideTussCode?.id || overrideTussCode.active === false)) {
        return res.status(422).json({
          success: false,
          code: 'AUTHORIZATION_TUSS_OVERRIDE_CODE_INVALID',
          error: 'Selecione um código TUSS ativo desta clínica para a exceção.'
        });
      }
      const resolvedMapping = automaticResolution.mapping;
      const resolvedService = automaticResolution.service;
      const resolvedTussCode = manualTussOverride ? overrideTussCode : automaticResolution.tussCode;
      const resolvedOfficialProcedureTussCode = sanitizeString(resolvedTussCode?.code, 80) || null;
      const resolvedProcedureTussCode = manualTussOverride
        ? resolvedOfficialProcedureTussCode
        : resolvePayerTussAuthorizedCode(resolvedMapping, resolvedOfficialProcedureTussCode);
      const resolvedBillingProcedureCode = manualTussOverride
        ? resolvedProcedureTussCode
        : resolvePayerTussBillingCode(resolvedMapping, resolvedOfficialProcedureTussCode);
      const resolvedProcedureCode = sanitizeString(resolvedService?.internal_code || submittedProcedureCode, 80) || null;
      const resolvedProcedureName = sanitizeString(
        resolvedMapping?.contract_description ||
          resolvedMapping?.payer_specific_description ||
          resolvedService?.name ||
          submittedProcedureName,
        180
      ) || null;
      const activePriceResolution = await fetchActivePayerProcedurePrice({
        organizationId,
        payerId,
        serviceCatalogId: resolvedServiceCatalogId,
        tussCodeId: sanitizeString(resolvedTussCode?.id, 120),
        payerTussMappingId: sanitizeString(resolvedMapping?.id, 120),
        tussCode: resolvedOfficialProcedureTussCode,
        appointmentDate: referenceDate
      });
      if (!activePriceResolution.price) {
        return res.status(409).json({
          success: false,
          code: 'AUTHORIZATION_PAYER_PRICE_MISSING',
          error: 'Nenhum valor negociado ativo foi encontrado para este procedimento e convênio. Cadastre o valor antes de criar a autorização TISS.'
        });
      }
      const payload = cleanObject({
        id: isUuid(authorizationId) ? authorizationId : undefined,
        organization_id: organizationId,
        clinic_id: organizationId,
        patient_id: patientId,
        payer_id: payerId,
        authorization_number: authorizationNumber,
        authorization_code: authorizationNumber,
        guide_number: guideNumber,
        issue_date: issueDate,
        issued_at: issueDate,
        valid_from: validFrom,
        valid_until: validUntil,
        authorized_quantity: authorizedQuantity,
        authorized_unit: sanitizeString(req.body?.authorizedUnit ?? req.body?.authorized_unit ?? resolvedMapping?.billing_unit ?? resolvedService?.billing_unit, 40) || null,
        used_quantity: usedQuantity,
        service_catalog_id: isUuid(resolvedServiceCatalogId) ? resolvedServiceCatalogId : null,
        tuss_code_id: isUuid(sanitizeString(resolvedTussCode?.id, 120)) ? sanitizeString(resolvedTussCode?.id, 120) : null,
        payer_tuss_mapping_id: isUuid(sanitizeString(resolvedMapping?.id, 120)) ? sanitizeString(resolvedMapping?.id, 120) : null,
        tuss_source: manualTussOverride ? 'manual_override' : 'payer_mapping',
        manual_tuss_override: manualTussOverride,
        override_reason: manualTussOverride ? overrideReason : null,
        synchronized_at: now,
        synchronized_by: isUuid(actorId) ? actorId : null,
        sync_metadata: cleanObject({
          expectedTussCode: resolvedOfficialProcedureTussCode,
          officialTussCode: resolvedOfficialProcedureTussCode,
          authorizedCode: resolvedProcedureTussCode,
          billingCode: resolvedBillingProcedureCode,
          resolvedTussCode: resolvedProcedureTussCode,
          payerTussMappingId: sanitizeString(resolvedMapping?.id, 120) || null,
          referenceDate: sanitizeString(referenceDate, 40) || null,
          manualOverride: manualTussOverride
        }),
        procedure_tuss_code: resolvedProcedureTussCode,
        procedure_code: resolvedProcedureCode,
        procedure_code_snapshot: resolvedProcedureCode,
        procedure_name_snapshot: resolvedProcedureName,
        status,
        notes: sanitizeTextField(req.body?.notes, 2000) || null,
        active: req.body?.active !== false,
        created_by: existingAuthorization?.created_by || (isUuid(actorId) ? actorId : null),
        updated_by: isUuid(actorId) ? actorId : null,
        created_at: existingAuthorization?.created_at || now,
        updated_at: now
      });

      const query = isUuid(authorizationId)
        ? supabase
            .from('patient_payer_authorizations')
            .update(payload)
            .eq('organization_id', organizationId)
            .eq('id', authorizationId)
            .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
            .maybeSingle()
        : supabase
            .from('patient_payer_authorizations')
            .insert(payload)
            .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
            .maybeSingle();
      const { data, error } = await query;
      if (error) {
        if (hasMissingFinancialSchema(error) || isMissingRelationError(error)) {
          return res.status(503).json({ success: false, error: 'Cadastro de autorizações indisponível. Verifique a migration e o cache do banco.', code: 'AUTHORIZATION_SCHEMA_UNAVAILABLE' });
        }
        throw error;
      }
      if (isUuid(appointmentId)) {
        const { error: staleError } = await supabase
          .from('appointment_tiss_pre_guides')
          .update({
            stale_reason: 'Autorização do paciente alterada.',
            updated_at: now
          })
          .eq('organization_id', organizationId)
          .eq('appointment_id', appointmentId);
        if (staleError && !hasMissingFinancialSchema(staleError) && !isMissingRelationError(staleError)) throw staleError;
      } else {
        await markTissPreGuidesStale({ organizationId, payerId, reason: 'Autorização do paciente alterada.' });
      }
      const affectedAppointmentIds = await collectTissPipelineAffectedFutureAppointmentIds({
        organizationId,
        patientId,
        payerId,
        appointmentId: isUuid(appointmentId) ? appointmentId : null
      });
      const pipelineResults = affectedAppointmentIds.length > 0
        ? await runTissPipelineForAppointments({
            appointmentIds: affectedAppointmentIds,
            user: req.session.user,
            reason: 'authorization_changed',
            mode: 'best_effort',
            revalidateAppointment: revalidateAppointmentBillingForAppointment,
            logger: console,
            concurrency: 4
          })
        : [];
      await recordTissRevenueCycleEvent({
        organizationId,
        clinicId: organizationId,
        patientId,
        appointmentId: isUuid(appointmentId) ? appointmentId : null,
        payerId,
        eventType: manualTussOverride ? 'AUTHORIZATION_TUSS_OVERRIDE_APPLIED' : 'AUTHORIZATION_TUSS_AUTO_RESOLVED',
        previousState: 'awaiting_authorization',
        newState: 'authorized',
        reason: manualTussOverride
          ? 'Código TUSS autorizado por exceção explícita do usuário.'
          : 'Código TUSS autorizado resolvido pelo De/Para vigente do convênio.',
        performedBy: isUuid(actorId) ? actorId : null,
        metadata: {
          authorizationId: sanitizeString(data?.id, 120) || null,
          payerTussMappingId: sanitizeString(resolvedMapping?.id, 120) || null,
          expectedTussCode: sanitizeString(automaticResolution.tussCode?.code, 80) || null,
          authorizedTussCode: resolvedProcedureTussCode,
          manualOverride: manualTussOverride,
          overrideReason: manualTussOverride ? overrideReason : null,
          notSentToPayer: true
        }
      });
      return sendNoStoreJson(res, {
        success: true,
        data,
        tissPipeline: {
          reason: 'authorization_changed',
          attempted: pipelineResults.length,
          updated: pipelineResults.filter((item) => item.ok).length,
          errors: pipelineResults.filter((item) => !item.ok).length
        },
        message: pipelineResults.length > 0
          ? 'Autorização salva. Pré-guias futuras afetadas foram revalidadas automaticamente.'
          : 'Autorização salva. O pipeline automático não encontrou Pré-guias futuras afetadas.'
      });
    } catch (error: any) {
      console.warn('[TissPreGuide] patient payer authorization save failed:', {
        patientId: sanitizeString(req.body?.patientId ?? req.body?.patient_id, 120) || null,
        payerId: sanitizeString(req.body?.payerId ?? req.body?.payer_id, 120) || null,
        code: sanitizeString(error?.code, 40) || null,
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return res.status(500).json({ success: false, error: 'Não foi possível salvar a autorização agora.', code: 'AUTHORIZATION_SAVE_FAILED' });
    }
  });

  app.patch('/api/patients/:patientId/tiss-authorizations/:authorizationId', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      if (!enforcePayloadLimit(req, res, 8 * 1024, 'Status da autorização TISS')) return;
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      const patientId = sanitizeString(req.params.patientId, 120);
      const authorizationId = sanitizeString(req.params.authorizationId, 120);
      if (!isUuid(organizationId) || !isUuid(patientId) || !isUuid(authorizationId)) return res.status(400).json(payerSafeError(400));
      if (!(await canAccessPatientInCurrentClinic(patientId, req.session.user))) {
        return res.status(404).json(payerSafeError(404));
      }
      const nextActive = req.body?.active === true;
      const { data: authorization, error: loadError } = await supabase
        .from('patient_payer_authorizations')
        .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('id', authorizationId)
        .limit(1)
        .maybeSingle();
      if (loadError) {
        if (hasMissingFinancialSchema(loadError) || isMissingRelationError(loadError)) return res.status(404).json(payerSafeError(404));
        throw loadError;
      }
      if (!authorization?.id) return res.status(404).json(payerSafeError(404));
      if (nextActive) {
        const activePriceResolution = await fetchActivePayerProcedurePrice({
          organizationId,
          payerId: sanitizeString(authorization.payer_id, 120),
          serviceCatalogId: sanitizeString(authorization.service_catalog_id, 120),
          tussCodeId: sanitizeString(authorization.tuss_code_id, 120),
          payerTussMappingId: sanitizeString(authorization.payer_tuss_mapping_id, 120),
          tussCode: sanitizeString(authorization.procedure_tuss_code, 80),
          appointmentDate: authorization.valid_from || authorization.issue_date || new Date().toISOString()
        });
        if (!activePriceResolution.price) {
          return res.status(409).json({
            success: false,
            code: 'AUTHORIZATION_REACTIVATION_PRICE_MISSING',
            error: 'Reative o De/Para e o valor negociado antes de reativar esta autorização.'
          });
        }
      }
      const { data: updated, error: updateError } = await supabase
        .from('patient_payer_authorizations')
        .update({
          active: nextActive,
          status: nextActive ? 'active' : 'cancelled',
          updated_by: req.session.user.id,
          updated_at: new Date().toISOString()
        })
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('id', authorizationId)
        .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
        .maybeSingle();
      if (updateError) throw updateError;
      await markTissPreGuidesStale({
        organizationId,
        payerId: sanitizeString(authorization.payer_id, 120),
        reason: 'Status da autorização do paciente alterado.'
      });
      const affectedAppointmentIds = await collectTissPipelineAffectedFutureAppointmentIds({
        organizationId,
        patientId,
        payerId: sanitizeString(authorization.payer_id, 120)
      });
      const pipelineResults = affectedAppointmentIds.length > 0
        ? await runTissPipelineForAppointments({
            appointmentIds: affectedAppointmentIds,
            user: req.session.user,
            reason: 'authorization_changed',
            mode: 'best_effort',
            revalidateAppointment: revalidateAppointmentBillingForAppointment,
            logger: console,
            concurrency: 4
          })
        : [];
      return sendNoStoreJson(res, {
        success: true,
        data: serializePatientPayerAuthorization(updated || { ...authorization, active: nextActive, status: nextActive ? 'active' : 'cancelled' }),
        tissPipeline: {
          reason: 'authorization_changed',
          attempted: pipelineResults.length,
          updated: pipelineResults.filter((item) => item.ok).length,
          errors: pipelineResults.filter((item) => !item.ok).length
        }
      });
    } catch (error: any) {
      console.warn('[TissPreGuide] patient authorization status update failed:', {
        patientId: sanitizeString(req.params.patientId, 120) || null,
        authorizationId: sanitizeString(req.params.authorizationId, 120) || null,
        code: sanitizeString(error?.code, 40) || null,
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return res.status(500).json({ success: false, error: 'Não foi possível atualizar a autorização TISS agora.', code: 'AUTHORIZATION_STATUS_UPDATE_FAILED' });
    }
  });

  app.delete('/api/patients/:patientId/tiss-authorizations/:authorizationId', portalActionLimiter, noStoreDynamicResponse, checkAuth, requireRoles('coordinator', 'admin', 'owner'), async (req: any, res) => {
    try {
      const organizationId = sanitizeString(currentClinicId(req.session.user), 120);
      const patientId = sanitizeString(req.params.patientId, 120);
      const authorizationId = sanitizeString(req.params.authorizationId, 120);
      if (!isUuid(organizationId) || !isUuid(patientId) || !isUuid(authorizationId)) return res.status(400).json(payerSafeError(400));
      if (!(await canAccessPatientInCurrentClinic(patientId, req.session.user))) {
        return res.status(404).json(payerSafeError(404));
      }
      const { data: authorization, error: loadError } = await supabase
        .from('patient_payer_authorizations')
        .select(PATIENT_PAYER_AUTHORIZATION_SELECT)
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('id', authorizationId)
        .limit(1)
        .maybeSingle();
      if (loadError) {
        if (hasMissingFinancialSchema(loadError) || isMissingRelationError(loadError)) return res.status(404).json(payerSafeError(404));
        throw loadError;
      }
      if (!authorization?.id) return res.status(404).json(payerSafeError(404));
      const linkedPreGuides = await fetchPreGuidesLinkedToAuthorization(organizationId, authorizationId, patientId);
      if (linkedPreGuides.length > 0) {
        const officialCount = linkedPreGuides.filter((row: any) => sanitizeString(row?.official_document_id, 120)).length;
        return res.status(409).json({
          success: false,
          code: 'AUTHORIZATION_DELETE_BLOCKED',
          error: 'Esta autorização já foi utilizada e não pode ser excluída. Inative para impedir novos usos.',
          dependencies: {
            preGuides: linkedPreGuides.length,
            officialDocuments: officialCount
          },
          recommendedAction: authorization.active === false ? 'keep_inactive' : 'deactivate'
        });
      }
      const { error: deleteError } = await supabase
        .from('patient_payer_authorizations')
        .delete()
        .eq('organization_id', organizationId)
        .eq('patient_id', patientId)
        .eq('id', authorizationId);
      if (deleteError) throw deleteError;
      const affectedAppointmentIds = await collectTissPipelineAffectedFutureAppointmentIds({
        organizationId,
        patientId,
        payerId: sanitizeString(authorization.payer_id, 120)
      });
      const pipelineResults = affectedAppointmentIds.length > 0
        ? await runTissPipelineForAppointments({
            appointmentIds: affectedAppointmentIds,
            user: req.session.user,
            reason: 'authorization_changed',
            mode: 'best_effort',
            revalidateAppointment: revalidateAppointmentBillingForAppointment,
            logger: console,
            concurrency: 4
          })
        : [];
      return sendNoStoreJson(res, {
        success: true,
        id: authorizationId,
        deleted: true,
        tissPipeline: {
          reason: 'authorization_changed',
          attempted: pipelineResults.length,
          updated: pipelineResults.filter((item) => item.ok).length,
          errors: pipelineResults.filter((item) => !item.ok).length
        }
      });
    } catch (error: any) {
      console.warn('[TissPreGuide] patient authorization delete failed:', {
        patientId: sanitizeString(req.params.patientId, 120) || null,
        authorizationId: sanitizeString(req.params.authorizationId, 120) || null,
        code: sanitizeString(error?.code, 40) || null,
        message: sanitizeTextField(error?.message, 300) || String(error)
      });
      return res.status(500).json({ success: false, error: 'Não foi possível excluir a autorização TISS agora.', code: 'AUTHORIZATION_DELETE_FAILED' });
    }
  });

  const assertProfessionalBillingProfileScope = async (organizationId: string, professionalId: string) => {
    const owner = await supabase
      .from('users')
      .select('id,clinic_id,role,name')
      .eq('id', professionalId)
      .or(`clinic_id.eq.${organizationId},id.eq.${organizationId}`)
      .limit(1)
      .maybeSingle();
    if (owner.error) throw owner.error;
    const ownerName = sanitizeString(owner.data?.name, 180).trim().toLowerCase();
    if (!owner.data?.id || ['equipe', 'team'].includes(ownerName)) return null;
    return owner.data;
  };

  const upsertProfessionalBillingProfile = async ({
    organizationId,
    professionalId,
    updatedBy,
    user,
    body,
  }: {
    organizationId: string;
    professionalId: string;
    updatedBy: string;
    user: any;
    body: any;
  }) => {
    const existingProfile = await fetchTissPreGuideProfile(
      'professional_billing_profiles',
      PROFESSIONAL_BILLING_PROFILE_SELECT,
      organizationId,
      'professional_id',
      professionalId,
    );
    const now = new Date().toISOString();
    const documentType = sanitizeString(body?.documentType ?? body?.document_type, 20).toUpperCase();
    const payload = cleanObject({
      organization_id: organizationId,
      clinic_id: organizationId,
      professional_id: professionalId,
      display_name: sanitizeString(body?.displayName ?? body?.display_name, 180) || null,
      document_type: ['CPF', 'CNPJ', 'OTHER'].includes(documentType) ? documentType : null,
      document_number: sanitizeString(body?.documentNumber ?? body?.document_number, 40).replace(/\D/g, '') || null,
      council_type: sanitizeString(body?.councilType ?? body?.council_type, 40) || null,
      council_number: sanitizeString(body?.councilNumber ?? body?.council_number, 80) || null,
      council_state: sanitizeString(body?.councilState ?? body?.council_state, 2).toUpperCase() || null,
      cbo_code: sanitizeString(body?.cboCode ?? body?.cbo_code, 40).replace(/\D/g, '') || null,
      specialty_name: sanitizeString(body?.specialtyName ?? body?.specialty_name, 120) || null,
      provider_code: sanitizeString(body?.providerCode ?? body?.provider_code, 80) || null,
      active: body?.active !== false,
      created_at: existingProfile?.created_at || now,
      updated_by: isUuid(updatedBy) ? updatedBy : null,
      updated_at: now
    });
    const { data, error } = await supabase
      .from('professional_billing_profiles')
      .upsert(payload, { onConflict: 'organization_id,professional_id' })
      .select(PROFESSIONAL_BILLING_PROFILE_SELECT)
      .maybeSingle();
    if (error) throw error;
    const tissPipeline = queueTissProfileRevalidation({
      organizationId,
      professionalId,
      user,
      reason: 'professional_billing_profile_changed'
    });
    return { data, tissPipeline };
  };

