  app.patch(
    "/api/owner/sales/pricing-catalogs/:versionId",
    checkAuth,
    checkOwner,
    async (req: any, res) => {
      const versionId = sanitizeString(req.params?.versionId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      const action = sanitizeString(req.body?.action, 40);
      const idempotencyKey = sanitizeString(
        req.headers?.["x-idempotency-key"] || req.body?.idempotencyKey,
        240,
      );
      const allowedActions = new Set([
        "version",
        "item",
        "tier",
        "cost_model",
      ]);
      if (
        !isUuid(versionId)
        || !isUuid(actorUserId)
        || !allowedActions.has(action)
        || idempotencyKey.length < 12
        || !req.body?.payload
        || typeof req.body.payload !== "object"
        || Array.isArray(req.body.payload)
      ) {
        return res.status(400).json({
          success: false,
          code: "PRICING_CATALOG_INVALID",
          error: "Alteração de catálogo inválida.",
        });
      }
      try {
        const { data, error } = await supabase.rpc(
          "save_sales_pricing_catalog_draft_v3",
          {
            p_catalog_version_id: versionId,
            p_action: action,
            p_payload: req.body.payload,
            p_actor_user_id: actorUserId,
            p_idempotency_key: idempotencyKey,
          },
        );
        if (error) throw error;
        return res.json({ success: true, data });
      } catch (error: any) {
        if (sendSalesProfitabilityPolicySchemaPending(res, error)) return;
        const rawCode = sanitizeString(
          error?.message || error?.code,
          180,
        );
        const immutable = rawCode.includes("PRICING_CATALOG_IMMUTABLE");
        const notFound = rawCode.includes("NOT_FOUND");
        const capacityPolicyInvalid = rawCode.includes(
          "PRICING_CUSTOM_CAPACITY_POLICY_INVALID",
        );
        const profitabilityPolicyInvalid = rawCode.includes(
          "PRICING_PROFITABILITY_POLICY_INVALID",
        );
        return res.status(immutable ? 409 : notFound ? 404 : 422).json({
          success: false,
          code: immutable
            ? "PRICING_CATALOG_IMMUTABLE"
            : notFound
              ? rawCode.includes("TIER")
                ? "PRICING_TIER_NOT_FOUND"
                : rawCode.includes("ITEM")
                  ? "PRICING_ITEM_NOT_FOUND"
                  : "PRICING_CATALOG_NOT_FOUND"
              : capacityPolicyInvalid
                ? "PRICING_CUSTOM_CAPACITY_POLICY_INVALID"
                : profitabilityPolicyInvalid
                  ? "PRICING_PROFITABILITY_POLICY_INVALID"
                : "PRICING_CATALOG_INVALID",
          error: immutable
            ? "Versões publicadas são imutáveis. Crie um novo rascunho."
            : notFound
              ? "O registro do catálogo não foi encontrado."
              : capacityPolicyInvalid
                ? "Revise a política de blocos: informe valores válidos, ajuste no próximo ciclo e acesso clínico sempre preservado."
                : profitabilityPolicyInvalid
                  ? "Revise os pisos de margem e complete as franquias de expansão habilitadas."
                : "Revise os valores informados.",
        });
      }
    },
  );

  app.post(
    "/api/owner/sales/pricing-catalogs/:versionId/publish",
    checkAuth,
    checkOwner,
    async (req: any, res) => {
      const versionId = sanitizeString(req.params?.versionId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      const idempotencyKey = sanitizeString(
        req.headers?.["x-idempotency-key"] || req.body?.idempotencyKey,
        240,
      );
      if (
        !isUuid(versionId)
        || !isUuid(actorUserId)
        || idempotencyKey.length < 12
      ) {
        return res.status(400).json({
          success: false,
          code: "PRICING_CATALOG_INVALID",
          error: "Publicação de catálogo inválida.",
        });
      }
      try {
        const catalog = await loadSalesPricingCatalog(versionId, {
          includeDraft: true,
        });
        const publicationBlocks = validateModularCatalogForPublication(catalog);
        if (publicationBlocks.length > 0) {
          return res.status(422).json({
            success: false,
            code: "PRICING_CATALOG_PUBLICATION_BLOCKED",
            error: "Resolva os bloqueios de custos e drivers antes de publicar.",
            blocks: publicationBlocks,
          });
        }
        const { data, error } = await supabase.rpc(
          "publish_sales_pricing_catalog_version_v3",
          {
            p_catalog_version_id: versionId,
            p_actor_user_id: actorUserId,
            p_idempotency_key: idempotencyKey,
          },
        );
        if (error) throw error;
        return res.json({ success: true, catalogVersion: data });
      } catch (error: any) {
        if (sendSalesProfitabilityPolicySchemaPending(res, error)) return;
        const rawCode = sanitizeString(
          error?.message || error?.code,
          180,
        );
        const immutable = rawCode.includes("IMMUTABLE");
        return res.status(immutable ? 409 : 422).json({
          success: false,
          code: immutable
            ? "PRICING_CATALOG_IMMUTABLE"
            : rawCode.includes("PUBLICATION_BLOCKED")
              ? "PRICING_CATALOG_PUBLICATION_BLOCKED"
              : "PRICING_CATALOG_INVALID",
          error: immutable
            ? "Esta versão já foi encerrada."
            : rawCode.includes("PUBLICATION_BLOCKED")
              ? "Resolva os bloqueios de custos, drivers, armazenamento, egress e duplicidade."
              : "O catálogo precisa de pacote-base, faixas e modelos de custo para ser publicado.",
        });
      }
    },
  );

