  app.post(
    "/api/owner/sales/leads/:leadId/simulations",
    checkAuth,
    checkOwner,
    async (req: any, res) => {
      const leadId = sanitizeString(req.params?.leadId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      const assumptionSetId = sanitizeString(
        req.body?.assumptionSetId,
        120,
      );
      const idempotencyKey = sanitizeString(
        req.headers?.["x-idempotency-key"] || req.body?.idempotencyKey,
        240,
      );
      if (
        !isUuid(leadId)
        || !isUuid(actorUserId)
        || !isUuid(assumptionSetId)
        || idempotencyKey.length < 12
      ) {
        return res.status(400).json({
          success: false,
          code: "SIMULATION_INPUT_INVALID",
          error: "Dados da simulação inválidos.",
        });
      }
      try {
        const simulationInput = normalizeSalesSimulationRequest(req.body);
        const invalidFields = validateSalesSimulationInput(simulationInput);
        if (invalidFields.length > 0) {
          return res.status(422).json({
            success: false,
            code: "SIMULATION_INPUT_INVALID",
            fields: invalidFields,
            error: "Revise os campos da simulação.",
          });
        }
        const [leadResult, assumptionResult, existingResult] =
          await Promise.all([
            supabase
              .from("sales_leads")
              .select("id")
              .eq("id", leadId)
              .is("deleted_at", null)
              .maybeSingle(),
            supabase
              .from("sales_financial_assumption_sets")
              .select(
                "id,version,name,effective_at,values,source_metadata",
              )
              .eq("id", assumptionSetId)
              .maybeSingle(),
            supabase
              .from("sales_offer_simulations")
              .select(SALES_OFFER_SIMULATION_SELECT)
              .eq("created_by", actorUserId)
              .eq("idempotency_key", idempotencyKey)
              .maybeSingle(),
          ]);
        if (leadResult.error) throw leadResult.error;
        if (!leadResult.data) {
          return res.status(404).json({
            success: false,
            code: "SIMULATION_LEAD_NOT_FOUND",
            error: "Lead não encontrado.",
          });
        }
        if (assumptionResult.error) throw assumptionResult.error;
        if (!assumptionResult.data) {
          return res.status(422).json({
            success: false,
            code: "SIMULATION_ASSUMPTIONS_MISSING",
            error: "Selecione uma versão de premissas válida.",
          });
        }
        const assumptionSnapshot = mapSalesAssumptionSnapshot(
          assumptionResult.data,
        );
        const results = calculateSalesProfitability(
          simulationInput,
          assumptionSnapshot,
        );
        const justification = sanitizeString(
          req.body?.internalJustification,
          1500,
        );
        if (results.requiresJustification && justification.length < 12) {
          return res.status(422).json({
            success: false,
            code: "SIMULATION_JUSTIFICATION_REQUIRED",
            error:
              "Informe uma justificativa administrativa para esta margem.",
          });
        }

        if (existingResult.error) throw existingResult.error;
        if (existingResult.data) {
          const existingInput =
            existingResult.data.results_snapshot?.input || {};
          const sameRequest =
            existingResult.data.lead_id === leadId
            && existingResult.data.assumption_set_id === assumptionSetId
            && JSON.stringify(existingInput) ===
              JSON.stringify(simulationInput);
          if (!sameRequest) {
            return res.status(409).json({
              success: false,
              code: "SIMULATION_VERSION_CONFLICT",
              error:
                "Esta chave já foi usada para outra simulação. Recalcule antes de salvar.",
            });
          }
          return res.json({
            success: true,
            simulation: existingResult.data,
            idempotent: true,
          });
        }

        const discountType =
          simulationInput.discountBasisPoints > 0 ? "coupon" : "none";
        const { data: simulation, error: insertError } = await supabase
          .from("sales_offer_simulations")
          .insert([
            {
              lead_id: leadId,
              created_by: actorUserId,
              status: "saved",
              assumption_set_id: assumptionSetId,
              model_version: results.modelVersion,
              initial_active_patient_quantity:
                simulationInput.initialActivePatientQuantity,
              base_unit_amount_cents: simulationInput.baseUnitAmountCents,
              currency: PUBLIC_ACTIVE_PATIENT_PRICE.currency,
              discount_type: discountType,
              discount_percentage:
                simulationInput.discountBasisPoints / 100,
              discount_duration_months:
                discountType === "coupon"
                  ? simulationInput.discountDurationMonths
                  : null,
              offer_validity_days: simulationInput.offerValidityDays,
              usage_profile: simulationInput.usageProfile,
              custom_monthly_cost_cents:
                simulationInput.customMonthlyCostCents,
              onboarding_cost_cents: simulationInput.onboardingCostCents,
              assumptions_snapshot: assumptionSnapshot,
              results_snapshot: results,
              profitability_rating: results.rating,
              internal_justification: justification || null,
              internal_notes:
                sanitizeString(req.body?.internalNotes, 2000) || null,
              idempotency_key: idempotencyKey,
            },
          ])
          .select(SALES_OFFER_SIMULATION_SELECT)
          .single();
        if (insertError) {
          if (String(insertError.code || "") === "23505") {
            const { data: concurrentSimulation, error: concurrentError } =
              await supabase
                .from("sales_offer_simulations")
                .select(SALES_OFFER_SIMULATION_SELECT)
                .eq("created_by", actorUserId)
                .eq("idempotency_key", idempotencyKey)
                .maybeSingle();
            if (concurrentError) throw concurrentError;
            if (concurrentSimulation) {
              return res.json({
                success: true,
                simulation: concurrentSimulation,
                idempotent: true,
              });
            }
          }
          throw insertError;
        }
        const { error: eventError } = await supabase
          .from("sales_lead_events")
          .upsert(
            [
              {
                lead_id: leadId,
                event_type: "lead_updated",
                actor_user_id: actorUserId,
                metadata: {
                  action: "profitability_simulation_created",
                  simulation_id: simulation.id,
                  assumption_version: assumptionSnapshot.version,
                  profitability_rating: results.rating,
                },
                idempotency_key: `simulation-created:${simulation.id}`,
              },
            ],
            { onConflict: "idempotency_key", ignoreDuplicates: true },
          );
        if (eventError) throw eventError;
        return res.status(201).json({
          success: true,
          simulation,
          idempotent: false,
        });
      } catch (error: any) {
        const rawCode = sanitizeString(
          error?.code || error?.message,
          160,
        );
        const inputInvalid = rawCode.includes("SIMULATION_INPUT_INVALID");
        console.error("[Sales Profitability] Falha ao salvar simulação.", {
          leadId,
          code: sanitizeString(error?.code, 80),
          message: sanitizeString(error?.message || String(error), 220),
        });
        return res.status(inputInvalid ? 422 : 500).json({
          success: false,
          code: inputInvalid
            ? "SIMULATION_INPUT_INVALID"
            : "SIMULATION_PERSISTENCE_FAILED",
          error: inputInvalid
            ? "Revise os dados informados."
            : "A simulação não pôde ser salva.",
        });
      }
    },
  );

  app.post(
    "/api/owner/sales/leads/:leadId/simulations/:simulationId/select",
    checkAuth,
    checkOwner,
    async (req: any, res) => {
      const leadId = sanitizeString(req.params?.leadId, 120);
      const simulationId = sanitizeString(req.params?.simulationId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      if (
        !isUuid(leadId)
        || !isUuid(simulationId)
        || !isUuid(actorUserId)
      ) {
        return res.status(400).json({
          success: false,
          code: "SIMULATION_INPUT_INVALID",
          error: "Simulação inválida.",
        });
      }
      try {
        const now = new Date().toISOString();
        const { data, error } = await supabase
          .from("sales_offer_simulations")
          .update({
            status: "selected",
            selected_for_offer_at: now,
            updated_at: now,
          })
          .eq("id", simulationId)
          .eq("lead_id", leadId)
          .is("deleted_at", null)
          .in("status", ["saved", "selected"])
          .select(
            "id,lead_id,status,selected_for_offer_at,updated_at",
          )
          .maybeSingle();
        if (error) throw error;
        if (!data) {
          return res.status(409).json({
            success: false,
            code: "SIMULATION_VERSION_CONFLICT",
            error:
              "Esta simulação já foi convertida ou não está mais disponível.",
          });
        }
        const { error: eventError } = await supabase
          .from("sales_lead_events")
          .upsert(
            [
              {
                lead_id: leadId,
                event_type: "lead_updated",
                actor_user_id: actorUserId,
                metadata: {
                  action: "profitability_simulation_selected",
                  simulation_id: simulationId,
                },
                idempotency_key: `simulation-selected:${simulationId}`,
              },
            ],
            { onConflict: "idempotency_key", ignoreDuplicates: true },
          );
        if (eventError) throw eventError;
        return res.json({ success: true, simulation: data });
      } catch (error: any) {
        console.error("[Sales Profitability] Falha ao selecionar simulação.", {
          leadId,
          simulationId,
          code: sanitizeString(error?.code, 80),
        });
        return res.status(500).json({
          success: false,
          code: "SIMULATION_SELECTION_FAILED",
          error: "Não foi possível selecionar a simulação.",
        });
      }
    },
  );

  const prepareSalesModularOffer = async (
    req: any,
    res: any,
    params: {
      leadId: string;
      simulationId: string;
      actorUserId: string;
      idempotencyKey: string;
    },
  ) => {
    const { leadId, simulationId, actorUserId, idempotencyKey } = params;
    if (
      req.session?.user?.role !== "owner"
      || !hasVerifiedOwnerMfaSession(req.session?.user)
    ) {
      return res.status(403).json({
        success: false,
        code: "PROPOSAL_ACCESS_DENIED",
        error: "Esta ação exige acesso owner com MFA validado.",
      });
    }
    if (
      !isUuid(leadId)
      || !isUuid(simulationId)
      || !isUuid(actorUserId)
      || idempotencyKey.length < 12
    ) {
      return res.status(400).json({
        success: false,
        code: "PROPOSAL_SIMULATION_INVALID",
        error: "Selecione um cenário modular salvo.",
      });
    }
    try {
      const [leadResult, simulationResult] = await Promise.all([
        supabase
          .from("sales_leads")
          .select("id")
          .eq("id", leadId)
          .is("deleted_at", null)
          .maybeSingle(),
        supabase
          .from("sales_offer_simulations")
          .select(SALES_MODULAR_SIMULATION_SELECT)
          .eq("id", simulationId)
          .eq("lead_id", leadId)
          .eq("simulation_type", "modular")
          .is("deleted_at", null)
          .maybeSingle(),
      ]);
      if (leadResult.error) throw leadResult.error;
      if (!leadResult.data) {
        return res.status(404).json({
          success: false,
          code: "PROPOSAL_ACCESS_DENIED",
          error: "Lead não encontrado.",
        });
      }
      if (simulationResult.error) throw simulationResult.error;
      const simulation = simulationResult.data;
      if (!simulation) {
        return res.status(404).json({
          success: false,
          code: "PROPOSAL_SIMULATION_INVALID",
          error: "Cenário modular não encontrado.",
        });
      }
      if (!["selected", "offered"].includes(
        sanitizeString(simulation.status, 30),
      )) {
        return res.status(409).json({
          success: false,
          code: "PROPOSAL_SIMULATION_INVALID",
          error: "Selecione o cenário antes de gerar a proposta pública.",
        });
      }
      const historicalPublishedOffer =
        sanitizeString(simulation.status, 30) === "offered";
      if (historicalPublishedOffer) {
        const { data: existingOffer, error: existingOfferError } =
          await supabase
            .from("sales_offers")
            .select(
              "id,simulation_id,status,expires_at,created_by,idempotency_key,created_at",
            )
            .eq("simulation_id", simulationId)
            .order("created_at", { ascending: false })
            .limit(1)
            .maybeSingle();
        if (existingOfferError) throw existingOfferError;
        const offerCreatedBy = sanitizeString(
          existingOffer?.created_by,
          120,
        );
        const offerIdempotencyKey = sanitizeString(
          existingOffer?.idempotency_key,
          240,
        );
        if (!existingOffer || !offerCreatedBy || !offerIdempotencyKey) {
          return res.status(409).json({
            success: false,
            code: "PROPOSAL_SNAPSHOT_CONFLICT",
            error:
              "A proposta publicada não possui os dados congelados necessários para recuperar o link original.",
          });
        }
        const publicToken = deriveSalesOfferPublicToken(
          offerCreatedBy,
          offerIdempotencyKey,
        );
        return res.status(200).json({
          success: true,
          offer: existingOffer,
          publicUrl: buildSalesOfferPublicUrl(req, publicToken),
          stripeReady: false,
          modularCheckoutEnabled: false,
          idempotent: true,
          message:
            "A proposta modular já existia; o mesmo link foi recuperado.",
        });
      }
      const [catalog, assumptionResult] = await Promise.all([
        loadSalesPricingCatalog(
          sanitizeString(simulation.catalog_version_id, 120),
        ),
        supabase
          .from("sales_financial_assumption_sets")
          .select("id,version,name,effective_at,values,source_metadata")
          .eq("id", simulation.assumption_set_id)
          .maybeSingle(),
      ]);
      if (assumptionResult.error) throw assumptionResult.error;
      if (!assumptionResult.data) {
        return res.status(409).json({
          success: false,
          code: "PROPOSAL_SNAPSHOT_CONFLICT",
          error: "As premissas congeladas não estão disponíveis.",
        });
      }
      const input = normalizeSalesModularProposalRequest(
        simulation.modular_input_snapshot,
      );
      const requiresVersionedProfitabilityPolicy =
        salesModularProposalRequiresVersionedProfitabilityPolicy(
          input,
          catalog,
        );
      const hasVersionedEconomicSnapshot =
        validateSalesProfitabilityPolicy(
          simulation.results_snapshot?.economics?.policy,
        );
      if (
        !historicalPublishedOffer
        && requiresVersionedProfitabilityPolicy
        && (
          !salesCatalogHasVersionedProfitabilityPolicy(catalog)
          || !hasVersionedEconomicSnapshot
        )
      ) {
        return sendSalesProfitabilityPolicyRequired(res);
      }
      const assumptions = mapSalesAssumptionSnapshot(
        assumptionResult.data,
      );
      const recalculated = calculateSalesModularProposal(
        input,
        catalog,
        assumptions,
      );
      if (
        sanitizeString(simulation.model_version, 80)
          !== recalculated.modelVersion
        || !salesModularResultMatches(
          simulation.results_snapshot,
          recalculated,
        )
      ) {
        return res.status(409).json({
          success: false,
          code: "PROPOSAL_SNAPSHOT_CONFLICT",
          error:
            "O cenário divergiu do catálogo congelado. Duplique e salve uma nova versão.",
        });
      }
      if (recalculated.missingCosts.length > 0) {
        return res.status(422).json({
          success: false,
          code: "PRICING_COST_MODEL_MISSING",
          error:
            "Complete os custos das funcionalidades antes de gerar a proposta.",
        });
      }
      if (
        recalculated.commercialPricing.enabled
        && recalculated.commercialPricing.missingPriceItemKeys.length > 0
      ) {
        return res.status(422).json({
          success: false,
          code: "PROPOSAL_PRICE_PER_PATIENT_MISSING",
          fields: recalculated.commercialPricing.missingPriceItemKeys,
          error:
            "Informe o preço por paciente dos módulos selecionados antes de gerar a proposta.",
          });
      }
      const proposalReview = classifySalesProposalReview(recalculated);
      if (proposalReview.technicalBlockingCodes.length > 0) {
        return res.status(422).json({
          success: false,
          code: "PROPOSAL_TECHNICAL_BLOCKED",
          blockingCodes: proposalReview.technicalBlockingCodes,
          error:
            "Corrija os dados técnicos obrigatórios antes de gerar a proposta.",
        });
      }
      if (
        proposalReview.requiresCommercialApproval
        && !salesCommercialExceptionApprovalMatches(
          recalculated,
          simulation.results_snapshot?.commercialExceptionApproval,
        )
      ) {
        return res.status(422).json({
          success: false,
          code: "PROPOSAL_MARGIN_POLICY_REVIEW_REQUIRED",
          alertCodes: proposalReview.commercialAlertCodes,
          error:
            "Esta condição comercial exige aprovação explícita de owner com MFA e justificativa.",
        });
      }
      const requestHash = crypto
        .createHash("sha256")
        .update(
          JSON.stringify({
            leadId,
            simulationId,
            catalogVersionId: catalog.id,
            resultModelVersion: recalculated.modelVersion,
            commercialExceptionResultHash:
              simulation.results_snapshot?.commercialExceptionApproval
                ?.resultHash || null,
          }),
        )
        .digest("hex");
      const provisionalToken = deriveSalesOfferPublicToken(
        actorUserId,
        idempotencyKey,
      );
      const expiresAt = new Date(
        Date.now()
          + input.offerValidityDays * 24 * 60 * 60 * 1000,
      ).toISOString();
      const { data, error } = await supabase.rpc(
        "create_sales_modular_offer_v1",
        {
          p_simulation_id: simulationId,
          p_lead_id: leadId,
          p_actor_user_id: actorUserId,
          p_idempotency_key: idempotencyKey,
          p_request_hash: requestHash,
          p_public_token_hash: hashSalesOfferToken(provisionalToken),
          p_expires_at: expiresAt,
        },
      );
      if (error) throw error;
      const offer = data?.offer || data;
      const publicToken = deriveSalesOfferPublicToken(
        sanitizeString(offer?.created_by, 120) || actorUserId,
        sanitizeString(offer?.idempotency_key, 240) || idempotencyKey,
      );
      return res.status(data?.idempotent ? 200 : 201).json({
        success: true,
        offer,
        publicUrl: buildSalesOfferPublicUrl(req, publicToken),
        stripeReady: false,
        modularCheckoutEnabled: false,
        idempotent: data?.idempotent === true,
        message: data?.idempotent
          ? "A proposta modular já existia; o mesmo link foi recuperado."
          : "Proposta pública modular criada sem acessar a Stripe.",
      });
    } catch (error: any) {
      if (sendSalesProfitabilityPolicySchemaPending(res, error)) return;
      const rawCode = sanitizeString(
        error?.message || error?.code,
        220,
      );
      const conflict = rawCode.includes("PROPOSAL_SNAPSHOT_CONFLICT");
      return res.status(conflict ? 409 : 500).json({
        success: false,
        code: conflict
          ? "PROPOSAL_SNAPSHOT_CONFLICT"
          : "PROPOSAL_PREPARATION_FAILED",
        error: conflict
          ? "A chave ou o snapshot diverge da proposta já criada."
          : "Não foi possível gerar a proposta modular.",
      });
    }
  };

  const prepareSalesOfferFromSimulation = async (
    req: any,
    res: any,
    params: {
      leadId: string;
      simulationId: string;
      actorUserId: string;
      idempotencyKey: string;
    },
  ) => {
    const { leadId, simulationId, actorUserId, idempotencyKey } = params;
    if (
      req.session?.user?.role !== "owner"
      || !hasVerifiedOwnerMfaSession(req.session?.user)
    ) {
      return res.status(403).json({
        success: false,
        code: "SIMULATION_ACCESS_DENIED",
        error: "Esta ação exige acesso owner com MFA validado.",
      });
    }
    if (
      !isUuid(leadId)
      || !isUuid(simulationId)
      || !isUuid(actorUserId)
      || idempotencyKey.length < 12
    ) {
      return res.status(400).json({
        success: false,
        code: "OFFER_SIMULATION_REQUIRED",
        error: "Selecione uma simulação salva antes de preparar a oferta.",
      });
    }

    const offerSelect =
      "id,lead_id,simulation_id,status,base_unit_amount_cents,currency,initial_active_patient_quantity,discount_duration_months,discount_type,discount_percentage,stripe_coupon_id,promotional_unit_amount_cents,promotional_monthly_amount_cents,post_discount_monthly_amount_cents,expires_at,created_by,idempotency_key,created_at";
    const stripeConfig = resolveSalesStripeConfiguration();

    const ensureStripeDiscount = async (offer: any, simulation: any) => {
      const discountPercentage = Number(
        simulation.discount_percentage || 0,
      );
      const duration = Number(
        simulation.discount_duration_months || 0,
      );
      const requiresCoupon =
        sanitizeString(simulation.discount_type, 20) === "coupon";
      if (!requiresCoupon) {
        if (sanitizeString(offer.status, 40) !== "ready") {
          const { data, error } = await supabase
            .from("sales_offers")
            .update({
              status: "ready",
              updated_at: new Date().toISOString(),
            })
            .eq("id", offer.id)
            .eq("simulation_id", simulation.id)
            .select(offerSelect)
            .single();
          if (error) throw error;
          return data;
        }
        return offer;
      }
      if (
        !Number.isFinite(discountPercentage)
        || discountPercentage <= 0
        || discountPercentage > 100
        || !isCustomCouponDurationMonths(duration)
      ) {
        const error = new Error("CUSTOM_DISCOUNT_INVALID");
        (error as any).code = "CUSTOM_DISCOUNT_INVALID";
        throw error;
      }
      if (!stripeConfig.enabled || !stripeConfig.basePriceId) {
        const error = new Error("CUSTOM_DISCOUNT_STRIPE_UNAVAILABLE");
        (error as any).code = "CUSTOM_DISCOUNT_STRIPE_UNAVAILABLE";
        throw error;
      }
      if (sanitizeString(offer.stripe_coupon_id, 240)) {
        if (sanitizeString(offer.status, 40) === "ready") return offer;
        const { data, error } = await supabase
          .from("sales_offers")
          .update({
            status: "ready",
            updated_at: new Date().toISOString(),
          })
          .eq("id", offer.id)
          .eq("simulation_id", simulation.id)
          .select(offerSelect)
          .single();
        if (error) throw error;
        return data;
      }

      const stripe = getStripe();
      let price: Stripe.Price;
      try {
        price = await stripe.prices.retrieve(stripeConfig.basePriceId);
      } catch (error: any) {
        const wrapped = new Error(
          error?.code === "resource_missing"
            ? "CUSTOM_DISCOUNT_MODE_MISMATCH"
            : "CUSTOM_DISCOUNT_STRIPE_UNAVAILABLE",
        );
        (wrapped as any).code = wrapped.message;
        throw wrapped;
      }
      if (
        !price.active
        || price.type !== "recurring"
        || Number(price.unit_amount || 0)
          !== PUBLIC_ACTIVE_PATIENT_PRICE.unitAmountCents
      ) {
        const error = new Error("CUSTOM_DISCOUNT_MODE_MISMATCH");
        (error as any).code = "CUSTOM_DISCOUNT_MODE_MISMATCH";
        throw error;
      }
      const productId =
        typeof price.product === "string" ? price.product : price.product?.id;
      let coupon: Stripe.Coupon;
      try {
        coupon = await stripe.coupons.create(
          {
            percent_off: discountPercentage,
            duration: "repeating",
            duration_in_months: duration,
            name: `Oferta Verto ${String(offer.id).slice(0, 8)}`,
            applies_to: productId
              ? { products: [productId] }
              : undefined,
            metadata: {
              flowType: "sales_assisted_signup",
              offerId: String(offer.id),
              leadId,
              simulationId,
            },
          },
          {
            idempotencyKey: `sales-offer-coupon:${offer.id}`,
          },
        );
      } catch (error: any) {
        const wrapped = new Error("CUSTOM_DISCOUNT_CREATION_FAILED");
        (wrapped as any).code = "CUSTOM_DISCOUNT_CREATION_FAILED";
        (wrapped as any).cause = error;
        throw wrapped;
      }
      const { data: persistedOffer, error: persistenceError } =
        await supabase
          .from("sales_offers")
          .update({
            stripe_coupon_id: coupon.id,
            status: "ready",
            updated_at: new Date().toISOString(),
          })
          .eq("id", offer.id)
          .eq("simulation_id", simulation.id)
          .select(offerSelect)
          .single();
      if (persistenceError || !persistedOffer) {
        const error = new Error("CUSTOM_DISCOUNT_PERSISTENCE_FAILED");
        (error as any).code = "CUSTOM_DISCOUNT_PERSISTENCE_FAILED";
        (error as any).cause = persistenceError || null;
        throw error;
      }
      return persistedOffer;
    };

    const serializePreparedOffer = (
      offer: any,
      rawToken: string,
      idempotent: boolean,
    ) => {
      const stripeReady = isSalesOfferStripeReady(offer, stripeConfig);
      return res.status(idempotent ? 200 : 201).json({
        success: true,
        offerId: offer.id,
        offer,
        publicUrl: stripeReady
          ? buildSalesOfferPublicUrl(req, rawToken)
          : null,
        status: offer.status,
        stripeReady,
        idempotent,
        message: idempotent
          ? "A mesma proposta individual foi recuperada."
          : "Proposta individual criada e pronta para envio.",
      });
    };
    const finalizePreparedOffer = async (
      offer: any,
      storedInput: SalesSimulationInput,
      recalculated: ReturnType<typeof calculateSalesProfitability>,
    ) => {
      const now = new Date().toISOString();
      const [simulationUpdate, leadUpdate, eventUpsert] =
        await Promise.all([
          supabase
            .from("sales_offer_simulations")
            .update({ status: "offered", updated_at: now })
            .eq("id", simulationId)
            .eq("lead_id", leadId)
            .in("status", ["saved", "selected", "offered"]),
          supabase
            .from("sales_leads")
            .update({
              status: "proposal_preparing",
              updated_at: now,
            })
            .eq("id", leadId)
            .is("deleted_at", null),
          supabase
            .from("sales_lead_events")
            .upsert(
              [
                {
                  lead_id: leadId,
                  event_type: "proposal_created",
                  actor_user_id: actorUserId,
                  metadata: {
                    offer_id: offer.id,
                    simulation_id: simulationId,
                    discount_percentage:
                      storedInput.discountBasisPoints / 100,
                    duration_months:
                      storedInput.discountDurationMonths || null,
                    profitability_rating: recalculated.rating,
                  },
                  idempotency_key: `proposal-created:${offer.id}`,
                },
              ],
              { onConflict: "idempotency_key", ignoreDuplicates: true },
            ),
        ]);
      const persistenceError = [
        simulationUpdate,
        leadUpdate,
        eventUpsert,
      ].find((result: any) => result?.error)?.error;
      if (persistenceError) {
        const error = new Error("CUSTOM_DISCOUNT_PERSISTENCE_FAILED");
        (error as any).code = "CUSTOM_DISCOUNT_PERSISTENCE_FAILED";
        (error as any).cause = persistenceError;
        throw error;
      }
    };

    try {
      const [leadResult, simulationResult, offerBySimulationResult] =
        await Promise.all([
          supabase
            .from("sales_leads")
            .select("id,status")
            .eq("id", leadId)
            .is("deleted_at", null)
            .maybeSingle(),
          supabase
            .from("sales_offer_simulations")
            .select(
              "id,lead_id,created_by,status,assumption_set_id,model_version,initial_active_patient_quantity,base_unit_amount_cents,currency,discount_type,discount_percentage,discount_duration_months,offer_validity_days,usage_profile,custom_monthly_cost_cents,onboarding_cost_cents,assumptions_snapshot,results_snapshot,profitability_rating,internal_justification,internal_notes,selected_for_offer_at,created_at,updated_at",
            )
            .eq("id", simulationId)
            .eq("lead_id", leadId)
            .is("deleted_at", null)
            .maybeSingle(),
          supabase
            .from("sales_offers")
            .select(offerSelect)
            .eq("simulation_id", simulationId)
            .maybeSingle(),
        ]);
      if (leadResult.error) throw leadResult.error;
      if (!leadResult.data) {
        return res.status(404).json({
          success: false,
          code: "SIMULATION_LEAD_NOT_FOUND",
          error: "Lead não encontrado.",
        });
      }
      if (simulationResult.error) throw simulationResult.error;
      const simulation = simulationResult.data;
      if (!simulation) {
        return res.status(404).json({
          success: false,
          code: "OFFER_SIMULATION_REQUIRED",
          error: "Simulação não encontrada.",
        });
      }
      if (offerBySimulationResult.error) {
        throw offerBySimulationResult.error;
      }

      const storedAssumptions = normalizeStoredSalesAssumptionSnapshot(
        simulation.assumptions_snapshot,
      );
      const storedInput: SalesSimulationInput = {
        initialActivePatientQuantity: Number(
          simulation.initial_active_patient_quantity,
        ),
        baseUnitAmountCents: Number(simulation.base_unit_amount_cents),
        discountBasisPoints: Math.round(
          Number(simulation.discount_percentage || 0) * 100,
        ),
        discountDurationMonths: Number(
          simulation.discount_duration_months || 0,
        ),
        offerValidityDays: Number(simulation.offer_validity_days || 14),
        usageProfile: sanitizeString(
          simulation.usage_profile,
          30,
        ) as SalesUsageProfile,
        customMonthlyCostCents: Number(
          simulation.custom_monthly_cost_cents || 0,
        ),
        onboardingCostCents: Number(
          simulation.onboarding_cost_cents || 0,
        ),
      };
      const recalculated = calculateSalesProfitability(
        storedInput,
        storedAssumptions,
      );
      const storedResult = simulation.results_snapshot || {};
      const snapshotMatches =
        simulation.model_version === recalculated.modelVersion
        && Number(storedResult.promotionalUnitAmountCents)
          === recalculated.promotionalUnitAmountCents
        && Number(storedResult.promotionalMonthlyRevenueCents)
          === recalculated.promotionalMonthlyRevenueCents
        && sanitizeString(storedResult.rating, 40) === recalculated.rating
        && Number(storedResult?.input?.discountBasisPoints)
          === storedInput.discountBasisPoints;
      if (!snapshotMatches) {
        return res.status(409).json({
          success: false,
          code: "OFFER_SIMULATION_CHANGED",
          error:
            "O snapshot da simulação divergiu. Duplique e salve uma nova simulação.",
        });
      }
      if (
        recalculated.rating === "insufficient_data"
        || recalculated.missingAssumptions.length > 0
      ) {
        return res.status(422).json({
          success: false,
          code: "SIMULATION_FINANCIAL_DATA_INSUFFICIENT",
          error:
            "Complete as premissas financeiras obrigatórias antes de preparar a oferta.",
        });
      }
      if (
        recalculated.requiresJustification
        && sanitizeString(
          simulation.internal_justification,
          1500,
        ).length < 12
      ) {
        return res.status(422).json({
          success: false,
          code: "SIMULATION_JUSTIFICATION_REQUIRED",
          error:
            "Esta oferta exige uma justificativa administrativa antes do preparo.",
        });
      }

      if (offerBySimulationResult.data) {
        const existingOffer = offerBySimulationResult.data;
        const existingToken = deriveSalesOfferPublicToken(
          sanitizeString(existingOffer.created_by, 120),
          sanitizeString(existingOffer.idempotency_key, 240),
        );
        const readyOffer = await ensureStripeDiscount(
          existingOffer,
          simulation,
        );
        await finalizePreparedOffer(
          readyOffer,
          storedInput,
          recalculated,
        );
        return serializePreparedOffer(readyOffer, existingToken, true);
      }

      const token = deriveSalesOfferPublicToken(
        actorUserId,
        idempotencyKey,
      );
      const expiresAt = new Date(
        Date.now()
          + storedInput.offerValidityDays * 24 * 60 * 60 * 1000,
      ).toISOString();
      const { data: insertedOffer, error: insertError } = await supabase
        .from("sales_offers")
        .insert([
          {
            lead_id: leadId,
            simulation_id: simulationId,
            simulation_snapshot: {
              modelVersion: recalculated.modelVersion,
              assumptionSet: storedAssumptions,
              input: storedInput,
              results: recalculated,
              createdAt: simulation.created_at,
            },
            status: "draft",
            base_unit_amount_cents:
              PUBLIC_ACTIVE_PATIENT_PRICE.unitAmountCents,
            currency: PUBLIC_ACTIVE_PATIENT_PRICE.currency,
            initial_active_patient_quantity:
              storedInput.initialActivePatientQuantity,
            discount_duration_months:
              storedInput.discountBasisPoints > 0
                ? storedInput.discountDurationMonths
                : null,
            discount_type:
              storedInput.discountBasisPoints > 0 ? "coupon" : "none",
            discount_percentage: storedInput.discountBasisPoints / 100,
            promotional_unit_amount_cents:
              recalculated.promotionalUnitAmountCents,
            promotional_monthly_amount_cents:
              recalculated.promotionalMonthlyRevenueCents,
            post_discount_monthly_amount_cents:
              recalculated.officialMonthlyRevenueCents,
            internal_justification:
              sanitizeString(
                simulation.internal_justification,
                1500,
              ) || null,
            public_token_hash: hashSalesOfferToken(token),
            commercial_notes:
              sanitizeString(simulation.internal_notes, 1500) || null,
            expires_at: expiresAt,
            created_by: actorUserId,
            idempotency_key: idempotencyKey,
          },
        ])
        .select(offerSelect)
        .single();
      if (insertError) {
        if (String(insertError.code || "") === "23505") {
          const { data: concurrentOffer, error: concurrentError } =
            await supabase
              .from("sales_offers")
              .select(offerSelect)
              .eq("simulation_id", simulationId)
              .maybeSingle();
          if (concurrentError) throw concurrentError;
          if (concurrentOffer) {
            const concurrentToken = deriveSalesOfferPublicToken(
              sanitizeString(concurrentOffer.created_by, 120),
              sanitizeString(concurrentOffer.idempotency_key, 240),
            );
            const readyConcurrent = await ensureStripeDiscount(
              concurrentOffer,
              simulation,
            );
            await finalizePreparedOffer(
              readyConcurrent,
              storedInput,
              recalculated,
            );
            return serializePreparedOffer(
              readyConcurrent,
              concurrentToken,
              true,
            );
          }
        }
        throw insertError;
      }

      const readyOffer = await ensureStripeDiscount(
        insertedOffer,
        simulation,
      );
      await finalizePreparedOffer(
        readyOffer,
        storedInput,
        recalculated,
      );
      return serializePreparedOffer(readyOffer, token, false);
    } catch (error: any) {
      const code = sanitizeString(
        error?.code || error?.message,
        160,
      );
      const expectedCodes = new Set([
        "CUSTOM_DISCOUNT_INVALID",
        "CUSTOM_DISCOUNT_STRIPE_UNAVAILABLE",
        "CUSTOM_DISCOUNT_MODE_MISMATCH",
        "CUSTOM_DISCOUNT_CREATION_FAILED",
        "CUSTOM_DISCOUNT_PERSISTENCE_FAILED",
        "OFFER_SIMULATION_CHANGED",
      ]);
      const publicCode = expectedCodes.has(code)
        ? code
        : "OFFER_SIMULATION_PREPARATION_FAILED";
      console.error(
        "[Owner Sales] Falha ao preparar oferta da simulação.",
        {
          leadId,
          simulationId,
          code: publicCode,
          message: sanitizeString(error?.message || String(error), 220),
        },
      );
      const status =
        code === "CUSTOM_DISCOUNT_INVALID"
          ? 422
          : code === "OFFER_SIMULATION_CHANGED"
            ? 409
            : code === "CUSTOM_DISCOUNT_STRIPE_UNAVAILABLE"
              || code === "CUSTOM_DISCOUNT_MODE_MISMATCH"
              || code === "CUSTOM_DISCOUNT_CREATION_FAILED"
              || code === "CUSTOM_DISCOUNT_PERSISTENCE_FAILED"
                ? 503
                : 500;
      const messages: Record<string, string> = {
        CUSTOM_DISCOUNT_INVALID:
          "O percentual ou a duração do desconto é inválido.",
        CUSTOM_DISCOUNT_STRIPE_UNAVAILABLE:
          "A Stripe está indisponível para preparar este desconto.",
        CUSTOM_DISCOUNT_MODE_MISMATCH:
          "O Price configurado não pertence ao mesmo ambiente Stripe.",
        CUSTOM_DISCOUNT_CREATION_FAILED:
          "Não foi possível criar o desconto personalizado. A simulação foi preservada.",
        CUSTOM_DISCOUNT_PERSISTENCE_FAILED:
          "A oferta foi reservada, mas sua persistência ainda precisa ser confirmada. Tente novamente.",
        OFFER_SIMULATION_CHANGED:
          "A simulação mudou. Salve uma nova versão antes de preparar a oferta.",
      };
      return res.status(status).json({
        success: false,
        code: publicCode,
        error:
          messages[publicCode]
          || "Não foi possível preparar a oferta agora.",
      });
    }
  };

  app.get(
    "/api/owner/sales/leads/:leadId/events",
    checkAuth,
    requireRoles("owner", "admin"),
    async (req: any, res) => {
      const leadId = sanitizeString(req.params?.leadId, 120);
      if (!isUuid(leadId))
        return res
          .status(400)
          .json({ success: false, error: "Lead inválido." });
      const { data, error } = await supabase
        .from("sales_lead_events")
        .select("id,event_type,actor_user_id,metadata,created_at")
        .eq("lead_id", leadId)
        .order("created_at", { ascending: false })
        .limit(200);
      if (error)
        return res.status(500).json({
          success: false,
          error: "Não foi possível carregar o histórico.",
        });
      return res.json({ success: true, data: data || [] });
    },
  );

  app.post(
    "/api/owner/sales/offers",
    checkAuth,
    requireRoles("owner", "admin"),
    async (req: any, res) => {
      const leadId = sanitizeString(req.body?.leadId, 120);
      const simulationId = sanitizeString(req.body?.simulationId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      const requestIdempotencyKey = sanitizeString(
        req.headers?.["x-idempotency-key"] || req.body?.idempotencyKey,
        180,
      );
      if (
        req.body?.stripeCouponId ||
        req.body?.couponId ||
        req.body?.stripePriceId ||
        req.body?.priceId
      ) {
        return res.status(400).json({
          success: false,
          error: "IDs Stripe não são aceitos pelo cliente.",
        });
      }
      if (simulationId) {
        const { data: simulationKind, error: simulationKindError } =
          await supabase
            .from("sales_offer_simulations")
            .select("simulation_type")
            .eq("id", simulationId)
            .eq("lead_id", leadId)
            .is("deleted_at", null)
            .maybeSingle();
        if (
          simulationKindError
          && !extractMissingColumnName(simulationKindError)
        ) {
          return res.status(500).json({
            success: false,
            code: "PROPOSAL_PREPARATION_FAILED",
            error: "Não foi possível validar o tipo da simulação.",
          });
        }
        if (
          sanitizeString(simulationKind?.simulation_type, 30)
            === "modular"
        ) {
          return prepareSalesModularOffer(req, res, {
            leadId,
            simulationId,
            actorUserId,
            idempotencyKey: requestIdempotencyKey,
          });
        }
        return prepareSalesOfferFromSimulation(req, res, {
          leadId,
          simulationId,
          actorUserId,
          idempotencyKey: requestIdempotencyKey,
        });
      }
      const quantity = normalizeSalesInteger(
        req.body?.initialActivePatientQuantity,
        SALES_ESTIMATED_ACTIVE_PATIENTS_MAX,
        true,
      );
      const rawDuration = req.body?.discountDurationMonths;
      const duration =
        rawDuration == null || Number(rawDuration) === 0
          ? null
          : Number(rawDuration);
      const expiresInDays = Math.max(
        1,
        Math.min(90, Number(req.body?.expiresInDays || 14)),
      );
      if (
        !isUuid(leadId) ||
        !isUuid(actorUserId) ||
        requestIdempotencyKey.length < 12 ||
        quantity === null ||
        quantity < 1 ||
        (duration !== null && !isCouponDurationMonths(duration))
      ) {
        return res
          .status(400)
          .json({ success: false, error: "Dados da oferta inválidos." });
      }
      try {
        const { data: lead } = await supabase
          .from("sales_leads")
          .select("id,status")
          .eq("id", leadId)
          .is("deleted_at", null)
          .maybeSingle();
        if (!lead)
          return res
            .status(404)
            .json({ success: false, error: "Lead não encontrado." });

        const token = deriveSalesOfferPublicToken(
          actorUserId,
          requestIdempotencyKey,
        );
        const tokenHash = hashSalesOfferToken(token);
        const stripeConfig = resolveSalesStripeConfiguration();
        const ready =
          stripeConfig.enabled && stripeConfig.readyForDuration(duration);

        const serializeOfferResponse = (offer: any, idempotent: boolean) => {
          const offerStatus = sanitizeString(offer?.status, 40);
          const linkAllowed =
            ready &&
            ["ready", "sent", "opened", "checkout_created"].includes(
              offerStatus,
            );
          return res.status(idempotent ? 200 : 201).json({
            success: true,
            offer,
            publicUrl: linkAllowed
              ? buildSalesOfferPublicUrl(req, token)
              : null,
            stripeReady: ready,
            idempotent,
            message: linkAllowed
              ? idempotent
                ? "Oferta já criada. O mesmo link individual foi recuperado."
                : "Oferta criada. O link individual está pronto para envio."
              : offerStatus === "draft"
                ? "Oferta salva como rascunho. Configuração Stripe pendente."
                : "Oferta já processada e preservada.",
          });
        };

        const offerSelect =
          "id,lead_id,status,base_unit_amount_cents,currency,initial_active_patient_quantity,discount_duration_months,discount_type,expires_at,created_at";
        const { data: existingOffer, error: existingOfferError } =
          await supabase
            .from("sales_offers")
            .select(offerSelect)
            .eq("created_by", actorUserId)
            .eq("idempotency_key", requestIdempotencyKey)
            .maybeSingle();
        if (existingOfferError) throw existingOfferError;
        if (existingOffer) return serializeOfferResponse(existingOffer, true);

        const expiresAt = new Date(
          Date.now() + expiresInDays * 24 * 60 * 60 * 1000,
        ).toISOString();
        const { data: offer, error } = await supabase
          .from("sales_offers")
          .insert([
            {
              lead_id: leadId,
              status: ready ? "ready" : "draft",
              base_unit_amount_cents:
                PUBLIC_ACTIVE_PATIENT_PRICE.unitAmountCents,
              currency: PUBLIC_ACTIVE_PATIENT_PRICE.currency,
              initial_active_patient_quantity: quantity,
              discount_duration_months: duration,
              discount_type: duration ? "coupon" : "none",
              discount_percentage: null,
              public_token_hash: tokenHash,
              expires_at: expiresAt,
              created_by: actorUserId,
              idempotency_key: requestIdempotencyKey,
              commercial_notes: sanitizeString(req.body?.notes, 1500) || null,
            },
          ])
          .select(offerSelect)
          .single();
        if (error) {
          if (String(error?.code || "") === "23505") {
            const { data: concurrentOffer, error: concurrentError } =
              await supabase
                .from("sales_offers")
                .select(offerSelect)
                .eq("created_by", actorUserId)
                .eq("idempotency_key", requestIdempotencyKey)
                .maybeSingle();
            if (concurrentError) throw concurrentError;
            if (concurrentOffer)
              return serializeOfferResponse(concurrentOffer, true);
          }
          throw error;
        }
        await Promise.all([
          supabase
            .from("sales_leads")
            .update({
              status: "proposal_preparing",
              updated_at: new Date().toISOString(),
            })
            .eq("id", leadId),
          supabase.from("sales_lead_events").insert([
            {
              lead_id: leadId,
              event_type: "proposal_created",
              actor_user_id: actorUserId,
              metadata: { offer_id: offer.id, duration_months: duration },
              idempotency_key: `proposal-created:${offer.id}`,
            },
          ]),
        ]);
        return serializeOfferResponse(offer, false);
      } catch (error: any) {
        console.error(
          "[Owner Sales] Falha ao criar oferta:",
          sanitizeString(error?.message || String(error), 240),
        );
        return res
          .status(500)
          .json({ success: false, error: "Não foi possível criar a oferta." });
      }
    },
  );

  app.post(
    "/api/owner/sales/offers/:offerId/accept",
    checkAuth,
    requireRoles("owner"),
    modularCheckoutLimiter,
    async (req: any, res) => {
      const offerId = sanitizeString(req.params?.offerId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      if (
        !isUuid(offerId)
        || !isUuid(actorUserId)
        || !hasVerifiedOwnerMfaSession(req.session?.user)
      ) {
        return res.status(403).json({ success: false, error: "OWNER_MFA_REQUIRED" });
      }
      if (req.body?.commercialValuesConsent !== true) {
        return res.status(400).json({
          success: false,
          error: "COMMERCIAL_VALUES_CONSENT_REQUIRED",
          message: "Confirme que o aceite incluiu valores promocionais e posteriores.",
        });
      }
      const now = new Date().toISOString();
      const { data: currentOffer, error: currentError } = await supabase
        .from("sales_offers")
        .select("id,lead_id,accepted_at,accepted_terms_at,accepted_terms_snapshot,status,expires_at,revoked_at,offer_type")
        .eq("id", offerId)
        .maybeSingle();
      if (
        currentError
        || !currentOffer
        || currentOffer.offer_type !== "modular"
        || currentOffer.revoked_at
        || Date.parse(String(currentOffer.expires_at || "")) <= Date.now()
      ) {
        return res.status(409).json({
          success: false,
          error: "MODULAR_OFFER_ACCEPTANCE_BLOCKED",
          message: "A proposta está vencida, revogada ou indisponível para aceite.",
        });
      }
      if (
        currentOffer.accepted_at
        && currentOffer.accepted_terms_at
        && currentOffer.accepted_terms_snapshot?.version === MODULAR_COMMERCIAL_CONSENT_VERSION
        && currentOffer.accepted_terms_snapshot?.statement === MODULAR_COMMERCIAL_CONSENT_TEXT
      ) {
        return res.json({
          success: true,
          acceptedAt: currentOffer.accepted_at,
          idempotent: true,
        });
      }
      if (currentOffer.accepted_at) {
        const { error: termsError } = await supabase
          .from("sales_offers")
          .update({
            accepted_terms_at: now,
            accepted_terms_snapshot: {
              version: MODULAR_COMMERCIAL_CONSENT_VERSION,
              statement: MODULAR_COMMERCIAL_CONSENT_TEXT,
              source: "owner_assisted",
              capturedAt: now,
            },
            updated_at: now,
          })
          .eq("id", offerId)
          .eq("accepted_at", currentOffer.accepted_at);
        if (termsError) {
          return res.status(500).json({
            success: false,
            error: "MODULAR_OFFER_ACCEPTANCE_FAILED",
          });
        }
        return res.json({
          success: true,
          acceptedAt: currentOffer.accepted_at,
          idempotent: false,
        });
      }
      const { data: offer, error } = await supabase
        .from("sales_offers")
        .update({
          accepted_at: now,
          accepted_terms_at: now,
          accepted_terms_snapshot: {
            version: MODULAR_COMMERCIAL_CONSENT_VERSION,
            statement: MODULAR_COMMERCIAL_CONSENT_TEXT,
            source: "owner_assisted",
            capturedAt: now,
          },
          updated_at: now,
        })
        .eq("id", offerId)
        .eq("offer_type", "modular")
        .is("revoked_at", null)
        .gt("expires_at", now)
        .in("status", ["ready", "sent", "opened", "checkout_created"])
        .is("accepted_at", null)
        .select("id,lead_id,accepted_at")
        .maybeSingle();
      if (error || !offer) {
        return res.status(409).json({
          success: false,
          error: "MODULAR_OFFER_ACCEPTANCE_BLOCKED",
          message: "A proposta está vencida, revogada ou indisponível para aceite.",
        });
      }
      await supabase.from("sales_lead_events").upsert(
        [{
          lead_id: offer.lead_id,
          event_type: "lead_updated",
          actor_user_id: actorUserId,
          metadata: {
            action: "modular_offer_acceptance_recorded_by_owner",
            offer_id: offer.id,
            commercial_values_consent: true,
          },
          idempotency_key: `modular-offer-owner-accepted:${offer.id}`,
        }],
        { onConflict: "idempotency_key", ignoreDuplicates: true },
      );
      return res.json({ success: true, acceptedAt: offer.accepted_at || now });
    },
  );

  app.get(
    "/api/public/sales-checkouts/:token",
    publicSalesLeadIpLimiter,
    async (req: any, res) => {
      const token = sanitizeString(req.params?.token, 300);
      if (token.length < 32) {
        return res.status(404).send("Link de pagamento indisponível.");
      }
      const { data: link, error } = await supabase
        .from("sales_checkout_links")
        .select("id,offer_id,lead_id,checkout_url,status,expires_at,logically_expired_at")
        .eq("public_token_hash", hashSalesOfferToken(token))
        .maybeSingle();
      const expired = !link?.expires_at
        || !Number.isFinite(Date.parse(String(link.expires_at)))
        || Date.parse(String(link.expires_at)) <= Date.now();
      if (
        error
        || !link?.checkout_url
        || expired
        || link.logically_expired_at
        || !["active", "sent", "opened", "payment_pending"].includes(link.status)
      ) {
        return res.status(404).send("Link de pagamento indisponível ou expirado.");
      }
      const now = new Date().toISOString();
      await Promise.all([
        supabase
          .from("sales_checkout_links")
          .update({
            status: link.status === "payment_pending" ? link.status : "opened",
            last_opened_at: now,
            updated_at: now,
          })
          .eq("id", link.id)
          .in("status", ["active", "sent", "opened", "payment_pending"]),
        supabase.from("sales_lead_events").upsert(
          [{
            lead_id: link.lead_id,
            event_type: "checkout_opened",
            metadata: { offer_id: link.offer_id, checkout_link_id: link.id },
            idempotency_key: `modular-checkout-opened:${link.id}`,
          }],
          { onConflict: "idempotency_key", ignoreDuplicates: true },
        ),
        supabase
          .from("sales_leads")
          .update({ status: "checkout_opened", updated_at: now })
          .eq("id", link.lead_id)
          .in("status", ["proposal_sent", "checkout_sent", "checkout_opened"])
          .is("deleted_at", null),
      ]);
      return res.redirect(303, link.checkout_url);
    },
  );

  app.post(
    "/api/owner/sales/offers/:offerId/modular-checkout",
    checkAuth,
    requireRoles("owner"),
    modularCheckoutLimiter,
    async (req: any, res) => {
      const offerId = sanitizeString(req.params?.offerId, 120);
      const actorUserId = sanitizeString(req.session?.user?.id, 120);
      const idempotencyKey = sanitizeString(
        req.headers?.["x-idempotency-key"] || req.body?.idempotencyKey,
        180,
      );
      const regenerate = req.body?.regenerate === true;
      if (
        !isUuid(offerId)
        || !isUuid(actorUserId)
        || idempotencyKey.length < 12
        || !hasVerifiedOwnerMfaSession(req.session?.user)
      ) {
        return res.status(403).json({
          success: false,
          code: "MODULAR_CHECKOUT_OWNER_MFA_REQUIRED",
          error: "Esta ação exige owner com MFA validado.",
        });
      }
      if (
        req.body?.amount
        || req.body?.price
        || req.body?.prices
        || req.body?.discount
        || req.body?.lineItems
        || req.body?.organizationId
      ) {
        return res.status(400).json({
          success: false,
          code: "MODULAR_CHECKOUT_BROWSER_VALUES_REJECTED",
          error: "Valores e tenant são reconstruídos no servidor.",
        });
      }
      try {
        const [offerResult, itemResult] = await Promise.all([
          supabase
            .from("sales_offers")
            .select(
              "id,lead_id,offer_type,status,accepted_at,accepted_terms_at,accepted_terms_snapshot,expires_at,revoked_at,currency,catalog_version_id,simulation_snapshot,modular_snapshot,internal_justification",
            )
            .eq("id", offerId)
            .maybeSingle(),
          supabase
            .from("sales_offer_items")
            .select(
              "id,item_key,public_name_snapshot,pricing_mode_snapshot,gross_recurring_amount_cents,recurring_amount_cents,post_promotion_recurring_amount_cents,one_time_amount_cents,internal_result_snapshot,sort_order",
            )
            .eq("offer_id", offerId)
            .order("sort_order", { ascending: true }),
        ]);
        if (offerResult.error || itemResult.error) {
          throw offerResult.error || itemResult.error;
        }
        const offer = offerResult.data;
        if (!offer || sanitizeString(offer.offer_type, 30) !== "modular") {
          return res.status(404).json({
            success: false,
            code: "MODULAR_OFFER_NOT_FOUND",
            error: "Proposta modular não encontrada.",
          });
        }
        if (!["ready", "sent", "opened", "checkout_created", "payment_pending"].includes(
          sanitizeString(offer.status, 40),
        )) {
          return res.status(409).json({
            success: false,
            code: "MODULAR_OFFER_STATE_INVALID",
            error: "O estado atual da proposta não permite gerar Checkout.",
          });
        }
        if (
          !offer.accepted_at
          || !offer.accepted_terms_at
          || offer.accepted_terms_snapshot?.version !== MODULAR_COMMERCIAL_CONSENT_VERSION
          || offer.accepted_terms_snapshot?.statement !== MODULAR_COMMERCIAL_CONSENT_TEXT
        ) {
          return res.status(409).json({
            success: false,
            code: "MODULAR_OFFER_ACCEPTANCE_REQUIRED",
            error: "Registre o aceite explícito antes de gerar o link.",
          });
        }
        if (
          offer.revoked_at
          || !Number.isFinite(Date.parse(String(offer.expires_at || "")))
          || Date.parse(String(offer.expires_at)) <= Date.now()
        ) {
          return res.status(409).json({
            success: false,
            code: "MODULAR_OFFER_EXPIRED",
            error: "A proposta está vencida ou revogada.",
          });
        }
        const snapshot =
          offer.modular_snapshot && typeof offer.modular_snapshot === "object"
            ? offer.modular_snapshot
            : {};
        const frozenResults =
          offer.simulation_snapshot?.results
          && typeof offer.simulation_snapshot.results === "object"
            ? offer.simulation_snapshot.results
            : {};
        const phases = Array.isArray(snapshot.commercialPhases)
          ? snapshot.commercialPhases
          : Array.isArray(frozenResults.commercialPhases)
            ? frozenResults.commercialPhases
            : [];
        if (phases.length < 1 || !Array.isArray(itemResult.data) || itemResult.data.length < 1) {
          return res.status(422).json({
            success: false,
            code: "MODULAR_CHECKOUT_SNAPSHOT_INCOMPLETE",
            error: "O snapshot congelado não contém fases reconciliáveis.",
          });
        }
        const frozenReview = classifySalesProposalReview(frozenResults);
        if (frozenReview.technicalBlockingCodes.length > 0) {
          return res.status(409).json({
            success: false,
            code: "MODULAR_CHECKOUT_TECHNICAL_BLOCKED",
            error:
              "O snapshot congelado possui uma pendência técnica não excepcionável.",
          });
        }
        if (
          frozenReview.requiresCommercialApproval
          && !salesCommercialExceptionApprovalMatches(
            frozenResults,
            frozenResults.commercialExceptionApproval,
          )
        ) {
          return res.status(409).json({
            success: false,
            code: "MODULAR_CHECKOUT_MARGIN_POLICY_REVIEW_REQUIRED",
            error:
              "A condição comercial congelada não possui uma aprovação excepcional válida.",
          });
        }
        const firstPhase = phases[0];
        const lastPhase = phases[phases.length - 1];
        const frozenItemsByKey = new Map(
          (itemResult.data || []).map((item: any) => [sanitizeString(item.item_key, 80), item]),
        );
        const phaseIsReconciled = (phase: any, phaseKind: "promotional" | "future") => {
          if (!phase || !Array.isArray(phase.lines)) return false;
          let recurringTotal = 0;
          let oneTimeTotal = 0;
          for (const line of phase.lines) {
            const itemKey = sanitizeString(line?.itemKey, 80);
            const stored: any = frozenItemsByKey.get(itemKey);
            const amount = Number(line?.activePriceCents);
            if (!stored || !Number.isSafeInteger(amount) || amount < 0) return false;
            if (sanitizeString(line?.billingInterval, 30) === "one_time") {
              if (phaseKind === "promotional") {
                oneTimeTotal += amount;
                if (amount !== Number(stored.one_time_amount_cents || 0)) return false;
              }
              continue;
            }
            recurringTotal += amount;
            const storedAmount = phaseKind === "promotional"
              ? Number(stored.recurring_amount_cents || 0)
              : Number(stored.post_promotion_recurring_amount_cents || stored.gross_recurring_amount_cents || 0);
            if (amount !== storedAmount) return false;
          }
          return recurringTotal === Number(phase.recurringRevenueCents)
            && (phaseKind !== "promotional" || recurringTotal + oneTimeTotal === Number(phase.invoiceAmountCents));
        };
        const everyPhaseIsInternallyReconciled = phases.every((phase: any, phaseIndex: number) => {
          if (!phase || !Array.isArray(phase.lines) || phase.lines.length < 1) return false;
          const itemKeys = new Set<string>();
          let recurringTotal = 0;
          let oneTimeTotal = 0;
          for (const line of phase.lines) {
            const itemKey = sanitizeString(line?.itemKey, 80);
            const amount = Number(line?.activePriceCents);
            if (
              !itemKey
              || itemKeys.has(itemKey)
              || !frozenItemsByKey.has(itemKey)
              || !Number.isSafeInteger(amount)
              || amount < 0
            ) {
              return false;
            }
            itemKeys.add(itemKey);
            if (sanitizeString(line?.billingInterval, 30) === "one_time") {
              const stored: any = frozenItemsByKey.get(itemKey);
              if (amount !== Number(stored?.one_time_amount_cents || 0)) return false;
              if (phaseIndex === 0) oneTimeTotal += amount;
            } else {
              recurringTotal += amount;
            }
          }
          return recurringTotal === Number(phase.recurringRevenueCents)
            && recurringTotal + oneTimeTotal === Number(phase.invoiceAmountCents);
        });
        if (
          !everyPhaseIsInternallyReconciled
          || !phaseIsReconciled(firstPhase, "promotional")
          || !phaseIsReconciled(lastPhase, "future")
        ) {
          return res.status(422).json({
            success: false,
            code: "MODULAR_CHECKOUT_RECONCILIATION_FAILED",
            error: "Os valores congelados da proposta não reconciliam com seus itens.",
          });
        }
        const capacity =
          snapshot.capacity
          || snapshot.basePackage?.capacity
          || frozenResults.basePackage?.capacity
          || null;
        const checkoutPlan = buildFrozenStripeCheckoutPlan({
          currency: sanitizeString(offer.currency, 12) || "brl",
          phases,
          capacity,
          effectiveAt: new Date().toISOString(),
        });
        const requestHash = crypto
          .createHash("sha256")
          .update(JSON.stringify({
            offerId,
            environment: "test",
            checkoutPlan: checkoutPlan.reconciliationHashInput,
          }))
          .digest("hex");
        const checkoutPublicToken = deriveSalesCheckoutPublicToken(
          offerId,
          `${requestHash}:${idempotencyKey}`,
        );
        const { data: sameKey, error: sameKeyError } = await supabase
          .from("sales_checkout_links")
          .select("*")
          .eq("created_by", actorUserId)
          .eq("idempotency_key", idempotencyKey)
          .maybeSingle();
        if (sameKeyError) throw sameKeyError;
        if (sameKey) {
          if (sameKey.request_hash !== requestHash || sameKey.offer_id !== offerId) {
            return res.status(409).json({
              success: false,
              code: "MODULAR_CHECKOUT_IDEMPOTENCY_CONFLICT",
              error: "A chave já foi usada com outro payload.",
            });
          }
          return res.json({
            success: true,
            link: serializeSalesCheckoutLink(req, sameKey),
            idempotent: true,
          });
        }
        const { data: activeLink, error: activeLinkError } = await supabase
          .from("sales_checkout_links")
          .select("*")
          .eq("offer_id", offerId)
          .eq("environment", "test")
          .in("status", ["active", "sent", "opened", "payment_pending"])
          .maybeSingle();
        if (activeLinkError) throw activeLinkError;
        if (activeLink && !regenerate) {
          return res.json({
            success: true,
            link: serializeSalesCheckoutLink(req, activeLink),
            idempotent: true,
          });
        }
        if (!activeLink) {
          const { data: failedSubscriptionLink, error: failedSubscriptionError } = await supabase
            .from("sales_checkout_links")
            .select("id,stripe_subscription_id,status")
            .eq("offer_id", offerId)
            .eq("environment", "test")
            .eq("status", "failed")
            .not("stripe_subscription_id", "is", null)
            .order("created_at", { ascending: false })
            .limit(1)
            .maybeSingle();
          if (failedSubscriptionError) throw failedSubscriptionError;
          if (failedSubscriptionLink?.stripe_subscription_id) {
            return res.status(409).json({
              success: false,
              code: "MODULAR_CHECKOUT_PAYMENT_RECOVERY_REQUIRED",
              error: "A assinatura já existe e possui falha de cobrança. Regularize-a na Stripe sem criar outra assinatura.",
            });
          }
        }
        const stripeSecret = sanitizeString(process.env.STRIPE_SECRET_KEY, 300);
        if (!stripeSecret.startsWith("sk_test_")) {
          return res.status(503).json({
            success: false,
            code: "MODULAR_CHECKOUT_TEST_CONFIGURATION_REQUIRED",
            error: "Configure credenciais Stripe de teste para validar este fluxo.",
          });
        }
        if (activeLink && regenerate) {
          await supabase
            .from("sales_checkout_links")
            .update({
              status: "expired",
              logically_expired_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
            })
            .eq("id", activeLink.id)
            .in("status", ["active", "sent", "opened", "payment_pending"]);
          if (activeLink.stripe_checkout_session_id) {
            await getStripe().checkout.sessions.expire(
              activeLink.stripe_checkout_session_id,
            ).catch(() => undefined);
          }
        }
        const { data: lead, error: leadError } = await supabase
          .from("sales_leads")
          .select("id,email,normalized_email")
          .eq("id", offer.lead_id)
          .is("deleted_at", null)
          .maybeSingle();
        if (leadError || !lead) throw leadError || new Error("SALES_LEAD_NOT_FOUND");
        const origin = salesApplicationOrigin(req);
        const stripeMetadata: Record<string, string> = {
          flowType: "sales_modular_assisted",
          offerId,
          leadId: offer.lead_id,
          requestHash,
          catalogVersion: sanitizeString(
            snapshot.catalogVersion || offer.catalog_version_id,
            100,
          ),
          assumptionsVersion: sanitizeString(
            snapshot.assumptionsSnapshotVersion
              || offer.simulation_snapshot?.assumptionSetId,
            100,
          ),
          environment: "test",
        };
        const session = await getStripe().checkout.sessions.create(
          {
            mode: "subscription",
            client_reference_id: offerId,
            customer_email:
              sanitizeEmail(lead.normalized_email || lead.email) || undefined,
            success_url: `${origin}/oferta/pagamento?payment=success&session_id={CHECKOUT_SESSION_ID}`,
            cancel_url: `${origin}/oferta/pagamento?payment=cancelled`,
            expires_at: Math.floor(Date.now() / 1000) + 24 * 60 * 60,
            metadata: stripeMetadata,
            subscription_data: { metadata: stripeMetadata },
            line_items: checkoutPlan.initialLineItems.map((line) => ({
              quantity: 1,
              price_data: {
                currency: checkoutPlan.currency,
                unit_amount: line.unitAmountCents,
                product_data: {
                  name: line.description,
                  metadata: line.metadata,
                },
                ...(line.recurring
                  ? { recurring: { interval: "month" as const } }
                  : {}),
              },
            })),
          },
          {
            idempotencyKey: crypto
              .createHash("sha256")
              .update(`modular-checkout:${offerId}:${requestHash}:${idempotencyKey}`)
              .digest("hex"),
          },
        );
        if (!session.url) throw new Error("STRIPE_CHECKOUT_URL_MISSING");
        const linkPayload = {
          offer_id: offerId,
          lead_id: offer.lead_id,
          environment: "test",
          status: "active",
          request_hash: requestHash,
          idempotency_key: idempotencyKey,
          stripe_checkout_session_id: session.id,
          checkout_url: session.url,
          public_token_hash: hashSalesOfferToken(checkoutPublicToken),
          catalog_snapshot_version: sanitizeString(
            snapshot.catalogVersion || offer.catalog_version_id,
            100,
          ),
          assumptions_snapshot_version: sanitizeString(
            snapshot.assumptionsSnapshotVersion
              || offer.simulation_snapshot?.assumptionSetId,
            100,
          ),
          checkout_plan_snapshot: checkoutPlan,
          initial_amount_cents: checkoutPlan.initialAmountCents,
          promotional_monthly_cents: checkoutPlan.promotionalMonthlyCents,
          future_monthly_cents: checkoutPlan.futureMonthlyCents,
          one_time_cents: checkoutPlan.oneTimeCents,
          expires_at: new Date(Number(session.expires_at) * 1000).toISOString(),
          created_by: actorUserId,
        };
        const { data: storedLink, error: storeError } = await supabase
          .from("sales_checkout_links")
          .insert([linkPayload])
          .select("*")
          .single();
        if (storeError) {
          await getStripe().checkout.sessions.expire(session.id).catch(() => undefined);
          if (String(storeError.code || "") === "23505") {
            const { data: racedLink, error: racedLinkError } = await supabase
              .from("sales_checkout_links")
              .select("*")
              .eq("offer_id", offerId)
              .eq("environment", "test")
              .in("status", ["active", "sent", "opened", "payment_pending"])
              .maybeSingle();
            if (racedLinkError) throw racedLinkError;
            if (racedLink) {
              return res.json({
                success: true,
                link: serializeSalesCheckoutLink(req, racedLink),
                idempotent: true,
              });
            }
          }
          throw storeError;
        }
        await Promise.all([
          supabase.from("sales_lead_events").upsert(
            [{
              lead_id: offer.lead_id,
              event_type: "checkout_created",
              actor_user_id: actorUserId,
              metadata: {
                offer_id: offerId,
                checkout_link_id: storedLink.id,
                environment: "test",
              },
              idempotency_key: `modular-checkout-created:${storedLink.id}`,
            }],
            { onConflict: "idempotency_key", ignoreDuplicates: true },
          ),
          supabase
            .from("sales_offers")
            .update({
              status: "checkout_created",
              stripe_checkout_session_id: session.id,
              updated_at: new Date().toISOString(),
            })
            .eq("id", offerId)
            .eq("lead_id", offer.lead_id)
            .in("status", ["ready", "sent", "opened", "checkout_created"]),
        ]);
        return res.status(201).json({
          success: true,
          link: serializeSalesCheckoutLink(req, storedLink),
          idempotent: false,
        });
      } catch (error: any) {
        console.error("[Sales Modular Checkout] Falha ao gerar link.", {
          offerId,
          actorUserId,
          code: sanitizeString(error?.code, 100),
          message: sanitizeString(error?.message || String(error), 220),
        });
        return res.status(500).json({
          success: false,
          code: "MODULAR_CHECKOUT_CREATION_FAILED",
          error: "Não foi possível gerar o link de pagamento.",
        });
      }
    },
  );

  app.get(
    "/api/owner/sales/offers/:offerId/modular-checkout",
    checkAuth,
    requireRoles("owner"),
    async (req: any, res) => {
      const offerId = sanitizeString(req.params?.offerId, 120);
      if (!isUuid(offerId)) return res.status(400).json({ success: false, error: "OFFER_INVALID" });
      const { data, error } = await supabase
        .from("sales_checkout_links")
        .select("*")
        .eq("offer_id", offerId)
        .order("created_at", { ascending: false })
        .limit(20);
      if (error) return res.status(500).json({ success: false, error: "CHECKOUT_LINKS_UNAVAILABLE" });
      const { data: offer } = await supabase
        .from("sales_offers")
        .select("accepted_at,accepted_terms_at")
        .eq("id", offerId)
        .eq("offer_type", "modular")
        .maybeSingle();
      return res.json({
        success: true,
        acceptedAt: offer?.accepted_at && offer?.accepted_terms_at
          ? offer.accepted_at
          : null,
        links: (data || []).map((link: any) => serializeSalesCheckoutLink(req, link)),
      });
    },
  );

  app.post(
    "/api/owner/sales/offers/:offerId/modular-checkout/expire",
    checkAuth,
    requireRoles("owner"),
    modularCheckoutLimiter,
    async (req: any, res) => {
      const offerId = sanitizeString(req.params?.offerId, 120);
      const linkId = sanitizeString(req.body?.linkId, 120);
      if (!isUuid(offerId) || !isUuid(linkId) || !hasVerifiedOwnerMfaSession(req.session?.user)) {
        return res.status(403).json({ success: false, error: "OWNER_MFA_REQUIRED" });
      }
      const { data: link, error } = await supabase
        .from("sales_checkout_links")
        .select("id,lead_id,stripe_checkout_session_id,status")
        .eq("id", linkId)
        .eq("offer_id", offerId)
        .maybeSingle();
      if (error || !link) return res.status(404).json({ success: false, error: "CHECKOUT_LINK_NOT_FOUND" });
      if (link.stripe_checkout_session_id && link.status !== "expired") {
        await getStripe().checkout.sessions.expire(link.stripe_checkout_session_id).catch(() => undefined);
      }
      const now = new Date().toISOString();
      await Promise.all([
        supabase.from("sales_checkout_links").update({ status: "expired", logically_expired_at: now, updated_at: now }).eq("id", linkId),
        supabase.from("sales_lead_events").upsert(
          [{
            lead_id: link.lead_id,
            event_type: "checkout_expired",
            actor_user_id: req.session.user.id,
            metadata: { offer_id: offerId, checkout_link_id: linkId },
            idempotency_key: `modular-checkout-expired:${linkId}`,
          }],
          { onConflict: "idempotency_key", ignoreDuplicates: true },
        ),
      ]);
      return res.json({ success: true, expiredAt: now });
    },
  );

  app.post(
    "/api/owner/sales/offers/:offerId/modular-checkout/email",
    checkAuth,
    requireRoles("owner"),
    modularCheckoutLimiter,
    async (req: any, res) => {
      const offerId = sanitizeString(req.params?.offerId, 120);
      const linkId = sanitizeString(req.body?.linkId, 120);
      if (!isUuid(offerId) || !isUuid(linkId) || !hasVerifiedOwnerMfaSession(req.session?.user)) {
        return res.status(403).json({ success: false, error: "OWNER_MFA_REQUIRED" });
      }
      const { data: link, error: linkError } = await supabase
        .from("sales_checkout_links")
        .select("id,offer_id,lead_id,checkout_url,request_hash,status,environment")
        .eq("id", linkId)
        .eq("offer_id", offerId)
        .in("status", ["active", "sent", "opened", "payment_pending"])
        .maybeSingle();
      if (linkError || !link?.checkout_url) {
        return res.status(404).json({ success: false, error: "ACTIVE_CHECKOUT_LINK_NOT_FOUND" });
      }
      const { data: lead, error: leadError } = await supabase
        .from("sales_leads")
        .select("email,normalized_email")
        .eq("id", link.lead_id)
        .is("deleted_at", null)
        .maybeSingle();
      const recipient = sanitizeEmail(lead?.normalized_email || lead?.email);
      if (leadError || !recipient) {
        return res.status(422).json({ success: false, error: "LEAD_EMAIL_REQUIRED" });
      }
      try {
        const publicCheckoutUrl = serializeSalesCheckoutLink(req, link).publicCheckoutUrl;
        const email = await getResend().emails.send(
          {
            from: sanitizeString(process.env.RESEND_FROM_EMAIL, 320) || OFFICIAL_FROM_NOREPLY,
            to: recipient,
            subject: "Seu link individual de pagamento Verto",
            html: `<div style="font-family:Arial,sans-serif;color:#1e293b;line-height:1.6"><h1 style="font-size:20px">Pagamento da proposta Verto</h1><p>O aceite comercial foi registrado. Use o link individual abaixo para concluir o pagamento em ambiente ${link.environment === "test" ? "de teste" : "de produção"}.</p><p><a href="${escapeHtml(publicCheckoutUrl)}" style="display:inline-block;padding:12px 18px;border-radius:10px;background:#7c3aed;color:#fff;text-decoration:none">Abrir Checkout seguro</a></p><p style="font-size:12px;color:#64748b">Esta mensagem contém apenas informações comerciais e não inclui dados clínicos.</p></div>`,
          },
          { idempotencyKey: `modular-checkout-email:${linkId}` },
        );
        if (email.error) throw email.error;
        const now = new Date().toISOString();
        await Promise.all([
          supabase.from("sales_checkout_links").update({ status: "sent", updated_at: now }).eq("id", linkId),
          supabase
            .from("sales_leads")
            .update({ status: "checkout_sent", updated_at: now })
            .eq("id", link.lead_id)
            .in("status", ["proposal_sent", "checkout_sent", "checkout_opened"])
            .is("deleted_at", null),
          supabase.from("sales_lead_events").upsert(
            [{
              lead_id: link.lead_id,
              event_type: "checkout_sent",
              actor_user_id: req.session.user.id,
              metadata: { offer_id: offerId, checkout_link_id: linkId },
              idempotency_key: `modular-checkout-sent:${linkId}`,
            }],
            { onConflict: "idempotency_key", ignoreDuplicates: true },
          ),
        ]);
        return res.json({ success: true, sentAt: now });
      } catch (error: any) {
        console.warn("[Sales Modular Checkout] Envio de link falhou.", {
          offerId,
          linkId,
          message: sanitizeString(error?.message || String(error), 180),
        });
        return res.status(502).json({ success: false, error: "CHECKOUT_EMAIL_FAILED" });
      }
    },
  );

  app.post(
    "/api/owner/sales/offers/:offerId/resend-activation",
    checkAuth,
    requireRoles("owner", "admin"),
    resendActivationLimiter,
    async (req: any, res) => {
      const offerId = sanitizeString(req.params?.offerId, 120);
      if (!isUuid(offerId)) {
        return res.status(400).json({
          success: false,
          error: "SALES_OFFER_INVALID",
        });
      }
      try {
        const { data: offer, error: offerError } = await supabase
          .from("sales_offers")
          .select(
            "id,lead_id,status,stripe_checkout_session_id,provisioning_status",
          )
          .eq("id", offerId)
          .eq("status", "paid")
          .maybeSingle();
        if (offerError) throw offerError;
        const checkoutSessionId = sanitizeString(
          offer?.stripe_checkout_session_id,
          200,
        );
        if (!offer || !checkoutSessionId) {
          return res.status(404).json({
            success: false,
            error: "PAID_SALES_OFFER_NOT_FOUND",
          });
        }

        const stripe = getStripe();
        const checkoutSession = await stripe.checkout.sessions.retrieve(
          checkoutSessionId,
        );
        const result = await processSalesAssistedCheckoutCompleted(
          stripe,
          checkoutSession,
        );
        return res.status(result.activationEmailSent ? 200 : 202).json({
          success: true,
          paymentConfirmed: result.paymentConfirmed,
          activationEmailSent: result.activationEmailSent,
          message: result.activationEmailSent
            ? "E-mail de ativacao confirmado."
            : "Pagamento preservado; o envio da ativacao continua pendente.",
        });
      } catch (error: any) {
        console.error("[Owner Sales] Falha ao reenviar ativacao.", {
          offerId,
          message: sanitizeString(error?.message || String(error), 200),
        });
        return res.status(503).json({
          success: false,
          error: "SALES_ACTIVATION_RESEND_FAILED",
        });
      }
    },
  );

